const PAYLOAD={"block_id":"DEEPDIVE01_NSCLC","case_id":"MTB_NSCLC_001_v0_6","version":"1.0","created_at":"2026-08-06T12:45:00+02:00","status":"READY_FOR_USER_REVIEW","block_hash_sha256":"fe15866ff7477bb490c6df8eb54d50248d50c269cde286b2e676b534f65948ce","source_manifest":{"case_metadata":{"path":"data/case_metadata_v1_5_AP1b_final.json","sha256":"55daaaef3113885b3b5bc0c84d2bbdeefb106f4720cfd04c5d8d8929ccbcd3da"},"base_case":{"path":"data/cases_v1_4_universal_methods.json","sha256":"aaed62f7091c9706f0ea1cc6a5526a74ce7d5ca696d366f14ffbf99d043d7723"},"deep_dive":{"path":"data/deep_dive_cases_v1_7b.json","sha256":"6a7a097b61ce39a2883f6c1148e99bd9748a051238ac3cc18ede7fde49a86062"},"message_catalog":{"path":"i18n_message_catalog_v2_2_3.json","sha256":"4cd851992eed4fc35d6361a24810640196adf3e292cf49edc02fff27b0430ee6"}},"de":{"metadata":{"case_id":"MTB_NSCLC_001_v0_6","base_id":"MTB_NSCLC_001","title":"Pulmonale Raumforderung → NSCLC → molekulare Therapieentscheidung","domain":"MTB","met_addon_type":"no","subdomain":"Onkogene Treiber / NSCLC / Resistenz","case_type":"clinical_decision","length_class":"Standard","estimated_minutes":{"min":8,"max":12},"difficulty":"Intermediate","status":"curated-core","review_flag":"Core/MVP prüfen","review_priority":"high","core_decision":"NSCLC → molekulare Therapieentscheidung","learning_objectives":["Zentrale klinisch-molekulare Fragestellung aus Anamnese, Histologie und Materialkontext ableiten","Passende molekulare/IHC-basierte Methode zur Kernentscheidung auswählen","Musterlösung im MTB klar, limitiert und patientenrelevant kommunizieren"],"tags":["NSCLC","IHC","DNA-NGS","RNA-NGS","PD-L1","ALK","Materialbudget","MTB"],"ap1b_decision":"MTB; Länge=Standard; Schwierigkeit=Intermediate; Status=curated-core"},"base_case":{"id":"MTB_NSCLC_001_v0_6","title":"Pulmonale Raumforderung → NSCLC → molekulare Therapieentscheidung","short":"NSCLC Erstdiagnose","mode":"patient_care","logic":"nsclc","difficulty":"intermediate","estimated_time_min":"8–12","budget":{"points_max":900,"sections_max":12,"tat_goal":8},"allowed_tests":["he_review","ihc_lung_lineage","ki67","pdl1","alk_ihc","egfr_pcr","kras_pcr","braf_pcr","alk_fish","ros1_fish","dna_lung_panel","rna_fusion_panel","dna_rna_lung_combo","liquid_biopsy","broad_pan_panel"],"story":[{"id":"intake","title":"Initialer Auftrag","items":[["Einsender","Onkologie / Bronchoskopie"],["Klinische Information","67-jähriger Patient, pulmonale Raumforderung links, multiple kleine Leberherde im CT."],["Fragestellung","Malignität? Primarius? Therapieentscheidende Diagnostik für MTB."],["Was ist noch unklar?","Zu Beginn ist noch nicht sicher, ob es wirklich ein primäres Lungenkarzinom ist."]]},{"id":"history","title":"Anamnese und klinischer Kontext","items":[["Raucherstatus","Ex-Raucher, 15 pack years; seit 20 Jahren abstinent."],["Performance / Situation","ECOG 1, keine kurative Option, systemische Therapie zeitnah geplant."],["Vorbefunde","Keine frühere Tumorerkrankung bekannt."],["MTB-Zeitdruck","Fall soll in 7 Tagen im MTB vorgestellt werden."]]},{"id":"histo","title":"Histologie + Vor-IHC","items":[["HE","Infiltrate eines nicht-kleinzelligen Karzinoms in kleiner Bronchialbiopsie."],["IHC","TTF-1 positiv, Napsin A positiv, CK7 positiv; p40/CK5/6 negativ."],["Proliferation","Ki67 ca. 35 %."],["Arbeitsdiagnose","Pulmonales Adenokarzinom / NSCLC, Stadium IV wahrscheinlich."],["Noch offen","PD-L1 und molekulares Treiberprofil fehlen."]]},{"id":"material","title":"Materialprüfung","items":[["Material","FFPE-Biopsie, Block B2."],["Tumoranteil","ca. 25–30 %, Makrodissektion empfohlen."],["Nekrose","fokal, aber beurteilbare Tumorareale vorhanden."],["Verfügbare ungefärbte Schnitte","12 Schnitte planbar."],["DNA/RNA-Prognose","DNA wahrscheinlich ausreichend; RNA bei kleiner Biopsie potenziell grenzwertig."],["Materialfalle","Serielle Einzeltests können das Material verbrauchen, bevor RNA-Fusionen geprüft wurden."]]}],"optimal_tests":["he_review","pdl1","dna_lung_panel","rna_fusion_panel"],"acceptable_alternatives":["dna_rna_lung_combo"],"result_truth":{"driver":"EML4::ALK-Fusion","pdl1":"TPS 5 %","dna":"keine EGFR/KRAS/BRAF/METex14/ERBB2-Hotspot-Alteration","qc":"DNA ausreichend; RNA knapp, aber verwertbar"},"tags":["NSCLC","IHC","DNA-NGS","RNA-NGS","PD-L1","ALK","Materialbudget","MTB"]},"deep_dive":{"version":"v1.7b","case_id":"MTB_NSCLC_001_v0_6","title":"Metastasiertes Lungenadenokarzinom, kleine Biopsie: vollständige prädiktive Diagnostik ohne Materialverschwendung","domain":"MTB","target_course":"MTB Basics","deep_dive_priority":"signature","target_role":"Pathologieassistenz / MTB-Einstieg","estimated_minutes_deep":"12-15","learning_objectives":["Treiber-, Fusions- und PD-L1-Diagnostik beim metastasierten NSCLC parallel und materialschonend planen.","DNA-only-Strategien bei fusionsrelevanter Fragestellung als potenziell unvollständig erkennen.","Befundlimitationen bei kleiner Biopsie und begrenztem Tumoranteil klar im MTB kommunizieren."],"opening_scene":"Montagmorgen, Tumorboard-Vorbereitung: Eine Bronchialbiopsie eines neu metastasierten Lungenkarzinoms liegt vor. Die Onkologie möchte innerhalb einer Woche wissen, ob eine zielgerichtete Therapie oder Immuntherapie infrage kommt. Das Material ist sichtbar knapp, aber die Therapieentscheidung hängt jetzt an der Pathologie.","case_briefing":"68-jähriger Patient, ehemaliger Raucher, multiple pulmonale und ossäre Metastasen. Klinische Anfrage: 'Bitte molekulare Therapierbarkeit prüfen, Erstlinientherapie soll im MTB festgelegt werden.' Vorbefund aus der Pathologie: Adenokarzinom der Lunge, nicht-kleinzellig, keine Resektionsoption.","context_cards":[{"title":"Klinischer Druck","content":"Der Patient ist symptomatisch, aber klinisch stabil. Eine Entscheidung über TKI vs. Immun-/Chemotherapie soll in 7 Tagen fallen.","teaching_point":"Zeitdruck rechtfertigt parallele, nicht sequentielle Diagnostik."},{"title":"Histologie","content":"Kleine Bronchialbiopsie mit invasivem Adenokarzinom. TTF-1 und Napsin A positiv, p40/CK5/6 negativ, CK7 positiv. Ki-67 ca. 35–40%.","teaching_point":"Die Entität ist ausreichend eingegrenzt; jetzt geht es um prädiktive Marker."},{"title":"Material","content":"Tumorareal ca. 25%, fokal Nekrose. Nach Diagnostik bleiben geschätzt 8 unstained Slides. RNA-Qualität ist nicht garantiert, aber noch plausibel nutzbar.","teaching_point":"Material Stewardship ist Teil der richtigen Entscheidung."},{"title":"MTB-Frage","content":"Die Onkologie fragt explizit nach EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS und PD-L1.","teaching_point":"Die Anfrage spricht gegen eine reine EGFR-PCR als alleinige Strategie."}],"pre_results":[{"title":"HE","content":"invasives Lungenadenokarzinom, mäßig differenziert, kleine Biopsie."},{"title":"IHC","content":"TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; PD-L1 noch nicht erfolgt."},{"title":"Material-QC","content":"Tumorzellanteil ausreichend, aber knapp; RNA-Fusionsdiagnostik sollte nicht durch unnötige Zusatztests gefährdet werden."}],"material_or_resource_constraints":["maximal 8 Schnitte verfügbar; unnötige IHC-/Methylierungs-/HRD-Tests reduzieren die Chance auf vollständige Molekulardiagnostik.","TAT-Ziel: 7 Kalendertage bis MTB.","DNA und RNA sollten möglichst aus demselben markierten Tumorareal gewonnen werden."],"reasoning_gate_upgrade":[{"id":"central_question","type":"single_choice","prompt":"Was ist die zentrale klinische Fragestellung?","options":[{"id":"driver_fusion_pdl1","label":"Vollständige prädiktive Erstliniendiagnostik mit Treibern, Fusionen und PD-L1"},{"id":"lynch","label":"Lynch-Syndrom-Abklärung"},{"id":"hrd","label":"HRD/PARP-Indikation"},{"id":"infection","label":"Infektionsdiagnostik"}],"correct":["driver_fusion_pdl1"],"rationale":"Beim metastasierten Lungenadenokarzinom steht die therapieentscheidende Treiber-/Fusions-/PD-L1-Diagnostik im Vordergrund."},{"id":"material_risk","type":"single_choice","prompt":"Was ist das wichtigste Materialrisiko?","options":[{"id":"small_biopsy","label":"Kleine Biopsie mit begrenztem Tumorareal und potenzieller RNA-Fragilität"},{"id":"no_relevance","label":"Material spielt bei NGS praktisch keine Rolle"},{"id":"plasma_replaces","label":"Plasma ersetzt Gewebe grundsätzlich"},{"id":"methylation_first","label":"Methylierung sollte grundsätzlich zuerst erfolgen"}],"correct":["small_biopsy"],"rationale":"Die vollständige Diagnostik muss materialschonend und priorisiert geplant werden."},{"id":"dna_only_limit","type":"single_choice","prompt":"Warum ist DNA-NGS allein in diesem Fall riskant?","options":[{"id":"fusion_gap","label":"Relevante Genfusionen können unzureichend erfasst werden, RNA-Fusionsdiagnostik ergänzt die Aussage"},{"id":"no_mutations","label":"DNA-NGS detektiert keine Mutationen"},{"id":"pdl1_in_dna","label":"PD-L1 wird zuverlässig aus DNA abgeleitet"},{"id":"crc_only","label":"Fusionen sind nur beim CRC relevant"}],"correct":["fusion_gap"],"rationale":"DNA-NGS ist für SNV/Indels stark, aber RNA-basierte Verfahren sind für relevante Fusionen häufig die bessere Ergänzung."}],"decision_task":"Wähle eine materialschonende Primäranforderung, die die Erstlinientherapie im MTB belastbar unterstützt.","expected_path":["PD-L1-IHC parallel anfordern.","DNA-basiertes Lungen-/Solid-Tumor-Panel für SNV/Indels/CNV inkl. EGFR, KRAS, BRAF, MET, ERBB2.","RNA-Fusionspanel für ALK, ROS1, RET, NTRK und weitere relevante Fusionen.","Tumorareal markieren und unnötige entitätsfremde Zusatzdiagnostik vermeiden.","Befund mit Methodengrenzen und Materialqualität berichten."],"acceptable_alternatives":["Bei extremem Zeitdruck kann EGFR-Schnelltest zusätzlich erfolgen, ersetzt aber nicht die Panel-/Fusionsdiagnostik.","ALK-IHC/FISH kann als schnelle Ergänzung sinnvoll sein, aber nicht als alleinige umfassende Strategie."],"low_value_traps":[{"label":"MLH1-Methylierung","why_bad":"Ohne dMMR-/CRC-/Lynch-Kontext entitätsfremd und materialverbrauchend."},{"label":"HRD-Score","why_bad":"Für die primäre NSCLC-Erstlinienentscheidung nicht zielführend."},{"label":"EGFR-PCR allein","why_bad":"Kann EGFR beantworten, lässt aber viele therapeutisch relevante Alterationen offen."}],"twist":{"title":"DNA-negativ ist nicht automatisch treibernegativ","content":"Wenn nur DNA-NGS und PD-L1 angefordert werden, ergibt sich ein Teilbefund: kein EGFR/KRAS/BRAF/METex14-Nachweis, PD-L1 TPS 5%. Erst bei RNA-Fusionsdiagnostik wird eine EML4::ALK-Fusion detektiert.","why_critical":"Die therapeutisch entscheidende Alteration wäre bei zu enger Primäranforderung verzögert oder verpasst worden."},"result_packages":[{"id":"optimal","title":"Vollständige Primäranforderung","result":"PD-L1 TPS 5%; DNA-Panel ohne EGFR/KRAS/BRAF/METex14; RNA-Panel mit EML4::ALK-Fusion.","feedback":"Sehr gute Strategie: vollständige prädiktive Diagnostik bei kleinem Material und direkter therapeutischer Konsequenz."},{"id":"incomplete_dna_only","title":"DNA-NGS + PD-L1 ohne RNA","result":"Teilbefund ohne SNV/Indel-Treiber, PD-L1 TPS 5%; Fusionsstatus nicht ausreichend beurteilt.","feedback":"Richtige Richtung, aber unvollständig. Nachforderung RNA rettet den Fall, kostet aber Material und TAT."},{"id":"overdiagnostic","title":"Breite, entitätsfremde Zusatzdiagnostik","result":"Vollständige Zielmarker ggf. verfügbar, aber unnötiger Materialverbrauch durch MMR/MLH1/HRD etc.","feedback":"Diagnostisch nicht katastrophal, aber Material Stewardship und Kommunikation leiden deutlich."}],"followup_logic":[{"trigger":"RNA-Fusionsdiagnostik primär fehlt","action":"Nachforderung RNA-Fusionspanel anbieten","consequence":"Ergebnis wird vollständig, aber Score-Cap wegen vermeidbarer Verzögerung."},{"trigger":"entitätsfremde Tests gewählt","action":"im Bericht als low value/misleading ausweisen","consequence":"Abzug bei Method Selection, Material Stewardship und Communication."}],"debrief_points":["Beim metastasierten NSCLC ist die klinische Frage breit prädiktiv, nicht nur EGFR-orientiert.","Fusionen sind ein klassischer Grund, DNA-only-Strategien kritisch zu hinterfragen.","Kleine Biopsie heißt nicht weniger Diagnostik, sondern bessere Priorisierung."],"instructor_notes":{"model_answer":"Optimale Lösung: PD-L1-IHC + DNA-NGS + RNA-Fusionspanel parallel, mit Materialhinweis und klarer MTB-Kommunikation. EGFR-Schnelltest nur als Zusatz bei Zeitdruck.","scoring_focus":["Clinical Reasoning: Erstlinienfrage erkannt","Method Selection: DNA/RNA/PD-L1 korrekt kombiniert","Material Stewardship: entitätsfremde Tests vermieden"],"discussion_questions":["Wann wäre Liquid Biopsy zusätzlich sinnvoll?","Wie kommuniziert man 'kein Treiber nachgewiesen' ohne RNA-Fusionsergebnis?","Welche Rolle spielt PD-L1 bei nachgewiesener ALK-Fusion?"]},"report_additions":["Twist / kritischer Wendepunkt: DNA-only hätte ALK verzögert","Typische Fehler: EGFR-only, RNA vergessen, Material durch Low-value-Tests verbraucht","Musterpfad: PD-L1 + DNA + RNA parallel"]}},"languages":{"en":{"metadata":{"case_id":"MTB_NSCLC_001_v0_6","base_id":"MTB_NSCLC_001","title":"Pulmonary mass → NSCLC → molecularly informed treatment decision","domain":"MTB","met_addon_type":"no","subdomain":"Oncogenic drivers / NSCLC / resistance","case_type":"clinical_decision","length_class":"Standard","estimated_minutes":{"min":8,"max":12},"difficulty":"Intermediate","status":"curated-core","review_flag":"Review for core/MVP","review_priority":"high","core_decision":"NSCLC → molecularly informed treatment decision","learning_objectives":["Derive the central clinical-molecular question from the history, histology and tissue context","Select the appropriate molecular or IHC-based method for the key decision","Communicate the reference answer clearly in the MTB, including limitations and patient relevance"],"tags":["NSCLC","IHC","DNA NGS","RNA NGS","PD-L1","ALK","Tissue budget","MTB"],"ap1b_decision":"MTB; length=standard; difficulty=intermediate; status=curated-core"},"base_case":{"id":"MTB_NSCLC_001_v0_6","title":"Pulmonary mass → NSCLC → molecularly informed treatment decision","short":"Newly diagnosed NSCLC","mode":"patient_care","logic":"nsclc","difficulty":"intermediate","estimated_time_min":"8–12","budget":{"points_max":900,"sections_max":12,"tat_goal":8},"allowed_tests":["he_review","ihc_lung_lineage","ki67","pdl1","alk_ihc","egfr_pcr","kras_pcr","braf_pcr","alk_fish","ros1_fish","dna_lung_panel","rna_fusion_panel","dna_rna_lung_combo","liquid_biopsy","broad_pan_panel"],"story":[{"id":"intake","title":"Initial request","items":[["Referrer","Oncology / bronchoscopy"],["Clinical information","67-year-old patient with a left pulmonary mass and multiple small liver lesions on CT."],["Clinical question","Malignancy? Primary site? Treatment-defining diagnostics for the MTB."],["What remains unclear?","At the outset, it is not yet certain that this is a primary lung carcinoma."]]},{"id":"history","title":"Medical history and clinical context","items":[["Smoking history","Former smoker, 15 pack-years; quit 20 years ago."],["Performance status / clinical situation","ECOG 1, no curative option; systemic treatment is planned promptly."],["Previous findings","No previous malignancy is known."],["MTB time pressure","The case is to be presented at the MTB in 7 days."]]},{"id":"histo","title":"Histology and initial IHC","items":[["H&E","Infiltrates of a non-small-cell carcinoma in a small bronchial biopsy."],["IHC","TTF-1 positive, Napsin A positive and CK7 positive; p40 and CK5/6 negative."],["Proliferation","Ki67 approximately 35%."],["Working diagnosis","Pulmonary adenocarcinoma / NSCLC, probably stage IV."],["Still pending","PD-L1 and the molecular driver profile are still pending."]]},{"id":"material","title":"Tissue assessment","items":[["Tissue material","FFPE biopsy, block B2."],["Tumour cell content","Approximately 25–30%; macrodissection recommended."],["Necrosis","Focal, but evaluable tumour areas are present."],["Available unstained sections","12 sections can be allocated."],["Expected DNA/RNA yield","DNA is likely sufficient; RNA may be borderline in this small biopsy."],["Tissue-use pitfall","Sequential single-gene tests can exhaust the tissue before RNA fusions have been assessed."]]}],"optimal_tests":["he_review","pdl1","dna_lung_panel","rna_fusion_panel"],"acceptable_alternatives":["dna_rna_lung_combo"],"result_truth":{"driver":"EML4::ALK fusion","pdl1":"TPS 5%","dna":"No EGFR/KRAS/BRAF/METex14/ERBB2 hotspot alteration","qc":"DNA sufficient; RNA limited but suitable for analysis"},"tags":["NSCLC","IHC","DNA NGS","RNA NGS","PD-L1","ALK","Tissue budget","MTB"]},"deep_dive":{"version":"v1.7b","case_id":"MTB_NSCLC_001_v0_6","title":"Metastatic lung adenocarcinoma, small biopsy: complete predictive testing without wasting tissue","domain":"MTB","target_course":"MTB Basics","deep_dive_priority":"signature","target_role":"Pathology trainee / introduction to MTB","estimated_minutes_deep":"12–15","learning_objectives":["Plan driver, fusion and PD-L1 testing in metastatic NSCLC in parallel while preserving tissue.","Recognise DNA-only strategies as potentially incomplete when fusions are clinically relevant.","Clearly communicate report limitations related to a small biopsy and limited tumour cell content in the MTB."],"opening_scene":"Monday morning, preparing for the tumour board: a bronchial biopsy from a newly diagnosed metastatic lung carcinoma has arrived. Oncology needs to know within one week whether targeted therapy or immunotherapy is an option. Tissue is clearly limited, but the treatment decision now depends on pathology.","case_briefing":"68-year-old patient, former smoker, with multiple pulmonary and bone metastases. Clinical request: 'Please assess molecularly targetable alterations; first-line treatment will be determined at the MTB.' Preliminary pathology diagnosis: non-small-cell adenocarcinoma of the lung, not amenable to resection.","context_cards":[{"title":"Clinical urgency","content":"The patient is symptomatic but clinically stable. A decision between TKI treatment and immunotherapy/chemotherapy is required within 7 days.","teaching_point":"Time pressure supports parallel rather than sequential testing."},{"title":"Histology","content":"Small bronchial biopsy showing invasive adenocarcinoma. TTF-1 and Napsin A positive, p40/CK5/6 negative, CK7 positive. Ki-67 approximately 35–40%.","teaching_point":"The tumour entity has been sufficiently defined; the focus now is on predictive biomarkers."},{"title":"Tissue material","content":"Tumour area approximately 25%, with focal necrosis. An estimated 8 unstained slides remain after the current work-up. RNA quality is not guaranteed but is still plausibly adequate for analysis.","teaching_point":"Tissue stewardship is part of the correct decision."},{"title":"MTB question","content":"Oncology explicitly requests testing for EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS and PD-L1.","teaching_point":"This request argues against using EGFR PCR alone as the sole strategy."}],"pre_results":[{"title":"H&E","content":"Invasive, moderately differentiated lung adenocarcinoma in a small biopsy."},{"title":"IHC","content":"TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; PD-L1 not yet performed."},{"title":"Tissue QC","content":"Tumour cell content is sufficient but limited; RNA fusion testing should not be jeopardised by unnecessary additional tests."}],"material_or_resource_constraints":["A maximum of 8 sections is available; unnecessary IHC, methylation or HRD tests reduce the likelihood of completing the molecular work-up.","TAT target: 7 calendar days to the MTB.","DNA and RNA should, whenever possible, be extracted from the same marked tumour area."],"reasoning_gate_upgrade":[{"id":"central_question","type":"single_choice","prompt":"What is the central clinical question?","options":[{"id":"driver_fusion_pdl1","label":"Complete predictive first-line testing for oncogenic drivers, fusions and PD-L1"},{"id":"lynch","label":"Evaluation for Lynch syndrome"},{"id":"hrd","label":"HRD/PARP indication"},{"id":"infection","label":"Infectious-disease testing"}],"correct":["driver_fusion_pdl1"],"rationale":"In metastatic lung adenocarcinoma, treatment-defining testing for oncogenic drivers, fusions and PD-L1 is the priority."},{"id":"material_risk","type":"single_choice","prompt":"What is the most important tissue-related risk?","options":[{"id":"small_biopsy","label":"Small biopsy with a limited tumour area and potentially fragile RNA"},{"id":"no_relevance","label":"Tissue availability is largely irrelevant for NGS"},{"id":"plasma_replaces","label":"Plasma always replaces tissue"},{"id":"methylation_first","label":"Methylation testing should always be performed first"}],"correct":["small_biopsy"],"rationale":"The complete diagnostic work-up must be prioritised and planned to preserve tissue."},{"id":"dna_only_limit","type":"single_choice","prompt":"Why is DNA NGS alone risky in this case?","options":[{"id":"fusion_gap","label":"Relevant gene fusions may be insufficiently detected; RNA fusion testing provides complementary information"},{"id":"no_mutations","label":"DNA NGS does not detect mutations"},{"id":"pdl1_in_dna","label":"PD-L1 can be reliably inferred from DNA"},{"id":"crc_only","label":"Fusions are relevant only in colorectal cancer"}],"correct":["fusion_gap"],"rationale":"DNA NGS performs well for SNVs and indels, but RNA-based methods are often the better complement for clinically relevant fusions."}],"decision_task":"Choose an initial test request that preserves tissue and robustly supports the first-line treatment decision in the MTB.","expected_path":["Request PD-L1 IHC in parallel.","DNA-based lung/solid-tumour panel for SNVs, indels and CNVs, including EGFR, KRAS, BRAF, MET and ERBB2.","RNA fusion panel for ALK, ROS1, RET, NTRK and other relevant fusions.","Mark the tumour area and avoid unnecessary additional testing unrelated to the tumour entity.","Report the findings together with method limitations and tissue quality."],"acceptable_alternatives":["Under extreme time pressure, a rapid EGFR test may be added, but it does not replace panel and fusion testing.","ALK IHC/FISH may be useful as a rapid adjunct, but not as the sole comprehensive strategy."],"low_value_traps":[{"label":"MLH1 promoter methylation","why_bad":"Without a dMMR, colorectal-cancer or Lynch context, this is unrelated to the tumour entity and consumes tissue."},{"label":"HRD score","why_bad":"Not relevant to the initial first-line decision in NSCLC."},{"label":"EGFR PCR alone","why_bad":"It can answer the EGFR question but leaves many treatment-relevant alterations unassessed."}],"twist":{"title":"A negative DNA result does not automatically mean driver-negative","content":"If only DNA NGS and PD-L1 are requested, the result is incomplete: no EGFR/KRAS/BRAF/METex14 alteration is detected and PD-L1 TPS is 5%. An EML4::ALK fusion is identified only when RNA fusion testing is performed.","why_critical":"The treatment-defining alteration would have been delayed or missed with an overly narrow initial request."},"result_packages":[{"id":"optimal","title":"Complete initial test request","result":"PD-L1 TPS 5%; DNA panel negative for EGFR/KRAS/BRAF/METex14; RNA panel identifies an EML4::ALK fusion.","feedback":"Very good strategy: complete predictive testing using limited tissue, with a direct treatment consequence."},{"id":"incomplete_dna_only","title":"DNA NGS and PD-L1 without RNA testing","result":"Incomplete result with no SNV/indel driver identified and PD-L1 TPS 5%; fusion status is not adequately assessed.","feedback":"The overall direction is correct, but the work-up is incomplete. Additional RNA testing resolves the case, but at the cost of tissue and TAT."},{"id":"overdiagnostic","title":"Broad additional testing unrelated to the tumour entity","result":"The required target markers may still be obtained, but tissue is unnecessarily consumed by MMR, MLH1, HRD and similar tests.","feedback":"Not diagnostically disastrous, but tissue stewardship and communication are clearly compromised."}],"followup_logic":[{"trigger":"Primary RNA fusion testing is missing","action":"Offer an additional RNA fusion panel","consequence":"The result becomes complete, but a score cap applies because of the avoidable delay."},{"trigger":"Tests unrelated to the tumour entity were selected","action":"Identify as low-value or misleading in the report","consequence":"Deduction in Method Selection, Material Stewardship and Communication."}],"debrief_points":["In metastatic NSCLC, the clinical question requires broad predictive testing and is not limited to EGFR.","Fusions are a classic reason to critically question DNA-only strategies.","A small biopsy does not mean less testing; it means better prioritisation."],"instructor_notes":{"model_answer":"Reference answer: PD-L1 IHC, DNA NGS and an RNA fusion panel in parallel, with a tissue-availability note and clear MTB communication. A rapid EGFR test is only an adjunct when time is critical.","scoring_focus":["Clinical reasoning: first-line treatment question identified","Method selection: DNA, RNA and PD-L1 correctly combined","Material stewardship: tests unrelated to the tumour entity avoided"],"discussion_questions":["When would liquid biopsy be useful as an additional test?","How should 'no driver alteration detected' be communicated when no RNA fusion result is available?","What is the role of PD-L1 when an ALK fusion has been detected?"]},"report_additions":["Twist / critical turning point: a DNA-only strategy would have delayed ALK detection","Typical errors: EGFR-only testing, omission of RNA testing, and tissue consumption by low-value tests","Reference pathway: PD-L1, DNA and RNA in parallel"]},"payload_hash_sha256":"682c200bea6b8827b0b8213815dcaa955e06b5b66b77d4033870736aba9bfd4f"},"ro":{"metadata":{"case_id":"MTB_NSCLC_001_v0_6","base_id":"MTB_NSCLC_001","title":"Formațiune pulmonară → NSCLC → decizie terapeutică bazată pe profilul molecular","domain":"MTB","met_addon_type":"no","subdomain":"Alterări oncogenice driver / NSCLC / rezistență","case_type":"clinical_decision","length_class":"Standard","estimated_minutes":{"min":8,"max":12},"difficulty":"Intermediate","status":"curated-core","review_flag":"De revizuit pentru conținutul de bază/MVP","review_priority":"high","core_decision":"NSCLC → decizie terapeutică bazată pe profilul molecular","learning_objectives":["Formulați întrebarea clinico-moleculară centrală pe baza anamnezei, histologiei și contextului materialului tisular","Selectați metoda moleculară sau bazată pe IHC adecvată pentru decizia principală","Comunicați clar soluția de referință în MTB, cu limitările și relevanța pentru pacient"],"tags":["NSCLC","IHC","NGS ADN","NGS ARN","PD-L1","ALK","Buget de material tisular","MTB"],"ap1b_decision":"MTB; lungime=standard; dificultate=intermediară; stare=curated-core"},"base_case":{"id":"MTB_NSCLC_001_v0_6","title":"Formațiune pulmonară → NSCLC → decizie terapeutică bazată pe profilul molecular","short":"Diagnostic inițial de NSCLC","mode":"patient_care","logic":"nsclc","difficulty":"intermediate","estimated_time_min":"8–12","budget":{"points_max":900,"sections_max":12,"tat_goal":8},"allowed_tests":["he_review","ihc_lung_lineage","ki67","pdl1","alk_ihc","egfr_pcr","kras_pcr","braf_pcr","alk_fish","ros1_fish","dna_lung_panel","rna_fusion_panel","dna_rna_lung_combo","liquid_biopsy","broad_pan_panel"],"story":[{"id":"intake","title":"Solicitare inițială","items":[["Solicitant","Oncologie / bronhoscopie"],["Informații clinice","Pacient în vârstă de 67 de ani, cu formațiune pulmonară stângă și multiple leziuni hepatice mici la CT."],["Întrebare clinică","Malignitate? Sediu primar? Diagnostic care să ghideze tratamentul pentru MTB."],["Ce rămâne neclar?","La început, nu este încă sigur că este vorba într-adevăr despre un carcinom pulmonar primar."]]},{"id":"history","title":"Anamneză și context clinic","items":[["Istoric de fumat","Fost fumător, 15 pachete-an; a renunțat la fumat în urmă cu 20 de ani."],["Status de performanță / situație clinică","ECOG 1, fără opțiune curativă; tratamentul sistemic este planificat în curând."],["Rezultate anterioare","Nu este cunoscută nicio neoplazie anterioară."],["Presiune de timp pentru MTB","Cazul trebuie prezentat în MTB peste 7 zile."]]},{"id":"histo","title":"Histologie și IHC inițială","items":[["H&E","Infiltrate de carcinom fără celule mici într-o biopsie bronșică de dimensiuni reduse."],["IHC","TTF-1 pozitiv, Napsin A pozitiv și CK7 pozitiv; p40 și CK5/6 negative."],["Proliferare","Ki67 aproximativ 35%."],["Diagnostic de lucru","Adenocarcinom pulmonar / NSCLC, probabil stadiul IV."],["Încă neefectuat","Analiza PD-L1 și profilul molecular al alterărilor driver sunt încă neefectuate."]]},{"id":"material","title":"Evaluarea materialului tisular","items":[["Material tisular","Biopsie FFPE, bloc B2."],["Procent tumoral","Aproximativ 25–30%; se recomandă macrodisecția."],["Necroză","Focală, dar există arii tumorale evaluabile."],["Secțiuni necolorate disponibile","Pot fi alocate 12 secțiuni."],["Prognosticul randamentului ADN/ARN","ADN-ul este probabil suficient; ARN-ul poate fi la limită în această biopsie mică."],["Capcană privind utilizarea materialului","Testele secvențiale pentru markeri individuali pot epuiza materialul înainte de evaluarea fuziunilor ARN."]]}],"optimal_tests":["he_review","pdl1","dna_lung_panel","rna_fusion_panel"],"acceptable_alternatives":["dna_rna_lung_combo"],"result_truth":{"driver":"Fuziune EML4::ALK","pdl1":"TPS 5%","dna":"Fără alterări hotspot EGFR/KRAS/BRAF/METex14/ERBB2","qc":"ADN suficient; ARN limitat, dar analizabil"},"tags":["NSCLC","IHC","NGS ADN","NGS ARN","PD-L1","ALK","Buget de material tisular","MTB"]},"deep_dive":{"version":"v1.7b","case_id":"MTB_NSCLC_001_v0_6","title":"Adenocarcinom pulmonar metastatic, biopsie mică: diagnostic predictiv complet fără irosirea materialului tisular","domain":"MTB","target_course":"Noțiuni de bază MTB","deep_dive_priority":"signature","target_role":"Medic în formare în patologie / introducere în MTB","estimated_minutes_deep":"12–15","learning_objectives":["Planificați în paralel testarea alterărilor driver, a fuziunilor și a PD-L1 în NSCLC metastatic, cu utilizarea responsabilă a materialului tisular.","Recunoașteți strategiile bazate exclusiv pe ADN ca potențial incomplete atunci când fuziunile sunt relevante clinic.","Comunicați clar în MTB limitările raportului determinate de biopsia mică și procentul tumoral limitat."],"opening_scene":"Luni dimineață, în pregătirea comisiei oncologice: este disponibilă o biopsie bronșică de la un carcinom pulmonar metastatic recent diagnosticat. Oncologia dorește să afle în decurs de o săptămână dacă este indicată o terapie țintită sau imunoterapia. Materialul tisular este evident limitat, iar decizia terapeutică depinde acum de patologie.","case_briefing":"Pacient în vârstă de 68 de ani, fost fumător, cu multiple metastaze pulmonare și osoase. Solicitare clinică: „Vă rugăm să evaluați opțiunile terapeutice moleculare; tratamentul de primă linie va fi stabilit în MTB.” Diagnostic anatomopatologic preliminar: adenocarcinom pulmonar fără celule mici, fără opțiune de rezecție.","context_cards":[{"title":"Urgență clinică","content":"Pacientul este simptomatic, dar stabil clinic. În decurs de 7 zile trebuie luată o decizie între tratamentul cu TKI și imunoterapie/chimioterapie.","teaching_point":"Presiunea de timp justifică testarea în paralel, nu secvențială."},{"title":"Histologie","content":"Biopsie bronșică mică cu adenocarcinom invaziv. TTF-1 și Napsin A pozitive, p40/CK5/6 negative, CK7 pozitiv. Ki-67 aproximativ 35–40%.","teaching_point":"Entitatea tumorală este suficient de bine delimitată; accentul se pune acum pe biomarkerii predictivi."},{"title":"Material tisular","content":"Aria tumorală este de aproximativ 25%, cu necroză focală. După investigațiile efectuate rămân estimate 8 lame necolorate. Calitatea ARN-ului nu este garantată, dar este încă plauzibil adecvată pentru analiză.","teaching_point":"Utilizarea responsabilă a materialului tisular face parte din decizia corectă."},{"title":"Întrebare pentru MTB","content":"Oncologia solicită explicit testarea EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS și PD-L1.","teaching_point":"Această solicitare nu susține utilizarea exclusivă a PCR pentru EGFR ca strategie unică."}],"pre_results":[{"title":"H&E","content":"Adenocarcinom pulmonar invaziv, moderat diferențiat, într-o biopsie mică."},{"title":"IHC","content":"TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; analiza PD-L1 nu a fost încă efectuată."},{"title":"QC al materialului tisular","content":"Procentul tumoral este suficient, dar limitat; testarea fuziunilor ARN nu trebuie compromisă prin analize suplimentare inutile."}],"material_or_resource_constraints":["Sunt disponibile cel mult 8 secțiuni; analizele IHC, de metilare sau HRD inutile reduc șansa de a finaliza diagnosticul molecular.","Obiectiv TAT: 7 zile calendaristice până la MTB.","ADN-ul și ARN-ul trebuie extrase, pe cât posibil, din aceeași arie tumorală marcată."],"reasoning_gate_upgrade":[{"id":"central_question","type":"single_choice","prompt":"Care este întrebarea clinică centrală?","options":[{"id":"driver_fusion_pdl1","label":"Diagnostic predictiv complet de primă linie pentru alterări driver, fuziuni și PD-L1"},{"id":"lynch","label":"Evaluare pentru sindromul Lynch"},{"id":"hrd","label":"Indicație HRD/PARP"},{"id":"infection","label":"Diagnostic infecțios"}],"correct":["driver_fusion_pdl1"],"rationale":"În adenocarcinomul pulmonar metastatic, prioritatea este testarea care determină tratamentul pentru alterări driver, fuziuni și PD-L1."},{"id":"material_risk","type":"single_choice","prompt":"Care este cel mai important risc legat de materialul tisular?","options":[{"id":"small_biopsy","label":"Biopsie mică, cu arie tumorală limitată și ARN potențial fragil"},{"id":"no_relevance","label":"Materialul tisular nu are practic nicio importanță pentru NGS"},{"id":"plasma_replaces","label":"Plasma înlocuiește întotdeauna țesutul"},{"id":"methylation_first","label":"Testarea metilării trebuie efectuată întotdeauna prima"}],"correct":["small_biopsy"],"rationale":"Investigațiile diagnostice complete trebuie prioritizate și planificate astfel încât să conserve materialul tisular."},{"id":"dna_only_limit","type":"single_choice","prompt":"De ce este riscantă utilizarea exclusivă a NGS pe ADN în acest caz?","options":[{"id":"fusion_gap","label":"Fuziunile genice relevante pot fi detectate insuficient; testarea fuziunilor ARN completează informația"},{"id":"no_mutations","label":"NGS pe ADN nu detectează mutații"},{"id":"pdl1_in_dna","label":"PD-L1 poate fi dedus în mod fiabil din ADN"},{"id":"crc_only","label":"Fuziunile sunt relevante numai în cancerul colorectal"}],"correct":["fusion_gap"],"rationale":"NGS pe ADN este performantă pentru SNV și indeluri, dar metodele bazate pe ARN reprezintă adesea completarea mai bună pentru fuziunile relevante clinic."}],"decision_task":"Alegeți o solicitare inițială de analize care conservă materialul tisular și susține în mod robust decizia de tratament de primă linie în MTB.","expected_path":["Solicitați în paralel IHC pentru PD-L1.","Panel pulmonar/pentru tumori solide bazat pe ADN pentru SNV, indeluri și CNV, incluzând EGFR, KRAS, BRAF, MET și ERBB2.","Panel de fuziuni ARN pentru ALK, ROS1, RET, NTRK și alte fuziuni relevante.","Marcați aria tumorală și evitați analizele suplimentare inutile, nerelevante pentru entitatea tumorală.","Raportați rezultatele împreună cu limitările metodei și calitatea materialului tisular."],"acceptable_alternatives":["În condiții de presiune temporală extremă, se poate adăuga un test rapid pentru EGFR, dar acesta nu înlocuiește testarea prin panel și pentru fuziuni.","IHC/FISH pentru ALK poate fi utilă ca analiză suplimentară rapidă, dar nu ca unică strategie completă."],"low_value_traps":[{"label":"Metilarea promotorului MLH1","why_bad":"Fără un context dMMR, de cancer colorectal sau Lynch, această analiză nu este relevantă pentru entitatea tumorală și consumă material tisular."},{"label":"Scor HRD","why_bad":"Nu este relevant pentru decizia inițială de tratament de primă linie în NSCLC."},{"label":"PCR pentru EGFR ca test unic","why_bad":"Poate răspunde întrebării privind EGFR, dar lasă neevaluate numeroase alterări relevante terapeutic."}],"twist":{"title":"Un rezultat negativ la analiza ADN nu înseamnă automat absența unei alterări driver","content":"Dacă sunt solicitate numai NGS pe ADN și PD-L1, rezultatul este incomplet: nu se detectează alterări EGFR/KRAS/BRAF/METex14, iar PD-L1 TPS este 5%. Fuziunea EML4::ALK este identificată numai după testarea fuziunilor ARN.","why_critical":"Alterarea care determină tratamentul ar fi fost identificată cu întârziere sau omisă dacă solicitarea inițială ar fi fost prea restrânsă."},"result_packages":[{"id":"optimal","title":"Solicitare inițială completă","result":"PD-L1 TPS 5%; panelul ADN este negativ pentru EGFR/KRAS/BRAF/METex14; panelul ARN identifică o fuziune EML4::ALK.","feedback":"Strategie foarte bună: diagnostic predictiv complet pe material tisular limitat, cu o consecință terapeutică directă."},{"id":"incomplete_dna_only","title":"NGS pe ADN și PD-L1 fără testare ARN","result":"Rezultat incomplet, fără alterare driver SNV/indel identificată și cu PD-L1 TPS 5%; statusul fuziunilor nu este evaluat adecvat.","feedback":"Direcția generală este corectă, dar investigațiile sunt incomplete. Testarea suplimentară a ARN-ului clarifică cazul, dar consumă material tisular și prelungește TAT."},{"id":"overdiagnostic","title":"Investigații suplimentare extinse, nerelevante pentru entitatea tumorală","result":"Markerii țintă necesari pot fi totuși disponibili, dar materialul tisular este consumat inutil prin analize MMR, MLH1, HRD și similare.","feedback":"Nu este o catastrofă diagnostică, dar utilizarea responsabilă a materialului tisular și comunicarea sunt clar compromise."}],"followup_logic":[{"trigger":"Lipsește testarea primară a fuziunilor ARN","action":"Oferiți suplimentar un panel de fuziuni ARN","consequence":"Rezultatul devine complet, dar se aplică un plafon de scor din cauza întârzierii evitabile."},{"trigger":"Au fost selectate teste fără legătură cu entitatea tumorală","action":"Menționați în raport ca analiză cu valoare redusă sau potențial înșelătoare","consequence":"Depunctare la Selectarea metodelor, Utilizarea responsabilă a materialului și Comunicare."}],"debrief_points":["În NSCLC metastatic, întrebarea clinică necesită o testare predictivă amplă și nu se limitează la EGFR.","Fuziunile reprezintă un motiv clasic pentru a evalua critic strategiile bazate exclusiv pe ADN.","O biopsie mică nu înseamnă mai puține analize, ci o prioritizare mai bună."],"instructor_notes":{"model_answer":"Soluție de referință: IHC pentru PD-L1, NGS pe ADN și panel de fuziuni ARN în paralel, cu mențiune privind disponibilitatea materialului tisular și comunicare clară în MTB. Testul rapid EGFR este doar o analiză suplimentară în condiții de presiune temporală.","scoring_focus":["Raționament clinic: întrebarea privind tratamentul de primă linie a fost identificată","Selectarea metodelor: ADN, ARN și PD-L1 combinate corect","Utilizarea responsabilă a materialului: au fost evitate analizele nerelevante pentru entitatea tumorală"],"discussion_questions":["Când ar fi utilă suplimentar o biopsie lichidă?","Cum trebuie comunicat mesajul „nu s-a detectat nicio alterare driver” în absența unui rezultat pentru fuziunile ARN?","Care este rolul PD-L1 atunci când a fost detectată o fuziune ALK?"]},"report_additions":["Element surpriză / punct critic de cotitură: o strategie bazată exclusiv pe ADN ar fi întârziat detectarea ALK","Erori tipice: testare exclusivă EGFR, omiterea testării ARN și consumarea materialului tisular prin analize cu valoare redusă","Traseu de referință: PD-L1, ADN și ARN în paralel"]},"payload_hash_sha256":"338c0a492896202f1de5ce4f974a1ab2683612e309229d7f675b833f4b6b2ba2"},"el":{"metadata":{"case_id":"MTB_NSCLC_001_v0_6","base_id":"MTB_NSCLC_001","title":"Πνευμονική μάζα → NSCLC → θεραπευτική απόφαση βάσει μοριακών δεδομένων","domain":"MTB","met_addon_type":"no","subdomain":"Ογκογονικές οδηγές αλλοιώσεις / NSCLC / αντοχή","case_type":"clinical_decision","length_class":"Standard","estimated_minutes":{"min":8,"max":12},"difficulty":"Intermediate","status":"curated-core","review_flag":"Έλεγχος για βασικό περιεχόμενο/MVP","review_priority":"high","core_decision":"NSCLC → θεραπευτική απόφαση βάσει μοριακών δεδομένων","learning_objectives":["Διατυπώστε το κεντρικό κλινικομοριακό ερώτημα από το ιστορικό, την ιστολογία και το πλαίσιο του ιστικού υλικού","Επιλέξτε την κατάλληλη μοριακή ή βασισμένη στην IHC μέθοδο για την κύρια απόφαση","Επικοινωνήστε με σαφήνεια την ενδεικτική λύση στο MTB, μαζί με τους περιορισμούς και τη σημασία για τον ασθενή"],"tags":["NSCLC","IHC","DNA-NGS","RNA-NGS","PD-L1","ALK","Απόθεμα ιστικού υλικού","MTB"],"ap1b_decision":"MTB· διάρκεια=τυπική· δυσκολία=ενδιάμεση· κατάσταση=curated-core"},"base_case":{"id":"MTB_NSCLC_001_v0_6","title":"Πνευμονική μάζα → NSCLC → θεραπευτική απόφαση βάσει μοριακών δεδομένων","short":"Αρχική διάγνωση NSCLC","mode":"patient_care","logic":"nsclc","difficulty":"intermediate","estimated_time_min":"8–12","budget":{"points_max":900,"sections_max":12,"tat_goal":8},"allowed_tests":["he_review","ihc_lung_lineage","ki67","pdl1","alk_ihc","egfr_pcr","kras_pcr","braf_pcr","alk_fish","ros1_fish","dna_lung_panel","rna_fusion_panel","dna_rna_lung_combo","liquid_biopsy","broad_pan_panel"],"story":[{"id":"intake","title":"Αρχικό αίτημα","items":[["Αποστέλλων ιατρός/τμήμα","Ογκολογία / βρογχοσκόπηση"],["Κλινικές πληροφορίες","Ασθενής 67 ετών με πνευμονική μάζα αριστερά και πολλαπλές μικρές ηπατικές εστίες στην αξονική τομογραφία."],["Κλινικό ερώτημα","Κακοήθεια; Πρωτοπαθής εστία; Διαγνωστικός έλεγχος που θα καθορίσει τη θεραπεία για το MTB."],["Τι παραμένει ασαφές;","Αρχικά δεν είναι ακόμη βέβαιο ότι πρόκειται πράγματι για πρωτοπαθές καρκίνωμα του πνεύμονα."]]},{"id":"history","title":"Ιατρικό ιστορικό και κλινικό πλαίσιο","items":[["Ιστορικό καπνίσματος","Πρώην καπνιστής, 15 πακετο-έτη· διακοπή καπνίσματος πριν από 20 χρόνια."],["Λειτουργική κατάσταση / κλινική κατάσταση","ECOG 1, χωρίς δυνατότητα ίασης· προγραμματίζεται άμεσα συστηματική θεραπεία."],["Προηγούμενα ευρήματα","Δεν υπάρχει γνωστό ιστορικό προηγούμενης νεοπλασίας."],["Χρονική πίεση για το MTB","Το περιστατικό πρέπει να παρουσιαστεί στο MTB σε 7 ημέρες."]]},{"id":"histo","title":"Ιστολογία και αρχική IHC","items":[["H&E","Διηθήσεις μη μικροκυτταρικού καρκινώματος σε μικρή βρογχική βιοψία."],["IHC","TTF-1 θετικό, Napsin A θετικό και CK7 θετικό· p40 και CK5/6 αρνητικά."],["Κυτταρικός πολλαπλασιασμός","Ki67 περίπου 35%."],["Προσωρινή διάγνωση","Πνευμονικό αδενοκαρκίνωμα / NSCLC, πιθανώς σταδίου IV."],["Εκκρεμεί","Εκκρεμούν η PD-L1 και το μοριακό προφίλ οδηγών αλλοιώσεων."]]},{"id":"material","title":"Αξιολόγηση ιστικού υλικού","items":[["Ιστικό υλικό","Βιοψία FFPE, κύβος B2."],["Ποσοστό νεοπλασματικών κυττάρων","Περίπου 25–30%· συνιστάται μακροδιατομή."],["Νέκρωση","Εστιακή, αλλά υπάρχουν αξιολογήσιμες νεοπλασματικές περιοχές."],["Διαθέσιμες μη χρωματισμένες τομές","Μπορούν να διατεθούν 12 τομές."],["Αναμενόμενη απόδοση DNA/RNA","Το DNA είναι πιθανώς επαρκές· το RNA μπορεί να είναι οριακό σε αυτή τη μικρή βιοψία."],["Παγίδα στη χρήση του ιστικού υλικού","Οι διαδοχικές μεμονωμένες εξετάσεις μπορεί να εξαντλήσουν το ιστικό υλικό πριν ελεγχθούν οι συντήξεις RNA."]]}],"optimal_tests":["he_review","pdl1","dna_lung_panel","rna_fusion_panel"],"acceptable_alternatives":["dna_rna_lung_combo"],"result_truth":{"driver":"Σύντηξη EML4::ALK","pdl1":"TPS 5%","dna":"Καμία hotspot αλλοίωση EGFR/KRAS/BRAF/METex14/ERBB2","qc":"DNA επαρκές· RNA περιορισμένο αλλά αξιοποιήσιμο"},"tags":["NSCLC","IHC","DNA-NGS","RNA-NGS","PD-L1","ALK","Απόθεμα ιστικού υλικού","MTB"]},"deep_dive":{"version":"v1.7b","case_id":"MTB_NSCLC_001_v0_6","title":"Μεταστατικό αδενοκαρκίνωμα πνεύμονα, μικρή βιοψία: πλήρης έλεγχος προβλεπτικών βιοδεικτών χωρίς σπατάλη ιστικού υλικού","domain":"MTB","target_course":"Βασικές αρχές MTB","deep_dive_priority":"signature","target_role":"Ειδικευόμενος/η παθολογικής ανατομικής / εισαγωγή στο MTB","estimated_minutes_deep":"12–15","learning_objectives":["Σχεδιάστε παράλληλα τον έλεγχο οδηγών αλλοιώσεων, συντήξεων και PD-L1 στο μεταστατικό NSCLC, με ορθολογική χρήση του ιστικού υλικού.","Αναγνωρίστε ότι οι στρατηγικές μόνο με DNA μπορεί να είναι ελλιπείς όταν οι συντήξεις είναι κλινικά σημαντικές.","Επικοινωνήστε με σαφήνεια στο MTB τους περιορισμούς της αναφοράς λόγω μικρής βιοψίας και περιορισμένου ποσοστού νεοπλασματικών κυττάρων."],"opening_scene":"Δευτέρα πρωί, κατά την προετοιμασία του ογκολογικού συμβουλίου: έχει παραληφθεί βρογχική βιοψία από πρόσφατα διαγνωσμένο μεταστατικό καρκίνωμα πνεύμονα. Η ογκολογική ομάδα χρειάζεται μέσα σε μία εβδομάδα να γνωρίζει αν ενδείκνυται στοχευμένη θεραπεία ή ανοσοθεραπεία. Το ιστικό υλικό είναι εμφανώς περιορισμένο, αλλά η θεραπευτική απόφαση εξαρτάται πλέον από την παθολογική ανατομική.","case_briefing":"Ασθενής 68 ετών, πρώην καπνιστής, με πολλαπλές πνευμονικές και οστικές μεταστάσεις. Κλινικό αίτημα: «Παρακαλείστε να αξιολογήσετε πιθανές μοριακά στοχεύσιμες αλλοιώσεις· η θεραπεία πρώτης γραμμής θα καθοριστεί στο MTB». Προκαταρκτική παθολογοανατομική διάγνωση: μη μικροκυτταρικό αδενοκαρκίνωμα πνεύμονα, χωρίς δυνατότητα εκτομής.","context_cards":[{"title":"Κλινική πίεση","content":"Ο ασθενής είναι συμπτωματικός αλλά κλινικά σταθερός. Εντός 7 ημερών πρέπει να ληφθεί απόφαση μεταξύ θεραπείας με TKI και ανοσοθεραπείας/χημειοθεραπείας.","teaching_point":"Η χρονική πίεση δικαιολογεί παράλληλο και όχι διαδοχικό έλεγχο."},{"title":"Ιστολογία","content":"Μικρή βρογχική βιοψία με διηθητικό αδενοκαρκίνωμα. TTF-1 και Napsin A θετικά, p40/CK5/6 αρνητικά, CK7 θετικό. Ki-67 περίπου 35–40%.","teaching_point":"Η οντότητα έχει προσδιοριστεί επαρκώς· το επόμενο βήμα αφορά τους προβλεπτικούς βιοδείκτες."},{"title":"Ιστικό υλικό","content":"Η νεοπλασματική περιοχή είναι περίπου 25%, με εστιακή νέκρωση. Μετά τον έως τώρα έλεγχο εκτιμάται ότι απομένουν 8 μη χρωματισμένες τομές. Η ποιότητα του RNA δεν είναι εγγυημένη, αλλά πιθανώς παραμένει κατάλληλη για ανάλυση.","teaching_point":"Η ορθολογική διαχείριση του ιστικού υλικού αποτελεί μέρος της σωστής απόφασης."},{"title":"Ερώτημα για το MTB","content":"Η ογκολογική ομάδα ζητά ρητά έλεγχο των EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS και PD-L1.","teaching_point":"Το αίτημα αυτό δεν υποστηρίζει τη χρήση μόνο PCR για EGFR ως μοναδικής στρατηγικής."}],"pre_results":[{"title":"H&E","content":"Διηθητικό, μέτρια διαφοροποιημένο αδενοκαρκίνωμα πνεύμονα σε μικρή βιοψία."},{"title":"IHC","content":"TTF-1+, Napsin A+, CK7+, p40−, CK5/6−· η PD-L1 δεν έχει ακόμη πραγματοποιηθεί."},{"title":"QC ιστικού υλικού","content":"Το ποσοστό νεοπλασματικών κυττάρων είναι επαρκές αλλά περιορισμένο· ο έλεγχος συντήξεων RNA δεν πρέπει να τεθεί σε κίνδυνο από περιττές πρόσθετες εξετάσεις."}],"material_or_resource_constraints":["Είναι διαθέσιμες το πολύ 8 τομές· περιττές εξετάσεις IHC, μεθυλίωσης ή HRD μειώνουν την πιθανότητα ολοκλήρωσης του μοριακού ελέγχου.","Στόχος TAT: 7 ημερολογιακές ημέρες έως το MTB.","Το DNA και το RNA θα πρέπει, εφόσον είναι δυνατόν, να εξαχθούν από την ίδια επισημασμένη νεοπλασματική περιοχή."],"reasoning_gate_upgrade":[{"id":"central_question","type":"single_choice","prompt":"Ποιο είναι το κεντρικό κλινικό ερώτημα;","options":[{"id":"driver_fusion_pdl1","label":"Πλήρης έλεγχος προβλεπτικών βιοδεικτών πρώτης γραμμής για οδηγές αλλοιώσεις, συντήξεις και PD-L1"},{"id":"lynch","label":"Διερεύνηση συνδρόμου Lynch"},{"id":"hrd","label":"Ένδειξη HRD/PARP"},{"id":"infection","label":"Λοιμωξιολογικός έλεγχος"}],"correct":["driver_fusion_pdl1"],"rationale":"Στο μεταστατικό αδενοκαρκίνωμα πνεύμονα προτεραιότητα έχει ο έλεγχος οδηγών αλλοιώσεων, συντήξεων και PD-L1 που καθορίζει τη θεραπεία."},{"id":"material_risk","type":"single_choice","prompt":"Ποιος είναι ο σημαντικότερος κίνδυνος που αφορά το ιστικό υλικό;","options":[{"id":"small_biopsy","label":"Μικρή βιοψία με περιορισμένη νεοπλασματική περιοχή και πιθανή ευθραυστότητα του RNA"},{"id":"no_relevance","label":"Το ιστικό υλικό πρακτικά δεν έχει σημασία για το NGS"},{"id":"plasma_replaces","label":"Το πλάσμα αντικαθιστά πάντα το ιστικό υλικό"},{"id":"methylation_first","label":"Ο έλεγχος μεθυλίωσης πρέπει να γίνεται πάντα πρώτος"}],"correct":["small_biopsy"],"rationale":"Ο πλήρης διαγνωστικός έλεγχος πρέπει να ιεραρχείται και να σχεδιάζεται με τρόπο που να διαφυλάσσει το ιστικό υλικό."},{"id":"dna_only_limit","type":"single_choice","prompt":"Γιατί είναι επικίνδυνη η χρήση μόνο DNA-NGS σε αυτό το περιστατικό;","options":[{"id":"fusion_gap","label":"Σημαντικές γονιδιακές συντήξεις μπορεί να ανιχνευθούν ανεπαρκώς· ο έλεγχος συντήξεων RNA συμπληρώνει την πληροφορία"},{"id":"no_mutations","label":"Το DNA-NGS δεν ανιχνεύει μεταλλάξεις"},{"id":"pdl1_in_dna","label":"Η PD-L1 μπορεί να εξαχθεί αξιόπιστα από το DNA"},{"id":"crc_only","label":"Οι συντήξεις είναι σημαντικές μόνο στον καρκίνο του παχέος εντέρου"}],"correct":["fusion_gap"],"rationale":"Το DNA-NGS αποδίδει καλά για SNV και indels, αλλά οι μέθοδοι που βασίζονται στο RNA αποτελούν συχνά την καλύτερη συμπλήρωση για κλινικά σημαντικές συντήξεις."}],"decision_task":"Επιλέξτε ένα αρχικό αίτημα εξετάσεων που διαφυλάσσει το ιστικό υλικό και υποστηρίζει αξιόπιστα την απόφαση θεραπείας πρώτης γραμμής στο MTB.","expected_path":["Ζητήστε παράλληλα IHC για PD-L1.","Πάνελ πνεύμονα/συμπαγών όγκων βασισμένο σε DNA για SNV, indels και CNV, συμπεριλαμβανομένων EGFR, KRAS, BRAF, MET και ERBB2.","Πάνελ συντήξεων RNA για ALK, ROS1, RET, NTRK και άλλες σημαντικές συντήξεις.","Επισημάνετε τη νεοπλασματική περιοχή και αποφύγετε περιττές πρόσθετες εξετάσεις άσχετες με την οντότητα.","Αναφέρετε τα ευρήματα μαζί με τους περιορισμούς της μεθόδου και την ποιότητα του ιστικού υλικού."],"acceptable_alternatives":["Σε συνθήκες ακραίας χρονικής πίεσης μπορεί να προστεθεί ταχεία εξέταση EGFR, αλλά δεν αντικαθιστά τον έλεγχο με πάνελ και συντήξεων.","Η IHC/FISH για ALK μπορεί να είναι χρήσιμη ως ταχεία συμπληρωματική εξέταση, αλλά όχι ως μοναδική ολοκληρωμένη στρατηγική."],"low_value_traps":[{"label":"Μεθυλίωση του υποκινητή MLH1","why_bad":"Χωρίς πλαίσιο dMMR, καρκίνου παχέος εντέρου ή Lynch, η εξέταση είναι άσχετη με την οντότητα και καταναλώνει ιστικό υλικό."},{"label":"Βαθμολογία HRD","why_bad":"Δεν είναι χρήσιμο για την αρχική απόφαση θεραπείας πρώτης γραμμής στο NSCLC."},{"label":"Μόνο PCR για EGFR","why_bad":"Μπορεί να απαντήσει στο ερώτημα του EGFR, αλλά αφήνει πολλές θεραπευτικά σημαντικές αλλοιώσεις χωρίς αξιολόγηση."}],"twist":{"title":"Αρνητικό αποτέλεσμα στο DNA δεν σημαίνει αυτομάτως απουσία οδηγού αλλοίωσης","content":"Εάν ζητηθούν μόνο DNA-NGS και PD-L1, το αποτέλεσμα είναι ελλιπές: δεν ανιχνεύεται αλλοίωση EGFR/KRAS/BRAF/METex14 και η PD-L1 TPS είναι 5%. Η σύντηξη EML4::ALK ανιχνεύεται μόνο μετά από έλεγχο συντήξεων RNA.","why_critical":"Η αλλοίωση που καθορίζει τη θεραπεία θα είχε καθυστερήσει ή χαθεί με ένα υπερβολικά περιορισμένο αρχικό αίτημα."},"result_packages":[{"id":"optimal","title":"Πλήρες αρχικό αίτημα εξετάσεων","result":"PD-L1 TPS 5%· το πάνελ DNA είναι αρνητικό για EGFR/KRAS/BRAF/METex14· το πάνελ RNA ανιχνεύει σύντηξη EML4::ALK.","feedback":"Πολύ καλή στρατηγική: πλήρης προβλεπτικός έλεγχος σε περιορισμένο ιστικό υλικό, με άμεση θεραπευτική συνέπεια."},{"id":"incomplete_dna_only","title":"DNA-NGS και PD-L1 χωρίς έλεγχο RNA","result":"Ελλιπές αποτέλεσμα χωρίς ανίχνευση οδηγού SNV/indel και με PD-L1 TPS 5%· η κατάσταση των συντήξεων δεν έχει αξιολογηθεί επαρκώς.","feedback":"Η γενική κατεύθυνση είναι σωστή, αλλά ο έλεγχος είναι ελλιπής. Ο συμπληρωματικός έλεγχος RNA επιλύει το περιστατικό, αλλά κοστίζει ιστικό υλικό και TAT."},{"id":"overdiagnostic","title":"Εκτεταμένες πρόσθετες εξετάσεις άσχετες με την οντότητα","result":"Οι απαιτούμενοι στόχοι μπορεί τελικά να είναι διαθέσιμοι, αλλά καταναλώνεται άσκοπα ιστικό υλικό από εξετάσεις MMR, MLH1, HRD κ.ά.","feedback":"Δεν αποτελεί διαγνωστική καταστροφή, αλλά η ορθολογική διαχείριση του ιστικού υλικού και η επικοινωνία επηρεάζονται σαφώς."}],"followup_logic":[{"trigger":"Λείπει ο αρχικός έλεγχος συντήξεων RNA","action":"Προτείνετε συμπληρωματικό πάνελ συντήξεων RNA","consequence":"Το αποτέλεσμα ολοκληρώνεται, αλλά εφαρμόζεται ανώτατο όριο βαθμολογίας λόγω της αποτρέψιμης καθυστέρησης."},{"trigger":"Επιλέχθηκαν εξετάσεις που δεν σχετίζονται με την οντότητα του όγκου","action":"Χαρακτηρίστε στην αναφορά ως χαμηλής αξίας ή παραπλανητικό","consequence":"Αφαίρεση βαθμών στην Επιλογή μεθόδων, την Ορθολογική χρήση υλικού και την Επικοινωνία."}],"debrief_points":["Στο μεταστατικό NSCLC, το κλινικό ερώτημα απαιτεί ευρύ προβλεπτικό έλεγχο και δεν περιορίζεται στο EGFR.","Οι συντήξεις αποτελούν κλασικό λόγο για κριτική αξιολόγηση στρατηγικών μόνο με DNA.","Μικρή βιοψία δεν σημαίνει λιγότερες εξετάσεις, αλλά καλύτερη ιεράρχηση."],"instructor_notes":{"model_answer":"Ενδεικτική λύση: IHC για PD-L1, DNA-NGS και πάνελ συντήξεων RNA παράλληλα, με αναφορά στη διαθεσιμότητα ιστικού υλικού και σαφή επικοινωνία στο MTB. Η ταχεία εξέταση EGFR αποτελεί μόνο συμπληρωματική επιλογή όταν υπάρχει χρονική πίεση.","scoring_focus":["Κλινικός συλλογισμός: αναγνωρίστηκε το ερώτημα θεραπείας πρώτης γραμμής","Επιλογή μεθόδων: σωστός συνδυασμός DNA, RNA και PD-L1","Ορθολογική χρήση υλικού: αποφεύχθηκαν εξετάσεις άσχετες με την οντότητα"],"discussion_questions":["Πότε θα ήταν χρήσιμη μια συμπληρωματική υγρή βιοψία;","Πώς πρέπει να επικοινωνείται το «δεν ανιχνεύθηκε οδηγός αλλοίωση» όταν δεν υπάρχει αποτέλεσμα ελέγχου συντήξεων RNA;","Ποιος είναι ο ρόλος της PD-L1 όταν έχει ανιχνευθεί σύντηξη ALK;"]},"report_additions":["Ανατροπή / κρίσιμο σημείο καμπής: μια στρατηγική μόνο με DNA θα καθυστερούσε την ανίχνευση ALK","Τυπικά σφάλματα: έλεγχος μόνο EGFR, παράλειψη ελέγχου RNA και κατανάλωση ιστικού υλικού από εξετάσεις χαμηλής αξίας","Ενδεικτική διαδρομή: PD-L1, DNA και RNA παράλληλα"]},"payload_hash_sha256":"0ef426207f27d956948de6f4909235073ee39c81314be4a68c669d044d5c93c6"},"es":{"metadata":{"case_id":"MTB_NSCLC_001_v0_6","base_id":"MTB_NSCLC_001","title":"Masa pulmonar → NSCLC → decisión terapéutica basada en datos moleculares","domain":"MTB","met_addon_type":"no","subdomain":"Alteraciones oncogénicas driver / NSCLC / resistencia","case_type":"clinical_decision","length_class":"Standard","estimated_minutes":{"min":8,"max":12},"difficulty":"Intermediate","status":"curated-core","review_flag":"Revisar para contenido central/MVP","review_priority":"high","core_decision":"NSCLC → decisión terapéutica basada en datos moleculares","learning_objectives":["Deducir la pregunta clínico-molecular central a partir de la anamnesis, la histología y el contexto del tejido","Seleccionar el método molecular o basado en IHC adecuado para la decisión principal","Comunicar con claridad la solución de referencia en el MTB, incluidas las limitaciones y la relevancia para el paciente"],"tags":["NSCLC","IHC","NGS de ADN","NGS de ARN","PD-L1","ALK","Reserva de tejido","MTB"],"ap1b_decision":"MTB; duración=estándar; dificultad=intermedia; estado=curated-core"},"base_case":{"id":"MTB_NSCLC_001_v0_6","title":"Masa pulmonar → NSCLC → decisión terapéutica basada en datos moleculares","short":"Diagnóstico inicial de NSCLC","mode":"patient_care","logic":"nsclc","difficulty":"intermediate","estimated_time_min":"8–12","budget":{"points_max":900,"sections_max":12,"tat_goal":8},"allowed_tests":["he_review","ihc_lung_lineage","ki67","pdl1","alk_ihc","egfr_pcr","kras_pcr","braf_pcr","alk_fish","ros1_fish","dna_lung_panel","rna_fusion_panel","dna_rna_lung_combo","liquid_biopsy","broad_pan_panel"],"story":[{"id":"intake","title":"Solicitud inicial","items":[["Solicitante","Oncología / broncoscopia"],["Información clínica","Paciente de 67 años con masa pulmonar izquierda y múltiples lesiones hepáticas pequeñas en la TC."],["Pregunta clínica","¿Malignidad? ¿Tumor primario? Diagnóstico determinante para el tratamiento en el MTB."],["¿Qué sigue sin estar claro?","Al inicio todavía no está claro que se trate realmente de un carcinoma pulmonar primario."]]},{"id":"history","title":"Anamnesis y contexto clínico","items":[["Antecedentes de tabaquismo","Exfumador, 15 paquetes-año; dejó de fumar hace 20 años."],["Estado funcional / situación clínica","ECOG 1, sin opción curativa; se prevé iniciar pronto tratamiento sistémico."],["Resultados previos","No se conoce ninguna neoplasia previa."],["Presión de tiempo para el MTB","El caso debe presentarse en el MTB dentro de 7 días."]]},{"id":"histo","title":"Histología e IHC inicial","items":[["H&E","Infiltrados de carcinoma no microcítico en una biopsia bronquial pequeña."],["IHC","TTF-1 positivo, Napsina A positiva y CK7 positivo; p40 y CK5/6 negativos."],["Proliferación","Ki67 aproximadamente 35%."],["Diagnóstico de trabajo","Adenocarcinoma pulmonar / NSCLC, probablemente estadio IV."],["Pendiente","Faltan PD-L1 y el perfil molecular de alteraciones driver."]]},{"id":"material","title":"Evaluación del tejido","items":[["Tejido","Biopsia FFPE, bloque B2."],["Porcentaje tumoral","Aproximadamente 25–30%; se recomienda macrodissección."],["Necrosis","Focal, pero existen áreas tumorales evaluables."],["Cortes sin teñir disponibles","Se pueden asignar 12 cortes."],["Previsión de rendimiento de ADN/ARN","El ADN probablemente sea suficiente; el ARN puede ser limitado en esta biopsia pequeña."],["Riesgo de agotamiento del tejido","Las pruebas individuales secuenciales pueden agotar el tejido antes de evaluar las fusiones de ARN."]]}],"optimal_tests":["he_review","pdl1","dna_lung_panel","rna_fusion_panel"],"acceptable_alternatives":["dna_rna_lung_combo"],"result_truth":{"driver":"Fusión EML4::ALK","pdl1":"TPS 5%","dna":"Sin alteraciones hotspot en EGFR/KRAS/BRAF/METex14/ERBB2","qc":"ADN suficiente; ARN limitado pero analizable"},"tags":["NSCLC","IHC","NGS de ADN","NGS de ARN","PD-L1","ALK","Reserva de tejido","MTB"]},"deep_dive":{"version":"v1.7b","case_id":"MTB_NSCLC_001_v0_6","title":"Adenocarcinoma pulmonar metastásico, biopsia pequeña: diagnóstico predictivo completo sin desperdiciar tejido","domain":"MTB","target_course":"Fundamentos del MTB","deep_dive_priority":"signature","target_role":"Residente de anatomía patológica / introducción al MTB","estimated_minutes_deep":"12–15","learning_objectives":["Planificar en paralelo el estudio de alteraciones driver, fusiones y PD-L1 en el NSCLC metastásico, preservando el tejido.","Reconocer que las estrategias basadas solo en ADN pueden ser incompletas cuando las fusiones son clínicamente relevantes.","Comunicar claramente en el MTB las limitaciones del informe derivadas de una biopsia pequeña y un porcentaje tumoral limitado."],"opening_scene":"Lunes por la mañana, preparando el comité de tumores: se dispone de una biopsia bronquial de un carcinoma pulmonar metastásico recién diagnosticado. Oncología necesita saber en una semana si procede una terapia dirigida o inmunoterapia. El tejido es claramente limitado, pero la decisión terapéutica depende ahora de anatomía patológica.","case_briefing":"Paciente de 68 años, exfumador, con múltiples metástasis pulmonares y óseas. Solicitud clínica: «Valorar opciones terapéuticas moleculares; el tratamiento de primera línea se decidirá en el MTB». Diagnóstico anatomopatológico preliminar: adenocarcinoma pulmonar no microcítico, sin opción de resección.","context_cards":[{"title":"Urgencia clínica","content":"El paciente presenta síntomas, pero está clínicamente estable. En 7 días debe tomarse una decisión entre tratamiento con TKI e inmunoterapia/quimioterapia.","teaching_point":"La presión de tiempo justifica realizar las pruebas en paralelo y no de forma secuencial."},{"title":"Histología","content":"Biopsia bronquial pequeña con adenocarcinoma invasivo. TTF-1 y Napsina A positivos, p40/CK5/6 negativos, CK7 positivo. Ki-67 aproximadamente 35–40%.","teaching_point":"La entidad tumoral está suficientemente definida; ahora el objetivo son los biomarcadores predictivos."},{"title":"Tejido","content":"Área tumoral aproximada del 25%, con necrosis focal. Tras el estudio realizado se estima que quedan 8 portaobjetos sin teñir. La calidad del ARN no está garantizada, pero todavía puede ser adecuada para el análisis.","teaching_point":"La gestión responsable del tejido forma parte de la decisión correcta."},{"title":"Pregunta para el MTB","content":"Oncología solicita expresamente el estudio de EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS y PD-L1.","teaching_point":"Esta solicitud desaconseja utilizar únicamente una PCR de EGFR como estrategia exclusiva."}],"pre_results":[{"title":"H&E","content":"Adenocarcinoma pulmonar invasivo, moderadamente diferenciado, en una biopsia pequeña."},{"title":"IHC","content":"TTF-1+, Napsina A+, CK7+, p40−, CK5/6−; el estudio de PD-L1 aún no se ha realizado."},{"title":"QC del tejido","content":"El porcentaje tumoral es suficiente, pero limitado; el estudio de fusiones de ARN no debe verse comprometido por pruebas adicionales innecesarias."}],"material_or_resource_constraints":["Hay un máximo de 8 cortes disponibles; las pruebas innecesarias de IHC, metilación o HRD reducen la posibilidad de completar el estudio molecular.","Objetivo de TAT: 7 días naturales hasta el MTB.","El ADN y el ARN deben extraerse, siempre que sea posible, de la misma área tumoral marcada."],"reasoning_gate_upgrade":[{"id":"central_question","type":"single_choice","prompt":"¿Cuál es la pregunta clínica central?","options":[{"id":"driver_fusion_pdl1","label":"Diagnóstico predictivo completo de primera línea de alteraciones driver, fusiones y PD-L1"},{"id":"lynch","label":"Estudio del síndrome de Lynch"},{"id":"hrd","label":"Indicación de HRD/PARP"},{"id":"infection","label":"Diagnóstico de infección"}],"correct":["driver_fusion_pdl1"],"rationale":"En el adenocarcinoma pulmonar metastásico, la prioridad es el estudio determinante para el tratamiento de alteraciones driver, fusiones y PD-L1."},{"id":"material_risk","type":"single_choice","prompt":"¿Cuál es el principal riesgo relacionado con el tejido?","options":[{"id":"small_biopsy","label":"Biopsia pequeña con área tumoral limitada y ARN potencialmente frágil"},{"id":"no_relevance","label":"El tejido apenas tiene importancia para el NGS"},{"id":"plasma_replaces","label":"El plasma sustituye siempre al tejido"},{"id":"methylation_first","label":"El estudio de metilación debe realizarse siempre primero"}],"correct":["small_biopsy"],"rationale":"El estudio diagnóstico completo debe priorizarse y planificarse para preservar el tejido."},{"id":"dna_only_limit","type":"single_choice","prompt":"¿Por qué es arriesgado utilizar solo NGS de ADN en este caso?","options":[{"id":"fusion_gap","label":"Las fusiones génicas relevantes pueden detectarse de forma insuficiente; el estudio de fusiones de ARN aporta información complementaria"},{"id":"no_mutations","label":"La NGS de ADN no detecta mutaciones"},{"id":"pdl1_in_dna","label":"PD-L1 puede inferirse de forma fiable a partir del ADN"},{"id":"crc_only","label":"Las fusiones solo son relevantes en el cáncer colorrectal"}],"correct":["fusion_gap"],"rationale":"La NGS de ADN funciona bien para SNV e indels, pero los métodos basados en ARN suelen ser el mejor complemento para las fusiones clínicamente relevantes."}],"decision_task":"Elija una solicitud inicial de pruebas que preserve el tejido y sustente de forma sólida la decisión de tratamiento de primera línea en el MTB.","expected_path":["Solicitar en paralelo IHC de PD-L1.","Panel pulmonar/de tumores sólidos basado en ADN para SNV, indels y CNV, incluidos EGFR, KRAS, BRAF, MET y ERBB2.","Panel de fusiones de ARN para ALK, ROS1, RET, NTRK y otras fusiones relevantes.","Marcar el área tumoral y evitar pruebas adicionales innecesarias ajenas a la entidad tumoral.","Informar los resultados junto con las limitaciones del método y la calidad del tejido."],"acceptable_alternatives":["Con una presión de tiempo extrema puede añadirse una prueba rápida de EGFR, pero no sustituye el estudio mediante panel y de fusiones.","La IHC/FISH de ALK puede ser útil como complemento rápido, pero no como única estrategia integral."],"low_value_traps":[{"label":"Metilación del promotor de MLH1","why_bad":"Sin un contexto de dMMR, cáncer colorrectal o Lynch, esta prueba no guarda relación con la entidad y consume tejido."},{"label":"Puntuación HRD","why_bad":"No es pertinente para la decisión inicial de primera línea en NSCLC."},{"label":"PCR de EGFR como única prueba","why_bad":"Puede responder a la pregunta sobre EGFR, pero deja sin evaluar muchas alteraciones relevantes para el tratamiento."}],"twist":{"title":"Un resultado negativo en ADN no significa automáticamente ausencia de una alteración driver","content":"Si solo se solicitan NGS de ADN y PD-L1, el resultado es incompleto: no se detectan alteraciones en EGFR/KRAS/BRAF/METex14 y el TPS de PD-L1 es del 5%. La fusión EML4::ALK solo se identifica al realizar el estudio de fusiones de ARN.","why_critical":"La alteración determinante para el tratamiento se habría detectado tarde o se habría pasado por alto con una solicitud inicial demasiado limitada."},"result_packages":[{"id":"optimal","title":"Solicitud inicial completa","result":"TPS de PD-L1 del 5%; panel de ADN negativo para EGFR/KRAS/BRAF/METex14; panel de ARN con fusión EML4::ALK.","feedback":"Muy buena estrategia: diagnóstico predictivo completo con tejido limitado y una consecuencia terapéutica directa."},{"id":"incomplete_dna_only","title":"NGS de ADN y PD-L1 sin estudio de ARN","result":"Resultado incompleto, sin alteración driver SNV/indel identificada y con TPS de PD-L1 del 5%; el estado de las fusiones no se ha evaluado adecuadamente.","feedback":"La orientación general es correcta, pero el estudio está incompleto. La prueba adicional de ARN resuelve el caso, pero consume tejido y aumenta el TAT."},{"id":"overdiagnostic","title":"Pruebas adicionales amplias ajenas a la entidad tumoral","result":"Los marcadores objetivo necesarios pueden llegar a estar disponibles, pero se consume tejido de forma innecesaria con pruebas de MMR, MLH1, HRD, etc.","feedback":"No es un desastre diagnóstico, pero la gestión responsable del tejido y la comunicación se ven claramente perjudicadas."}],"followup_logic":[{"trigger":"Falta el estudio primario de fusiones de ARN","action":"Ofrecer un panel adicional de fusiones de ARN","consequence":"El resultado queda completo, pero se aplica un límite de puntuación por el retraso evitable."},{"trigger":"Se seleccionaron pruebas no pertinentes para la entidad tumoral","action":"Indicar en el informe que se trata de una prueba de bajo valor o potencialmente engañosa","consequence":"Penalización en Selección de métodos, Uso responsable del material y Comunicación."}],"debrief_points":["En el NSCLC metastásico, la pregunta clínica requiere un estudio predictivo amplio y no se limita a EGFR.","Las fusiones son un motivo clásico para cuestionar críticamente las estrategias basadas solo en ADN.","Una biopsia pequeña no significa menos pruebas, sino una mejor priorización."],"instructor_notes":{"model_answer":"Solución de referencia: IHC de PD-L1, NGS de ADN y panel de fusiones de ARN en paralelo, con una nota sobre la disponibilidad de tejido y una comunicación clara en el MTB. La prueba rápida de EGFR es solo un complemento cuando existe presión de tiempo.","scoring_focus":["Razonamiento clínico: se identificó la pregunta sobre el tratamiento de primera línea","Selección de métodos: combinación correcta de ADN, ARN y PD-L1","Uso responsable del material: se evitaron pruebas ajenas a la entidad tumoral"],"discussion_questions":["¿Cuándo sería útil añadir una biopsia líquida?","¿Cómo debe comunicarse «no se ha detectado ninguna alteración driver» si no se dispone del resultado de fusiones de ARN?","¿Qué papel desempeña PD-L1 cuando se ha detectado una fusión de ALK?"]},"report_additions":["Giro / punto de inflexión crítico: una estrategia basada solo en ADN habría retrasado la detección de ALK","Errores típicos: estudio exclusivo de EGFR, olvido del análisis de ARN y consumo de tejido por pruebas de bajo valor","Ruta de referencia: PD-L1, ADN y ARN en paralelo"]},"payload_hash_sha256":"28d1c670e45cc039d2708a1bce83dcf4dbcfcb7e01a8ce8f9a8fd514228601f8"},"fr":{"metadata":{"case_id":"MTB_NSCLC_001_v0_6","base_id":"MTB_NSCLC_001","title":"Masse pulmonaire → NSCLC → décision thérapeutique guidée par les données moléculaires","domain":"MTB","met_addon_type":"no","subdomain":"Altérations oncogéniques conductrices / NSCLC / résistance","case_type":"clinical_decision","length_class":"Standard","estimated_minutes":{"min":8,"max":12},"difficulty":"Intermediate","status":"curated-core","review_flag":"À vérifier pour le contenu principal/MVP","review_priority":"high","core_decision":"NSCLC → décision thérapeutique guidée par les données moléculaires","learning_objectives":["Dégager la question clinico-moléculaire centrale à partir de l’anamnèse, de l’histologie et du contexte tissulaire","Sélectionner la méthode moléculaire ou fondée sur l’IHC adaptée à la décision centrale","Communiquer clairement la solution de référence en MTB, avec ses limites et sa pertinence pour le patient"],"tags":["NSCLC","IHC","NGS ADN","NGS ARN","PD-L1","ALK","Capital tissulaire","MTB"],"ap1b_decision":"MTB ; durée=standard ; difficulté=intermédiaire ; statut=curated-core"},"base_case":{"id":"MTB_NSCLC_001_v0_6","title":"Masse pulmonaire → NSCLC → décision thérapeutique guidée par les données moléculaires","short":"Diagnostic initial de NSCLC","mode":"patient_care","logic":"nsclc","difficulty":"intermediate","estimated_time_min":"8–12","budget":{"points_max":900,"sections_max":12,"tat_goal":8},"allowed_tests":["he_review","ihc_lung_lineage","ki67","pdl1","alk_ihc","egfr_pcr","kras_pcr","braf_pcr","alk_fish","ros1_fish","dna_lung_panel","rna_fusion_panel","dna_rna_lung_combo","liquid_biopsy","broad_pan_panel"],"story":[{"id":"intake","title":"Demande initiale","items":[["Prescripteur","Oncologie / bronchoscopie"],["Informations cliniques","Patient de 67 ans présentant une masse pulmonaire gauche et de multiples petites lésions hépatiques au scanner."],["Question clinique","Malignité ? Site primitif ? Bilan diagnostique déterminant pour le traitement en MTB."],["Que reste-t-il à clarifier ?","Au départ, il n’est pas encore certain qu’il s’agisse réellement d’un carcinome pulmonaire primitif."]]},{"id":"history","title":"Anamnèse et contexte clinique","items":[["Statut tabagique","Ancien fumeur, 15 paquets-années ; sevré depuis 20 ans."],["Indice de performance / situation clinique","ECOG 1, aucune option curative ; un traitement systémique est prévu rapidement."],["Résultats antérieurs","Aucun antécédent de cancer n’est connu."],["Contrainte de délai pour le MTB","Le cas doit être présenté en MTB dans 7 jours."]]},{"id":"histo","title":"Histologie et IHC initiale","items":[["H&E","Infiltrats d’un carcinome non à petites cellules dans une petite biopsie bronchique."],["IHC","TTF-1 positif, Napsine A positive et CK7 positif ; p40 et CK5/6 négatifs."],["Prolifération","Ki67 d’environ 35 %."],["Diagnostic de travail","Adénocarcinome pulmonaire / NSCLC, probablement de stade IV."],["À compléter","L’analyse de PD-L1 et le profil moléculaire des altérations conductrices restent à réaliser."]]},{"id":"material","title":"Évaluation du matériel tissulaire","items":[["Matériel tissulaire","Biopsie FFPE, bloc B2."],["Cellularité tumorale","Environ 25–30 % ; macrodissection recommandée."],["Nécrose","Focale, mais des zones tumorales évaluables sont présentes."],["Coupes non colorées disponibles","12 coupes peuvent être prévues."],["Rendement attendu en ADN/ARN","L’ADN est probablement suffisant ; l’ARN peut être limite dans cette petite biopsie."],["Piège lié à l’utilisation du tissu","Des tests unitaires séquentiels peuvent épuiser le tissu avant l’évaluation des fusions d’ARN."]]}],"optimal_tests":["he_review","pdl1","dna_lung_panel","rna_fusion_panel"],"acceptable_alternatives":["dna_rna_lung_combo"],"result_truth":{"driver":"Fusion EML4::ALK","pdl1":"TPS 5 %","dna":"Aucune altération hotspot d’EGFR/KRAS/BRAF/METex14/ERBB2","qc":"ADN suffisant ; ARN limité mais exploitable"},"tags":["NSCLC","IHC","NGS ADN","NGS ARN","PD-L1","ALK","Capital tissulaire","MTB"]},"deep_dive":{"version":"v1.7b","case_id":"MTB_NSCLC_001_v0_6","title":"Adénocarcinome pulmonaire métastatique, petite biopsie : bilan prédictif complet sans gaspillage tissulaire","domain":"MTB","target_course":"Bases du MTB","deep_dive_priority":"signature","target_role":"Interne en anatomopathologie / initiation au MTB","estimated_minutes_deep":"12–15","learning_objectives":["Planifier en parallèle l’analyse des altérations conductrices, des fusions et de PD-L1 dans le NSCLC métastatique, en préservant le tissu.","Reconnaître qu’une stratégie fondée uniquement sur l’ADN peut être incomplète lorsque les fusions sont cliniquement pertinentes.","Communiquer clairement en MTB les limites du compte rendu liées à la petite biopsie et à la faible cellularité tumorale."],"opening_scene":"Lundi matin, préparation de la réunion de concertation : une biopsie bronchique d’un carcinome pulmonaire métastatique récemment diagnostiqué est disponible. L’oncologie souhaite savoir dans un délai d’une semaine si une thérapie ciblée ou une immunothérapie est envisageable. Le matériel tissulaire est manifestement limité, mais la décision thérapeutique dépend désormais de l’anatomopathologie.","case_briefing":"Patient de 68 ans, ancien fumeur, présentant de multiples métastases pulmonaires et osseuses. Demande clinique : « Évaluer les altérations moléculaires potentiellement ciblables ; le traitement de première ligne sera défini en MTB. » Diagnostic anatomopathologique préliminaire : adénocarcinome pulmonaire non à petites cellules, non résécable.","context_cards":[{"title":"Urgence clinique","content":"Le patient est symptomatique mais cliniquement stable. Une décision entre un traitement par TKI et une immunothérapie/chimiothérapie doit être prise dans les 7 jours.","teaching_point":"La contrainte de délai justifie des analyses parallèles plutôt que séquentielles."},{"title":"Histologie","content":"Petite biopsie bronchique montrant un adénocarcinome invasif. TTF-1 et Napsine A positifs, p40/CK5/6 négatifs, CK7 positif. Ki-67 d’environ 35–40 %.","teaching_point":"L’entité tumorale est suffisamment caractérisée ; l’enjeu porte désormais sur les biomarqueurs prédictifs."},{"title":"Matériel tissulaire","content":"Zone tumorale d’environ 25 %, avec nécrose focale. Après le bilan déjà réalisé, il resterait environ 8 lames non colorées. La qualité de l’ARN n’est pas garantie, mais elle reste vraisemblablement compatible avec une analyse.","teaching_point":"La gestion responsable du tissu fait partie de la bonne décision."},{"title":"Question pour le MTB","content":"L’oncologie demande explicitement l’analyse d’EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS et de PD-L1.","teaching_point":"Cette demande va à l’encontre d’une stratégie reposant uniquement sur une PCR EGFR."}],"pre_results":[{"title":"H&E","content":"Adénocarcinome pulmonaire invasif, moyennement différencié, sur petite biopsie."},{"title":"IHC","content":"TTF-1+, Napsine A+, CK7+, p40−, CK5/6− ; l’analyse de PD-L1 n’a pas encore été réalisée."},{"title":"CQ du matériel tissulaire","content":"La cellularité tumorale est suffisante mais limitée ; l’analyse des fusions d’ARN ne doit pas être compromise par des examens complémentaires inutiles."}],"material_or_resource_constraints":["Au maximum 8 coupes sont disponibles ; des analyses IHC, de méthylation ou HRD inutiles réduisent la probabilité de mener à terme le bilan moléculaire.","Objectif de TAT : 7 jours calendaires avant le MTB.","L’ADN et l’ARN doivent, dans la mesure du possible, être extraits de la même zone tumorale repérée."],"reasoning_gate_upgrade":[{"id":"central_question","type":"single_choice","prompt":"Quelle est la question clinique centrale ?","options":[{"id":"driver_fusion_pdl1","label":"Bilan prédictif complet de première ligne portant sur les altérations conductrices, les fusions et PD-L1"},{"id":"lynch","label":"Exploration d’un syndrome de Lynch"},{"id":"hrd","label":"Indication HRD/PARP"},{"id":"infection","label":"Diagnostic infectieux"}],"correct":["driver_fusion_pdl1"],"rationale":"Dans l’adénocarcinome pulmonaire métastatique, la priorité est le bilan des altérations conductrices, des fusions et de PD-L1 qui détermine le traitement."},{"id":"material_risk","type":"single_choice","prompt":"Quel est le principal risque lié au matériel tissulaire ?","options":[{"id":"small_biopsy","label":"Petite biopsie avec zone tumorale limitée et ARN potentiellement fragile"},{"id":"no_relevance","label":"La disponibilité du tissu n’a pratiquement aucune importance pour le NGS"},{"id":"plasma_replaces","label":"Le plasma remplace systématiquement le tissu"},{"id":"methylation_first","label":"L’analyse de la méthylation doit toujours être réalisée en premier"}],"correct":["small_biopsy"],"rationale":"Le bilan diagnostique complet doit être hiérarchisé et planifié de manière à préserver le tissu."},{"id":"dna_only_limit","type":"single_choice","prompt":"Pourquoi une analyse NGS de l’ADN seule est-elle risquée dans ce cas ?","options":[{"id":"fusion_gap","label":"Des fusions géniques pertinentes peuvent être insuffisamment détectées ; l’analyse des fusions d’ARN complète l’information"},{"id":"no_mutations","label":"Le NGS de l’ADN ne détecte pas les mutations"},{"id":"pdl1_in_dna","label":"PD-L1 peut être déduit de manière fiable à partir de l’ADN"},{"id":"crc_only","label":"Les fusions ne sont pertinentes que dans le cancer colorectal"}],"correct":["fusion_gap"],"rationale":"Le NGS de l’ADN est performant pour les SNV et les indels, mais les méthodes fondées sur l’ARN constituent souvent le meilleur complément pour les fusions cliniquement pertinentes."}],"decision_task":"Choisissez une demande initiale d’analyses qui préserve le tissu et étaye solidement la décision de traitement de première ligne en MTB.","expected_path":["Demander en parallèle une IHC PD-L1.","Panel pulmonaire/tumeurs solides fondé sur l’ADN pour les SNV, les indels et les CNV, comprenant EGFR, KRAS, BRAF, MET et ERBB2.","Panel de fusions d’ARN pour ALK, ROS1, RET, NTRK et d’autres fusions pertinentes.","Repérer la zone tumorale et éviter les examens complémentaires inutiles sans rapport avec l’entité tumorale.","Rendre les résultats en précisant les limites de la méthode et la qualité du matériel tissulaire."],"acceptable_alternatives":["En cas de contrainte de délai extrême, un test rapide EGFR peut être ajouté, mais il ne remplace pas le panel ni l’analyse des fusions.","L’IHC/FISH ALK peut être utile comme complément rapide, mais pas comme stratégie exhaustive unique."],"low_value_traps":[{"label":"Méthylation du promoteur de MLH1","why_bad":"En l’absence de contexte dMMR, colorectal ou Lynch, cet examen est sans rapport avec l’entité tumorale et consomme du tissu."},{"label":"Score HRD","why_bad":"Non pertinent pour la décision initiale de traitement de première ligne dans le NSCLC."},{"label":"PCR EGFR seule","why_bad":"Elle peut répondre à la question d’EGFR, mais laisse de nombreuses altérations pertinentes pour le traitement non évaluées."}],"twist":{"title":"Un résultat négatif sur l’ADN ne signifie pas automatiquement l’absence d’altération conductrice","content":"Si seuls le NGS de l’ADN et PD-L1 sont demandés, le résultat est incomplet : aucune altération d’EGFR/KRAS/BRAF/METex14 n’est détectée et le TPS de PD-L1 est de 5 %. La fusion EML4::ALK n’est identifiée qu’après analyse des fusions d’ARN.","why_critical":"L’altération déterminante pour le traitement aurait été retardée ou manquée avec une demande initiale trop restreinte."},"result_packages":[{"id":"optimal","title":"Demande initiale complète","result":"TPS de PD-L1 à 5 % ; panel ADN négatif pour EGFR/KRAS/BRAF/METex14 ; panel ARN mettant en évidence une fusion EML4::ALK.","feedback":"Très bonne stratégie : bilan prédictif complet sur un matériel tissulaire limité, avec une conséquence thérapeutique directe."},{"id":"incomplete_dna_only","title":"NGS ADN et PD-L1 sans analyse de l’ARN","result":"Résultat incomplet sans altération conductrice de type SNV/indel identifiée, avec un TPS de PD-L1 à 5 % ; le statut des fusions n’est pas évalué de manière adéquate.","feedback":"L’orientation générale est correcte, mais le bilan est incomplet. L’analyse complémentaire de l’ARN permet de résoudre le cas, au prix d’une consommation de tissu et d’un allongement du TAT."},{"id":"overdiagnostic","title":"Bilan complémentaire large sans rapport avec l’entité tumorale","result":"Les marqueurs cibles requis peuvent malgré tout être disponibles, mais du tissu est inutilement consommé par des analyses MMR, MLH1, HRD, etc.","feedback":"Ce n’est pas une catastrophe diagnostique, mais la gestion responsable du tissu et la communication sont nettement compromises."}],"followup_logic":[{"trigger":"Le dépistage initial des fusions d’ARN est absent","action":"Proposer un panel complémentaire de fusions d’ARN","consequence":"Le résultat devient complet, mais un plafond de score s’applique en raison du retard évitable."},{"trigger":"Des analyses non pertinentes pour l’entité tumorale ont été sélectionnées","action":"Signaler dans le compte rendu comme examen de faible valeur ou potentiellement trompeur","consequence":"Pénalité dans les domaines Sélection des méthodes, Gestion responsable du matériel et Communication."}],"debrief_points":["Dans le NSCLC métastatique, la question clinique nécessite un bilan prédictif large et ne se limite pas à EGFR.","Les fusions constituent une raison classique de remettre en question les stratégies fondées uniquement sur l’ADN.","Une petite biopsie ne signifie pas moins d’analyses, mais une meilleure hiérarchisation."],"instructor_notes":{"model_answer":"Solution de référence : IHC PD-L1, NGS ADN et panel de fusions d’ARN en parallèle, avec une mention sur la disponibilité du tissu et une communication claire en MTB. Le test rapide EGFR n’est qu’un complément en cas de forte contrainte de délai.","scoring_focus":["Raisonnement clinique : la question du traitement de première ligne a été identifiée","Sélection des méthodes : combinaison correcte de l’ADN, de l’ARN et de PD-L1","Gestion responsable du matériel : les examens sans rapport avec l’entité tumorale ont été évités"],"discussion_questions":["Quand une biopsie liquide serait-elle utile en complément ?","Comment communiquer « aucune altération conductrice détectée » en l’absence de résultat sur les fusions d’ARN ?","Quel est le rôle de PD-L1 lorsqu’une fusion d’ALK a été détectée ?"]},"report_additions":["Rebondissement / point critique : une stratégie fondée uniquement sur l’ADN aurait retardé la détection d’ALK","Erreurs typiques : analyse d’EGFR seule, oubli de l’analyse de l’ARN et consommation de tissu par des examens de faible valeur","Parcours de référence : PD-L1, ADN et ARN en parallèle"]},"payload_hash_sha256":"686a979fe0b89a1cf0008531d779fb2a9a089caa12f6991aed11c02737eed843"}}};
const EXACT={"en":{"NSCLC":"NSCLC","IHC":"IHC","DNA-NGS":"DNA NGS","RNA-NGS":"RNA NGS","PD-L1":"PD-L1","ALK":"ALK","Materialbudget":"Tissue budget","MTB":"MTB","Zentrale klinisch-molekulare Fragestellung aus Anamnese, Histologie und Materialkontext ableiten":"Derive the central clinical-molecular question from the history, histology and tissue context","Passende molekulare/IHC-basierte Methode zur Kernentscheidung auswählen":"Select the appropriate molecular or IHC-based method for the key decision","Musterlösung im MTB klar, limitiert und patientenrelevant kommunizieren":"Communicate the reference answer clearly in the MTB, including limitations and patient relevance","Pulmonale Raumforderung → NSCLC → molekulare Therapieentscheidung":"Pulmonary mass → NSCLC → molecularly informed treatment decision","Onkogene Treiber / NSCLC / Resistenz":"Oncogenic drivers / NSCLC / resistance","NSCLC → molekulare Therapieentscheidung":"NSCLC → molecularly informed treatment decision","NSCLC Erstdiagnose":"Newly diagnosed NSCLC","Initialer Auftrag":"Initial request","Einsender":"Referrer","Onkologie / Bronchoskopie":"Oncology / bronchoscopy","Klinische Information":"Clinical information","67-jähriger Patient, pulmonale Raumforderung links, multiple kleine Leberherde im CT.":"67-year-old patient with a left pulmonary mass and multiple small liver lesions on CT.","Fragestellung":"Clinical question","Malignität? Primarius? Therapieentscheidende Diagnostik für MTB.":"Malignancy? Primary site? Treatment-defining diagnostics for the MTB.","Was ist noch unklar?":"What remains unclear?","Zu Beginn ist noch nicht sicher, ob es wirklich ein primäres Lungenkarzinom ist.":"At the outset, it is not yet certain that this is a primary lung carcinoma.","Anamnese und klinischer Kontext":"Medical history and clinical context","Raucherstatus":"Smoking history","Ex-Raucher, 15 pack years; seit 20 Jahren abstinent.":"Former smoker, 15 pack-years; quit 20 years ago.","Performance / Situation":"Performance status / clinical situation","ECOG 1, keine kurative Option, systemische Therapie zeitnah geplant.":"ECOG 1, no curative option; systemic treatment is planned promptly.","Vorbefunde":"Previous findings","Keine frühere Tumorerkrankung bekannt.":"No previous malignancy is known.","MTB-Zeitdruck":"MTB time pressure","Fall soll in 7 Tagen im MTB vorgestellt werden.":"The case is to be presented at the MTB in 7 days.","Histologie + Vor-IHC":"Histology and initial IHC","HE":"H&E","Infiltrate eines nicht-kleinzelligen Karzinoms in kleiner Bronchialbiopsie.":"Infiltrates of a non-small-cell carcinoma in a small bronchial biopsy.","TTF-1 positiv, Napsin A positiv, CK7 positiv; p40/CK5/6 negativ.":"TTF-1 positive, Napsin A positive and CK7 positive; p40 and CK5/6 negative.","Proliferation":"Proliferation","Ki67 ca. 35 %.":"Ki67 approximately 35%.","Arbeitsdiagnose":"Working diagnosis","Pulmonales Adenokarzinom / NSCLC, Stadium IV wahrscheinlich.":"Pulmonary adenocarcinoma / NSCLC, probably stage IV.","Noch offen":"Still pending","PD-L1 und molekulares Treiberprofil fehlen.":"PD-L1 and the molecular driver profile are still pending.","Materialprüfung":"Tissue assessment","Material":"Tissue material","FFPE-Biopsie, Block B2.":"FFPE biopsy, block B2.","Tumoranteil":"Tumour cell content","ca. 25–30 %, Makrodissektion empfohlen.":"Approximately 25–30%; macrodissection recommended.","Nekrose":"Necrosis","fokal, aber beurteilbare Tumorareale vorhanden.":"Focal, but evaluable tumour areas are present.","Verfügbare ungefärbte Schnitte":"Available unstained sections","12 Schnitte planbar.":"12 sections can be allocated.","DNA/RNA-Prognose":"Expected DNA/RNA yield","DNA wahrscheinlich ausreichend; RNA bei kleiner Biopsie potenziell grenzwertig.":"DNA is likely sufficient; RNA may be borderline in this small biopsy.","Materialfalle":"Tissue-use pitfall","Serielle Einzeltests können das Material verbrauchen, bevor RNA-Fusionen geprüft wurden.":"Sequential single-gene tests can exhaust the tissue before RNA fusions have been assessed.","EML4::ALK-Fusion":"EML4::ALK fusion","TPS 5 %":"TPS 5%","keine EGFR/KRAS/BRAF/METex14/ERBB2-Hotspot-Alteration":"No EGFR/KRAS/BRAF/METex14/ERBB2 hotspot alteration","DNA ausreichend; RNA knapp, aber verwertbar":"DNA sufficient; RNA limited but suitable for analysis","Metastasiertes Lungenadenokarzinom, kleine Biopsie: vollständige prädiktive Diagnostik ohne Materialverschwendung":"Metastatic lung adenocarcinoma, small biopsy: complete predictive testing without wasting tissue","MTB Basics":"MTB Basics","Pathologieassistenz / MTB-Einstieg":"Pathology trainee / introduction to MTB","12-15":"12–15","Treiber-, Fusions- und PD-L1-Diagnostik beim metastasierten NSCLC parallel und materialschonend planen.":"Plan driver, fusion and PD-L1 testing in metastatic NSCLC in parallel while preserving tissue.","DNA-only-Strategien bei fusionsrelevanter Fragestellung als potenziell unvollständig erkennen.":"Recognise DNA-only strategies as potentially incomplete when fusions are clinically relevant.","Befundlimitationen bei kleiner Biopsie und begrenztem Tumoranteil klar im MTB kommunizieren.":"Clearly communicate report limitations related to a small biopsy and limited tumour cell content in the MTB.","Montagmorgen, Tumorboard-Vorbereitung: Eine Bronchialbiopsie eines neu metastasierten Lungenkarzinoms liegt vor. Die Onkologie möchte innerhalb einer Woche wissen, ob eine zielgerichtete Therapie oder Immuntherapie infrage kommt. Das Material ist sichtbar knapp, aber die Therapieentscheidung hängt jetzt an der Pathologie.":"Monday morning, preparing for the tumour board: a bronchial biopsy from a newly diagnosed metastatic lung carcinoma has arrived. Oncology needs to know within one week whether targeted therapy or immunotherapy is an option. Tissue is clearly limited, but the treatment decision now depends on pathology.","68-jähriger Patient, ehemaliger Raucher, multiple pulmonale und ossäre Metastasen. Klinische Anfrage: 'Bitte molekulare Therapierbarkeit prüfen, Erstlinientherapie soll im MTB festgelegt werden.' Vorbefund aus der Pathologie: Adenokarzinom der Lunge, nicht-kleinzellig, keine Resektionsoption.":"68-year-old patient, former smoker, with multiple pulmonary and bone metastases. Clinical request: 'Please assess molecularly targetable alterations; first-line treatment will be determined at the MTB.' Preliminary pathology diagnosis: non-small-cell adenocarcinoma of the lung, not amenable to resection.","Klinischer Druck":"Clinical urgency","Der Patient ist symptomatisch, aber klinisch stabil. Eine Entscheidung über TKI vs. Immun-/Chemotherapie soll in 7 Tagen fallen.":"The patient is symptomatic but clinically stable. A decision between TKI treatment and immunotherapy/chemotherapy is required within 7 days.","Zeitdruck rechtfertigt parallele, nicht sequentielle Diagnostik.":"Time pressure supports parallel rather than sequential testing.","Histologie":"Histology","Kleine Bronchialbiopsie mit invasivem Adenokarzinom. TTF-1 und Napsin A positiv, p40/CK5/6 negativ, CK7 positiv. Ki-67 ca. 35–40%.":"Small bronchial biopsy showing invasive adenocarcinoma. TTF-1 and Napsin A positive, p40/CK5/6 negative, CK7 positive. Ki-67 approximately 35–40%.","Die Entität ist ausreichend eingegrenzt; jetzt geht es um prädiktive Marker.":"The tumour entity has been sufficiently defined; the focus now is on predictive biomarkers.","Tumorareal ca. 25%, fokal Nekrose. Nach Diagnostik bleiben geschätzt 8 unstained Slides. RNA-Qualität ist nicht garantiert, aber noch plausibel nutzbar.":"Tumour area approximately 25%, with focal necrosis. An estimated 8 unstained slides remain after the current work-up. RNA quality is not guaranteed but is still plausibly adequate for analysis.","Material Stewardship ist Teil der richtigen Entscheidung.":"Tissue stewardship is part of the correct decision.","MTB-Frage":"MTB question","Die Onkologie fragt explizit nach EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS und PD-L1.":"Oncology explicitly requests testing for EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS and PD-L1.","Die Anfrage spricht gegen eine reine EGFR-PCR als alleinige Strategie.":"This request argues against using EGFR PCR alone as the sole strategy.","invasives Lungenadenokarzinom, mäßig differenziert, kleine Biopsie.":"Invasive, moderately differentiated lung adenocarcinoma in a small biopsy.","TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; PD-L1 noch nicht erfolgt.":"TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; PD-L1 not yet performed.","Material-QC":"Tissue QC","Tumorzellanteil ausreichend, aber knapp; RNA-Fusionsdiagnostik sollte nicht durch unnötige Zusatztests gefährdet werden.":"Tumour cell content is sufficient but limited; RNA fusion testing should not be jeopardised by unnecessary additional tests.","maximal 8 Schnitte verfügbar; unnötige IHC-/Methylierungs-/HRD-Tests reduzieren die Chance auf vollständige Molekulardiagnostik.":"A maximum of 8 sections is available; unnecessary IHC, methylation or HRD tests reduce the likelihood of completing the molecular work-up.","TAT-Ziel: 7 Kalendertage bis MTB.":"TAT target: 7 calendar days to the MTB.","DNA und RNA sollten möglichst aus demselben markierten Tumorareal gewonnen werden.":"DNA and RNA should, whenever possible, be extracted from the same marked tumour area.","Was ist die zentrale klinische Fragestellung?":"What is the central clinical question?","Vollständige prädiktive Erstliniendiagnostik mit Treibern, Fusionen und PD-L1":"Complete predictive first-line testing for oncogenic drivers, fusions and PD-L1","Lynch-Syndrom-Abklärung":"Evaluation for Lynch syndrome","HRD/PARP-Indikation":"HRD/PARP indication","Infektionsdiagnostik":"Infectious-disease testing","Beim metastasierten Lungenadenokarzinom steht die therapieentscheidende Treiber-/Fusions-/PD-L1-Diagnostik im Vordergrund.":"In metastatic lung adenocarcinoma, treatment-defining testing for oncogenic drivers, fusions and PD-L1 is the priority.","Was ist das wichtigste Materialrisiko?":"What is the most important tissue-related risk?","Kleine Biopsie mit begrenztem Tumorareal und potenzieller RNA-Fragilität":"Small biopsy with a limited tumour area and potentially fragile RNA","Material spielt bei NGS praktisch keine Rolle":"Tissue availability is largely irrelevant for NGS","Plasma ersetzt Gewebe grundsätzlich":"Plasma always replaces tissue","Methylierung sollte grundsätzlich zuerst erfolgen":"Methylation testing should always be performed first","Die vollständige Diagnostik muss materialschonend und priorisiert geplant werden.":"The complete diagnostic work-up must be prioritised and planned to preserve tissue.","Warum ist DNA-NGS allein in diesem Fall riskant?":"Why is DNA NGS alone risky in this case?","Relevante Genfusionen können unzureichend erfasst werden, RNA-Fusionsdiagnostik ergänzt die Aussage":"Relevant gene fusions may be insufficiently detected; RNA fusion testing provides complementary information","DNA-NGS detektiert keine Mutationen":"DNA NGS does not detect mutations","PD-L1 wird zuverlässig aus DNA abgeleitet":"PD-L1 can be reliably inferred from DNA","Fusionen sind nur beim CRC relevant":"Fusions are relevant only in colorectal cancer","DNA-NGS ist für SNV/Indels stark, aber RNA-basierte Verfahren sind für relevante Fusionen häufig die bessere Ergänzung.":"DNA NGS performs well for SNVs and indels, but RNA-based methods are often the better complement for clinically relevant fusions.","Wähle eine materialschonende Primäranforderung, die die Erstlinientherapie im MTB belastbar unterstützt.":"Choose an initial test request that preserves tissue and robustly supports the first-line treatment decision in the MTB.","PD-L1-IHC parallel anfordern.":"Request PD-L1 IHC in parallel.","DNA-basiertes Lungen-/Solid-Tumor-Panel für SNV/Indels/CNV inkl. EGFR, KRAS, BRAF, MET, ERBB2.":"DNA-based lung/solid-tumour panel for SNVs, indels and CNVs, including EGFR, KRAS, BRAF, MET and ERBB2.","RNA-Fusionspanel für ALK, ROS1, RET, NTRK und weitere relevante Fusionen.":"RNA fusion panel for ALK, ROS1, RET, NTRK and other relevant fusions.","Tumorareal markieren und unnötige entitätsfremde Zusatzdiagnostik vermeiden.":"Mark the tumour area and avoid unnecessary additional testing unrelated to the tumour entity.","Befund mit Methodengrenzen und Materialqualität berichten.":"Report the findings together with method limitations and tissue quality.","Bei extremem Zeitdruck kann EGFR-Schnelltest zusätzlich erfolgen, ersetzt aber nicht die Panel-/Fusionsdiagnostik.":"Under extreme time pressure, a rapid EGFR test may be added, but it does not replace panel and fusion testing.","ALK-IHC/FISH kann als schnelle Ergänzung sinnvoll sein, aber nicht als alleinige umfassende Strategie.":"ALK IHC/FISH may be useful as a rapid adjunct, but not as the sole comprehensive strategy.","MLH1-Methylierung":"MLH1 promoter methylation","Ohne dMMR-/CRC-/Lynch-Kontext entitätsfremd und materialverbrauchend.":"Without a dMMR, colorectal-cancer or Lynch context, this is unrelated to the tumour entity and consumes tissue.","HRD-Score":"HRD score","Für die primäre NSCLC-Erstlinienentscheidung nicht zielführend.":"Not relevant to the initial first-line decision in NSCLC.","EGFR-PCR allein":"EGFR PCR alone","Kann EGFR beantworten, lässt aber viele therapeutisch relevante Alterationen offen.":"It can answer the EGFR question but leaves many treatment-relevant alterations unassessed.","DNA-negativ ist nicht automatisch treibernegativ":"A negative DNA result does not automatically mean driver-negative","Wenn nur DNA-NGS und PD-L1 angefordert werden, ergibt sich ein Teilbefund: kein EGFR/KRAS/BRAF/METex14-Nachweis, PD-L1 TPS 5%. Erst bei RNA-Fusionsdiagnostik wird eine EML4::ALK-Fusion detektiert.":"If only DNA NGS and PD-L1 are requested, the result is incomplete: no EGFR/KRAS/BRAF/METex14 alteration is detected and PD-L1 TPS is 5%. An EML4::ALK fusion is identified only when RNA fusion testing is performed.","Die therapeutisch entscheidende Alteration wäre bei zu enger Primäranforderung verzögert oder verpasst worden.":"The treatment-defining alteration would have been delayed or missed with an overly narrow initial request.","Vollständige Primäranforderung":"Complete initial test request","PD-L1 TPS 5%; DNA-Panel ohne EGFR/KRAS/BRAF/METex14; RNA-Panel mit EML4::ALK-Fusion.":"PD-L1 TPS 5%; DNA panel negative for EGFR/KRAS/BRAF/METex14; RNA panel identifies an EML4::ALK fusion.","Sehr gute Strategie: vollständige prädiktive Diagnostik bei kleinem Material und direkter therapeutischer Konsequenz.":"Very good strategy: complete predictive testing using limited tissue, with a direct treatment consequence.","DNA-NGS + PD-L1 ohne RNA":"DNA NGS and PD-L1 without RNA testing","Teilbefund ohne SNV/Indel-Treiber, PD-L1 TPS 5%; Fusionsstatus nicht ausreichend beurteilt.":"Incomplete result with no SNV/indel driver identified and PD-L1 TPS 5%; fusion status is not adequately assessed.","Richtige Richtung, aber unvollständig. Nachforderung RNA rettet den Fall, kostet aber Material und TAT.":"The overall direction is correct, but the work-up is incomplete. Additional RNA testing resolves the case, but at the cost of tissue and TAT.","Breite, entitätsfremde Zusatzdiagnostik":"Broad additional testing unrelated to the tumour entity","Vollständige Zielmarker ggf. verfügbar, aber unnötiger Materialverbrauch durch MMR/MLH1/HRD etc.":"The required target markers may still be obtained, but tissue is unnecessarily consumed by MMR, MLH1, HRD and similar tests.","Diagnostisch nicht katastrophal, aber Material Stewardship und Kommunikation leiden deutlich.":"Not diagnostically disastrous, but tissue stewardship and communication are clearly compromised.","Nachforderung RNA-Fusionspanel anbieten":"Offer an additional RNA fusion panel","Ergebnis wird vollständig, aber Score-Cap wegen vermeidbarer Verzögerung.":"The result becomes complete, but a score cap applies because of the avoidable delay.","im Bericht als low value/misleading ausweisen":"Identify as low-value or misleading in the report","Abzug bei Method Selection, Material Stewardship und Communication.":"Deduction in Method Selection, Material Stewardship and Communication.","Beim metastasierten NSCLC ist die klinische Frage breit prädiktiv, nicht nur EGFR-orientiert.":"In metastatic NSCLC, the clinical question requires broad predictive testing and is not limited to EGFR.","Fusionen sind ein klassischer Grund, DNA-only-Strategien kritisch zu hinterfragen.":"Fusions are a classic reason to critically question DNA-only strategies.","Kleine Biopsie heißt nicht weniger Diagnostik, sondern bessere Priorisierung.":"A small biopsy does not mean less testing; it means better prioritisation.","Optimale Lösung: PD-L1-IHC + DNA-NGS + RNA-Fusionspanel parallel, mit Materialhinweis und klarer MTB-Kommunikation. EGFR-Schnelltest nur als Zusatz bei Zeitdruck.":"Reference answer: PD-L1 IHC, DNA NGS and an RNA fusion panel in parallel, with a tissue-availability note and clear MTB communication. A rapid EGFR test is only an adjunct when time is critical.","Clinical Reasoning: Erstlinienfrage erkannt":"Clinical reasoning: first-line treatment question identified","Method Selection: DNA/RNA/PD-L1 korrekt kombiniert":"Method selection: DNA, RNA and PD-L1 correctly combined","Material Stewardship: entitätsfremde Tests vermieden":"Material stewardship: tests unrelated to the tumour entity avoided","Wann wäre Liquid Biopsy zusätzlich sinnvoll?":"When would liquid biopsy be useful as an additional test?","Wie kommuniziert man 'kein Treiber nachgewiesen' ohne RNA-Fusionsergebnis?":"How should 'no driver alteration detected' be communicated when no RNA fusion result is available?","Welche Rolle spielt PD-L1 bei nachgewiesener ALK-Fusion?":"What is the role of PD-L1 when an ALK fusion has been detected?","Twist / kritischer Wendepunkt: DNA-only hätte ALK verzögert":"Twist / critical turning point: a DNA-only strategy would have delayed ALK detection","Typische Fehler: EGFR-only, RNA vergessen, Material durch Low-value-Tests verbraucht":"Typical errors: EGFR-only testing, omission of RNA testing, and tissue consumption by low-value tests","Musterpfad: PD-L1 + DNA + RNA parallel":"Reference pathway: PD-L1, DNA and RNA in parallel","RNA-Fusionsdiagnostik primär fehlt":"Primary RNA fusion testing is missing","entitätsfremde Tests gewählt":"Tests unrelated to the tumour entity were selected","Core/MVP prüfen":"Review for core/MVP","MTB; Länge=Standard; Schwierigkeit=Intermediate; Status=curated-core":"MTB; length=standard; difficulty=intermediate; status=curated-core"},"ro":{"NSCLC":"NSCLC","IHC":"IHC","DNA-NGS":"NGS ADN","RNA-NGS":"NGS ARN","PD-L1":"PD-L1","ALK":"ALK","Materialbudget":"Buget de material tisular","MTB":"MTB","Zentrale klinisch-molekulare Fragestellung aus Anamnese, Histologie und Materialkontext ableiten":"Formulați întrebarea clinico-moleculară centrală pe baza anamnezei, histologiei și contextului materialului tisular","Passende molekulare/IHC-basierte Methode zur Kernentscheidung auswählen":"Selectați metoda moleculară sau bazată pe IHC adecvată pentru decizia principală","Musterlösung im MTB klar, limitiert und patientenrelevant kommunizieren":"Comunicați clar soluția de referință în MTB, cu limitările și relevanța pentru pacient","Pulmonale Raumforderung → NSCLC → molekulare Therapieentscheidung":"Formațiune pulmonară → NSCLC → decizie terapeutică bazată pe profilul molecular","Onkogene Treiber / NSCLC / Resistenz":"Alterări oncogenice driver / NSCLC / rezistență","NSCLC → molekulare Therapieentscheidung":"NSCLC → decizie terapeutică bazată pe profilul molecular","NSCLC Erstdiagnose":"Diagnostic inițial de NSCLC","Initialer Auftrag":"Solicitare inițială","Einsender":"Solicitant","Onkologie / Bronchoskopie":"Oncologie / bronhoscopie","Klinische Information":"Informații clinice","67-jähriger Patient, pulmonale Raumforderung links, multiple kleine Leberherde im CT.":"Pacient în vârstă de 67 de ani, cu formațiune pulmonară stângă și multiple leziuni hepatice mici la CT.","Fragestellung":"Întrebare clinică","Malignität? Primarius? Therapieentscheidende Diagnostik für MTB.":"Malignitate? Sediu primar? Diagnostic care să ghideze tratamentul pentru MTB.","Was ist noch unklar?":"Ce rămâne neclar?","Zu Beginn ist noch nicht sicher, ob es wirklich ein primäres Lungenkarzinom ist.":"La început, nu este încă sigur că este vorba într-adevăr despre un carcinom pulmonar primar.","Anamnese und klinischer Kontext":"Anamneză și context clinic","Raucherstatus":"Istoric de fumat","Ex-Raucher, 15 pack years; seit 20 Jahren abstinent.":"Fost fumător, 15 pachete-an; a renunțat la fumat în urmă cu 20 de ani.","Performance / Situation":"Status de performanță / situație clinică","ECOG 1, keine kurative Option, systemische Therapie zeitnah geplant.":"ECOG 1, fără opțiune curativă; tratamentul sistemic este planificat în curând.","Vorbefunde":"Rezultate anterioare","Keine frühere Tumorerkrankung bekannt.":"Nu este cunoscută nicio neoplazie anterioară.","MTB-Zeitdruck":"Presiune de timp pentru MTB","Fall soll in 7 Tagen im MTB vorgestellt werden.":"Cazul trebuie prezentat în MTB peste 7 zile.","Histologie + Vor-IHC":"Histologie și IHC inițială","HE":"H&E","Infiltrate eines nicht-kleinzelligen Karzinoms in kleiner Bronchialbiopsie.":"Infiltrate de carcinom fără celule mici într-o biopsie bronșică de dimensiuni reduse.","TTF-1 positiv, Napsin A positiv, CK7 positiv; p40/CK5/6 negativ.":"TTF-1 pozitiv, Napsin A pozitiv și CK7 pozitiv; p40 și CK5/6 negative.","Proliferation":"Proliferare","Ki67 ca. 35 %.":"Ki67 aproximativ 35%.","Arbeitsdiagnose":"Diagnostic de lucru","Pulmonales Adenokarzinom / NSCLC, Stadium IV wahrscheinlich.":"Adenocarcinom pulmonar / NSCLC, probabil stadiul IV.","Noch offen":"Încă neefectuat","PD-L1 und molekulares Treiberprofil fehlen.":"Analiza PD-L1 și profilul molecular al alterărilor driver sunt încă neefectuate.","Materialprüfung":"Evaluarea materialului tisular","Material":"Material tisular","FFPE-Biopsie, Block B2.":"Biopsie FFPE, bloc B2.","Tumoranteil":"Procent tumoral","ca. 25–30 %, Makrodissektion empfohlen.":"Aproximativ 25–30%; se recomandă macrodisecția.","Nekrose":"Necroză","fokal, aber beurteilbare Tumorareale vorhanden.":"Focală, dar există arii tumorale evaluabile.","Verfügbare ungefärbte Schnitte":"Secțiuni necolorate disponibile","12 Schnitte planbar.":"Pot fi alocate 12 secțiuni.","DNA/RNA-Prognose":"Prognosticul randamentului ADN/ARN","DNA wahrscheinlich ausreichend; RNA bei kleiner Biopsie potenziell grenzwertig.":"ADN-ul este probabil suficient; ARN-ul poate fi la limită în această biopsie mică.","Materialfalle":"Capcană privind utilizarea materialului","Serielle Einzeltests können das Material verbrauchen, bevor RNA-Fusionen geprüft wurden.":"Testele secvențiale pentru markeri individuali pot epuiza materialul înainte de evaluarea fuziunilor ARN.","EML4::ALK-Fusion":"Fuziune EML4::ALK","TPS 5 %":"TPS 5%","keine EGFR/KRAS/BRAF/METex14/ERBB2-Hotspot-Alteration":"Fără alterări hotspot EGFR/KRAS/BRAF/METex14/ERBB2","DNA ausreichend; RNA knapp, aber verwertbar":"ADN suficient; ARN limitat, dar analizabil","Metastasiertes Lungenadenokarzinom, kleine Biopsie: vollständige prädiktive Diagnostik ohne Materialverschwendung":"Adenocarcinom pulmonar metastatic, biopsie mică: diagnostic predictiv complet fără irosirea materialului tisular","MTB Basics":"Noțiuni de bază MTB","Pathologieassistenz / MTB-Einstieg":"Medic în formare în patologie / introducere în MTB","12-15":"12–15","Treiber-, Fusions- und PD-L1-Diagnostik beim metastasierten NSCLC parallel und materialschonend planen.":"Planificați în paralel testarea alterărilor driver, a fuziunilor și a PD-L1 în NSCLC metastatic, cu utilizarea responsabilă a materialului tisular.","DNA-only-Strategien bei fusionsrelevanter Fragestellung als potenziell unvollständig erkennen.":"Recunoașteți strategiile bazate exclusiv pe ADN ca potențial incomplete atunci când fuziunile sunt relevante clinic.","Befundlimitationen bei kleiner Biopsie und begrenztem Tumoranteil klar im MTB kommunizieren.":"Comunicați clar în MTB limitările raportului determinate de biopsia mică și procentul tumoral limitat.","Montagmorgen, Tumorboard-Vorbereitung: Eine Bronchialbiopsie eines neu metastasierten Lungenkarzinoms liegt vor. Die Onkologie möchte innerhalb einer Woche wissen, ob eine zielgerichtete Therapie oder Immuntherapie infrage kommt. Das Material ist sichtbar knapp, aber die Therapieentscheidung hängt jetzt an der Pathologie.":"Luni dimineață, în pregătirea comisiei oncologice: este disponibilă o biopsie bronșică de la un carcinom pulmonar metastatic recent diagnosticat. Oncologia dorește să afle în decurs de o săptămână dacă este indicată o terapie țintită sau imunoterapia. Materialul tisular este evident limitat, iar decizia terapeutică depinde acum de patologie.","68-jähriger Patient, ehemaliger Raucher, multiple pulmonale und ossäre Metastasen. Klinische Anfrage: 'Bitte molekulare Therapierbarkeit prüfen, Erstlinientherapie soll im MTB festgelegt werden.' Vorbefund aus der Pathologie: Adenokarzinom der Lunge, nicht-kleinzellig, keine Resektionsoption.":"Pacient în vârstă de 68 de ani, fost fumător, cu multiple metastaze pulmonare și osoase. Solicitare clinică: „Vă rugăm să evaluați opțiunile terapeutice moleculare; tratamentul de primă linie va fi stabilit în MTB.” Diagnostic anatomopatologic preliminar: adenocarcinom pulmonar fără celule mici, fără opțiune de rezecție.","Klinischer Druck":"Urgență clinică","Der Patient ist symptomatisch, aber klinisch stabil. Eine Entscheidung über TKI vs. Immun-/Chemotherapie soll in 7 Tagen fallen.":"Pacientul este simptomatic, dar stabil clinic. În decurs de 7 zile trebuie luată o decizie între tratamentul cu TKI și imunoterapie/chimioterapie.","Zeitdruck rechtfertigt parallele, nicht sequentielle Diagnostik.":"Presiunea de timp justifică testarea în paralel, nu secvențială.","Histologie":"Histologie","Kleine Bronchialbiopsie mit invasivem Adenokarzinom. TTF-1 und Napsin A positiv, p40/CK5/6 negativ, CK7 positiv. Ki-67 ca. 35–40%.":"Biopsie bronșică mică cu adenocarcinom invaziv. TTF-1 și Napsin A pozitive, p40/CK5/6 negative, CK7 pozitiv. Ki-67 aproximativ 35–40%.","Die Entität ist ausreichend eingegrenzt; jetzt geht es um prädiktive Marker.":"Entitatea tumorală este suficient de bine delimitată; accentul se pune acum pe biomarkerii predictivi.","Tumorareal ca. 25%, fokal Nekrose. Nach Diagnostik bleiben geschätzt 8 unstained Slides. RNA-Qualität ist nicht garantiert, aber noch plausibel nutzbar.":"Aria tumorală este de aproximativ 25%, cu necroză focală. După investigațiile efectuate rămân estimate 8 lame necolorate. Calitatea ARN-ului nu este garantată, dar este încă plauzibil adecvată pentru analiză.","Material Stewardship ist Teil der richtigen Entscheidung.":"Utilizarea responsabilă a materialului tisular face parte din decizia corectă.","MTB-Frage":"Întrebare pentru MTB","Die Onkologie fragt explizit nach EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS und PD-L1.":"Oncologia solicită explicit testarea EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS și PD-L1.","Die Anfrage spricht gegen eine reine EGFR-PCR als alleinige Strategie.":"Această solicitare nu susține utilizarea exclusivă a PCR pentru EGFR ca strategie unică.","invasives Lungenadenokarzinom, mäßig differenziert, kleine Biopsie.":"Adenocarcinom pulmonar invaziv, moderat diferențiat, într-o biopsie mică.","TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; PD-L1 noch nicht erfolgt.":"TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; analiza PD-L1 nu a fost încă efectuată.","Material-QC":"QC al materialului tisular","Tumorzellanteil ausreichend, aber knapp; RNA-Fusionsdiagnostik sollte nicht durch unnötige Zusatztests gefährdet werden.":"Procentul tumoral este suficient, dar limitat; testarea fuziunilor ARN nu trebuie compromisă prin analize suplimentare inutile.","maximal 8 Schnitte verfügbar; unnötige IHC-/Methylierungs-/HRD-Tests reduzieren die Chance auf vollständige Molekulardiagnostik.":"Sunt disponibile cel mult 8 secțiuni; analizele IHC, de metilare sau HRD inutile reduc șansa de a finaliza diagnosticul molecular.","TAT-Ziel: 7 Kalendertage bis MTB.":"Obiectiv TAT: 7 zile calendaristice până la MTB.","DNA und RNA sollten möglichst aus demselben markierten Tumorareal gewonnen werden.":"ADN-ul și ARN-ul trebuie extrase, pe cât posibil, din aceeași arie tumorală marcată.","Was ist die zentrale klinische Fragestellung?":"Care este întrebarea clinică centrală?","Vollständige prädiktive Erstliniendiagnostik mit Treibern, Fusionen und PD-L1":"Diagnostic predictiv complet de primă linie pentru alterări driver, fuziuni și PD-L1","Lynch-Syndrom-Abklärung":"Evaluare pentru sindromul Lynch","HRD/PARP-Indikation":"Indicație HRD/PARP","Infektionsdiagnostik":"Diagnostic infecțios","Beim metastasierten Lungenadenokarzinom steht die therapieentscheidende Treiber-/Fusions-/PD-L1-Diagnostik im Vordergrund.":"În adenocarcinomul pulmonar metastatic, prioritatea este testarea care determină tratamentul pentru alterări driver, fuziuni și PD-L1.","Was ist das wichtigste Materialrisiko?":"Care este cel mai important risc legat de materialul tisular?","Kleine Biopsie mit begrenztem Tumorareal und potenzieller RNA-Fragilität":"Biopsie mică, cu arie tumorală limitată și ARN potențial fragil","Material spielt bei NGS praktisch keine Rolle":"Materialul tisular nu are practic nicio importanță pentru NGS","Plasma ersetzt Gewebe grundsätzlich":"Plasma înlocuiește întotdeauna țesutul","Methylierung sollte grundsätzlich zuerst erfolgen":"Testarea metilării trebuie efectuată întotdeauna prima","Die vollständige Diagnostik muss materialschonend und priorisiert geplant werden.":"Investigațiile diagnostice complete trebuie prioritizate și planificate astfel încât să conserve materialul tisular.","Warum ist DNA-NGS allein in diesem Fall riskant?":"De ce este riscantă utilizarea exclusivă a NGS pe ADN în acest caz?","Relevante Genfusionen können unzureichend erfasst werden, RNA-Fusionsdiagnostik ergänzt die Aussage":"Fuziunile genice relevante pot fi detectate insuficient; testarea fuziunilor ARN completează informația","DNA-NGS detektiert keine Mutationen":"NGS pe ADN nu detectează mutații","PD-L1 wird zuverlässig aus DNA abgeleitet":"PD-L1 poate fi dedus în mod fiabil din ADN","Fusionen sind nur beim CRC relevant":"Fuziunile sunt relevante numai în cancerul colorectal","DNA-NGS ist für SNV/Indels stark, aber RNA-basierte Verfahren sind für relevante Fusionen häufig die bessere Ergänzung.":"NGS pe ADN este performantă pentru SNV și indeluri, dar metodele bazate pe ARN reprezintă adesea completarea mai bună pentru fuziunile relevante clinic.","Wähle eine materialschonende Primäranforderung, die die Erstlinientherapie im MTB belastbar unterstützt.":"Alegeți o solicitare inițială de analize care conservă materialul tisular și susține în mod robust decizia de tratament de primă linie în MTB.","PD-L1-IHC parallel anfordern.":"Solicitați în paralel IHC pentru PD-L1.","DNA-basiertes Lungen-/Solid-Tumor-Panel für SNV/Indels/CNV inkl. EGFR, KRAS, BRAF, MET, ERBB2.":"Panel pulmonar/pentru tumori solide bazat pe ADN pentru SNV, indeluri și CNV, incluzând EGFR, KRAS, BRAF, MET și ERBB2.","RNA-Fusionspanel für ALK, ROS1, RET, NTRK und weitere relevante Fusionen.":"Panel de fuziuni ARN pentru ALK, ROS1, RET, NTRK și alte fuziuni relevante.","Tumorareal markieren und unnötige entitätsfremde Zusatzdiagnostik vermeiden.":"Marcați aria tumorală și evitați analizele suplimentare inutile, nerelevante pentru entitatea tumorală.","Befund mit Methodengrenzen und Materialqualität berichten.":"Raportați rezultatele împreună cu limitările metodei și calitatea materialului tisular.","Bei extremem Zeitdruck kann EGFR-Schnelltest zusätzlich erfolgen, ersetzt aber nicht die Panel-/Fusionsdiagnostik.":"În condiții de presiune temporală extremă, se poate adăuga un test rapid pentru EGFR, dar acesta nu înlocuiește testarea prin panel și pentru fuziuni.","ALK-IHC/FISH kann als schnelle Ergänzung sinnvoll sein, aber nicht als alleinige umfassende Strategie.":"IHC/FISH pentru ALK poate fi utilă ca analiză suplimentară rapidă, dar nu ca unică strategie completă.","MLH1-Methylierung":"Metilarea promotorului MLH1","Ohne dMMR-/CRC-/Lynch-Kontext entitätsfremd und materialverbrauchend.":"Fără un context dMMR, de cancer colorectal sau Lynch, această analiză nu este relevantă pentru entitatea tumorală și consumă material tisular.","HRD-Score":"Scor HRD","Für die primäre NSCLC-Erstlinienentscheidung nicht zielführend.":"Nu este relevant pentru decizia inițială de tratament de primă linie în NSCLC.","EGFR-PCR allein":"PCR pentru EGFR ca test unic","Kann EGFR beantworten, lässt aber viele therapeutisch relevante Alterationen offen.":"Poate răspunde întrebării privind EGFR, dar lasă neevaluate numeroase alterări relevante terapeutic.","DNA-negativ ist nicht automatisch treibernegativ":"Un rezultat negativ la analiza ADN nu înseamnă automat absența unei alterări driver","Wenn nur DNA-NGS und PD-L1 angefordert werden, ergibt sich ein Teilbefund: kein EGFR/KRAS/BRAF/METex14-Nachweis, PD-L1 TPS 5%. Erst bei RNA-Fusionsdiagnostik wird eine EML4::ALK-Fusion detektiert.":"Dacă sunt solicitate numai NGS pe ADN și PD-L1, rezultatul este incomplet: nu se detectează alterări EGFR/KRAS/BRAF/METex14, iar PD-L1 TPS este 5%. Fuziunea EML4::ALK este identificată numai după testarea fuziunilor ARN.","Die therapeutisch entscheidende Alteration wäre bei zu enger Primäranforderung verzögert oder verpasst worden.":"Alterarea care determină tratamentul ar fi fost identificată cu întârziere sau omisă dacă solicitarea inițială ar fi fost prea restrânsă.","Vollständige Primäranforderung":"Solicitare inițială completă","PD-L1 TPS 5%; DNA-Panel ohne EGFR/KRAS/BRAF/METex14; RNA-Panel mit EML4::ALK-Fusion.":"PD-L1 TPS 5%; panelul ADN este negativ pentru EGFR/KRAS/BRAF/METex14; panelul ARN identifică o fuziune EML4::ALK.","Sehr gute Strategie: vollständige prädiktive Diagnostik bei kleinem Material und direkter therapeutischer Konsequenz.":"Strategie foarte bună: diagnostic predictiv complet pe material tisular limitat, cu o consecință terapeutică directă.","DNA-NGS + PD-L1 ohne RNA":"NGS pe ADN și PD-L1 fără testare ARN","Teilbefund ohne SNV/Indel-Treiber, PD-L1 TPS 5%; Fusionsstatus nicht ausreichend beurteilt.":"Rezultat incomplet, fără alterare driver SNV/indel identificată și cu PD-L1 TPS 5%; statusul fuziunilor nu este evaluat adecvat.","Richtige Richtung, aber unvollständig. Nachforderung RNA rettet den Fall, kostet aber Material und TAT.":"Direcția generală este corectă, dar investigațiile sunt incomplete. Testarea suplimentară a ARN-ului clarifică cazul, dar consumă material tisular și prelungește TAT.","Breite, entitätsfremde Zusatzdiagnostik":"Investigații suplimentare extinse, nerelevante pentru entitatea tumorală","Vollständige Zielmarker ggf. verfügbar, aber unnötiger Materialverbrauch durch MMR/MLH1/HRD etc.":"Markerii țintă necesari pot fi totuși disponibili, dar materialul tisular este consumat inutil prin analize MMR, MLH1, HRD și similare.","Diagnostisch nicht katastrophal, aber Material Stewardship und Kommunikation leiden deutlich.":"Nu este o catastrofă diagnostică, dar utilizarea responsabilă a materialului tisular și comunicarea sunt clar compromise.","Nachforderung RNA-Fusionspanel anbieten":"Oferiți suplimentar un panel de fuziuni ARN","Ergebnis wird vollständig, aber Score-Cap wegen vermeidbarer Verzögerung.":"Rezultatul devine complet, dar se aplică un plafon de scor din cauza întârzierii evitabile.","im Bericht als low value/misleading ausweisen":"Menționați în raport ca analiză cu valoare redusă sau potențial înșelătoare","Abzug bei Method Selection, Material Stewardship und Communication.":"Depunctare la Selectarea metodelor, Utilizarea responsabilă a materialului și Comunicare.","Beim metastasierten NSCLC ist die klinische Frage breit prädiktiv, nicht nur EGFR-orientiert.":"În NSCLC metastatic, întrebarea clinică necesită o testare predictivă amplă și nu se limitează la EGFR.","Fusionen sind ein klassischer Grund, DNA-only-Strategien kritisch zu hinterfragen.":"Fuziunile reprezintă un motiv clasic pentru a evalua critic strategiile bazate exclusiv pe ADN.","Kleine Biopsie heißt nicht weniger Diagnostik, sondern bessere Priorisierung.":"O biopsie mică nu înseamnă mai puține analize, ci o prioritizare mai bună.","Optimale Lösung: PD-L1-IHC + DNA-NGS + RNA-Fusionspanel parallel, mit Materialhinweis und klarer MTB-Kommunikation. EGFR-Schnelltest nur als Zusatz bei Zeitdruck.":"Soluție de referință: IHC pentru PD-L1, NGS pe ADN și panel de fuziuni ARN în paralel, cu mențiune privind disponibilitatea materialului tisular și comunicare clară în MTB. Testul rapid EGFR este doar o analiză suplimentară în condiții de presiune temporală.","Clinical Reasoning: Erstlinienfrage erkannt":"Raționament clinic: întrebarea privind tratamentul de primă linie a fost identificată","Method Selection: DNA/RNA/PD-L1 korrekt kombiniert":"Selectarea metodelor: ADN, ARN și PD-L1 combinate corect","Material Stewardship: entitätsfremde Tests vermieden":"Utilizarea responsabilă a materialului: au fost evitate analizele nerelevante pentru entitatea tumorală","Wann wäre Liquid Biopsy zusätzlich sinnvoll?":"Când ar fi utilă suplimentar o biopsie lichidă?","Wie kommuniziert man 'kein Treiber nachgewiesen' ohne RNA-Fusionsergebnis?":"Cum trebuie comunicat mesajul „nu s-a detectat nicio alterare driver” în absența unui rezultat pentru fuziunile ARN?","Welche Rolle spielt PD-L1 bei nachgewiesener ALK-Fusion?":"Care este rolul PD-L1 atunci când a fost detectată o fuziune ALK?","Twist / kritischer Wendepunkt: DNA-only hätte ALK verzögert":"Element surpriză / punct critic de cotitură: o strategie bazată exclusiv pe ADN ar fi întârziat detectarea ALK","Typische Fehler: EGFR-only, RNA vergessen, Material durch Low-value-Tests verbraucht":"Erori tipice: testare exclusivă EGFR, omiterea testării ARN și consumarea materialului tisular prin analize cu valoare redusă","Musterpfad: PD-L1 + DNA + RNA parallel":"Traseu de referință: PD-L1, ADN și ARN în paralel","RNA-Fusionsdiagnostik primär fehlt":"Lipsește testarea primară a fuziunilor ARN","entitätsfremde Tests gewählt":"Au fost selectate teste fără legătură cu entitatea tumorală","Core/MVP prüfen":"De revizuit pentru conținutul de bază/MVP","MTB; Länge=Standard; Schwierigkeit=Intermediate; Status=curated-core":"MTB; lungime=standard; dificultate=intermediară; stare=curated-core"},"el":{"NSCLC":"NSCLC","IHC":"IHC","DNA-NGS":"DNA-NGS","RNA-NGS":"RNA-NGS","PD-L1":"PD-L1","ALK":"ALK","Materialbudget":"Απόθεμα ιστικού υλικού","MTB":"MTB","Zentrale klinisch-molekulare Fragestellung aus Anamnese, Histologie und Materialkontext ableiten":"Διατυπώστε το κεντρικό κλινικομοριακό ερώτημα από το ιστορικό, την ιστολογία και το πλαίσιο του ιστικού υλικού","Passende molekulare/IHC-basierte Methode zur Kernentscheidung auswählen":"Επιλέξτε την κατάλληλη μοριακή ή βασισμένη στην IHC μέθοδο για την κύρια απόφαση","Musterlösung im MTB klar, limitiert und patientenrelevant kommunizieren":"Επικοινωνήστε με σαφήνεια την ενδεικτική λύση στο MTB, μαζί με τους περιορισμούς και τη σημασία για τον ασθενή","Pulmonale Raumforderung → NSCLC → molekulare Therapieentscheidung":"Πνευμονική μάζα → NSCLC → θεραπευτική απόφαση βάσει μοριακών δεδομένων","Onkogene Treiber / NSCLC / Resistenz":"Ογκογονικές οδηγές αλλοιώσεις / NSCLC / αντοχή","NSCLC → molekulare Therapieentscheidung":"NSCLC → θεραπευτική απόφαση βάσει μοριακών δεδομένων","NSCLC Erstdiagnose":"Αρχική διάγνωση NSCLC","Initialer Auftrag":"Αρχικό αίτημα","Einsender":"Αποστέλλων ιατρός/τμήμα","Onkologie / Bronchoskopie":"Ογκολογία / βρογχοσκόπηση","Klinische Information":"Κλινικές πληροφορίες","67-jähriger Patient, pulmonale Raumforderung links, multiple kleine Leberherde im CT.":"Ασθενής 67 ετών με πνευμονική μάζα αριστερά και πολλαπλές μικρές ηπατικές εστίες στην αξονική τομογραφία.","Fragestellung":"Κλινικό ερώτημα","Malignität? Primarius? Therapieentscheidende Diagnostik für MTB.":"Κακοήθεια; Πρωτοπαθής εστία; Διαγνωστικός έλεγχος που θα καθορίσει τη θεραπεία για το MTB.","Was ist noch unklar?":"Τι παραμένει ασαφές;","Zu Beginn ist noch nicht sicher, ob es wirklich ein primäres Lungenkarzinom ist.":"Αρχικά δεν είναι ακόμη βέβαιο ότι πρόκειται πράγματι για πρωτοπαθές καρκίνωμα του πνεύμονα.","Anamnese und klinischer Kontext":"Ιατρικό ιστορικό και κλινικό πλαίσιο","Raucherstatus":"Ιστορικό καπνίσματος","Ex-Raucher, 15 pack years; seit 20 Jahren abstinent.":"Πρώην καπνιστής, 15 πακετο-έτη· διακοπή καπνίσματος πριν από 20 χρόνια.","Performance / Situation":"Λειτουργική κατάσταση / κλινική κατάσταση","ECOG 1, keine kurative Option, systemische Therapie zeitnah geplant.":"ECOG 1, χωρίς δυνατότητα ίασης· προγραμματίζεται άμεσα συστηματική θεραπεία.","Vorbefunde":"Προηγούμενα ευρήματα","Keine frühere Tumorerkrankung bekannt.":"Δεν υπάρχει γνωστό ιστορικό προηγούμενης νεοπλασίας.","MTB-Zeitdruck":"Χρονική πίεση για το MTB","Fall soll in 7 Tagen im MTB vorgestellt werden.":"Το περιστατικό πρέπει να παρουσιαστεί στο MTB σε 7 ημέρες.","Histologie + Vor-IHC":"Ιστολογία και αρχική IHC","HE":"H&E","Infiltrate eines nicht-kleinzelligen Karzinoms in kleiner Bronchialbiopsie.":"Διηθήσεις μη μικροκυτταρικού καρκινώματος σε μικρή βρογχική βιοψία.","TTF-1 positiv, Napsin A positiv, CK7 positiv; p40/CK5/6 negativ.":"TTF-1 θετικό, Napsin A θετικό και CK7 θετικό· p40 και CK5/6 αρνητικά.","Proliferation":"Κυτταρικός πολλαπλασιασμός","Ki67 ca. 35 %.":"Ki67 περίπου 35%.","Arbeitsdiagnose":"Προσωρινή διάγνωση","Pulmonales Adenokarzinom / NSCLC, Stadium IV wahrscheinlich.":"Πνευμονικό αδενοκαρκίνωμα / NSCLC, πιθανώς σταδίου IV.","Noch offen":"Εκκρεμεί","PD-L1 und molekulares Treiberprofil fehlen.":"Εκκρεμούν η PD-L1 και το μοριακό προφίλ οδηγών αλλοιώσεων.","Materialprüfung":"Αξιολόγηση ιστικού υλικού","Material":"Ιστικό υλικό","FFPE-Biopsie, Block B2.":"Βιοψία FFPE, κύβος B2.","Tumoranteil":"Ποσοστό νεοπλασματικών κυττάρων","ca. 25–30 %, Makrodissektion empfohlen.":"Περίπου 25–30%· συνιστάται μακροδιατομή.","Nekrose":"Νέκρωση","fokal, aber beurteilbare Tumorareale vorhanden.":"Εστιακή, αλλά υπάρχουν αξιολογήσιμες νεοπλασματικές περιοχές.","Verfügbare ungefärbte Schnitte":"Διαθέσιμες μη χρωματισμένες τομές","12 Schnitte planbar.":"Μπορούν να διατεθούν 12 τομές.","DNA/RNA-Prognose":"Αναμενόμενη απόδοση DNA/RNA","DNA wahrscheinlich ausreichend; RNA bei kleiner Biopsie potenziell grenzwertig.":"Το DNA είναι πιθανώς επαρκές· το RNA μπορεί να είναι οριακό σε αυτή τη μικρή βιοψία.","Materialfalle":"Παγίδα στη χρήση του ιστικού υλικού","Serielle Einzeltests können das Material verbrauchen, bevor RNA-Fusionen geprüft wurden.":"Οι διαδοχικές μεμονωμένες εξετάσεις μπορεί να εξαντλήσουν το ιστικό υλικό πριν ελεγχθούν οι συντήξεις RNA.","EML4::ALK-Fusion":"Σύντηξη EML4::ALK","TPS 5 %":"TPS 5%","keine EGFR/KRAS/BRAF/METex14/ERBB2-Hotspot-Alteration":"Καμία hotspot αλλοίωση EGFR/KRAS/BRAF/METex14/ERBB2","DNA ausreichend; RNA knapp, aber verwertbar":"DNA επαρκές· RNA περιορισμένο αλλά αξιοποιήσιμο","Metastasiertes Lungenadenokarzinom, kleine Biopsie: vollständige prädiktive Diagnostik ohne Materialverschwendung":"Μεταστατικό αδενοκαρκίνωμα πνεύμονα, μικρή βιοψία: πλήρης έλεγχος προβλεπτικών βιοδεικτών χωρίς σπατάλη ιστικού υλικού","MTB Basics":"Βασικές αρχές MTB","Pathologieassistenz / MTB-Einstieg":"Ειδικευόμενος/η παθολογικής ανατομικής / εισαγωγή στο MTB","12-15":"12–15","Treiber-, Fusions- und PD-L1-Diagnostik beim metastasierten NSCLC parallel und materialschonend planen.":"Σχεδιάστε παράλληλα τον έλεγχο οδηγών αλλοιώσεων, συντήξεων και PD-L1 στο μεταστατικό NSCLC, με ορθολογική χρήση του ιστικού υλικού.","DNA-only-Strategien bei fusionsrelevanter Fragestellung als potenziell unvollständig erkennen.":"Αναγνωρίστε ότι οι στρατηγικές μόνο με DNA μπορεί να είναι ελλιπείς όταν οι συντήξεις είναι κλινικά σημαντικές.","Befundlimitationen bei kleiner Biopsie und begrenztem Tumoranteil klar im MTB kommunizieren.":"Επικοινωνήστε με σαφήνεια στο MTB τους περιορισμούς της αναφοράς λόγω μικρής βιοψίας και περιορισμένου ποσοστού νεοπλασματικών κυττάρων.","Montagmorgen, Tumorboard-Vorbereitung: Eine Bronchialbiopsie eines neu metastasierten Lungenkarzinoms liegt vor. Die Onkologie möchte innerhalb einer Woche wissen, ob eine zielgerichtete Therapie oder Immuntherapie infrage kommt. Das Material ist sichtbar knapp, aber die Therapieentscheidung hängt jetzt an der Pathologie.":"Δευτέρα πρωί, κατά την προετοιμασία του ογκολογικού συμβουλίου: έχει παραληφθεί βρογχική βιοψία από πρόσφατα διαγνωσμένο μεταστατικό καρκίνωμα πνεύμονα. Η ογκολογική ομάδα χρειάζεται μέσα σε μία εβδομάδα να γνωρίζει αν ενδείκνυται στοχευμένη θεραπεία ή ανοσοθεραπεία. Το ιστικό υλικό είναι εμφανώς περιορισμένο, αλλά η θεραπευτική απόφαση εξαρτάται πλέον από την παθολογική ανατομική.","68-jähriger Patient, ehemaliger Raucher, multiple pulmonale und ossäre Metastasen. Klinische Anfrage: 'Bitte molekulare Therapierbarkeit prüfen, Erstlinientherapie soll im MTB festgelegt werden.' Vorbefund aus der Pathologie: Adenokarzinom der Lunge, nicht-kleinzellig, keine Resektionsoption.":"Ασθενής 68 ετών, πρώην καπνιστής, με πολλαπλές πνευμονικές και οστικές μεταστάσεις. Κλινικό αίτημα: «Παρακαλείστε να αξιολογήσετε πιθανές μοριακά στοχεύσιμες αλλοιώσεις· η θεραπεία πρώτης γραμμής θα καθοριστεί στο MTB». Προκαταρκτική παθολογοανατομική διάγνωση: μη μικροκυτταρικό αδενοκαρκίνωμα πνεύμονα, χωρίς δυνατότητα εκτομής.","Klinischer Druck":"Κλινική πίεση","Der Patient ist symptomatisch, aber klinisch stabil. Eine Entscheidung über TKI vs. Immun-/Chemotherapie soll in 7 Tagen fallen.":"Ο ασθενής είναι συμπτωματικός αλλά κλινικά σταθερός. Εντός 7 ημερών πρέπει να ληφθεί απόφαση μεταξύ θεραπείας με TKI και ανοσοθεραπείας/χημειοθεραπείας.","Zeitdruck rechtfertigt parallele, nicht sequentielle Diagnostik.":"Η χρονική πίεση δικαιολογεί παράλληλο και όχι διαδοχικό έλεγχο.","Histologie":"Ιστολογία","Kleine Bronchialbiopsie mit invasivem Adenokarzinom. TTF-1 und Napsin A positiv, p40/CK5/6 negativ, CK7 positiv. Ki-67 ca. 35–40%.":"Μικρή βρογχική βιοψία με διηθητικό αδενοκαρκίνωμα. TTF-1 και Napsin A θετικά, p40/CK5/6 αρνητικά, CK7 θετικό. Ki-67 περίπου 35–40%.","Die Entität ist ausreichend eingegrenzt; jetzt geht es um prädiktive Marker.":"Η οντότητα έχει προσδιοριστεί επαρκώς· το επόμενο βήμα αφορά τους προβλεπτικούς βιοδείκτες.","Tumorareal ca. 25%, fokal Nekrose. Nach Diagnostik bleiben geschätzt 8 unstained Slides. RNA-Qualität ist nicht garantiert, aber noch plausibel nutzbar.":"Η νεοπλασματική περιοχή είναι περίπου 25%, με εστιακή νέκρωση. Μετά τον έως τώρα έλεγχο εκτιμάται ότι απομένουν 8 μη χρωματισμένες τομές. Η ποιότητα του RNA δεν είναι εγγυημένη, αλλά πιθανώς παραμένει κατάλληλη για ανάλυση.","Material Stewardship ist Teil der richtigen Entscheidung.":"Η ορθολογική διαχείριση του ιστικού υλικού αποτελεί μέρος της σωστής απόφασης.","MTB-Frage":"Ερώτημα για το MTB","Die Onkologie fragt explizit nach EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS und PD-L1.":"Η ογκολογική ομάδα ζητά ρητά έλεγχο των EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS και PD-L1.","Die Anfrage spricht gegen eine reine EGFR-PCR als alleinige Strategie.":"Το αίτημα αυτό δεν υποστηρίζει τη χρήση μόνο PCR για EGFR ως μοναδικής στρατηγικής.","invasives Lungenadenokarzinom, mäßig differenziert, kleine Biopsie.":"Διηθητικό, μέτρια διαφοροποιημένο αδενοκαρκίνωμα πνεύμονα σε μικρή βιοψία.","TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; PD-L1 noch nicht erfolgt.":"TTF-1+, Napsin A+, CK7+, p40−, CK5/6−· η PD-L1 δεν έχει ακόμη πραγματοποιηθεί.","Material-QC":"QC ιστικού υλικού","Tumorzellanteil ausreichend, aber knapp; RNA-Fusionsdiagnostik sollte nicht durch unnötige Zusatztests gefährdet werden.":"Το ποσοστό νεοπλασματικών κυττάρων είναι επαρκές αλλά περιορισμένο· ο έλεγχος συντήξεων RNA δεν πρέπει να τεθεί σε κίνδυνο από περιττές πρόσθετες εξετάσεις.","maximal 8 Schnitte verfügbar; unnötige IHC-/Methylierungs-/HRD-Tests reduzieren die Chance auf vollständige Molekulardiagnostik.":"Είναι διαθέσιμες το πολύ 8 τομές· περιττές εξετάσεις IHC, μεθυλίωσης ή HRD μειώνουν την πιθανότητα ολοκλήρωσης του μοριακού ελέγχου.","TAT-Ziel: 7 Kalendertage bis MTB.":"Στόχος TAT: 7 ημερολογιακές ημέρες έως το MTB.","DNA und RNA sollten möglichst aus demselben markierten Tumorareal gewonnen werden.":"Το DNA και το RNA θα πρέπει, εφόσον είναι δυνατόν, να εξαχθούν από την ίδια επισημασμένη νεοπλασματική περιοχή.","Was ist die zentrale klinische Fragestellung?":"Ποιο είναι το κεντρικό κλινικό ερώτημα;","Vollständige prädiktive Erstliniendiagnostik mit Treibern, Fusionen und PD-L1":"Πλήρης έλεγχος προβλεπτικών βιοδεικτών πρώτης γραμμής για οδηγές αλλοιώσεις, συντήξεις και PD-L1","Lynch-Syndrom-Abklärung":"Διερεύνηση συνδρόμου Lynch","HRD/PARP-Indikation":"Ένδειξη HRD/PARP","Infektionsdiagnostik":"Λοιμωξιολογικός έλεγχος","Beim metastasierten Lungenadenokarzinom steht die therapieentscheidende Treiber-/Fusions-/PD-L1-Diagnostik im Vordergrund.":"Στο μεταστατικό αδενοκαρκίνωμα πνεύμονα προτεραιότητα έχει ο έλεγχος οδηγών αλλοιώσεων, συντήξεων και PD-L1 που καθορίζει τη θεραπεία.","Was ist das wichtigste Materialrisiko?":"Ποιος είναι ο σημαντικότερος κίνδυνος που αφορά το ιστικό υλικό;","Kleine Biopsie mit begrenztem Tumorareal und potenzieller RNA-Fragilität":"Μικρή βιοψία με περιορισμένη νεοπλασματική περιοχή και πιθανή ευθραυστότητα του RNA","Material spielt bei NGS praktisch keine Rolle":"Το ιστικό υλικό πρακτικά δεν έχει σημασία για το NGS","Plasma ersetzt Gewebe grundsätzlich":"Το πλάσμα αντικαθιστά πάντα το ιστικό υλικό","Methylierung sollte grundsätzlich zuerst erfolgen":"Ο έλεγχος μεθυλίωσης πρέπει να γίνεται πάντα πρώτος","Die vollständige Diagnostik muss materialschonend und priorisiert geplant werden.":"Ο πλήρης διαγνωστικός έλεγχος πρέπει να ιεραρχείται και να σχεδιάζεται με τρόπο που να διαφυλάσσει το ιστικό υλικό.","Warum ist DNA-NGS allein in diesem Fall riskant?":"Γιατί είναι επικίνδυνη η χρήση μόνο DNA-NGS σε αυτό το περιστατικό;","Relevante Genfusionen können unzureichend erfasst werden, RNA-Fusionsdiagnostik ergänzt die Aussage":"Σημαντικές γονιδιακές συντήξεις μπορεί να ανιχνευθούν ανεπαρκώς· ο έλεγχος συντήξεων RNA συμπληρώνει την πληροφορία","DNA-NGS detektiert keine Mutationen":"Το DNA-NGS δεν ανιχνεύει μεταλλάξεις","PD-L1 wird zuverlässig aus DNA abgeleitet":"Η PD-L1 μπορεί να εξαχθεί αξιόπιστα από το DNA","Fusionen sind nur beim CRC relevant":"Οι συντήξεις είναι σημαντικές μόνο στον καρκίνο του παχέος εντέρου","DNA-NGS ist für SNV/Indels stark, aber RNA-basierte Verfahren sind für relevante Fusionen häufig die bessere Ergänzung.":"Το DNA-NGS αποδίδει καλά για SNV και indels, αλλά οι μέθοδοι που βασίζονται στο RNA αποτελούν συχνά την καλύτερη συμπλήρωση για κλινικά σημαντικές συντήξεις.","Wähle eine materialschonende Primäranforderung, die die Erstlinientherapie im MTB belastbar unterstützt.":"Επιλέξτε ένα αρχικό αίτημα εξετάσεων που διαφυλάσσει το ιστικό υλικό και υποστηρίζει αξιόπιστα την απόφαση θεραπείας πρώτης γραμμής στο MTB.","PD-L1-IHC parallel anfordern.":"Ζητήστε παράλληλα IHC για PD-L1.","DNA-basiertes Lungen-/Solid-Tumor-Panel für SNV/Indels/CNV inkl. EGFR, KRAS, BRAF, MET, ERBB2.":"Πάνελ πνεύμονα/συμπαγών όγκων βασισμένο σε DNA για SNV, indels και CNV, συμπεριλαμβανομένων EGFR, KRAS, BRAF, MET και ERBB2.","RNA-Fusionspanel für ALK, ROS1, RET, NTRK und weitere relevante Fusionen.":"Πάνελ συντήξεων RNA για ALK, ROS1, RET, NTRK και άλλες σημαντικές συντήξεις.","Tumorareal markieren und unnötige entitätsfremde Zusatzdiagnostik vermeiden.":"Επισημάνετε τη νεοπλασματική περιοχή και αποφύγετε περιττές πρόσθετες εξετάσεις άσχετες με την οντότητα.","Befund mit Methodengrenzen und Materialqualität berichten.":"Αναφέρετε τα ευρήματα μαζί με τους περιορισμούς της μεθόδου και την ποιότητα του ιστικού υλικού.","Bei extremem Zeitdruck kann EGFR-Schnelltest zusätzlich erfolgen, ersetzt aber nicht die Panel-/Fusionsdiagnostik.":"Σε συνθήκες ακραίας χρονικής πίεσης μπορεί να προστεθεί ταχεία εξέταση EGFR, αλλά δεν αντικαθιστά τον έλεγχο με πάνελ και συντήξεων.","ALK-IHC/FISH kann als schnelle Ergänzung sinnvoll sein, aber nicht als alleinige umfassende Strategie.":"Η IHC/FISH για ALK μπορεί να είναι χρήσιμη ως ταχεία συμπληρωματική εξέταση, αλλά όχι ως μοναδική ολοκληρωμένη στρατηγική.","MLH1-Methylierung":"Μεθυλίωση του υποκινητή MLH1","Ohne dMMR-/CRC-/Lynch-Kontext entitätsfremd und materialverbrauchend.":"Χωρίς πλαίσιο dMMR, καρκίνου παχέος εντέρου ή Lynch, η εξέταση είναι άσχετη με την οντότητα και καταναλώνει ιστικό υλικό.","HRD-Score":"Βαθμολογία HRD","Für die primäre NSCLC-Erstlinienentscheidung nicht zielführend.":"Δεν είναι χρήσιμο για την αρχική απόφαση θεραπείας πρώτης γραμμής στο NSCLC.","EGFR-PCR allein":"Μόνο PCR για EGFR","Kann EGFR beantworten, lässt aber viele therapeutisch relevante Alterationen offen.":"Μπορεί να απαντήσει στο ερώτημα του EGFR, αλλά αφήνει πολλές θεραπευτικά σημαντικές αλλοιώσεις χωρίς αξιολόγηση.","DNA-negativ ist nicht automatisch treibernegativ":"Αρνητικό αποτέλεσμα στο DNA δεν σημαίνει αυτομάτως απουσία οδηγού αλλοίωσης","Wenn nur DNA-NGS und PD-L1 angefordert werden, ergibt sich ein Teilbefund: kein EGFR/KRAS/BRAF/METex14-Nachweis, PD-L1 TPS 5%. Erst bei RNA-Fusionsdiagnostik wird eine EML4::ALK-Fusion detektiert.":"Εάν ζητηθούν μόνο DNA-NGS και PD-L1, το αποτέλεσμα είναι ελλιπές: δεν ανιχνεύεται αλλοίωση EGFR/KRAS/BRAF/METex14 και η PD-L1 TPS είναι 5%. Η σύντηξη EML4::ALK ανιχνεύεται μόνο μετά από έλεγχο συντήξεων RNA.","Die therapeutisch entscheidende Alteration wäre bei zu enger Primäranforderung verzögert oder verpasst worden.":"Η αλλοίωση που καθορίζει τη θεραπεία θα είχε καθυστερήσει ή χαθεί με ένα υπερβολικά περιορισμένο αρχικό αίτημα.","Vollständige Primäranforderung":"Πλήρες αρχικό αίτημα εξετάσεων","PD-L1 TPS 5%; DNA-Panel ohne EGFR/KRAS/BRAF/METex14; RNA-Panel mit EML4::ALK-Fusion.":"PD-L1 TPS 5%· το πάνελ DNA είναι αρνητικό για EGFR/KRAS/BRAF/METex14· το πάνελ RNA ανιχνεύει σύντηξη EML4::ALK.","Sehr gute Strategie: vollständige prädiktive Diagnostik bei kleinem Material und direkter therapeutischer Konsequenz.":"Πολύ καλή στρατηγική: πλήρης προβλεπτικός έλεγχος σε περιορισμένο ιστικό υλικό, με άμεση θεραπευτική συνέπεια.","DNA-NGS + PD-L1 ohne RNA":"DNA-NGS και PD-L1 χωρίς έλεγχο RNA","Teilbefund ohne SNV/Indel-Treiber, PD-L1 TPS 5%; Fusionsstatus nicht ausreichend beurteilt.":"Ελλιπές αποτέλεσμα χωρίς ανίχνευση οδηγού SNV/indel και με PD-L1 TPS 5%· η κατάσταση των συντήξεων δεν έχει αξιολογηθεί επαρκώς.","Richtige Richtung, aber unvollständig. Nachforderung RNA rettet den Fall, kostet aber Material und TAT.":"Η γενική κατεύθυνση είναι σωστή, αλλά ο έλεγχος είναι ελλιπής. Ο συμπληρωματικός έλεγχος RNA επιλύει το περιστατικό, αλλά κοστίζει ιστικό υλικό και TAT.","Breite, entitätsfremde Zusatzdiagnostik":"Εκτεταμένες πρόσθετες εξετάσεις άσχετες με την οντότητα","Vollständige Zielmarker ggf. verfügbar, aber unnötiger Materialverbrauch durch MMR/MLH1/HRD etc.":"Οι απαιτούμενοι στόχοι μπορεί τελικά να είναι διαθέσιμοι, αλλά καταναλώνεται άσκοπα ιστικό υλικό από εξετάσεις MMR, MLH1, HRD κ.ά.","Diagnostisch nicht katastrophal, aber Material Stewardship und Kommunikation leiden deutlich.":"Δεν αποτελεί διαγνωστική καταστροφή, αλλά η ορθολογική διαχείριση του ιστικού υλικού και η επικοινωνία επηρεάζονται σαφώς.","Nachforderung RNA-Fusionspanel anbieten":"Προτείνετε συμπληρωματικό πάνελ συντήξεων RNA","Ergebnis wird vollständig, aber Score-Cap wegen vermeidbarer Verzögerung.":"Το αποτέλεσμα ολοκληρώνεται, αλλά εφαρμόζεται ανώτατο όριο βαθμολογίας λόγω της αποτρέψιμης καθυστέρησης.","im Bericht als low value/misleading ausweisen":"Χαρακτηρίστε στην αναφορά ως χαμηλής αξίας ή παραπλανητικό","Abzug bei Method Selection, Material Stewardship und Communication.":"Αφαίρεση βαθμών στην Επιλογή μεθόδων, την Ορθολογική χρήση υλικού και την Επικοινωνία.","Beim metastasierten NSCLC ist die klinische Frage breit prädiktiv, nicht nur EGFR-orientiert.":"Στο μεταστατικό NSCLC, το κλινικό ερώτημα απαιτεί ευρύ προβλεπτικό έλεγχο και δεν περιορίζεται στο EGFR.","Fusionen sind ein klassischer Grund, DNA-only-Strategien kritisch zu hinterfragen.":"Οι συντήξεις αποτελούν κλασικό λόγο για κριτική αξιολόγηση στρατηγικών μόνο με DNA.","Kleine Biopsie heißt nicht weniger Diagnostik, sondern bessere Priorisierung.":"Μικρή βιοψία δεν σημαίνει λιγότερες εξετάσεις, αλλά καλύτερη ιεράρχηση.","Optimale Lösung: PD-L1-IHC + DNA-NGS + RNA-Fusionspanel parallel, mit Materialhinweis und klarer MTB-Kommunikation. EGFR-Schnelltest nur als Zusatz bei Zeitdruck.":"Ενδεικτική λύση: IHC για PD-L1, DNA-NGS και πάνελ συντήξεων RNA παράλληλα, με αναφορά στη διαθεσιμότητα ιστικού υλικού και σαφή επικοινωνία στο MTB. Η ταχεία εξέταση EGFR αποτελεί μόνο συμπληρωματική επιλογή όταν υπάρχει χρονική πίεση.","Clinical Reasoning: Erstlinienfrage erkannt":"Κλινικός συλλογισμός: αναγνωρίστηκε το ερώτημα θεραπείας πρώτης γραμμής","Method Selection: DNA/RNA/PD-L1 korrekt kombiniert":"Επιλογή μεθόδων: σωστός συνδυασμός DNA, RNA και PD-L1","Material Stewardship: entitätsfremde Tests vermieden":"Ορθολογική χρήση υλικού: αποφεύχθηκαν εξετάσεις άσχετες με την οντότητα","Wann wäre Liquid Biopsy zusätzlich sinnvoll?":"Πότε θα ήταν χρήσιμη μια συμπληρωματική υγρή βιοψία;","Wie kommuniziert man 'kein Treiber nachgewiesen' ohne RNA-Fusionsergebnis?":"Πώς πρέπει να επικοινωνείται το «δεν ανιχνεύθηκε οδηγός αλλοίωση» όταν δεν υπάρχει αποτέλεσμα ελέγχου συντήξεων RNA;","Welche Rolle spielt PD-L1 bei nachgewiesener ALK-Fusion?":"Ποιος είναι ο ρόλος της PD-L1 όταν έχει ανιχνευθεί σύντηξη ALK;","Twist / kritischer Wendepunkt: DNA-only hätte ALK verzögert":"Ανατροπή / κρίσιμο σημείο καμπής: μια στρατηγική μόνο με DNA θα καθυστερούσε την ανίχνευση ALK","Typische Fehler: EGFR-only, RNA vergessen, Material durch Low-value-Tests verbraucht":"Τυπικά σφάλματα: έλεγχος μόνο EGFR, παράλειψη ελέγχου RNA και κατανάλωση ιστικού υλικού από εξετάσεις χαμηλής αξίας","Musterpfad: PD-L1 + DNA + RNA parallel":"Ενδεικτική διαδρομή: PD-L1, DNA και RNA παράλληλα","RNA-Fusionsdiagnostik primär fehlt":"Λείπει ο αρχικός έλεγχος συντήξεων RNA","entitätsfremde Tests gewählt":"Επιλέχθηκαν εξετάσεις που δεν σχετίζονται με την οντότητα του όγκου","Core/MVP prüfen":"Έλεγχος για βασικό περιεχόμενο/MVP","MTB; Länge=Standard; Schwierigkeit=Intermediate; Status=curated-core":"MTB· διάρκεια=τυπική· δυσκολία=ενδιάμεση· κατάσταση=curated-core"},"es":{"NSCLC":"NSCLC","IHC":"IHC","DNA-NGS":"NGS de ADN","RNA-NGS":"NGS de ARN","PD-L1":"PD-L1","ALK":"ALK","Materialbudget":"Reserva de tejido","MTB":"MTB","Zentrale klinisch-molekulare Fragestellung aus Anamnese, Histologie und Materialkontext ableiten":"Deducir la pregunta clínico-molecular central a partir de la anamnesis, la histología y el contexto del tejido","Passende molekulare/IHC-basierte Methode zur Kernentscheidung auswählen":"Seleccionar el método molecular o basado en IHC adecuado para la decisión principal","Musterlösung im MTB klar, limitiert und patientenrelevant kommunizieren":"Comunicar con claridad la solución de referencia en el MTB, incluidas las limitaciones y la relevancia para el paciente","Pulmonale Raumforderung → NSCLC → molekulare Therapieentscheidung":"Masa pulmonar → NSCLC → decisión terapéutica basada en datos moleculares","Onkogene Treiber / NSCLC / Resistenz":"Alteraciones oncogénicas driver / NSCLC / resistencia","NSCLC → molekulare Therapieentscheidung":"NSCLC → decisión terapéutica basada en datos moleculares","NSCLC Erstdiagnose":"Diagnóstico inicial de NSCLC","Initialer Auftrag":"Solicitud inicial","Einsender":"Solicitante","Onkologie / Bronchoskopie":"Oncología / broncoscopia","Klinische Information":"Información clínica","67-jähriger Patient, pulmonale Raumforderung links, multiple kleine Leberherde im CT.":"Paciente de 67 años con masa pulmonar izquierda y múltiples lesiones hepáticas pequeñas en la TC.","Fragestellung":"Pregunta clínica","Malignität? Primarius? Therapieentscheidende Diagnostik für MTB.":"¿Malignidad? ¿Tumor primario? Diagnóstico determinante para el tratamiento en el MTB.","Was ist noch unklar?":"¿Qué sigue sin estar claro?","Zu Beginn ist noch nicht sicher, ob es wirklich ein primäres Lungenkarzinom ist.":"Al inicio todavía no está claro que se trate realmente de un carcinoma pulmonar primario.","Anamnese und klinischer Kontext":"Anamnesis y contexto clínico","Raucherstatus":"Antecedentes de tabaquismo","Ex-Raucher, 15 pack years; seit 20 Jahren abstinent.":"Exfumador, 15 paquetes-año; dejó de fumar hace 20 años.","Performance / Situation":"Estado funcional / situación clínica","ECOG 1, keine kurative Option, systemische Therapie zeitnah geplant.":"ECOG 1, sin opción curativa; se prevé iniciar pronto tratamiento sistémico.","Vorbefunde":"Resultados previos","Keine frühere Tumorerkrankung bekannt.":"No se conoce ninguna neoplasia previa.","MTB-Zeitdruck":"Presión de tiempo para el MTB","Fall soll in 7 Tagen im MTB vorgestellt werden.":"El caso debe presentarse en el MTB dentro de 7 días.","Histologie + Vor-IHC":"Histología e IHC inicial","HE":"H&E","Infiltrate eines nicht-kleinzelligen Karzinoms in kleiner Bronchialbiopsie.":"Infiltrados de carcinoma no microcítico en una biopsia bronquial pequeña.","TTF-1 positiv, Napsin A positiv, CK7 positiv; p40/CK5/6 negativ.":"TTF-1 positivo, Napsina A positiva y CK7 positivo; p40 y CK5/6 negativos.","Proliferation":"Proliferación","Ki67 ca. 35 %.":"Ki67 aproximadamente 35%.","Arbeitsdiagnose":"Diagnóstico de trabajo","Pulmonales Adenokarzinom / NSCLC, Stadium IV wahrscheinlich.":"Adenocarcinoma pulmonar / NSCLC, probablemente estadio IV.","Noch offen":"Pendiente","PD-L1 und molekulares Treiberprofil fehlen.":"Faltan PD-L1 y el perfil molecular de alteraciones driver.","Materialprüfung":"Evaluación del tejido","Material":"Tejido","FFPE-Biopsie, Block B2.":"Biopsia FFPE, bloque B2.","Tumoranteil":"Porcentaje tumoral","ca. 25–30 %, Makrodissektion empfohlen.":"Aproximadamente 25–30%; se recomienda macrodissección.","Nekrose":"Necrosis","fokal, aber beurteilbare Tumorareale vorhanden.":"Focal, pero existen áreas tumorales evaluables.","Verfügbare ungefärbte Schnitte":"Cortes sin teñir disponibles","12 Schnitte planbar.":"Se pueden asignar 12 cortes.","DNA/RNA-Prognose":"Previsión de rendimiento de ADN/ARN","DNA wahrscheinlich ausreichend; RNA bei kleiner Biopsie potenziell grenzwertig.":"El ADN probablemente sea suficiente; el ARN puede ser limitado en esta biopsia pequeña.","Materialfalle":"Riesgo de agotamiento del tejido","Serielle Einzeltests können das Material verbrauchen, bevor RNA-Fusionen geprüft wurden.":"Las pruebas individuales secuenciales pueden agotar el tejido antes de evaluar las fusiones de ARN.","EML4::ALK-Fusion":"Fusión EML4::ALK","TPS 5 %":"TPS 5%","keine EGFR/KRAS/BRAF/METex14/ERBB2-Hotspot-Alteration":"Sin alteraciones hotspot en EGFR/KRAS/BRAF/METex14/ERBB2","DNA ausreichend; RNA knapp, aber verwertbar":"ADN suficiente; ARN limitado pero analizable","Metastasiertes Lungenadenokarzinom, kleine Biopsie: vollständige prädiktive Diagnostik ohne Materialverschwendung":"Adenocarcinoma pulmonar metastásico, biopsia pequeña: diagnóstico predictivo completo sin desperdiciar tejido","MTB Basics":"Fundamentos del MTB","Pathologieassistenz / MTB-Einstieg":"Residente de anatomía patológica / introducción al MTB","12-15":"12–15","Treiber-, Fusions- und PD-L1-Diagnostik beim metastasierten NSCLC parallel und materialschonend planen.":"Planificar en paralelo el estudio de alteraciones driver, fusiones y PD-L1 en el NSCLC metastásico, preservando el tejido.","DNA-only-Strategien bei fusionsrelevanter Fragestellung als potenziell unvollständig erkennen.":"Reconocer que las estrategias basadas solo en ADN pueden ser incompletas cuando las fusiones son clínicamente relevantes.","Befundlimitationen bei kleiner Biopsie und begrenztem Tumoranteil klar im MTB kommunizieren.":"Comunicar claramente en el MTB las limitaciones del informe derivadas de una biopsia pequeña y un porcentaje tumoral limitado.","Montagmorgen, Tumorboard-Vorbereitung: Eine Bronchialbiopsie eines neu metastasierten Lungenkarzinoms liegt vor. Die Onkologie möchte innerhalb einer Woche wissen, ob eine zielgerichtete Therapie oder Immuntherapie infrage kommt. Das Material ist sichtbar knapp, aber die Therapieentscheidung hängt jetzt an der Pathologie.":"Lunes por la mañana, preparando el comité de tumores: se dispone de una biopsia bronquial de un carcinoma pulmonar metastásico recién diagnosticado. Oncología necesita saber en una semana si procede una terapia dirigida o inmunoterapia. El tejido es claramente limitado, pero la decisión terapéutica depende ahora de anatomía patológica.","68-jähriger Patient, ehemaliger Raucher, multiple pulmonale und ossäre Metastasen. Klinische Anfrage: 'Bitte molekulare Therapierbarkeit prüfen, Erstlinientherapie soll im MTB festgelegt werden.' Vorbefund aus der Pathologie: Adenokarzinom der Lunge, nicht-kleinzellig, keine Resektionsoption.":"Paciente de 68 años, exfumador, con múltiples metástasis pulmonares y óseas. Solicitud clínica: «Valorar opciones terapéuticas moleculares; el tratamiento de primera línea se decidirá en el MTB». Diagnóstico anatomopatológico preliminar: adenocarcinoma pulmonar no microcítico, sin opción de resección.","Klinischer Druck":"Urgencia clínica","Der Patient ist symptomatisch, aber klinisch stabil. Eine Entscheidung über TKI vs. Immun-/Chemotherapie soll in 7 Tagen fallen.":"El paciente presenta síntomas, pero está clínicamente estable. En 7 días debe tomarse una decisión entre tratamiento con TKI e inmunoterapia/quimioterapia.","Zeitdruck rechtfertigt parallele, nicht sequentielle Diagnostik.":"La presión de tiempo justifica realizar las pruebas en paralelo y no de forma secuencial.","Histologie":"Histología","Kleine Bronchialbiopsie mit invasivem Adenokarzinom. TTF-1 und Napsin A positiv, p40/CK5/6 negativ, CK7 positiv. Ki-67 ca. 35–40%.":"Biopsia bronquial pequeña con adenocarcinoma invasivo. TTF-1 y Napsina A positivos, p40/CK5/6 negativos, CK7 positivo. Ki-67 aproximadamente 35–40%.","Die Entität ist ausreichend eingegrenzt; jetzt geht es um prädiktive Marker.":"La entidad tumoral está suficientemente definida; ahora el objetivo son los biomarcadores predictivos.","Tumorareal ca. 25%, fokal Nekrose. Nach Diagnostik bleiben geschätzt 8 unstained Slides. RNA-Qualität ist nicht garantiert, aber noch plausibel nutzbar.":"Área tumoral aproximada del 25%, con necrosis focal. Tras el estudio realizado se estima que quedan 8 portaobjetos sin teñir. La calidad del ARN no está garantizada, pero todavía puede ser adecuada para el análisis.","Material Stewardship ist Teil der richtigen Entscheidung.":"La gestión responsable del tejido forma parte de la decisión correcta.","MTB-Frage":"Pregunta para el MTB","Die Onkologie fragt explizit nach EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS und PD-L1.":"Oncología solicita expresamente el estudio de EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS y PD-L1.","Die Anfrage spricht gegen eine reine EGFR-PCR als alleinige Strategie.":"Esta solicitud desaconseja utilizar únicamente una PCR de EGFR como estrategia exclusiva.","invasives Lungenadenokarzinom, mäßig differenziert, kleine Biopsie.":"Adenocarcinoma pulmonar invasivo, moderadamente diferenciado, en una biopsia pequeña.","TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; PD-L1 noch nicht erfolgt.":"TTF-1+, Napsina A+, CK7+, p40−, CK5/6−; el estudio de PD-L1 aún no se ha realizado.","Material-QC":"QC del tejido","Tumorzellanteil ausreichend, aber knapp; RNA-Fusionsdiagnostik sollte nicht durch unnötige Zusatztests gefährdet werden.":"El porcentaje tumoral es suficiente, pero limitado; el estudio de fusiones de ARN no debe verse comprometido por pruebas adicionales innecesarias.","maximal 8 Schnitte verfügbar; unnötige IHC-/Methylierungs-/HRD-Tests reduzieren die Chance auf vollständige Molekulardiagnostik.":"Hay un máximo de 8 cortes disponibles; las pruebas innecesarias de IHC, metilación o HRD reducen la posibilidad de completar el estudio molecular.","TAT-Ziel: 7 Kalendertage bis MTB.":"Objetivo de TAT: 7 días naturales hasta el MTB.","DNA und RNA sollten möglichst aus demselben markierten Tumorareal gewonnen werden.":"El ADN y el ARN deben extraerse, siempre que sea posible, de la misma área tumoral marcada.","Was ist die zentrale klinische Fragestellung?":"¿Cuál es la pregunta clínica central?","Vollständige prädiktive Erstliniendiagnostik mit Treibern, Fusionen und PD-L1":"Diagnóstico predictivo completo de primera línea de alteraciones driver, fusiones y PD-L1","Lynch-Syndrom-Abklärung":"Estudio del síndrome de Lynch","HRD/PARP-Indikation":"Indicación de HRD/PARP","Infektionsdiagnostik":"Diagnóstico de infección","Beim metastasierten Lungenadenokarzinom steht die therapieentscheidende Treiber-/Fusions-/PD-L1-Diagnostik im Vordergrund.":"En el adenocarcinoma pulmonar metastásico, la prioridad es el estudio determinante para el tratamiento de alteraciones driver, fusiones y PD-L1.","Was ist das wichtigste Materialrisiko?":"¿Cuál es el principal riesgo relacionado con el tejido?","Kleine Biopsie mit begrenztem Tumorareal und potenzieller RNA-Fragilität":"Biopsia pequeña con área tumoral limitada y ARN potencialmente frágil","Material spielt bei NGS praktisch keine Rolle":"El tejido apenas tiene importancia para el NGS","Plasma ersetzt Gewebe grundsätzlich":"El plasma sustituye siempre al tejido","Methylierung sollte grundsätzlich zuerst erfolgen":"El estudio de metilación debe realizarse siempre primero","Die vollständige Diagnostik muss materialschonend und priorisiert geplant werden.":"El estudio diagnóstico completo debe priorizarse y planificarse para preservar el tejido.","Warum ist DNA-NGS allein in diesem Fall riskant?":"¿Por qué es arriesgado utilizar solo NGS de ADN en este caso?","Relevante Genfusionen können unzureichend erfasst werden, RNA-Fusionsdiagnostik ergänzt die Aussage":"Las fusiones génicas relevantes pueden detectarse de forma insuficiente; el estudio de fusiones de ARN aporta información complementaria","DNA-NGS detektiert keine Mutationen":"La NGS de ADN no detecta mutaciones","PD-L1 wird zuverlässig aus DNA abgeleitet":"PD-L1 puede inferirse de forma fiable a partir del ADN","Fusionen sind nur beim CRC relevant":"Las fusiones solo son relevantes en el cáncer colorrectal","DNA-NGS ist für SNV/Indels stark, aber RNA-basierte Verfahren sind für relevante Fusionen häufig die bessere Ergänzung.":"La NGS de ADN funciona bien para SNV e indels, pero los métodos basados en ARN suelen ser el mejor complemento para las fusiones clínicamente relevantes.","Wähle eine materialschonende Primäranforderung, die die Erstlinientherapie im MTB belastbar unterstützt.":"Elija una solicitud inicial de pruebas que preserve el tejido y sustente de forma sólida la decisión de tratamiento de primera línea en el MTB.","PD-L1-IHC parallel anfordern.":"Solicitar en paralelo IHC de PD-L1.","DNA-basiertes Lungen-/Solid-Tumor-Panel für SNV/Indels/CNV inkl. EGFR, KRAS, BRAF, MET, ERBB2.":"Panel pulmonar/de tumores sólidos basado en ADN para SNV, indels y CNV, incluidos EGFR, KRAS, BRAF, MET y ERBB2.","RNA-Fusionspanel für ALK, ROS1, RET, NTRK und weitere relevante Fusionen.":"Panel de fusiones de ARN para ALK, ROS1, RET, NTRK y otras fusiones relevantes.","Tumorareal markieren und unnötige entitätsfremde Zusatzdiagnostik vermeiden.":"Marcar el área tumoral y evitar pruebas adicionales innecesarias ajenas a la entidad tumoral.","Befund mit Methodengrenzen und Materialqualität berichten.":"Informar los resultados junto con las limitaciones del método y la calidad del tejido.","Bei extremem Zeitdruck kann EGFR-Schnelltest zusätzlich erfolgen, ersetzt aber nicht die Panel-/Fusionsdiagnostik.":"Con una presión de tiempo extrema puede añadirse una prueba rápida de EGFR, pero no sustituye el estudio mediante panel y de fusiones.","ALK-IHC/FISH kann als schnelle Ergänzung sinnvoll sein, aber nicht als alleinige umfassende Strategie.":"La IHC/FISH de ALK puede ser útil como complemento rápido, pero no como única estrategia integral.","MLH1-Methylierung":"Metilación del promotor de MLH1","Ohne dMMR-/CRC-/Lynch-Kontext entitätsfremd und materialverbrauchend.":"Sin un contexto de dMMR, cáncer colorrectal o Lynch, esta prueba no guarda relación con la entidad y consume tejido.","HRD-Score":"Puntuación HRD","Für die primäre NSCLC-Erstlinienentscheidung nicht zielführend.":"No es pertinente para la decisión inicial de primera línea en NSCLC.","EGFR-PCR allein":"PCR de EGFR como única prueba","Kann EGFR beantworten, lässt aber viele therapeutisch relevante Alterationen offen.":"Puede responder a la pregunta sobre EGFR, pero deja sin evaluar muchas alteraciones relevantes para el tratamiento.","DNA-negativ ist nicht automatisch treibernegativ":"Un resultado negativo en ADN no significa automáticamente ausencia de una alteración driver","Wenn nur DNA-NGS und PD-L1 angefordert werden, ergibt sich ein Teilbefund: kein EGFR/KRAS/BRAF/METex14-Nachweis, PD-L1 TPS 5%. Erst bei RNA-Fusionsdiagnostik wird eine EML4::ALK-Fusion detektiert.":"Si solo se solicitan NGS de ADN y PD-L1, el resultado es incompleto: no se detectan alteraciones en EGFR/KRAS/BRAF/METex14 y el TPS de PD-L1 es del 5%. La fusión EML4::ALK solo se identifica al realizar el estudio de fusiones de ARN.","Die therapeutisch entscheidende Alteration wäre bei zu enger Primäranforderung verzögert oder verpasst worden.":"La alteración determinante para el tratamiento se habría detectado tarde o se habría pasado por alto con una solicitud inicial demasiado limitada.","Vollständige Primäranforderung":"Solicitud inicial completa","PD-L1 TPS 5%; DNA-Panel ohne EGFR/KRAS/BRAF/METex14; RNA-Panel mit EML4::ALK-Fusion.":"TPS de PD-L1 del 5%; panel de ADN negativo para EGFR/KRAS/BRAF/METex14; panel de ARN con fusión EML4::ALK.","Sehr gute Strategie: vollständige prädiktive Diagnostik bei kleinem Material und direkter therapeutischer Konsequenz.":"Muy buena estrategia: diagnóstico predictivo completo con tejido limitado y una consecuencia terapéutica directa.","DNA-NGS + PD-L1 ohne RNA":"NGS de ADN y PD-L1 sin estudio de ARN","Teilbefund ohne SNV/Indel-Treiber, PD-L1 TPS 5%; Fusionsstatus nicht ausreichend beurteilt.":"Resultado incompleto, sin alteración driver SNV/indel identificada y con TPS de PD-L1 del 5%; el estado de las fusiones no se ha evaluado adecuadamente.","Richtige Richtung, aber unvollständig. Nachforderung RNA rettet den Fall, kostet aber Material und TAT.":"La orientación general es correcta, pero el estudio está incompleto. La prueba adicional de ARN resuelve el caso, pero consume tejido y aumenta el TAT.","Breite, entitätsfremde Zusatzdiagnostik":"Pruebas adicionales amplias ajenas a la entidad tumoral","Vollständige Zielmarker ggf. verfügbar, aber unnötiger Materialverbrauch durch MMR/MLH1/HRD etc.":"Los marcadores objetivo necesarios pueden llegar a estar disponibles, pero se consume tejido de forma innecesaria con pruebas de MMR, MLH1, HRD, etc.","Diagnostisch nicht katastrophal, aber Material Stewardship und Kommunikation leiden deutlich.":"No es un desastre diagnóstico, pero la gestión responsable del tejido y la comunicación se ven claramente perjudicadas.","Nachforderung RNA-Fusionspanel anbieten":"Ofrecer un panel adicional de fusiones de ARN","Ergebnis wird vollständig, aber Score-Cap wegen vermeidbarer Verzögerung.":"El resultado queda completo, pero se aplica un límite de puntuación por el retraso evitable.","im Bericht als low value/misleading ausweisen":"Indicar en el informe que se trata de una prueba de bajo valor o potencialmente engañosa","Abzug bei Method Selection, Material Stewardship und Communication.":"Penalización en Selección de métodos, Uso responsable del material y Comunicación.","Beim metastasierten NSCLC ist die klinische Frage breit prädiktiv, nicht nur EGFR-orientiert.":"En el NSCLC metastásico, la pregunta clínica requiere un estudio predictivo amplio y no se limita a EGFR.","Fusionen sind ein klassischer Grund, DNA-only-Strategien kritisch zu hinterfragen.":"Las fusiones son un motivo clásico para cuestionar críticamente las estrategias basadas solo en ADN.","Kleine Biopsie heißt nicht weniger Diagnostik, sondern bessere Priorisierung.":"Una biopsia pequeña no significa menos pruebas, sino una mejor priorización.","Optimale Lösung: PD-L1-IHC + DNA-NGS + RNA-Fusionspanel parallel, mit Materialhinweis und klarer MTB-Kommunikation. EGFR-Schnelltest nur als Zusatz bei Zeitdruck.":"Solución de referencia: IHC de PD-L1, NGS de ADN y panel de fusiones de ARN en paralelo, con una nota sobre la disponibilidad de tejido y una comunicación clara en el MTB. La prueba rápida de EGFR es solo un complemento cuando existe presión de tiempo.","Clinical Reasoning: Erstlinienfrage erkannt":"Razonamiento clínico: se identificó la pregunta sobre el tratamiento de primera línea","Method Selection: DNA/RNA/PD-L1 korrekt kombiniert":"Selección de métodos: combinación correcta de ADN, ARN y PD-L1","Material Stewardship: entitätsfremde Tests vermieden":"Uso responsable del material: se evitaron pruebas ajenas a la entidad tumoral","Wann wäre Liquid Biopsy zusätzlich sinnvoll?":"¿Cuándo sería útil añadir una biopsia líquida?","Wie kommuniziert man 'kein Treiber nachgewiesen' ohne RNA-Fusionsergebnis?":"¿Cómo debe comunicarse «no se ha detectado ninguna alteración driver» si no se dispone del resultado de fusiones de ARN?","Welche Rolle spielt PD-L1 bei nachgewiesener ALK-Fusion?":"¿Qué papel desempeña PD-L1 cuando se ha detectado una fusión de ALK?","Twist / kritischer Wendepunkt: DNA-only hätte ALK verzögert":"Giro / punto de inflexión crítico: una estrategia basada solo en ADN habría retrasado la detección de ALK","Typische Fehler: EGFR-only, RNA vergessen, Material durch Low-value-Tests verbraucht":"Errores típicos: estudio exclusivo de EGFR, olvido del análisis de ARN y consumo de tejido por pruebas de bajo valor","Musterpfad: PD-L1 + DNA + RNA parallel":"Ruta de referencia: PD-L1, ADN y ARN en paralelo","RNA-Fusionsdiagnostik primär fehlt":"Falta el estudio primario de fusiones de ARN","entitätsfremde Tests gewählt":"Se seleccionaron pruebas no pertinentes para la entidad tumoral","Core/MVP prüfen":"Revisar para contenido central/MVP","MTB; Länge=Standard; Schwierigkeit=Intermediate; Status=curated-core":"MTB; duración=estándar; dificultad=intermedia; estado=curated-core"},"fr":{"NSCLC":"NSCLC","IHC":"IHC","DNA-NGS":"NGS ADN","RNA-NGS":"NGS ARN","PD-L1":"PD-L1","ALK":"ALK","Materialbudget":"Capital tissulaire","MTB":"MTB","Zentrale klinisch-molekulare Fragestellung aus Anamnese, Histologie und Materialkontext ableiten":"Dégager la question clinico-moléculaire centrale à partir de l’anamnèse, de l’histologie et du contexte tissulaire","Passende molekulare/IHC-basierte Methode zur Kernentscheidung auswählen":"Sélectionner la méthode moléculaire ou fondée sur l’IHC adaptée à la décision centrale","Musterlösung im MTB klar, limitiert und patientenrelevant kommunizieren":"Communiquer clairement la solution de référence en MTB, avec ses limites et sa pertinence pour le patient","Pulmonale Raumforderung → NSCLC → molekulare Therapieentscheidung":"Masse pulmonaire → NSCLC → décision thérapeutique guidée par les données moléculaires","Onkogene Treiber / NSCLC / Resistenz":"Altérations oncogéniques conductrices / NSCLC / résistance","NSCLC → molekulare Therapieentscheidung":"NSCLC → décision thérapeutique guidée par les données moléculaires","NSCLC Erstdiagnose":"Diagnostic initial de NSCLC","Initialer Auftrag":"Demande initiale","Einsender":"Prescripteur","Onkologie / Bronchoskopie":"Oncologie / bronchoscopie","Klinische Information":"Informations cliniques","67-jähriger Patient, pulmonale Raumforderung links, multiple kleine Leberherde im CT.":"Patient de 67 ans présentant une masse pulmonaire gauche et de multiples petites lésions hépatiques au scanner.","Fragestellung":"Question clinique","Malignität? Primarius? Therapieentscheidende Diagnostik für MTB.":"Malignité ? Site primitif ? Bilan diagnostique déterminant pour le traitement en MTB.","Was ist noch unklar?":"Que reste-t-il à clarifier ?","Zu Beginn ist noch nicht sicher, ob es wirklich ein primäres Lungenkarzinom ist.":"Au départ, il n’est pas encore certain qu’il s’agisse réellement d’un carcinome pulmonaire primitif.","Anamnese und klinischer Kontext":"Anamnèse et contexte clinique","Raucherstatus":"Statut tabagique","Ex-Raucher, 15 pack years; seit 20 Jahren abstinent.":"Ancien fumeur, 15 paquets-années ; sevré depuis 20 ans.","Performance / Situation":"Indice de performance / situation clinique","ECOG 1, keine kurative Option, systemische Therapie zeitnah geplant.":"ECOG 1, aucune option curative ; un traitement systémique est prévu rapidement.","Vorbefunde":"Résultats antérieurs","Keine frühere Tumorerkrankung bekannt.":"Aucun antécédent de cancer n’est connu.","MTB-Zeitdruck":"Contrainte de délai pour le MTB","Fall soll in 7 Tagen im MTB vorgestellt werden.":"Le cas doit être présenté en MTB dans 7 jours.","Histologie + Vor-IHC":"Histologie et IHC initiale","HE":"H&E","Infiltrate eines nicht-kleinzelligen Karzinoms in kleiner Bronchialbiopsie.":"Infiltrats d’un carcinome non à petites cellules dans une petite biopsie bronchique.","TTF-1 positiv, Napsin A positiv, CK7 positiv; p40/CK5/6 negativ.":"TTF-1 positif, Napsine A positive et CK7 positif ; p40 et CK5/6 négatifs.","Proliferation":"Prolifération","Ki67 ca. 35 %.":"Ki67 d’environ 35 %.","Arbeitsdiagnose":"Diagnostic de travail","Pulmonales Adenokarzinom / NSCLC, Stadium IV wahrscheinlich.":"Adénocarcinome pulmonaire / NSCLC, probablement de stade IV.","Noch offen":"À compléter","PD-L1 und molekulares Treiberprofil fehlen.":"L’analyse de PD-L1 et le profil moléculaire des altérations conductrices restent à réaliser.","Materialprüfung":"Évaluation du matériel tissulaire","Material":"Matériel tissulaire","FFPE-Biopsie, Block B2.":"Biopsie FFPE, bloc B2.","Tumoranteil":"Cellularité tumorale","ca. 25–30 %, Makrodissektion empfohlen.":"Environ 25–30 % ; macrodissection recommandée.","Nekrose":"Nécrose","fokal, aber beurteilbare Tumorareale vorhanden.":"Focale, mais des zones tumorales évaluables sont présentes.","Verfügbare ungefärbte Schnitte":"Coupes non colorées disponibles","12 Schnitte planbar.":"12 coupes peuvent être prévues.","DNA/RNA-Prognose":"Rendement attendu en ADN/ARN","DNA wahrscheinlich ausreichend; RNA bei kleiner Biopsie potenziell grenzwertig.":"L’ADN est probablement suffisant ; l’ARN peut être limite dans cette petite biopsie.","Materialfalle":"Piège lié à l’utilisation du tissu","Serielle Einzeltests können das Material verbrauchen, bevor RNA-Fusionen geprüft wurden.":"Des tests unitaires séquentiels peuvent épuiser le tissu avant l’évaluation des fusions d’ARN.","EML4::ALK-Fusion":"Fusion EML4::ALK","TPS 5 %":"TPS 5 %","keine EGFR/KRAS/BRAF/METex14/ERBB2-Hotspot-Alteration":"Aucune altération hotspot d’EGFR/KRAS/BRAF/METex14/ERBB2","DNA ausreichend; RNA knapp, aber verwertbar":"ADN suffisant ; ARN limité mais exploitable","Metastasiertes Lungenadenokarzinom, kleine Biopsie: vollständige prädiktive Diagnostik ohne Materialverschwendung":"Adénocarcinome pulmonaire métastatique, petite biopsie : bilan prédictif complet sans gaspillage tissulaire","MTB Basics":"Bases du MTB","Pathologieassistenz / MTB-Einstieg":"Interne en anatomopathologie / initiation au MTB","12-15":"12–15","Treiber-, Fusions- und PD-L1-Diagnostik beim metastasierten NSCLC parallel und materialschonend planen.":"Planifier en parallèle l’analyse des altérations conductrices, des fusions et de PD-L1 dans le NSCLC métastatique, en préservant le tissu.","DNA-only-Strategien bei fusionsrelevanter Fragestellung als potenziell unvollständig erkennen.":"Reconnaître qu’une stratégie fondée uniquement sur l’ADN peut être incomplète lorsque les fusions sont cliniquement pertinentes.","Befundlimitationen bei kleiner Biopsie und begrenztem Tumoranteil klar im MTB kommunizieren.":"Communiquer clairement en MTB les limites du compte rendu liées à la petite biopsie et à la faible cellularité tumorale.","Montagmorgen, Tumorboard-Vorbereitung: Eine Bronchialbiopsie eines neu metastasierten Lungenkarzinoms liegt vor. Die Onkologie möchte innerhalb einer Woche wissen, ob eine zielgerichtete Therapie oder Immuntherapie infrage kommt. Das Material ist sichtbar knapp, aber die Therapieentscheidung hängt jetzt an der Pathologie.":"Lundi matin, préparation de la réunion de concertation : une biopsie bronchique d’un carcinome pulmonaire métastatique récemment diagnostiqué est disponible. L’oncologie souhaite savoir dans un délai d’une semaine si une thérapie ciblée ou une immunothérapie est envisageable. Le matériel tissulaire est manifestement limité, mais la décision thérapeutique dépend désormais de l’anatomopathologie.","68-jähriger Patient, ehemaliger Raucher, multiple pulmonale und ossäre Metastasen. Klinische Anfrage: 'Bitte molekulare Therapierbarkeit prüfen, Erstlinientherapie soll im MTB festgelegt werden.' Vorbefund aus der Pathologie: Adenokarzinom der Lunge, nicht-kleinzellig, keine Resektionsoption.":"Patient de 68 ans, ancien fumeur, présentant de multiples métastases pulmonaires et osseuses. Demande clinique : « Évaluer les altérations moléculaires potentiellement ciblables ; le traitement de première ligne sera défini en MTB. » Diagnostic anatomopathologique préliminaire : adénocarcinome pulmonaire non à petites cellules, non résécable.","Klinischer Druck":"Urgence clinique","Der Patient ist symptomatisch, aber klinisch stabil. Eine Entscheidung über TKI vs. Immun-/Chemotherapie soll in 7 Tagen fallen.":"Le patient est symptomatique mais cliniquement stable. Une décision entre un traitement par TKI et une immunothérapie/chimiothérapie doit être prise dans les 7 jours.","Zeitdruck rechtfertigt parallele, nicht sequentielle Diagnostik.":"La contrainte de délai justifie des analyses parallèles plutôt que séquentielles.","Histologie":"Histologie","Kleine Bronchialbiopsie mit invasivem Adenokarzinom. TTF-1 und Napsin A positiv, p40/CK5/6 negativ, CK7 positiv. Ki-67 ca. 35–40%.":"Petite biopsie bronchique montrant un adénocarcinome invasif. TTF-1 et Napsine A positifs, p40/CK5/6 négatifs, CK7 positif. Ki-67 d’environ 35–40 %.","Die Entität ist ausreichend eingegrenzt; jetzt geht es um prädiktive Marker.":"L’entité tumorale est suffisamment caractérisée ; l’enjeu porte désormais sur les biomarqueurs prédictifs.","Tumorareal ca. 25%, fokal Nekrose. Nach Diagnostik bleiben geschätzt 8 unstained Slides. RNA-Qualität ist nicht garantiert, aber noch plausibel nutzbar.":"Zone tumorale d’environ 25 %, avec nécrose focale. Après le bilan déjà réalisé, il resterait environ 8 lames non colorées. La qualité de l’ARN n’est pas garantie, mais elle reste vraisemblablement compatible avec une analyse.","Material Stewardship ist Teil der richtigen Entscheidung.":"La gestion responsable du tissu fait partie de la bonne décision.","MTB-Frage":"Question pour le MTB","Die Onkologie fragt explizit nach EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS und PD-L1.":"L’oncologie demande explicitement l’analyse d’EGFR/ALK/ROS1/RET/NTRK/MET/HER2/BRAF/KRAS et de PD-L1.","Die Anfrage spricht gegen eine reine EGFR-PCR als alleinige Strategie.":"Cette demande va à l’encontre d’une stratégie reposant uniquement sur une PCR EGFR.","invasives Lungenadenokarzinom, mäßig differenziert, kleine Biopsie.":"Adénocarcinome pulmonaire invasif, moyennement différencié, sur petite biopsie.","TTF-1+, Napsin A+, CK7+, p40−, CK5/6−; PD-L1 noch nicht erfolgt.":"TTF-1+, Napsine A+, CK7+, p40−, CK5/6− ; l’analyse de PD-L1 n’a pas encore été réalisée.","Material-QC":"CQ du matériel tissulaire","Tumorzellanteil ausreichend, aber knapp; RNA-Fusionsdiagnostik sollte nicht durch unnötige Zusatztests gefährdet werden.":"La cellularité tumorale est suffisante mais limitée ; l’analyse des fusions d’ARN ne doit pas être compromise par des examens complémentaires inutiles.","maximal 8 Schnitte verfügbar; unnötige IHC-/Methylierungs-/HRD-Tests reduzieren die Chance auf vollständige Molekulardiagnostik.":"Au maximum 8 coupes sont disponibles ; des analyses IHC, de méthylation ou HRD inutiles réduisent la probabilité de mener à terme le bilan moléculaire.","TAT-Ziel: 7 Kalendertage bis MTB.":"Objectif de TAT : 7 jours calendaires avant le MTB.","DNA und RNA sollten möglichst aus demselben markierten Tumorareal gewonnen werden.":"L’ADN et l’ARN doivent, dans la mesure du possible, être extraits de la même zone tumorale repérée.","Was ist die zentrale klinische Fragestellung?":"Quelle est la question clinique centrale ?","Vollständige prädiktive Erstliniendiagnostik mit Treibern, Fusionen und PD-L1":"Bilan prédictif complet de première ligne portant sur les altérations conductrices, les fusions et PD-L1","Lynch-Syndrom-Abklärung":"Exploration d’un syndrome de Lynch","HRD/PARP-Indikation":"Indication HRD/PARP","Infektionsdiagnostik":"Diagnostic infectieux","Beim metastasierten Lungenadenokarzinom steht die therapieentscheidende Treiber-/Fusions-/PD-L1-Diagnostik im Vordergrund.":"Dans l’adénocarcinome pulmonaire métastatique, la priorité est le bilan des altérations conductrices, des fusions et de PD-L1 qui détermine le traitement.","Was ist das wichtigste Materialrisiko?":"Quel est le principal risque lié au matériel tissulaire ?","Kleine Biopsie mit begrenztem Tumorareal und potenzieller RNA-Fragilität":"Petite biopsie avec zone tumorale limitée et ARN potentiellement fragile","Material spielt bei NGS praktisch keine Rolle":"La disponibilité du tissu n’a pratiquement aucune importance pour le NGS","Plasma ersetzt Gewebe grundsätzlich":"Le plasma remplace systématiquement le tissu","Methylierung sollte grundsätzlich zuerst erfolgen":"L’analyse de la méthylation doit toujours être réalisée en premier","Die vollständige Diagnostik muss materialschonend und priorisiert geplant werden.":"Le bilan diagnostique complet doit être hiérarchisé et planifié de manière à préserver le tissu.","Warum ist DNA-NGS allein in diesem Fall riskant?":"Pourquoi une analyse NGS de l’ADN seule est-elle risquée dans ce cas ?","Relevante Genfusionen können unzureichend erfasst werden, RNA-Fusionsdiagnostik ergänzt die Aussage":"Des fusions géniques pertinentes peuvent être insuffisamment détectées ; l’analyse des fusions d’ARN complète l’information","DNA-NGS detektiert keine Mutationen":"Le NGS de l’ADN ne détecte pas les mutations","PD-L1 wird zuverlässig aus DNA abgeleitet":"PD-L1 peut être déduit de manière fiable à partir de l’ADN","Fusionen sind nur beim CRC relevant":"Les fusions ne sont pertinentes que dans le cancer colorectal","DNA-NGS ist für SNV/Indels stark, aber RNA-basierte Verfahren sind für relevante Fusionen häufig die bessere Ergänzung.":"Le NGS de l’ADN est performant pour les SNV et les indels, mais les méthodes fondées sur l’ARN constituent souvent le meilleur complément pour les fusions cliniquement pertinentes.","Wähle eine materialschonende Primäranforderung, die die Erstlinientherapie im MTB belastbar unterstützt.":"Choisissez une demande initiale d’analyses qui préserve le tissu et étaye solidement la décision de traitement de première ligne en MTB.","PD-L1-IHC parallel anfordern.":"Demander en parallèle une IHC PD-L1.","DNA-basiertes Lungen-/Solid-Tumor-Panel für SNV/Indels/CNV inkl. EGFR, KRAS, BRAF, MET, ERBB2.":"Panel pulmonaire/tumeurs solides fondé sur l’ADN pour les SNV, les indels et les CNV, comprenant EGFR, KRAS, BRAF, MET et ERBB2.","RNA-Fusionspanel für ALK, ROS1, RET, NTRK und weitere relevante Fusionen.":"Panel de fusions d’ARN pour ALK, ROS1, RET, NTRK et d’autres fusions pertinentes.","Tumorareal markieren und unnötige entitätsfremde Zusatzdiagnostik vermeiden.":"Repérer la zone tumorale et éviter les examens complémentaires inutiles sans rapport avec l’entité tumorale.","Befund mit Methodengrenzen und Materialqualität berichten.":"Rendre les résultats en précisant les limites de la méthode et la qualité du matériel tissulaire.","Bei extremem Zeitdruck kann EGFR-Schnelltest zusätzlich erfolgen, ersetzt aber nicht die Panel-/Fusionsdiagnostik.":"En cas de contrainte de délai extrême, un test rapide EGFR peut être ajouté, mais il ne remplace pas le panel ni l’analyse des fusions.","ALK-IHC/FISH kann als schnelle Ergänzung sinnvoll sein, aber nicht als alleinige umfassende Strategie.":"L’IHC/FISH ALK peut être utile comme complément rapide, mais pas comme stratégie exhaustive unique.","MLH1-Methylierung":"Méthylation du promoteur de MLH1","Ohne dMMR-/CRC-/Lynch-Kontext entitätsfremd und materialverbrauchend.":"En l’absence de contexte dMMR, colorectal ou Lynch, cet examen est sans rapport avec l’entité tumorale et consomme du tissu.","HRD-Score":"Score HRD","Für die primäre NSCLC-Erstlinienentscheidung nicht zielführend.":"Non pertinent pour la décision initiale de traitement de première ligne dans le NSCLC.","EGFR-PCR allein":"PCR EGFR seule","Kann EGFR beantworten, lässt aber viele therapeutisch relevante Alterationen offen.":"Elle peut répondre à la question d’EGFR, mais laisse de nombreuses altérations pertinentes pour le traitement non évaluées.","DNA-negativ ist nicht automatisch treibernegativ":"Un résultat négatif sur l’ADN ne signifie pas automatiquement l’absence d’altération conductrice","Wenn nur DNA-NGS und PD-L1 angefordert werden, ergibt sich ein Teilbefund: kein EGFR/KRAS/BRAF/METex14-Nachweis, PD-L1 TPS 5%. Erst bei RNA-Fusionsdiagnostik wird eine EML4::ALK-Fusion detektiert.":"Si seuls le NGS de l’ADN et PD-L1 sont demandés, le résultat est incomplet : aucune altération d’EGFR/KRAS/BRAF/METex14 n’est détectée et le TPS de PD-L1 est de 5 %. La fusion EML4::ALK n’est identifiée qu’après analyse des fusions d’ARN.","Die therapeutisch entscheidende Alteration wäre bei zu enger Primäranforderung verzögert oder verpasst worden.":"L’altération déterminante pour le traitement aurait été retardée ou manquée avec une demande initiale trop restreinte.","Vollständige Primäranforderung":"Demande initiale complète","PD-L1 TPS 5%; DNA-Panel ohne EGFR/KRAS/BRAF/METex14; RNA-Panel mit EML4::ALK-Fusion.":"TPS de PD-L1 à 5 % ; panel ADN négatif pour EGFR/KRAS/BRAF/METex14 ; panel ARN mettant en évidence une fusion EML4::ALK.","Sehr gute Strategie: vollständige prädiktive Diagnostik bei kleinem Material und direkter therapeutischer Konsequenz.":"Très bonne stratégie : bilan prédictif complet sur un matériel tissulaire limité, avec une conséquence thérapeutique directe.","DNA-NGS + PD-L1 ohne RNA":"NGS ADN et PD-L1 sans analyse de l’ARN","Teilbefund ohne SNV/Indel-Treiber, PD-L1 TPS 5%; Fusionsstatus nicht ausreichend beurteilt.":"Résultat incomplet sans altération conductrice de type SNV/indel identifiée, avec un TPS de PD-L1 à 5 % ; le statut des fusions n’est pas évalué de manière adéquate.","Richtige Richtung, aber unvollständig. Nachforderung RNA rettet den Fall, kostet aber Material und TAT.":"L’orientation générale est correcte, mais le bilan est incomplet. L’analyse complémentaire de l’ARN permet de résoudre le cas, au prix d’une consommation de tissu et d’un allongement du TAT.","Breite, entitätsfremde Zusatzdiagnostik":"Bilan complémentaire large sans rapport avec l’entité tumorale","Vollständige Zielmarker ggf. verfügbar, aber unnötiger Materialverbrauch durch MMR/MLH1/HRD etc.":"Les marqueurs cibles requis peuvent malgré tout être disponibles, mais du tissu est inutilement consommé par des analyses MMR, MLH1, HRD, etc.","Diagnostisch nicht katastrophal, aber Material Stewardship und Kommunikation leiden deutlich.":"Ce n’est pas une catastrophe diagnostique, mais la gestion responsable du tissu et la communication sont nettement compromises.","Nachforderung RNA-Fusionspanel anbieten":"Proposer un panel complémentaire de fusions d’ARN","Ergebnis wird vollständig, aber Score-Cap wegen vermeidbarer Verzögerung.":"Le résultat devient complet, mais un plafond de score s’applique en raison du retard évitable.","im Bericht als low value/misleading ausweisen":"Signaler dans le compte rendu comme examen de faible valeur ou potentiellement trompeur","Abzug bei Method Selection, Material Stewardship und Communication.":"Pénalité dans les domaines Sélection des méthodes, Gestion responsable du matériel et Communication.","Beim metastasierten NSCLC ist die klinische Frage breit prädiktiv, nicht nur EGFR-orientiert.":"Dans le NSCLC métastatique, la question clinique nécessite un bilan prédictif large et ne se limite pas à EGFR.","Fusionen sind ein klassischer Grund, DNA-only-Strategien kritisch zu hinterfragen.":"Les fusions constituent une raison classique de remettre en question les stratégies fondées uniquement sur l’ADN.","Kleine Biopsie heißt nicht weniger Diagnostik, sondern bessere Priorisierung.":"Une petite biopsie ne signifie pas moins d’analyses, mais une meilleure hiérarchisation.","Optimale Lösung: PD-L1-IHC + DNA-NGS + RNA-Fusionspanel parallel, mit Materialhinweis und klarer MTB-Kommunikation. EGFR-Schnelltest nur als Zusatz bei Zeitdruck.":"Solution de référence : IHC PD-L1, NGS ADN et panel de fusions d’ARN en parallèle, avec une mention sur la disponibilité du tissu et une communication claire en MTB. Le test rapide EGFR n’est qu’un complément en cas de forte contrainte de délai.","Clinical Reasoning: Erstlinienfrage erkannt":"Raisonnement clinique : la question du traitement de première ligne a été identifiée","Method Selection: DNA/RNA/PD-L1 korrekt kombiniert":"Sélection des méthodes : combinaison correcte de l’ADN, de l’ARN et de PD-L1","Material Stewardship: entitätsfremde Tests vermieden":"Gestion responsable du matériel : les examens sans rapport avec l’entité tumorale ont été évités","Wann wäre Liquid Biopsy zusätzlich sinnvoll?":"Quand une biopsie liquide serait-elle utile en complément ?","Wie kommuniziert man 'kein Treiber nachgewiesen' ohne RNA-Fusionsergebnis?":"Comment communiquer « aucune altération conductrice détectée » en l’absence de résultat sur les fusions d’ARN ?","Welche Rolle spielt PD-L1 bei nachgewiesener ALK-Fusion?":"Quel est le rôle de PD-L1 lorsqu’une fusion d’ALK a été détectée ?","Twist / kritischer Wendepunkt: DNA-only hätte ALK verzögert":"Rebondissement / point critique : une stratégie fondée uniquement sur l’ADN aurait retardé la détection d’ALK","Typische Fehler: EGFR-only, RNA vergessen, Material durch Low-value-Tests verbraucht":"Erreurs typiques : analyse d’EGFR seule, oubli de l’analyse de l’ARN et consommation de tissu par des examens de faible valeur","Musterpfad: PD-L1 + DNA + RNA parallel":"Parcours de référence : PD-L1, ADN et ARN en parallèle","RNA-Fusionsdiagnostik primär fehlt":"Le dépistage initial des fusions d’ARN est absent","entitätsfremde Tests gewählt":"Des analyses non pertinentes pour l’entité tumorale ont été sélectionnées","Core/MVP prüfen":"À vérifier pour le contenu principal/MVP","MTB; Länge=Standard; Schwierigkeit=Intermediate; Status=curated-core":"MTB ; durée=standard ; difficulté=intermédiaire ; statut=curated-core"}};
const LANGS=['de','en','ro','el','es','fr'];
let applying=false;
function langNow(){
  const x=(localStorage.getItem('molpath_lang')||document.documentElement.lang||'de').toLowerCase();
  return window.MolPathLanguageRegistry?window.MolPathLanguageRegistry.normalize(x):'de';
}
function clone(v){return JSON.parse(JSON.stringify(v));}
function patchStrings(target,de,localized){
  if(!target||de==null||localized==null)return;
  if(Array.isArray(de)&&Array.isArray(localized)&&Array.isArray(target)){
    const n=Math.min(de.length,localized.length,target.length);
    for(let i=0;i<n;i++){
      if(typeof de[i]==='string'&&typeof localized[i]==='string')target[i]=localized[i];
      else if(de[i]&&localized[i]&&target[i])patchStrings(target[i],de[i],localized[i]);
    }
    return;
  }
  if(typeof de==='object'&&typeof localized==='object'&&typeof target==='object'){
    for(const k of Object.keys(de)){
      if(!(k in localized)||!(k in target))continue;
      if(typeof de[k]==='string'&&typeof localized[k]==='string')target[k]=localized[k];
      else if(de[k]&&localized[k]&&target[k])patchStrings(target[k],de[k],localized[k]);
    }
  }
}
function findCase(){try{return (typeof cases!=='undefined'?cases:[]).find(c=>c&&c.id===CASE_ID)||null;}catch(_e){return null;}}
function findMeta(){try{return (typeof V15_META_RECORDS!=='undefined'?V15_META_RECORDS:[]).find(x=>x&&x.case_id===CASE_ID)||null;}catch(_e){return null;}}
function findDeep(){
  try{if(typeof DEEP_DIVE_MAP_V17!=='undefined'&&DEEP_DIVE_MAP_V17[CASE_ID])return DEEP_DIVE_MAP_V17[CASE_ID];}catch(_e){}
  try{return (typeof DEEP_DIVE_CASES_V17!=='undefined'?DEEP_DIVE_CASES_V17:[]).find(x=>x&&x.case_id===CASE_ID)||null;}catch(_e){return null;}
}
function mergeDictionary(){
  if(!window.MolPathI18n||!window.MolPathI18n.dict)return false;
  for(const lang of Object.keys(EXACT)){
    window.MolPathI18n.dict[lang]=window.MolPathI18n.dict[lang]||{};
    Object.assign(window.MolPathI18n.dict[lang],EXACT[lang]);
  }
  window.MolPathI18n.version=VERSION;
  window.MolPathI18n.deepDive01NSCLC={version:VERSION,caseId:CASE_ID,messages:148,locations:153,status:'approved_for_runtime_integration'};
  return true;
}
function applyLanguage(lang){
  if(applying)return false;
  applying=true;
  try{
    lang=window.MolPathLanguageRegistry?window.MolPathLanguageRegistry.normalize(lang):'de';
    const src=PAYLOAD.de;
    const loc=lang==='de'?PAYLOAD.de:(PAYLOAD.languages[lang]||PAYLOAD.de);
    if(!loc)return false;
    const c=findCase(); if(c)patchStrings(c,src.base_case,loc.base_case);
    const m=findMeta(); if(m)patchStrings(m,src.metadata,loc.metadata);
    const d=findDeep(); if(d)patchStrings(d,src.deep_dive,loc.deep_dive);
    try{if(typeof activeCase!=='undefined'&&activeCase&&activeCase.id===CASE_ID&&c&&activeCase!==c)patchStrings(activeCase,src.base_case,loc.base_case);}catch(_e){}
    return !!(c&&d);
  }finally{applying=false;}
}
function stampVersion(){
  try{
    const el=document.getElementById('versionBadge');
    if(el){el.setAttribute('data-i18n-skip','1');if(el.textContent!==VERSION)el.textContent=VERSION;}
  }catch(_e){}
  try{document.querySelectorAll('.v20b-topstatus .v20b-pill.primary').forEach(el=>{el.setAttribute('data-i18n-skip','1');if(el.textContent!==VERSION)el.textContent=VERSION;});}catch(_e){}
  try{const t='MolPath Simulator '+VERSION;if(document.title!==t)document.title=t;}catch(_e){}
}
const PREV_RENDER=window.render;
if(typeof PREV_RENDER==='function'){
  window.render=function(){
    applyLanguage(langNow());
    const out=PREV_RENDER.apply(this,arguments);
    setTimeout(function(){try{window.MolPathI18n&&window.MolPathI18n.apply();}catch(_e){}stampVersion();},0);
    return out;
  };
}
function boot(){
  mergeDictionary();
  applyLanguage(langNow());
  try{if(typeof window.render==='function')window.render();else if(window.MolPathI18n)window.MolPathI18n.apply();}catch(e){console.error('NSCLC i18n boot failed',e);}
  stampVersion();
}
if(!mergeDictionary()){let n=0;const timer=setInterval(function(){n++;if(mergeDictionary()||n>200)clearInterval(timer);},25);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(boot,0);},{once:true});else setTimeout(boot,0);
// Do not observe the whole document here. The base i18n observer rewrites translated text nodes;
// a second observer that repeatedly re-stamps the version badge can create a mutation ping-pong
// and starve click handlers while compositor scrolling still works.
document.addEventListener('change',function(ev){
  const target=ev&&ev.target;
  if(!target||target.id!=='molpathLangSelect')return;
  setTimeout(function(){
    applyLanguage(langNow());
    try{if(typeof window.render==='function')window.render();}catch(_e){}
    stampVersion();
  },30);
},true);
