const PAYLOAD={"block_id":"DEEPDIVE07_LAB_POST","case_id":"LAB_POST_001_v1_0","version":"1.0","created_at":"2026-08-10T08:42:00+02:00","status":"READY_FOR_USER_REVIEW","block_hash_sha256":"03ac63de20d2dfff4fbe9a3fc842e7dd3a4fe97d592ae949ab88fa0142d9a0aa","source_manifest":{"case_metadata":{"path":"data/case_metadata_v1_5_AP1b_final.json","sha256":"55daaaef3113885b3b5bc0c84d2bbdeefb106f4720cfd04c5d8d8929ccbcd3da"},"base_case":{"path":"data/cases_v1_4_universal_methods.json","sha256":"aaed62f7091c9706f0ea1cc6a5526a74ce7d5ca696d366f14ffbf99d043d7723"},"deep_dive":{"path":"data/deep_dive_cases_v1_7b.json","sha256":"6a7a097b61ce39a2883f6c1148e99bd9748a051238ac3cc18ede7fde49a86062"},"message_catalog":{"path":"i18n_message_catalog_v2_2_3.json","sha256":"4cd851992eed4fc35d6361a24810640196adf3e292cf49edc02fff27b0430ee6"},"index":{"path":"index.html","sha256":"d58ded509c788b2ffae30d6a2c96241f7377ffbbd5546428d2aa7e8f9dd9571a"}},"de":{"metadata":{"case_id":"LAB_POST_001_v1_0","base_id":"LAB_POST_001","title":"Pipeline-Version geändert, kein Change-Log → Bioinformatik-QM und Impact-Analyse","domain":"LAB","met_addon_type":"no","subdomain":"Postanalytik / Bioinformatik / Change-Control","case_type":"qm_capa_decision","length_class":"Complex","estimated_minutes":{"min":20,"max":30},"difficulty":"Advanced","status":"curated-core","review_flag":"Core/MVP prüfen","review_priority":"high","core_decision":"Variant Caller wurde von Version 3.4 auf 4.1 aktualisiert.","learning_objectives":["Patientensicherheits- und Qualitätsrisiko des Ereignisses korrekt priorisieren","Pipeline-/Softwareänderungen über Change-Control, Revalidierung und Versionierung absichern","Freigabe-, Sperr- oder Wiederholungsentscheidung auditfähig begründen"],"tags":["Bioinformatik","Pipeline","Versionierung","Change-Control","Audit","NGS, complex_case, AP1b_length_reclass"],"ap1b_decision":"LAB; Länge=Complex; Schwierigkeit=Advanced; Status=curated-core"},"base_case":{"id":"LAB_POST_001_v1_0","title":"Pipeline-Version geändert, kein Change-Log → Bioinformatik-QM und Impact-Analyse","short":"Pipeline ohne Change-Log","mode":"lab_qm","logic":"lab_pipeline","difficulty":"intermediate","estimated_time_min":"10–15","tags":["Bioinformatik","Pipeline","Versionierung","Change-Control","Audit","NGS"],"run_overview":{"System":"Targeted DNA-NGS Pipeline","Ausgangslage":"Variant Caller wurde von Version 3.4 auf 4.1 aktualisiert.","Dokumentation":"Kein Change-Log, keine formale Freigabe, keine Verifizierungsnotiz.","Betroffene Zeit":"2 Wochen Routinebetrieb.","Problem":"Zwei Varianten werden in der neuen Version anders gefiltert/klassifiziert."},"qc_title":"Nicht dokumentierte Pipelineänderung","qc_event":{"Auffälligkeit":"Alte und neue Auswertung sind nicht mehr eindeutig vergleichbar.","Risiko":"Falsch-negative oder falsch-positive Befundkonsequenzen, besonders bei therapieentscheidenden Varianten.","Audit-Risiko":"Rückverfolgbarkeit von Auswertungsschritten und Datenbank-/Pipelineversion fehlt.","Konflikt":"Weiterarbeiten mit neuer Software vs. Befunde pausieren und Impact klären."},"decision_options":[{"id":"do_nothing","label":"Nichts tun, neue Pipeline ist vermutlich besser.","kind":"bad","feedback":"Kritisch falsch: Softwareänderungen sind methodisch relevante Änderungen und müssen kontrolliert werden.","score":{"safety":0,"process":0,"documentation":0,"capa":0,"communication":0}},{"id":"bioinfo_only","label":"Nur Bioinformatik informieren, Laborbefunde weiter freigeben.","kind":"partial","feedback":"Unzureichend: Es geht um Befundvalidität, Freigabe und QM, nicht nur um Technik.","score":{"safety":8,"process":8,"documentation":4,"capa":2,"communication":4}},{"id":"impact_capa","label":"Abweichung eröffnen, Freigabe risikobasiert pausieren, betroffene Fälle identifizieren, Impact-Analyse und ggf. Reanalyse festlegen.","kind":"optimal","feedback":"Optimal: Change-Control, Patientensicherheit und Audit-Trail werden gesichert.","score":{"safety":30,"process":24,"documentation":18,"capa":14,"communication":8}},{"id":"recall_all","label":"Alle alten Befunde sofort pauschal zurückrufen.","kind":"partial","feedback":"Zu pauschal: Reanalyse/Rückruf müssen durch Impact- und Risikoanalyse begründet werden.","score":{"safety":20,"process":10,"documentation":10,"capa":8,"communication":6}}],"root_cause_options":[{"id":"affected_runs","label":"Alle Runs/Fälle im Zeitraum der neuen Pipelineversion identifizieren","correct":true,"feedback":"Ohne Fallliste keine Impact-Analyse."},{"id":"calling_vs_annotation","label":"Prüfen, ob Calling/Filtering oder nur Annotation betroffen ist","correct":true,"feedback":"Calling-/Filtering-Änderungen sind befundkritischer."},{"id":"released_reports","label":"Bereits freigegebene therapieentscheidende Befunde priorisieren","correct":true,"feedback":"Klinische Relevanz steuert Reanalysebedarf."},{"id":"ignore_negative","label":"Negative Fälle nicht prüfen","correct":false,"feedback":"Falsch: Gerade negative Befunde können betroffen sein."},{"id":"verification_set","label":"Referenz-/Verifizierungsdatensatz für Version 4.1 nachziehen","correct":true,"feedback":"Neue Versionen müssen lokal kontrolliert werden."}],"capa_components":[{"id":"dev","label":"Abweichung: nicht dokumentierte Pipelineänderung"},{"id":"pause","label":"Sofortmaßnahme: Freigaben risikobasiert pausieren/kontrollieren"},{"id":"impact","label":"Korrektur: Impact-Analyse und definierte Reanalyse"},{"id":"sop","label":"Prävention: SOP für Pipeline-Change mit Pflichtfeldern"},{"id":"eff","label":"Wirksamkeitsprüfung: nächste Änderungen vollständig dokumentiert"}],"audit_checks":[{"id":"version","label":"Alte/neue Pipelineversion und Zeitpunkt dokumentiert","correct":true},{"id":"risk","label":"Risikobewertung pro Befundklasse nachvollziehbar","correct":true},{"id":"approval","label":"Freigabe der neuen Pipelineversion dokumentiert","correct":true},{"id":"training","label":"Kommunikation/Schulung der betroffenen Personen dokumentiert","correct":true},{"id":"hide","label":"Change nur intern mündlich besprechen, nicht dokumentieren","correct":false}],"optimal_summary":"Optimale Lösung: Pipelineänderung als Abweichung behandeln, Impact-Analyse durchführen, betroffene Befunde risikobasiert reanalysieren und Change-Control für künftige Updates etablieren."},"deep_dive":{"version":"v1.7b","case_id":"LAB_POST_001_v1_0","title":"Pipeline-Version geändert, kein Change-Log: Bioinformatik-QM und Impact-Analyse","domain":"LAB","target_course":"Advanced Integrated","deep_dive_priority":"complex_anchor","target_role":"Laborleitung / Bioinformatik-QM","estimated_minutes_deep":"20-30","learning_objectives":["Pipeline-/Softwareänderungen als qualitätsrelevante Methodenänderung erkennen.","Impact-Analyse, Versionierung und Revalidierung/Verifizierung ableiten.","Befundfreigabe bei diskordanten Pipeline-Ergebnissen auditfähig steuern."],"opening_scene":"Ein Bioinformatik-Update wurde 'nur kurz' eingespielt, weil der neue Caller bessere Indel-Erkennung verspricht. Am nächsten Tag unterscheiden sich mehrere Variantenlisten von alten Ergebnissen. Ein Change-Log existiert nicht.","case_briefing":"Molekularpathologisches NGS-Panel, 48 Patientenfälle im aktuellen Batch. Variant Caller von 3.4 auf 4.1 aktualisiert. Referenzdatenbank und Annotation wurden ebenfalls minor aktualisiert. Die Änderung wurde nicht vorab in der QM-Dokumentation freigegeben.","context_cards":[{"title":"Diskordanz","content":"Bei 6/48 Fällen unterscheiden sich reportable variants. Ein Fall betrifft eine potenziell therapieentscheidende MET-Splice-Region.","teaching_point":"Nicht jede Softwareänderung ist rein technisch."},{"title":"Versionierung","content":"Im Berichtsentwurf ist keine Pipeline-Version angegeben; alte Reports enthalten nur 'NGS Pipeline'.","teaching_point":"Ohne Versionierung fehlt Rückverfolgbarkeit."},{"title":"Teamkonflikt","content":"Bioinformatik sagt: 'Der neue Caller ist besser.' QM fragt: 'Wo ist die Verifizierung?' Klinik wartet auf Befunde.","teaching_point":"Besser ist nicht gleich freigegeben."},{"title":"Risiko","content":"Sowohl falsch-positive als auch falsch-negative Änderungen sind möglich; Impact ist nicht auf einen Fall begrenzt.","teaching_point":"Impact-Analyse muss systematisch erfolgen."}],"pre_results":[{"title":"Alter Lauf","content":"Validierte Pipeline v3.4 mit dokumentierter Leistungsfähigkeit."},{"title":"Neuer Lauf","content":"v4.1 ruft zusätzliche Indels/Splice-Varianten, darunter ein potenziell reportables MET-Ereignis."},{"title":"Dokumentation","content":"kein Change-Control-Eintrag, keine Freigabe, keine definierte Vergleichsmatrix."}],"material_or_resource_constraints":["Klinischer TAT-Druck, aber potenzieller Einfluss auf Befundqualität.","Vergleichsdatensätze und Alt-Runs sind verfügbar.","Re-Analyse früherer Fälle könnte nötig werden, wenn systematischer Einfluss besteht."],"reasoning_gate_upgrade":[{"id":"change_type","type":"single_choice","prompt":"Wie ist die Pipelineänderung zu bewerten?","options":[{"id":"qm_relevant","label":"qualitätsrelevante Methoden-/Auswertungsänderung mit Change-Control-Bedarf"},{"id":"cosmetic","label":"rein kosmetische Änderung"},{"id":"ignore","label":"irrelevant, wenn Software neuer ist"},{"id":"clinical_only","label":"nur klinische Entscheidung"}],"correct":["qm_relevant"],"rationale":"Pipelineversionen beeinflussen berichtete Varianten und benötigen Kontrolle."},{"id":"immediate","type":"single_choice","prompt":"Was ist die richtige Sofortmaßnahme?","options":[{"id":"hold_impact","label":"Freigabe betroffener Befunde pausieren und Impact-Analyse starten"},{"id":"release_new","label":"alle neuen Calls freigeben"},{"id":"rollback_silent","label":"heimlich zurückrollen ohne Doku"},{"id":"delete_old","label":"alte Ergebnisse löschen"}],"correct":["hold_impact"],"rationale":"Freigabe ohne Impact wäre riskant."},{"id":"documentation","type":"multi_select","prompt":"Was muss dokumentiert werden?","options":[{"id":"version","label":"exakte Pipeline-/Caller-/DB-Versionen"},{"id":"validation","label":"Verifizierungs-/Vergleichsergebnisse"},{"id":"approval","label":"Freigabe/Change-Control"},{"id":"none","label":"nichts, wenn Ergebnis plausibel"}],"correct":["version","validation","approval"],"rationale":"Rückverfolgbarkeit ist Kern der Postanalytik."},{"id":"affected_cases","type":"single_choice","prompt":"Wie geht man mit potenziell betroffenen Fällen um?","options":[{"id":"case_review","label":"betroffene Fälle identifizieren und medizinisch/QM-seitig bewerten"},{"id":"ignore_past","label":"alte Fälle nie prüfen"},{"id":"report_all","label":"alle neuen Varianten ohne Prüfung reporten"},{"id":"annotation_only","label":"nur Annotation ändern"}],"correct":["case_review"],"rationale":"Impact-Analyse ist fall- und markerbezogen."}],"decision_task":"Entscheide, wie mit der ungeplanten Pipelineänderung, den diskordanten Calls und der Befundfreigabe umzugehen ist.","expected_path":["Freigabe diskordanter/entscheidungsrelevanter Befunde pausieren.","Change-Control nachholen: Änderung, Grund, Versionen, Verantwortliche dokumentieren.","Verifizierung mit definiertem Referenz-/Altfallset durchführen.","Diskordante Calls medizinisch-technisch bewerten und ggf. orthogonal bestätigen.","Berichtsvorlagen mit Pipeline-Version/Auswertungsstand korrigieren.","Entscheiden, ob frühere Fälle reevaluiert werden müssen."],"acceptable_alternatives":["Temporärer Rollback auf validierte Pipeline für Routinefreigabe, während v4.1 verifiziert wird.","Teilfreigabe nicht betroffener Befunde, wenn Trennung auditfähig dokumentiert ist."],"low_value_traps":[{"label":"Neue Pipeline ist automatisch besser","why_bad":"ohne Verifizierung keine Routinefreigabe."},{"label":"Silent rollback","why_bad":"verschleiert das Ereignis und zerstört Audit-Trail."},{"label":"Nur Bioinformatik entscheidet","why_bad":"klinisch-reportable Änderungen brauchen Laborleitung/QM/ärztliche Bewertung."}],"twist":{"title":"Ein alter negativer Fall wäre heute positiv","content":"Die Impact-Analyse zeigt, dass v4.1 eine MET-Splice-Region in einem aktuellen Fall plausibel ruft, aber auch zwei alte low-quality Artefakte neu als Varianten markiert. Die Änderung verbessert einen Bereich, erzeugt aber neue Review-Bedürfnisse.","why_critical":"Der Fall zeigt, warum Verifizierung nicht Innovationsbremse, sondern Patientenschutz ist."},"result_packages":[{"id":"optimal_change_control","title":"Change-Control + Impact","result":"Befunde pausiert, v4.1 mit Altfallset geprüft, MET-Call orthogonal bestätigt, Artefaktfilter angepasst, Versionierung dokumentiert.","feedback":"Sehr gute Balance aus Innovation und QM."},{"id":"release_without_validation","title":"Neue Pipeline direkt freigegeben","result":"Später werden diskordante Artefakte entdeckt, Reports müssen korrigiert werden.","feedback":"Kritischer Postanalytik-/QM-Fehler."},{"id":"rollback_no_doc","title":"Stiller Rollback","result":"Routine läuft weiter, aber Ereignis ist nicht nachvollziehbar; Audit-Finding wahrscheinlich.","feedback":"Prozess scheinbar gerettet, Auditfähigkeit verloren."}],"followup_logic":[{"trigger":"keine Versionierung","action":"Audit-Trail-Abzug und Cap","consequence":"Documentation und Process Decision betroffen."},{"trigger":"Befund freigegeben ohne Impact","action":"critical_fail möglich","consequence":"Score-Cap und Berichtswarnung."}],"debrief_points":["Bioinformatik-Pipelines sind Teil der Methode.","Change-Control schützt nicht vor Fortschritt, sondern vor unkontrolliertem Fortschritt.","Versionierung muss im Befund-/Archivkontext rückverfolgbar sein."],"instructor_notes":{"model_answer":"Hold/Impact-Analyse, Change-Control, Verifizierung, Versionierung, medizinische Bewertung diskordanter Fälle, ggf. Rollback auf validierten Stand bis Freigabe.","scoring_focus":["Process Decision","Documentation","Patient Safety","CAPA/Audit"],"discussion_questions":["Was ist minimale Verifizierung für Pipeline-Update?","Wann müssen Altbefunde reevaluiert werden?","Wie dokumentiert man Annotation-Datenbanken?"]},"report_additions":["Twist: bessere Sensitivität + neue Artefaktlast","Critical Error: Freigabe ohne Verifizierung","Musterpfad: Hold → Impact → Change-Control → Verifizierung → Freigabe"]}},"languages":{"en":{"metadata":{"case_id":"LAB_POST_001_v1_0","base_id":"LAB_POST_001","title":"Pipeline version changed, no change log → bioinformatics QC and impact analysis","domain":"LAB","met_addon_type":"no","subdomain":"Post-analytics / bioinformatics / change control","case_type":"qm_capa_decision","length_class":"Complex","estimated_minutes":{"min":20,"max":30},"difficulty":"Advanced","status":"curated-core","review_flag":"Review core/MVP","review_priority":"high","core_decision":"The variant caller was updated from version 3.4 to 4.1.","learning_objectives":["Correctly prioritize the patient-safety and quality risk of the event","Safeguard pipeline/software changes through change control, revalidation and versioning","Provide an audit-ready justification for release, hold or repeat decisions"],"tags":["Bioinformatics","Pipeline","Versioning","Change control","Audit","NGS, complex_case, AP1b_length_reclass"],"ap1b_decision":"LAB; length=complex; difficulty=advanced; status=curated-core"},"base_case":{"id":"LAB_POST_001_v1_0","title":"Pipeline version changed, no change log → bioinformatics QC and impact analysis","short":"Pipeline without a change log","mode":"lab_qm","logic":"lab_pipeline","difficulty":"intermediate","estimated_time_min":"10–15","tags":["Bioinformatics","Pipeline","Versioning","Change control","Audit","NGS"],"run_overview":{"System":"Targeted DNA-NGS pipeline","Ausgangslage":"The variant caller was updated from version 3.4 to 4.1.","Dokumentation":"No change log, no formal approval, no verification record.","Betroffene Zeit":"2 weeks of routine operation.","Problem":"Two variants are filtered/classified differently in the new version."},"qc_title":"Undocumented pipeline change","qc_event":{"Auffälligkeit":"The old and new analyses are no longer directly comparable.","Risiko":"False-negative or false-positive reporting consequences, especially for treatment-determining variants.","Audit-Risiko":"Traceability of analysis steps and database/pipeline versions is missing.","Konflikt":"Continue with the new software vs. hold reports and clarify the impact."},"decision_options":[{"id":"do_nothing","label":"Do nothing; the new pipeline is probably better.","kind":"bad","feedback":"Critically wrong: software changes are methodologically relevant changes and must be controlled.","score":{"safety":0,"process":0,"documentation":0,"capa":0,"communication":0}},{"id":"bioinfo_only","label":"Inform bioinformatics only and continue releasing laboratory reports.","kind":"partial","feedback":"Insufficient: this concerns report validity, release and quality management, not just technology.","score":{"safety":8,"process":8,"documentation":4,"capa":2,"communication":4}},{"id":"impact_capa","label":"Open a deviation, pause release based on risk, identify affected cases, and define impact analysis and reanalysis if needed.","kind":"optimal","feedback":"Optimal: change control, patient safety and the audit trail are secured.","score":{"safety":30,"process":24,"documentation":18,"capa":14,"communication":8}},{"id":"recall_all","label":"Immediately recall all previous reports across the board.","kind":"partial","feedback":"Too broad: reanalysis/recall must be justified by impact and risk analysis.","score":{"safety":20,"process":10,"documentation":10,"capa":8,"communication":6}}],"root_cause_options":[{"id":"affected_runs","label":"Identify all runs/cases processed during the period of the new pipeline version","correct":true,"feedback":"No impact analysis is possible without a case list."},{"id":"calling_vs_annotation","label":"Check whether calling/filtering or only annotation is affected","correct":true,"feedback":"Calling/filtering changes are more critical for reporting."},{"id":"released_reports","label":"Prioritize already released reports that affect treatment decisions","correct":true,"feedback":"Clinical relevance determines the need for reanalysis."},{"id":"ignore_negative","label":"Do not review negative cases","correct":false,"feedback":"Wrong: negative reports in particular may be affected."},{"id":"verification_set","label":"Complete the reference/verification dataset for version 4.1","correct":true,"feedback":"New versions must be evaluated locally."}],"capa_components":[{"id":"dev","label":"Deviation: undocumented pipeline change"},{"id":"pause","label":"Immediate action: pause/control releases based on risk"},{"id":"impact","label":"Correction: impact analysis and defined reanalysis"},{"id":"sop","label":"Prevention: SOP for pipeline changes with mandatory fields"},{"id":"eff","label":"Effectiveness check: subsequent changes are fully documented"}],"audit_checks":[{"id":"version","label":"Old/new pipeline version and timing documented","correct":true},{"id":"risk","label":"Risk assessment is traceable for each report class","correct":true},{"id":"approval","label":"Approval of the new pipeline version documented","correct":true},{"id":"training","label":"Communication/training of affected personnel documented","correct":true},{"id":"hide","label":"Discuss the change only verbally in-house; do not document it","correct":false}],"optimal_summary":"Optimal solution: treat the pipeline change as a deviation, perform an impact analysis, reanalyse affected reports based on risk, and establish change control for future updates."},"deep_dive":{"version":"v1.7b","case_id":"LAB_POST_001_v1_0","title":"Pipeline version changed, no change log: bioinformatics QC and impact analysis","domain":"LAB","target_course":"Advanced Integrated","deep_dive_priority":"complex_anchor","target_role":"Laboratory management / bioinformatics QC","estimated_minutes_deep":"20–30","learning_objectives":["Recognize pipeline/software changes as quality-relevant methodological changes.","Derive the required impact analysis, versioning and revalidation/verification.","Manage report release for discordant pipeline results in an audit-ready manner."],"opening_scene":"A bioinformatics update was installed 'just quickly' because the new caller promises better indel detection. The next day, several variant lists differ from previous results. There is no change log.","case_briefing":"Molecular pathology NGS panel, 48 patient cases in the current batch. The variant caller was updated from 3.4 to 4.1. The reference database and annotation were also updated with minor revisions. The change was not approved in the quality documentation beforehand.","context_cards":[{"title":"Discordance","content":"Reportable variants differ in 6/48 cases. One case involves a potentially treatment-determining MET splice region.","teaching_point":"Not every software change is purely technical."},{"title":"Versioning","content":"The draft report does not specify a pipeline version; old reports contain only 'NGS Pipeline'.","teaching_point":"Without versioning, traceability is lost."},{"title":"Team conflict","content":"Bioinformatics says: 'The new caller is better.' Quality management asks: 'Where is the verification?' The clinical team is waiting for reports.","teaching_point":"Better does not mean approved for release."},{"title":"Risk","content":"Both false-positive and false-negative changes are possible; the impact is not limited to a single case.","teaching_point":"Impact analysis must be systematic."}],"pre_results":[{"title":"Previous run","content":"Validated pipeline v3.4 with documented performance."},{"title":"New run","content":"v4.1 calls additional indels/splice variants, including a potentially reportable MET event."},{"title":"Documentation","content":"No change-control entry, no approval, no defined comparison matrix."}],"material_or_resource_constraints":["Clinical TAT pressure, but a potential impact on report quality.","Comparison datasets and previous runs are available.","Reanalysis of previous cases may be necessary if there is a systematic impact."],"reasoning_gate_upgrade":[{"id":"change_type","type":"single_choice","prompt":"How should the pipeline change be assessed?","options":[{"id":"qm_relevant","label":"quality-relevant method/analysis change requiring change control"},{"id":"cosmetic","label":"purely cosmetic change"},{"id":"ignore","label":"irrelevant if the software is newer"},{"id":"clinical_only","label":"clinical decision only"}],"correct":["qm_relevant"],"rationale":"Pipeline versions affect reported variants and require control."},{"id":"immediate","type":"single_choice","prompt":"What is the correct immediate action?","options":[{"id":"hold_impact","label":"Pause release of affected reports and start an impact analysis"},{"id":"release_new","label":"release all new calls"},{"id":"rollback_silent","label":"roll back silently without documentation"},{"id":"delete_old","label":"delete old results"}],"correct":["hold_impact"],"rationale":"Release without assessing the impact would be risky."},{"id":"documentation","type":"multi_select","prompt":"What must be documented?","options":[{"id":"version","label":"exact pipeline/caller/database versions"},{"id":"validation","label":"verification/comparison results"},{"id":"approval","label":"approval/change control"},{"id":"none","label":"nothing if the result seems plausible"}],"correct":["version","validation","approval"],"rationale":"Traceability is a core requirement of post-analytics."},{"id":"affected_cases","type":"single_choice","prompt":"How should potentially affected cases be handled?","options":[{"id":"case_review","label":"identify affected cases and assess them medically and from a quality perspective"},{"id":"ignore_past","label":"never review old cases"},{"id":"report_all","label":"report all new variants without review"},{"id":"annotation_only","label":"change annotation only"}],"correct":["case_review"],"rationale":"Impact analysis is case- and marker-specific."}],"decision_task":"Decide how to handle the unplanned pipeline change, discordant calls and report release.","expected_path":["Pause release of discordant or decision-relevant reports.","Complete change control retrospectively: document the change, reason, versions and responsible persons.","Perform verification using a defined reference/previous-case set.","Assess discordant calls medically and technically and confirm orthogonally if needed.","Correct report templates to include the pipeline version/analysis status.","Decide whether previous cases need to be re-evaluated."],"acceptable_alternatives":["Temporary rollback to the validated pipeline for routine release while v4.1 is being verified.","Partial release of unaffected reports if the separation is documented in an audit-ready manner."],"low_value_traps":[{"label":"The new pipeline is automatically better","why_bad":"No routine release without verification."},{"label":"Silent rollback","why_bad":"conceals the event and destroys the audit trail."},{"label":"Bioinformatics decides alone","why_bad":"Clinically reportable changes require assessment by laboratory management, quality management and medical staff."}],"twist":{"title":"A previously negative case would be positive today","content":"The impact analysis shows that v4.1 plausibly calls a MET splice region in a current case, but also newly flags two old low-quality artefacts as variants. The change improves one area but creates new review requirements.","why_critical":"The case shows why verification is not a brake on innovation but a patient-safety measure."},"result_packages":[{"id":"optimal_change_control","title":"Change control + impact","result":"Reports held, v4.1 tested with a previous-case set, the MET call confirmed orthogonally, artefact filters adjusted and versioning documented.","feedback":"Very good balance between innovation and quality management."},{"id":"release_without_validation","title":"New pipeline released directly","result":"Discordant artefacts are discovered later and reports have to be corrected.","feedback":"Critical post-analytics/quality-management error."},{"id":"rollback_no_doc","title":"Silent rollback","result":"Routine operation continues, but the event is not traceable; an audit finding is likely.","feedback":"Process apparently rescued, auditability lost."}],"followup_logic":[{"trigger":"no versioning","action":"Audit-trail deduction and cap","consequence":"Documentation and Process Decision are affected."},{"trigger":"Report released without impact assessment","action":"critical_fail possible","consequence":"Score cap and report warning."}],"debrief_points":["Bioinformatics pipelines are part of the method.","Change control does not protect against progress; it protects against uncontrolled progress.","Versioning must be traceable in the report/archive context."],"instructor_notes":{"model_answer":"Hold/impact analysis, change control, verification, versioning, medical assessment of discordant cases and, if needed, rollback to the validated state until approval.","scoring_focus":["Process decision","Documentation","Patient safety","CAPA/Audit"],"discussion_questions":["What is the minimum verification required for a pipeline update?","When must previous reports be re-evaluated?","How should annotation databases be documented?"]},"report_additions":["Twist: better sensitivity + new artefact burden","Critical Error: release without verification","Reference pathway: Hold → Impact → Change control → Verification → Release"]}},"ro":{"metadata":{"case_id":"LAB_POST_001_v1_0","base_id":"LAB_POST_001","title":"Versiunea pipeline-ului modificată, fără jurnal de schimbări → QM bioinformatic și analiză de impact","domain":"LAB","met_addon_type":"no","subdomain":"Postanalitică / bioinformatică / controlul modificărilor","case_type":"qm_capa_decision","length_class":"Complex","estimated_minutes":{"min":20,"max":30},"difficulty":"Avansat","status":"curated-core","review_flag":"Verificare core/MVP","review_priority":"high","core_decision":"Apelatorul de variante a fost actualizat de la versiunea 3.4 la 4.1.","learning_objectives":["Prioritizați corect riscul pentru siguranța pacientului și calitate asociat evenimentului","Asigurați modificările pipeline-ului/software-ului prin controlul modificărilor, revalidare și versionare","Justificați într-un mod auditabil decizia de eliberare, blocare sau repetare"],"tags":["Bioinformatică","Pipeline","Versionare","Controlul modificărilor","Audit","NGS, complex_case, AP1b_length_reclass"],"ap1b_decision":"LAB; lungime=complexă; dificultate=avansată; statut=curated-core"},"base_case":{"id":"LAB_POST_001_v1_0","title":"Versiunea pipeline-ului modificată, fără jurnal de schimbări → QM bioinformatic și analiză de impact","short":"Pipeline fără jurnal de schimbări","mode":"lab_qm","logic":"lab_pipeline","difficulty":"intermediate","estimated_time_min":"10–15","tags":["Bioinformatică","Pipeline","Versionare","Controlul modificărilor","Audit","NGS"],"run_overview":{"System":"Pipeline NGS ADN țintit","Ausgangslage":"Apelatorul de variante a fost actualizat de la versiunea 3.4 la 4.1.","Dokumentation":"Fără jurnal de schimbări, fără aprobare formală, fără notă de verificare.","Betroffene Zeit":"2 săptămâni de funcționare de rutină.","Problem":"Două variante sunt filtrate/clasificate diferit în noua versiune."},"qc_title":"Modificare nedocumentată a pipeline-ului","qc_event":{"Auffälligkeit":"Analizele vechi și noi nu mai sunt comparabile în mod clar.","Risiko":"Consecințe fals negative sau fals pozitive asupra raportării, în special pentru variante care influențează tratamentul.","Audit-Risiko":"Lipsește trasabilitatea etapelor de analiză și a versiunilor bazei de date/pipeline-ului.","Konflikt":"Continuarea cu noul software vs. suspendarea rapoartelor și clarificarea impactului."},"decision_options":[{"id":"do_nothing","label":"Nu faceți nimic; noul pipeline este probabil mai bun.","kind":"bad","feedback":"Critic greșit: modificările software sunt modificări metodologice relevante și trebuie controlate.","score":{"safety":0,"process":0,"documentation":0,"capa":0,"communication":0}},{"id":"bioinfo_only","label":"Informați doar bioinformatica și continuați eliberarea rapoartelor de laborator.","kind":"partial","feedback":"Insuficient: este vorba despre validitatea raportului, eliberare și managementul calității, nu doar despre tehnică.","score":{"safety":8,"process":8,"documentation":4,"capa":2,"communication":4}},{"id":"impact_capa","label":"Deschideți o abatere, suspendați eliberarea pe baza riscului, identificați cazurile afectate și stabiliți analiza de impact și, dacă este necesar, reanaliza.","kind":"optimal","feedback":"Optim: sunt asigurate controlul modificărilor, siguranța pacientului și pista de audit.","score":{"safety":30,"process":24,"documentation":18,"capa":14,"communication":8}},{"id":"recall_all","label":"Retrageți imediat, în mod generalizat, toate rapoartele anterioare.","kind":"partial","feedback":"Prea general: reanaliza/retragerea trebuie justificată prin analiza de impact și de risc.","score":{"safety":20,"process":10,"documentation":10,"capa":8,"communication":6}}],"root_cause_options":[{"id":"affected_runs","label":"Identificați toate rulările/cazurile din perioada noii versiuni a pipeline-ului","correct":true,"feedback":"Fără o listă de cazuri nu este posibilă analiza de impact."},{"id":"calling_vs_annotation","label":"Verificați dacă sunt afectate calling-ul/filtering-ul sau doar adnotarea","correct":true,"feedback":"Modificările de calling/filtering sunt mai critice pentru raportare."},{"id":"released_reports","label":"Prioritizați rapoartele deja eliberate care influențează deciziile terapeutice","correct":true,"feedback":"Relevanța clinică determină necesitatea reanalizei."},{"id":"ignore_negative","label":"Nu revizuiți cazurile negative","correct":false,"feedback":"Greșit: tocmai rapoartele negative pot fi afectate."},{"id":"verification_set","label":"Completați setul de date de referință/verificare pentru versiunea 4.1","correct":true,"feedback":"Versiunile noi trebuie evaluate local."}],"capa_components":[{"id":"dev","label":"Abatere: modificare nedocumentată a pipeline-ului"},{"id":"pause","label":"Măsură imediată: suspendați/controlați eliberările pe baza riscului"},{"id":"impact","label":"Corecție: analiză de impact și reanaliză definită"},{"id":"sop","label":"Prevenție: SOP pentru modificări ale pipeline-ului cu câmpuri obligatorii"},{"id":"eff","label":"Verificarea eficacității: modificările următoare sunt documentate complet"}],"audit_checks":[{"id":"version","label":"Versiunea veche/nouă a pipeline-ului și momentul modificării sunt documentate","correct":true},{"id":"risk","label":"Evaluarea riscului este trasabilă pentru fiecare clasă de raport","correct":true},{"id":"approval","label":"Aprobarea noii versiuni a pipeline-ului este documentată","correct":true},{"id":"training","label":"Comunicarea/instruirea personalului afectat este documentată","correct":true},{"id":"hide","label":"Discutați schimbarea doar verbal, intern; nu o documentați","correct":false}],"optimal_summary":"Soluția optimă: tratați modificarea pipeline-ului ca pe o abatere, efectuați o analiză de impact, reanalizați pe baza riscului rapoartele afectate și instituiți controlul modificărilor pentru actualizările viitoare."},"deep_dive":{"version":"v1.7b","case_id":"LAB_POST_001_v1_0","title":"Versiunea pipeline-ului modificată, fără jurnal de schimbări: QM bioinformatic și analiză de impact","domain":"LAB","target_course":"Avansat integrat","deep_dive_priority":"complex_anchor","target_role":"Conducerea laboratorului / QM bioinformatic","estimated_minutes_deep":"20–30","learning_objectives":["Recunoașteți modificările pipeline-ului/software-ului ca modificări metodologice relevante pentru calitate.","Stabiliți analiza de impact, versionarea și revalidarea/verificarea necesare.","Gestionați eliberarea rapoartelor în cazul rezultatelor discordante ale pipeline-ului într-un mod auditabil."],"opening_scene":"O actualizare bioinformatică a fost instalată 'doar rapid', deoarece noul apelator promite o detecție mai bună a indelurilor. A doua zi, mai multe liste de variante diferă de rezultatele anterioare. Nu există jurnal de schimbări.","case_briefing":"Panel NGS de patologie moleculară, 48 de cazuri de pacienți în lotul curent. Apelatorul de variante a fost actualizat de la 3.4 la 4.1. Baza de date de referință și adnotarea au primit, de asemenea, actualizări minore. Modificarea nu a fost aprobată în prealabil în documentația de calitate.","context_cards":[{"title":"Discordanță","content":"Variantele raportabile diferă în 6/48 de cazuri. Un caz implică o regiune de splice MET cu potențial impact asupra tratamentului.","teaching_point":"Nu orice modificare software este pur tehnică."},{"title":"Versionare","content":"Proiectul de raport nu specifică versiunea pipeline-ului; rapoartele vechi conțin doar 'NGS Pipeline'.","teaching_point":"Fără versionare, trasabilitatea lipsește."},{"title":"Conflict în echipă","content":"Bioinformatica spune: 'Noul apelator este mai bun.' QM întreabă: 'Unde este verificarea?' Echipa clinică așteaptă rapoartele.","teaching_point":"Mai bun nu înseamnă automat aprobat pentru utilizare."},{"title":"Risc","content":"Sunt posibile atât modificări fals pozitive, cât și fals negative; impactul nu este limitat la un singur caz.","teaching_point":"Analiza de impact trebuie realizată sistematic."}],"pre_results":[{"title":"Rulare anterioară","content":"Pipeline validat v3.4 cu performanță documentată."},{"title":"Rulare nouă","content":"v4.1 detectează indeluri/variante de splice suplimentare, inclusiv un eveniment MET potențial raportabil."},{"title":"Documentație","content":"Fără înregistrare de control al modificărilor, fără aprobare, fără matrice de comparație definită."}],"material_or_resource_constraints":["Presiune clinică privind TAT, dar cu posibil impact asupra calității raportului.","Sunt disponibile seturi de date comparative și rulări anterioare.","Reanaliza cazurilor anterioare poate fi necesară dacă există un impact sistematic."],"reasoning_gate_upgrade":[{"id":"change_type","type":"single_choice","prompt":"Cum trebuie evaluată modificarea pipeline-ului?","options":[{"id":"qm_relevant","label":"modificare relevantă pentru calitate a metodei/analizei, care necesită controlul modificărilor"},{"id":"cosmetic","label":"modificare pur cosmetică"},{"id":"ignore","label":"irelevant dacă software-ul este mai nou"},{"id":"clinical_only","label":"doar o decizie clinică"}],"correct":["qm_relevant"],"rationale":"Versiunile pipeline-ului influențează variantele raportate și necesită control."},{"id":"immediate","type":"single_choice","prompt":"Care este măsura imediată corectă?","options":[{"id":"hold_impact","label":"Suspendați eliberarea rapoartelor afectate și începeți o analiză de impact"},{"id":"release_new","label":"eliberați toate noile call-uri"},{"id":"rollback_silent","label":"reveniți în secret la versiunea anterioară fără documentare"},{"id":"delete_old","label":"ștergeți rezultatele vechi"}],"correct":["hold_impact"],"rationale":"Eliberarea fără evaluarea impactului ar fi riscantă."},{"id":"documentation","type":"multi_select","prompt":"Ce trebuie documentat?","options":[{"id":"version","label":"versiunile exacte ale pipeline-ului/caller-ului/bazei de date"},{"id":"validation","label":"rezultatele verificării/comparației"},{"id":"approval","label":"aprobare/controlul modificărilor"},{"id":"none","label":"nimic dacă rezultatul pare plauzibil"}],"correct":["version","validation","approval"],"rationale":"Trasabilitatea este o cerință esențială a postanaliticii."},{"id":"affected_cases","type":"single_choice","prompt":"Cum trebuie gestionate cazurile potențial afectate?","options":[{"id":"case_review","label":"identificați cazurile afectate și evaluați-le medical și din perspectiva calității"},{"id":"ignore_past","label":"nu revizuiți niciodată cazurile vechi"},{"id":"report_all","label":"raportați toate variantele noi fără verificare"},{"id":"annotation_only","label":"modificați doar adnotarea"}],"correct":["case_review"],"rationale":"Analiza de impact este specifică fiecărui caz și marker."}],"decision_task":"Decideți cum trebuie gestionate modificarea neplanificată a pipeline-ului, call-urile discordante și eliberarea rapoartelor.","expected_path":["Suspendați eliberarea rapoartelor discordante sau relevante pentru decizie.","Completați retrospectiv controlul modificărilor: documentați schimbarea, motivul, versiunile și persoanele responsabile.","Efectuați verificarea folosind un set definit de referință/cazuri anterioare.","Evaluați medical și tehnic call-urile discordante și confirmați-le ortogonal dacă este necesar.","Corectați șabloanele de raport pentru a include versiunea pipeline-ului/stadiul analizei.","Decideți dacă trebuie reevaluate cazurile anterioare."],"acceptable_alternatives":["Rollback temporar la pipeline-ul validat pentru eliberarea de rutină, în timp ce v4.1 este verificată.","Eliberarea parțială a rapoartelor neafectate dacă separarea este documentată într-un mod auditabil."],"low_value_traps":[{"label":"Noul pipeline este automat mai bun","why_bad":"Fără eliberare de rutină fără verificare."},{"label":"Rollback silențios","why_bad":"ascunde evenimentul și distruge pista de audit."},{"label":"Doar bioinformatica decide","why_bad":"Modificările raportabile clinic necesită evaluare din partea conducerii laboratorului, a QM și a personalului medical."}],"twist":{"title":"Un caz anterior negativ ar fi astăzi pozitiv","content":"Analiza de impact arată că v4.1 identifică plauzibil o regiune de splice MET într-un caz curent, dar marchează și două artefacte vechi de calitate scăzută ca variante. Modificarea îmbunătățește un domeniu, dar creează noi necesități de revizuire.","why_critical":"Cazul arată de ce verificarea nu frânează inovația, ci protejează pacientul."},"result_packages":[{"id":"optimal_change_control","title":"Controlul modificărilor + impact","result":"Rapoartele au fost suspendate, v4.1 a fost testată cu un set de cazuri anterioare, call-ul MET a fost confirmat ortogonal, filtrele de artefacte au fost ajustate și versionarea a fost documentată.","feedback":"Echilibru foarte bun între inovație și managementul calității."},{"id":"release_without_validation","title":"Noul pipeline aprobat direct","result":"Ulterior sunt descoperite artefacte discordante, iar rapoartele trebuie corectate.","feedback":"Eroare critică de postanalitică/management al calității."},{"id":"rollback_no_doc","title":"Rollback silențios","result":"Activitatea de rutină continuă, dar evenimentul nu este trasabil; este probabilă o constatare la audit.","feedback":"Procesul pare salvat, dar auditabilitatea este pierdută."}],"followup_logic":[{"trigger":"fără versionare","action":"Penalizare pentru pista de audit și plafon","consequence":"Sunt afectate Documentația și Decizia de proces."},{"trigger":"Raport eliberat fără evaluarea impactului","action":"critical_fail posibil","consequence":"Plafon de scor și avertizare în raport."}],"debrief_points":["Pipeline-urile bioinformatice fac parte din metodă.","Controlul modificărilor nu protejează împotriva progresului, ci împotriva progresului necontrolat.","Versionarea trebuie să fie trasabilă în contextul raportului/arhivei."],"instructor_notes":{"model_answer":"Hold/analiză de impact, controlul modificărilor, verificare, versionare, evaluarea medicală a cazurilor discordante și, dacă este necesar, rollback la starea validată până la aprobare.","scoring_focus":["Decizie de proces","Documentație","Siguranța pacientului","CAPA/Audit"],"discussion_questions":["Care este verificarea minimă necesară pentru o actualizare a pipeline-ului?","Când trebuie reevaluate rapoartele anterioare?","Cum trebuie documentate bazele de date de adnotare?"]},"report_additions":["Twist: sensibilitate mai bună + o nouă povară de artefacte","Eroare critică: eliberare fără verificare","Traseu de referință: Hold → Impact → Controlul modificărilor → Verificare → Eliberare"]}},"el":{"metadata":{"case_id":"LAB_POST_001_v1_0","base_id":"LAB_POST_001","title":"Αλλαγή έκδοσης pipeline χωρίς αρχείο αλλαγών → ποιοτικός έλεγχος βιοπληροφορικής και ανάλυση επιπτώσεων","domain":"LAB","met_addon_type":"no","subdomain":"Μετα-αναλυτικό στάδιο / βιοπληροφορική / έλεγχος αλλαγών","case_type":"qm_capa_decision","length_class":"Σύνθετο","estimated_minutes":{"min":20,"max":30},"difficulty":"Προχωρημένο","status":"curated-core","review_flag":"Έλεγχος core/MVP","review_priority":"high","core_decision":"Ο αλγόριθμος κλήσης παραλλαγών ενημερώθηκε από την έκδοση 3.4 στην 4.1.","learning_objectives":["Ιεραρχήστε σωστά τον κίνδυνο του συμβάντος για την ασφάλεια των ασθενών και την ποιότητα","Διασφαλίστε τις αλλαγές pipeline/λογισμικού μέσω ελέγχου αλλαγών, επανεπικύρωσης και διαχείρισης εκδόσεων","Τεκμηριώστε με τρόπο κατάλληλο για έλεγχο την απόφαση αποδέσμευσης, αναστολής ή επανάληψης"],"tags":["Βιοπληροφορική","Pipeline","Διαχείριση εκδόσεων","Έλεγχος αλλαγών","Έλεγχος","NGS, complex_case, AP1b_length_reclass"],"ap1b_decision":"LAB· διάρκεια=σύνθετη· δυσκολία=προχωρημένη· κατάσταση=curated-core"},"base_case":{"id":"LAB_POST_001_v1_0","title":"Αλλαγή έκδοσης pipeline χωρίς αρχείο αλλαγών → ποιοτικός έλεγχος βιοπληροφορικής και ανάλυση επιπτώσεων","short":"Pipeline χωρίς αρχείο αλλαγών","mode":"lab_qm","logic":"lab_pipeline","difficulty":"intermediate","estimated_time_min":"10–15","tags":["Βιοπληροφορική","Pipeline","Διαχείριση εκδόσεων","Έλεγχος αλλαγών","Έλεγχος","NGS"],"run_overview":{"System":"Στοχευμένο pipeline DNA-NGS","Ausgangslage":"Ο αλγόριθμος κλήσης παραλλαγών ενημερώθηκε από την έκδοση 3.4 στην 4.1.","Dokumentation":"Χωρίς αρχείο αλλαγών, χωρίς επίσημη έγκριση, χωρίς καταγραφή επαλήθευσης.","Betroffene Zeit":"2 εβδομάδες λειτουργίας ρουτίνας.","Problem":"Δύο παραλλαγές φιλτράρονται/ταξινομούνται διαφορετικά στη νέα έκδοση."},"qc_title":"Μη τεκμηριωμένη αλλαγή pipeline","qc_event":{"Auffälligkeit":"Η παλιά και η νέα ανάλυση δεν είναι πλέον σαφώς συγκρίσιμες.","Risiko":"Ψευδώς αρνητικές ή ψευδώς θετικές συνέπειες στην αναφορά, ιδιαίτερα για παραλλαγές που καθορίζουν τη θεραπεία.","Audit-Risiko":"Απουσιάζει η ιχνηλασιμότητα των βημάτων ανάλυσης και των εκδόσεων βάσης δεδομένων/pipeline.","Konflikt":"Συνέχιση με το νέο λογισμικό έναντι αναστολής των αναφορών και διερεύνησης των επιπτώσεων."},"decision_options":[{"id":"do_nothing","label":"Καμία ενέργεια· το νέο pipeline είναι πιθανώς καλύτερο.","kind":"bad","feedback":"Κρίσιμο σφάλμα: οι αλλαγές λογισμικού είναι μεθοδολογικά σημαντικές αλλαγές και πρέπει να ελέγχονται.","score":{"safety":0,"process":0,"documentation":0,"capa":0,"communication":0}},{"id":"bioinfo_only","label":"Ενημερώστε μόνο τη βιοπληροφορική και συνεχίστε την αποδέσμευση των εργαστηριακών αναφορών.","kind":"partial","feedback":"Ανεπαρκές: αφορά την εγκυρότητα της αναφοράς, την αποδέσμευση και τη διαχείριση ποιότητας, όχι μόνο την τεχνική.","score":{"safety":8,"process":8,"documentation":4,"capa":2,"communication":4}},{"id":"impact_capa","label":"Ανοίξτε απόκλιση, αναστείλετε την αποδέσμευση βάσει κινδύνου, εντοπίστε τα επηρεαζόμενα περιστατικά και καθορίστε ανάλυση επιπτώσεων και, εφόσον απαιτείται, επανάλυση.","kind":"optimal","feedback":"Βέλτιστο: διασφαλίζονται ο έλεγχος αλλαγών, η ασφάλεια των ασθενών και το ίχνος ελέγχου.","score":{"safety":30,"process":24,"documentation":18,"capa":14,"communication":8}},{"id":"recall_all","label":"Ανακαλέστε άμεσα και συλλήβδην όλες τις παλαιότερες αναφορές.","kind":"partial","feedback":"Υπερβολικά γενικό: η επανάλυση/ανάκληση πρέπει να τεκμηριώνεται με ανάλυση επιπτώσεων και κινδύνου.","score":{"safety":20,"process":10,"documentation":10,"capa":8,"communication":6}}],"root_cause_options":[{"id":"affected_runs","label":"Εντοπίστε όλες τις σειρές/περιστατικά κατά την περίοδο χρήσης της νέας έκδοσης του pipeline","correct":true,"feedback":"Χωρίς κατάλογο περιστατικών δεν είναι δυνατή η ανάλυση επιπτώσεων."},{"id":"calling_vs_annotation","label":"Ελέγξτε εάν επηρεάζονται το calling/filtering ή μόνο η επισημείωση","correct":true,"feedback":"Οι αλλαγές στο calling/filtering είναι πιο κρίσιμες για την αναφορά."},{"id":"released_reports","label":"Δώστε προτεραιότητα σε ήδη αποδεσμευμένες αναφορές που επηρεάζουν θεραπευτικές αποφάσεις","correct":true,"feedback":"Η κλινική σημασία καθορίζει την ανάγκη επανάλυσης."},{"id":"ignore_negative","label":"Μην ελέγξετε τα αρνητικά περιστατικά","correct":false,"feedback":"Λάθος: ιδιαίτερα οι αρνητικές αναφορές μπορεί να επηρεάζονται."},{"id":"verification_set","label":"Συμπληρώστε το σύνολο δεδομένων αναφοράς/επαλήθευσης για την έκδοση 4.1","correct":true,"feedback":"Οι νέες εκδόσεις πρέπει να ελέγχονται τοπικά."}],"capa_components":[{"id":"dev","label":"Απόκλιση: μη τεκμηριωμένη αλλαγή pipeline"},{"id":"pause","label":"Άμεσο μέτρο: αναστολή/έλεγχος αποδεσμεύσεων βάσει κινδύνου"},{"id":"impact","label":"Διόρθωση: ανάλυση επιπτώσεων και καθορισμένη επανάλυση"},{"id":"sop","label":"Πρόληψη: SOP για αλλαγές pipeline με υποχρεωτικά πεδία"},{"id":"eff","label":"Έλεγχος αποτελεσματικότητας: οι επόμενες αλλαγές τεκμηριώνονται πλήρως"}],"audit_checks":[{"id":"version","label":"Η παλιά/νέα έκδοση του pipeline και ο χρόνος αλλαγής έχουν τεκμηριωθεί","correct":true},{"id":"risk","label":"Η αξιολόγηση κινδύνου είναι ιχνηλάσιμη για κάθε κατηγορία αναφοράς","correct":true},{"id":"approval","label":"Η έγκριση της νέας έκδοσης του pipeline έχει τεκμηριωθεί","correct":true},{"id":"training","label":"Η επικοινωνία/εκπαίδευση του εμπλεκόμενου προσωπικού έχει τεκμηριωθεί","correct":true},{"id":"hide","label":"Συζητήστε την αλλαγή μόνο προφορικά εντός της ομάδας· μην την τεκμηριώσετε","correct":false}],"optimal_summary":"Βέλτιστη λύση: αντιμετωπίστε την αλλαγή pipeline ως απόκλιση, πραγματοποιήστε ανάλυση επιπτώσεων, επαναναλύστε βάσει κινδύνου τις επηρεαζόμενες αναφορές και καθιερώστε έλεγχο αλλαγών για μελλοντικές ενημερώσεις."},"deep_dive":{"version":"v1.7b","case_id":"LAB_POST_001_v1_0","title":"Αλλαγή έκδοσης pipeline χωρίς αρχείο αλλαγών: ποιοτικός έλεγχος βιοπληροφορικής και ανάλυση επιπτώσεων","domain":"LAB","target_course":"Προχωρημένο ολοκληρωμένο","deep_dive_priority":"complex_anchor","target_role":"Διοίκηση εργαστηρίου / ποιοτικός έλεγχος βιοπληροφορικής","estimated_minutes_deep":"20–30","learning_objectives":["Αναγνωρίστε τις αλλαγές pipeline/λογισμικού ως μεθοδολογικές αλλαγές με σημασία για την ποιότητα.","Προσδιορίστε την απαιτούμενη ανάλυση επιπτώσεων, διαχείριση εκδόσεων και επανεπικύρωση/επαλήθευση.","Διαχειριστείτε την αποδέσμευση αναφορών σε ασύμφωνα αποτελέσματα pipeline με τρόπο κατάλληλο για έλεγχο."],"opening_scene":"Μια ενημέρωση βιοπληροφορικής εγκαταστάθηκε 'στα γρήγορα', επειδή ο νέος caller υπόσχεται καλύτερη ανίχνευση indel. Την επόμενη ημέρα, αρκετές λίστες παραλλαγών διαφέρουν από τα παλαιότερα αποτελέσματα. Δεν υπάρχει αρχείο αλλαγών.","case_briefing":"Panel NGS μοριακής παθολογίας, 48 περιστατικά ασθενών στην τρέχουσα παρτίδα. Ο αλγόριθμος κλήσης παραλλαγών ενημερώθηκε από 3.4 σε 4.1. Η βάση δεδομένων αναφοράς και η επισημείωση ενημερώθηκαν επίσης σε μικρό βαθμό. Η αλλαγή δεν είχε εγκριθεί εκ των προτέρων στην τεκμηρίωση ποιότητας.","context_cards":[{"title":"Ασυμφωνία","content":"Οι παραλλαγές προς αναφορά διαφέρουν σε 6/48 περιστατικά. Ένα περιστατικό αφορά περιοχή splice του MET που ενδέχεται να καθορίζει τη θεραπεία.","teaching_point":"Δεν είναι κάθε αλλαγή λογισμικού καθαρά τεχνική."},{"title":"Διαχείριση εκδόσεων","content":"Στο προσχέδιο της αναφοράς δεν αναφέρεται έκδοση pipeline· οι παλιές αναφορές περιέχουν μόνο 'NGS Pipeline'.","teaching_point":"Χωρίς διαχείριση εκδόσεων, χάνεται η ιχνηλασιμότητα."},{"title":"Σύγκρουση στην ομάδα","content":"Η βιοπληροφορική λέει: 'Ο νέος caller είναι καλύτερος.' Η διαχείριση ποιότητας ρωτά: 'Πού είναι η επαλήθευση;' Η κλινική ομάδα περιμένει τις αναφορές.","teaching_point":"Καλύτερο δεν σημαίνει αυτομάτως εγκεκριμένο για αποδέσμευση."},{"title":"Κίνδυνος","content":"Είναι δυνατές τόσο ψευδώς θετικές όσο και ψευδώς αρνητικές μεταβολές· οι επιπτώσεις δεν περιορίζονται σε ένα περιστατικό.","teaching_point":"Η ανάλυση επιπτώσεων πρέπει να γίνεται συστηματικά."}],"pre_results":[{"title":"Παλαιότερη σειρά","content":"Επικυρωμένο pipeline v3.4 με τεκμηριωμένη επίδοση."},{"title":"Νέα σειρά","content":"Η v4.1 καλεί επιπλέον indel/παραλλαγές splice, μεταξύ των οποίων ένα δυνητικά αναφέρσιμο συμβάν MET."},{"title":"Τεκμηρίωση","content":"Χωρίς καταχώριση ελέγχου αλλαγών, χωρίς έγκριση, χωρίς καθορισμένο πίνακα σύγκρισης."}],"material_or_resource_constraints":["Κλινική πίεση ως προς το TAT, αλλά με πιθανή επίπτωση στην ποιότητα της αναφοράς.","Υπάρχουν διαθέσιμα σύνολα δεδομένων σύγκρισης και παλαιότερες σειρές.","Μπορεί να απαιτηθεί επανάλυση παλαιότερων περιστατικών εάν υπάρχει συστηματική επίπτωση."],"reasoning_gate_upgrade":[{"id":"change_type","type":"single_choice","prompt":"Πώς πρέπει να αξιολογηθεί η αλλαγή του pipeline;","options":[{"id":"qm_relevant","label":"αλλαγή μεθόδου/ανάλυσης με σημασία για την ποιότητα και ανάγκη ελέγχου αλλαγών"},{"id":"cosmetic","label":"αμιγώς αισθητική αλλαγή"},{"id":"ignore","label":"άσχετο εφόσον το λογισμικό είναι νεότερο"},{"id":"clinical_only","label":"μόνο κλινική απόφαση"}],"correct":["qm_relevant"],"rationale":"Οι εκδόσεις του pipeline επηρεάζουν τις παραλλαγές που αναφέρονται και απαιτούν έλεγχο."},{"id":"immediate","type":"single_choice","prompt":"Ποιο είναι το σωστό άμεσο μέτρο;","options":[{"id":"hold_impact","label":"Αναστείλετε την αποδέσμευση των επηρεαζόμενων αναφορών και ξεκινήστε ανάλυση επιπτώσεων"},{"id":"release_new","label":"αποδεσμεύστε όλα τα νέα calls"},{"id":"rollback_silent","label":"σιωπηλή επαναφορά χωρίς τεκμηρίωση"},{"id":"delete_old","label":"διαγράψτε τα παλιά αποτελέσματα"}],"correct":["hold_impact"],"rationale":"Η αποδέσμευση χωρίς αξιολόγηση των επιπτώσεων θα ήταν επικίνδυνη."},{"id":"documentation","type":"multi_select","prompt":"Τι πρέπει να τεκμηριωθεί;","options":[{"id":"version","label":"ακριβείς εκδόσεις pipeline/caller/βάσης δεδομένων"},{"id":"validation","label":"αποτελέσματα επαλήθευσης/σύγκρισης"},{"id":"approval","label":"έγκριση/έλεγχος αλλαγών"},{"id":"none","label":"τίποτα εάν το αποτέλεσμα φαίνεται εύλογο"}],"correct":["version","validation","approval"],"rationale":"Η ιχνηλασιμότητα αποτελεί βασική απαίτηση του μετα-αναλυτικού σταδίου."},{"id":"affected_cases","type":"single_choice","prompt":"Πώς πρέπει να αντιμετωπιστούν τα δυνητικά επηρεαζόμενα περιστατικά;","options":[{"id":"case_review","label":"εντοπίστε τα επηρεαζόμενα περιστατικά και αξιολογήστε τα ιατρικά και από πλευράς ποιότητας"},{"id":"ignore_past","label":"μην ελέγχετε ποτέ παλαιότερα περιστατικά"},{"id":"report_all","label":"αναφέρετε όλες τις νέες παραλλαγές χωρίς έλεγχο"},{"id":"annotation_only","label":"αλλάξτε μόνο την επισημείωση"}],"correct":["case_review"],"rationale":"Η ανάλυση επιπτώσεων είναι ειδική για το περιστατικό και τον δείκτη."}],"decision_task":"Αποφασίστε πώς θα αντιμετωπιστούν η μη προγραμματισμένη αλλαγή του pipeline, τα ασύμφωνα calls και η αποδέσμευση των αναφορών.","expected_path":["Αναστείλετε την αποδέσμευση ασύμφωνων ή κλινικά κρίσιμων αναφορών.","Ολοκληρώστε εκ των υστέρων τον έλεγχο αλλαγών: τεκμηριώστε την αλλαγή, την αιτία, τις εκδόσεις και τους υπευθύνους.","Πραγματοποιήστε επαλήθευση με καθορισμένο σύνολο αναφοράς/παλαιότερων περιστατικών.","Αξιολογήστε τα ασύμφωνα calls ιατρικά και τεχνικά και επιβεβαιώστε τα ορθογωνικά εφόσον απαιτείται.","Διορθώστε τα πρότυπα αναφοράς ώστε να περιλαμβάνουν την έκδοση του pipeline/κατάσταση ανάλυσης.","Αποφασίστε εάν πρέπει να επαναξιολογηθούν παλαιότερα περιστατικά."],"acceptable_alternatives":["Προσωρινό rollback στο επικυρωμένο pipeline για αποδέσμευση ρουτίνας όσο επαληθεύεται η v4.1.","Μερική αποδέσμευση μη επηρεαζόμενων αναφορών εφόσον ο διαχωρισμός τεκμηριώνεται με τρόπο κατάλληλο για έλεγχο."],"low_value_traps":[{"label":"Το νέο pipeline είναι αυτομάτως καλύτερο","why_bad":"Καμία αποδέσμευση ρουτίνας χωρίς επαλήθευση."},{"label":"Σιωπηλό rollback","why_bad":"αποκρύπτει το συμβάν και καταστρέφει το ίχνος ελέγχου."},{"label":"Αποφασίζει μόνο η βιοπληροφορική","why_bad":"Οι κλινικά αναφέρσιμες αλλαγές απαιτούν αξιολόγηση από τη διοίκηση του εργαστηρίου, τη διαχείριση ποιότητας και ιατρικό προσωπικό."}],"twist":{"title":"Ένα παλαιότερα αρνητικό περιστατικό θα ήταν σήμερα θετικό","content":"Η ανάλυση επιπτώσεων δείχνει ότι η v4.1 καλεί εύλογα μια περιοχή splice του MET σε τρέχον περιστατικό, αλλά επισημαίνει επίσης δύο παλαιά artefacts χαμηλής ποιότητας ως παραλλαγές. Η αλλαγή βελτιώνει έναν τομέα, αλλά δημιουργεί νέες ανάγκες ελέγχου.","why_critical":"Το περιστατικό δείχνει γιατί η επαλήθευση δεν αποτελεί τροχοπέδη στην καινοτομία αλλά μέτρο προστασίας των ασθενών."},"result_packages":[{"id":"optimal_change_control","title":"Έλεγχος αλλαγών + επιπτώσεις","result":"Οι αναφορές τέθηκαν σε αναστολή, η v4.1 ελέγχθηκε με σύνολο παλαιότερων περιστατικών, το call του MET επιβεβαιώθηκε ορθογωνικά, τα φίλτρα artefacts προσαρμόστηκαν και η διαχείριση εκδόσεων τεκμηριώθηκε.","feedback":"Πολύ καλή ισορροπία μεταξύ καινοτομίας και διαχείρισης ποιότητας."},{"id":"release_without_validation","title":"Άμεση έγκριση του νέου pipeline","result":"Αργότερα εντοπίζονται ασύμφωνα artefacts και οι αναφορές πρέπει να διορθωθούν.","feedback":"Κρίσιμο σφάλμα μετα-αναλυτικού σταδίου/διαχείρισης ποιότητας."},{"id":"rollback_no_doc","title":"Σιωπηλό rollback","result":"Η λειτουργία ρουτίνας συνεχίζεται, αλλά το συμβάν δεν είναι ιχνηλάσιμο· είναι πιθανό εύρημα ελέγχου.","feedback":"Η διαδικασία φαίνεται να διασώθηκε, αλλά χάθηκε η δυνατότητα ελέγχου."}],"followup_logic":[{"trigger":"χωρίς διαχείριση εκδόσεων","action":"Αφαίρεση για το ίχνος ελέγχου και ανώτατο όριο","consequence":"Επηρεάζονται η Τεκμηρίωση και η Απόφαση διαδικασίας."},{"trigger":"Αναφορά αποδεσμεύτηκε χωρίς αξιολόγηση επιπτώσεων","action":"δυνατό critical_fail","consequence":"Ανώτατο όριο βαθμολογίας και προειδοποίηση στην αναφορά."}],"debrief_points":["Τα pipeline βιοπληροφορικής αποτελούν μέρος της μεθόδου.","Ο έλεγχος αλλαγών δεν προστατεύει από την πρόοδο, αλλά από την ανεξέλεγκτη πρόοδο.","Η διαχείριση εκδόσεων πρέπει να είναι ιχνηλάσιμη στο πλαίσιο αναφοράς/αρχειοθέτησης."],"instructor_notes":{"model_answer":"Hold/ανάλυση επιπτώσεων, έλεγχος αλλαγών, επαλήθευση, διαχείριση εκδόσεων, ιατρική αξιολόγηση ασύμφωνων περιστατικών και, εφόσον απαιτείται, rollback στην επικυρωμένη κατάσταση έως την έγκριση.","scoring_focus":["Απόφαση διαδικασίας","Τεκμηρίωση","Ασφάλεια ασθενών","CAPA/Έλεγχος"],"discussion_questions":["Ποια είναι η ελάχιστη επαλήθευση που απαιτείται για ενημέρωση pipeline;","Πότε πρέπει να επαναξιολογούνται παλαιότερες αναφορές;","Πώς πρέπει να τεκμηριώνονται οι βάσεις δεδομένων επισημείωσης;"]},"report_additions":["Ανατροπή: καλύτερη ευαισθησία + νέο φορτίο artefacts","Κρίσιμο σφάλμα: αποδέσμευση χωρίς επαλήθευση","Πρότυπη διαδρομή: Hold → Επιπτώσεις → Έλεγχος αλλαγών → Επαλήθευση → Αποδέσμευση"]}},"es":{"metadata":{"case_id":"LAB_POST_001_v1_0","base_id":"LAB_POST_001","title":"Versión del pipeline modificada, sin registro de cambios → calidad bioinformática y análisis de impacto","domain":"LAB","met_addon_type":"no","subdomain":"Postanalítica / bioinformática / control de cambios","case_type":"qm_capa_decision","length_class":"Complejo","estimated_minutes":{"min":20,"max":30},"difficulty":"Avanzado","status":"curated-core","review_flag":"Revisar core/MVP","review_priority":"high","core_decision":"El caller de variantes se actualizó de la versión 3.4 a la 4.1.","learning_objectives":["Priorizar correctamente el riesgo del evento para la seguridad del paciente y la calidad","Asegurar los cambios del pipeline/software mediante control de cambios, revalidación y versionado","Justificar de forma auditable la decisión de liberar, bloquear o repetir"],"tags":["Bioinformática","Pipeline","Versionado","Control de cambios","Auditoría","NGS, complex_case, AP1b_length_reclass"],"ap1b_decision":"LAB; longitud=compleja; dificultad=avanzada; estado=curated-core"},"base_case":{"id":"LAB_POST_001_v1_0","title":"Versión del pipeline modificada, sin registro de cambios → calidad bioinformática y análisis de impacto","short":"Pipeline sin registro de cambios","mode":"lab_qm","logic":"lab_pipeline","difficulty":"intermediate","estimated_time_min":"10–15","tags":["Bioinformática","Pipeline","Versionado","Control de cambios","Auditoría","NGS"],"run_overview":{"System":"Pipeline de NGS de ADN dirigido","Ausgangslage":"El caller de variantes se actualizó de la versión 3.4 a la 4.1.","Dokumentation":"Sin registro de cambios, sin aprobación formal y sin nota de verificación.","Betroffene Zeit":"2 semanas de funcionamiento rutinario.","Problem":"Dos variantes se filtran/clasifican de forma diferente en la nueva versión."},"qc_title":"Cambio de pipeline no documentado","qc_event":{"Auffälligkeit":"Los análisis antiguo y nuevo ya no son claramente comparables.","Risiko":"Consecuencias falsamente negativas o positivas en el informe, especialmente en variantes que determinan el tratamiento.","Audit-Risiko":"Falta la trazabilidad de los pasos de análisis y de las versiones de la base de datos/pipeline.","Konflikt":"Seguir trabajando con el nuevo software frente a pausar los informes y aclarar el impacto."},"decision_options":[{"id":"do_nothing","label":"No hacer nada; probablemente el nuevo pipeline sea mejor.","kind":"bad","feedback":"Críticamente incorrecto: los cambios de software son cambios metodológicos relevantes y deben controlarse.","score":{"safety":0,"process":0,"documentation":0,"capa":0,"communication":0}},{"id":"bioinfo_only","label":"Informar solo a bioinformática y seguir liberando los informes de laboratorio.","kind":"partial","feedback":"Insuficiente: se trata de la validez del informe, la liberación y la gestión de calidad, no solo de la técnica.","score":{"safety":8,"process":8,"documentation":4,"capa":2,"communication":4}},{"id":"impact_capa","label":"Abrir una desviación, pausar la liberación en función del riesgo, identificar los casos afectados y definir el análisis de impacto y, si procede, el reanálisis.","kind":"optimal","feedback":"Óptimo: se aseguran el control de cambios, la seguridad del paciente y la pista de auditoría.","score":{"safety":30,"process":24,"documentation":18,"capa":14,"communication":8}},{"id":"recall_all","label":"Retirar de inmediato y de forma general todos los informes anteriores.","kind":"partial","feedback":"Demasiado general: el reanálisis/la retirada deben justificarse mediante un análisis de impacto y riesgo.","score":{"safety":20,"process":10,"documentation":10,"capa":8,"communication":6}}],"root_cause_options":[{"id":"affected_runs","label":"Identificar todas las corridas/casos del periodo de la nueva versión del pipeline","correct":true,"feedback":"Sin una lista de casos no es posible realizar un análisis de impacto."},{"id":"calling_vs_annotation","label":"Comprobar si se ven afectados el calling/filtering o solo la anotación","correct":true,"feedback":"Los cambios de calling/filtering son más críticos para el informe."},{"id":"released_reports","label":"Priorizar los informes ya liberados que condicionan decisiones terapéuticas","correct":true,"feedback":"La relevancia clínica determina la necesidad de reanálisis."},{"id":"ignore_negative","label":"No revisar los casos negativos","correct":false,"feedback":"Incorrecto: precisamente los informes negativos pueden estar afectados."},{"id":"verification_set","label":"Completar el conjunto de datos de referencia/verificación para la versión 4.1","correct":true,"feedback":"Las nuevas versiones deben evaluarse localmente."}],"capa_components":[{"id":"dev","label":"Desviación: cambio de pipeline no documentado"},{"id":"pause","label":"Medida inmediata: pausar/controlar las liberaciones según el riesgo"},{"id":"impact","label":"Corrección: análisis de impacto y reanálisis definido"},{"id":"sop","label":"Prevención: SOP para cambios del pipeline con campos obligatorios"},{"id":"eff","label":"Comprobación de eficacia: los cambios posteriores quedan completamente documentados"}],"audit_checks":[{"id":"version","label":"Versión antigua/nueva del pipeline y momento del cambio documentados","correct":true},{"id":"risk","label":"La evaluación de riesgo es trazable para cada clase de informe","correct":true},{"id":"approval","label":"Aprobación de la nueva versión del pipeline documentada","correct":true},{"id":"training","label":"Comunicación/formación del personal afectado documentada","correct":true},{"id":"hide","label":"Comentar el cambio solo verbalmente de forma interna; no documentarlo","correct":false}],"optimal_summary":"Solución óptima: tratar el cambio del pipeline como una desviación, realizar un análisis de impacto, reanalizar según el riesgo los informes afectados y establecer control de cambios para futuras actualizaciones."},"deep_dive":{"version":"v1.7b","case_id":"LAB_POST_001_v1_0","title":"Versión del pipeline modificada, sin registro de cambios: calidad bioinformática y análisis de impacto","domain":"LAB","target_course":"Avanzado integrado","deep_dive_priority":"complex_anchor","target_role":"Dirección del laboratorio / calidad bioinformática","estimated_minutes_deep":"20–30","learning_objectives":["Reconocer los cambios del pipeline/software como cambios metodológicos relevantes para la calidad.","Derivar el análisis de impacto, el versionado y la revalidación/verificación necesarios.","Gestionar de forma auditable la liberación de informes ante resultados discordantes del pipeline."],"opening_scene":"Se instaló 'rápidamente' una actualización bioinformática porque el nuevo caller promete una mejor detección de indels. Al día siguiente, varias listas de variantes difieren de los resultados anteriores. No existe registro de cambios.","case_briefing":"Panel NGS de patología molecular, 48 casos de pacientes en el lote actual. El caller de variantes se actualizó de 3.4 a 4.1. La base de datos de referencia y la anotación también recibieron actualizaciones menores. El cambio no había sido aprobado previamente en la documentación de calidad.","context_cards":[{"title":"Discordancia","content":"Las variantes informables difieren en 6/48 casos. Un caso afecta a una región de splice de MET potencialmente determinante para el tratamiento.","teaching_point":"No todos los cambios de software son puramente técnicos."},{"title":"Versionado","content":"El borrador del informe no indica la versión del pipeline; los informes antiguos solo contienen 'NGS Pipeline'.","teaching_point":"Sin versionado se pierde la trazabilidad."},{"title":"Conflicto de equipo","content":"Bioinformática dice: 'El nuevo caller es mejor.' Calidad pregunta: '¿Dónde está la verificación?' El equipo clínico espera los informes.","teaching_point":"Mejor no significa aprobado para su liberación."},{"title":"Riesgo","content":"Son posibles cambios tanto falsamente positivos como falsamente negativos; el impacto no se limita a un solo caso.","teaching_point":"El análisis de impacto debe realizarse de forma sistemática."}],"pre_results":[{"title":"Corrida anterior","content":"Pipeline validado v3.4 con rendimiento documentado."},{"title":"Nueva corrida","content":"v4.1 detecta indels/variantes de splice adicionales, incluido un evento MET potencialmente informable."},{"title":"Documentación","content":"Sin registro de control de cambios, sin aprobación y sin matriz de comparación definida."}],"material_or_resource_constraints":["Presión clínica por el TAT, pero con posible impacto en la calidad del informe.","Hay disponibles conjuntos de datos comparativos y corridas anteriores.","Puede ser necesario reanalizar casos anteriores si existe un impacto sistemático."],"reasoning_gate_upgrade":[{"id":"change_type","type":"single_choice","prompt":"¿Cómo debe evaluarse el cambio del pipeline?","options":[{"id":"qm_relevant","label":"cambio de método/análisis relevante para la calidad que requiere control de cambios"},{"id":"cosmetic","label":"cambio puramente cosmético"},{"id":"ignore","label":"irrelevante si el software es más nuevo"},{"id":"clinical_only","label":"solo una decisión clínica"}],"correct":["qm_relevant"],"rationale":"Las versiones del pipeline afectan a las variantes informadas y requieren control."},{"id":"immediate","type":"single_choice","prompt":"¿Cuál es la medida inmediata correcta?","options":[{"id":"hold_impact","label":"Pausar la liberación de los informes afectados e iniciar un análisis de impacto"},{"id":"release_new","label":"liberar todos los nuevos calls"},{"id":"rollback_silent","label":"hacer un rollback silencioso sin documentación"},{"id":"delete_old","label":"eliminar los resultados antiguos"}],"correct":["hold_impact"],"rationale":"Liberar sin evaluar el impacto sería arriesgado."},{"id":"documentation","type":"multi_select","prompt":"¿Qué debe documentarse?","options":[{"id":"version","label":"versiones exactas del pipeline/caller/base de datos"},{"id":"validation","label":"resultados de verificación/comparación"},{"id":"approval","label":"aprobación/control de cambios"},{"id":"none","label":"nada si el resultado parece plausible"}],"correct":["version","validation","approval"],"rationale":"La trazabilidad es un requisito esencial de la postanalítica."},{"id":"affected_cases","type":"single_choice","prompt":"¿Cómo deben gestionarse los casos potencialmente afectados?","options":[{"id":"case_review","label":"identificar los casos afectados y evaluarlos médica y cualitativamente"},{"id":"ignore_past","label":"no revisar nunca los casos antiguos"},{"id":"report_all","label":"informar todas las variantes nuevas sin revisión"},{"id":"annotation_only","label":"cambiar solo la anotación"}],"correct":["case_review"],"rationale":"El análisis de impacto es específico del caso y del marcador."}],"decision_task":"Decidir cómo gestionar el cambio no planificado del pipeline, los calls discordantes y la liberación de informes.","expected_path":["Pausar la liberación de informes discordantes o relevantes para la decisión.","Completar retrospectivamente el control de cambios: documentar el cambio, el motivo, las versiones y los responsables.","Realizar la verificación con un conjunto definido de referencia/casos anteriores.","Evaluar médica y técnicamente los calls discordantes y confirmarlos de forma ortogonal si es necesario.","Corregir las plantillas de informe para incluir la versión del pipeline/el estado del análisis.","Decidir si es necesario reevaluar casos anteriores."],"acceptable_alternatives":["Rollback temporal al pipeline validado para la liberación rutinaria mientras se verifica v4.1.","Liberación parcial de los informes no afectados si la separación está documentada de forma auditable."],"low_value_traps":[{"label":"El nuevo pipeline es automáticamente mejor","why_bad":"No hay liberación rutinaria sin verificación."},{"label":"Rollback silencioso","why_bad":"oculta el evento y destruye la pista de auditoría."},{"label":"Solo bioinformática decide","why_bad":"Los cambios clínicamente informables requieren evaluación por la dirección del laboratorio, calidad y personal médico."}],"twist":{"title":"Un caso antiguo negativo sería hoy positivo","content":"El análisis de impacto muestra que v4.1 detecta de forma plausible una región de splice de MET en un caso actual, pero también marca dos artefactos antiguos de baja calidad como variantes. El cambio mejora un área, pero genera nuevas necesidades de revisión.","why_critical":"El caso muestra por qué la verificación no frena la innovación, sino que protege al paciente."},"result_packages":[{"id":"optimal_change_control","title":"Control de cambios + impacto","result":"Se pausaron los informes, se evaluó v4.1 con un conjunto de casos anteriores, se confirmó ortogonalmente el call de MET, se ajustaron los filtros de artefactos y se documentó el versionado.","feedback":"Muy buen equilibrio entre innovación y gestión de calidad."},{"id":"release_without_validation","title":"Nuevo pipeline liberado directamente","result":"Más tarde se descubren artefactos discordantes y es necesario corregir los informes.","feedback":"Error crítico de postanalítica/gestión de calidad."},{"id":"rollback_no_doc","title":"Rollback silencioso","result":"La rutina continúa, pero el evento no es trazable; es probable un hallazgo de auditoría.","feedback":"Proceso aparentemente salvado, pero se pierde la auditabilidad."}],"followup_logic":[{"trigger":"sin versionado","action":"Penalización por pista de auditoría y tope","consequence":"Se ven afectadas la Documentación y la Decisión de proceso."},{"trigger":"Informe liberado sin evaluación de impacto","action":"critical_fail posible","consequence":"Tope de puntuación y advertencia en el informe."}],"debrief_points":["Los pipelines bioinformáticos forman parte del método.","El control de cambios no protege frente al progreso, sino frente al progreso no controlado.","El versionado debe ser trazable en el contexto del informe/archivo."],"instructor_notes":{"model_answer":"Hold/análisis de impacto, control de cambios, verificación, versionado, evaluación médica de los casos discordantes y, si es necesario, rollback al estado validado hasta la aprobación.","scoring_focus":["Decisión de proceso","Documentación","Seguridad del paciente","CAPA/Auditoría"],"discussion_questions":["¿Cuál es la verificación mínima necesaria para una actualización del pipeline?","¿Cuándo deben reevaluarse los informes anteriores?","¿Cómo deben documentarse las bases de datos de anotación?"]},"report_additions":["Giro: mejor sensibilidad + nueva carga de artefactos","Error crítico: liberación sin verificación","Ruta de referencia: Hold → Impacto → Control de cambios → Verificación → Liberación"]}},"fr":{"metadata":{"case_id":"LAB_POST_001_v1_0","base_id":"LAB_POST_001","title":"Version du pipeline modifiée, sans journal des modifications → qualité bioinformatique et analyse d’impact","domain":"LAB","met_addon_type":"no","subdomain":"Post-analytique / bioinformatique / gestion des modifications","case_type":"qm_capa_decision","length_class":"Complexe","estimated_minutes":{"min":20,"max":30},"difficulty":"Avancé","status":"curated-core","review_flag":"Vérifier core/MVP","review_priority":"high","core_decision":"Le logiciel d’appel de variants a été mis à jour de la version 3.4 à la 4.1.","learning_objectives":["Hiérarchiser correctement le risque de l’événement pour la sécurité des patients et la qualité","Sécuriser les modifications du pipeline/logiciel par la gestion des modifications, la revalidation et le versionnage","Justifier de manière auditable la décision de libérer, bloquer ou répéter"],"tags":["Bioinformatique","Pipeline","Versionnage","Gestion des modifications","Audit","NGS, complex_case, AP1b_length_reclass"],"ap1b_decision":"LAB ; longueur=complexe ; difficulté=avancée ; statut=curated-core"},"base_case":{"id":"LAB_POST_001_v1_0","title":"Version du pipeline modifiée, sans journal des modifications → qualité bioinformatique et analyse d’impact","short":"Pipeline sans journal des modifications","mode":"lab_qm","logic":"lab_pipeline","difficulty":"intermediate","estimated_time_min":"10–15","tags":["Bioinformatique","Pipeline","Versionnage","Gestion des modifications","Audit","NGS"],"run_overview":{"System":"Pipeline de NGS ADN ciblé","Ausgangslage":"Le logiciel d’appel de variants a été mis à jour de la version 3.4 à la 4.1.","Dokumentation":"Aucun journal des modifications, aucune approbation formelle, aucune note de vérification.","Betroffene Zeit":"2 semaines d’utilisation en routine.","Problem":"Deux variants sont filtrés/classés différemment dans la nouvelle version."},"qc_title":"Modification non documentée du pipeline","qc_event":{"Auffälligkeit":"Les analyses ancienne et nouvelle ne sont plus clairement comparables.","Risiko":"Conséquences faussement négatives ou positives sur le compte rendu, en particulier pour les variants déterminant le traitement.","Audit-Risiko":"La traçabilité des étapes d’analyse et des versions de la base de données/du pipeline fait défaut.","Konflikt":"Continuer avec le nouveau logiciel ou suspendre les comptes rendus et clarifier l’impact."},"decision_options":[{"id":"do_nothing","label":"Ne rien faire ; le nouveau pipeline est probablement meilleur.","kind":"bad","feedback":"Erreur critique : les modifications logicielles sont des changements méthodologiquement pertinents et doivent être maîtrisées.","score":{"safety":0,"process":0,"documentation":0,"capa":0,"communication":0}},{"id":"bioinfo_only","label":"Informer uniquement la bioinformatique et continuer à libérer les comptes rendus de laboratoire.","kind":"partial","feedback":"Insuffisant : il s’agit de la validité du compte rendu, de sa libération et de la qualité, pas seulement de la technique.","score":{"safety":8,"process":8,"documentation":4,"capa":2,"communication":4}},{"id":"impact_capa","label":"Ouvrir une déviation, suspendre la libération selon le risque, identifier les cas concernés et définir l’analyse d’impact ainsi qu’une éventuelle réanalyse.","kind":"optimal","feedback":"Optimal : la gestion des modifications, la sécurité des patients et la piste d’audit sont garanties.","score":{"safety":30,"process":24,"documentation":18,"capa":14,"communication":8}},{"id":"recall_all","label":"Rappeler immédiatement et systématiquement tous les anciens comptes rendus.","kind":"partial","feedback":"Trop général : la réanalyse/le rappel doivent être justifiés par une analyse d’impact et de risque.","score":{"safety":20,"process":10,"documentation":10,"capa":8,"communication":6}}],"root_cause_options":[{"id":"affected_runs","label":"Identifier toutes les séries/tous les cas de la période d’utilisation de la nouvelle version du pipeline","correct":true,"feedback":"Aucune analyse d’impact n’est possible sans liste des cas."},{"id":"calling_vs_annotation","label":"Vérifier si le calling/le filtrage ou seulement l’annotation sont concernés","correct":true,"feedback":"Les modifications du calling/filtrage sont plus critiques pour le compte rendu."},{"id":"released_reports","label":"Prioriser les comptes rendus déjà libérés influençant une décision thérapeutique","correct":true,"feedback":"La pertinence clinique détermine la nécessité d’une réanalyse."},{"id":"ignore_negative","label":"Ne pas revoir les cas négatifs","correct":false,"feedback":"Faux : les comptes rendus négatifs peuvent justement être concernés."},{"id":"verification_set","label":"Compléter le jeu de données de référence/vérification pour la version 4.1","correct":true,"feedback":"Les nouvelles versions doivent être contrôlées localement."}],"capa_components":[{"id":"dev","label":"Déviation : modification non documentée du pipeline"},{"id":"pause","label":"Mesure immédiate : suspendre/contrôler les libérations en fonction du risque"},{"id":"impact","label":"Correction : analyse d’impact et réanalyse définie"},{"id":"sop","label":"Prévention : SOP pour les modifications du pipeline avec champs obligatoires"},{"id":"eff","label":"Vérification d’efficacité : les modifications suivantes sont intégralement documentées"}],"audit_checks":[{"id":"version","label":"Ancienne/nouvelle version du pipeline et date du changement documentées","correct":true},{"id":"risk","label":"L’évaluation du risque est traçable pour chaque catégorie de compte rendu","correct":true},{"id":"approval","label":"Approbation de la nouvelle version du pipeline documentée","correct":true},{"id":"training","label":"Communication/formation des personnes concernées documentée","correct":true},{"id":"hide","label":"Discuter du changement uniquement oralement en interne ; ne pas le documenter","correct":false}],"optimal_summary":"Solution optimale : traiter la modification du pipeline comme une déviation, réaliser une analyse d’impact, réanalyser les comptes rendus concernés selon le risque et instaurer une gestion des modifications pour les futures mises à jour."},"deep_dive":{"version":"v1.7b","case_id":"LAB_POST_001_v1_0","title":"Version du pipeline modifiée, sans journal des modifications : qualité bioinformatique et analyse d’impact","domain":"LAB","target_course":"Avancé intégré","deep_dive_priority":"complex_anchor","target_role":"Direction du laboratoire / qualité bioinformatique","estimated_minutes_deep":"20–30","learning_objectives":["Reconnaître les modifications du pipeline/logiciel comme des changements méthodologiques pertinents pour la qualité.","Déduire l’analyse d’impact, le versionnage et la revalidation/vérification nécessaires.","Gérer de manière auditable la libération des comptes rendus en cas de résultats discordants du pipeline."],"opening_scene":"Une mise à jour bioinformatique a été installée 'juste rapidement', car le nouveau caller promet une meilleure détection des indels. Le lendemain, plusieurs listes de variants diffèrent des résultats antérieurs. Il n’existe aucun journal des modifications.","case_briefing":"Panel NGS de pathologie moléculaire, 48 cas patients dans le lot actuel. Le logiciel d’appel de variants est passé de la version 3.4 à 4.1. La base de données de référence et l’annotation ont également fait l’objet de mises à jour mineures. La modification n’avait pas été approuvée au préalable dans la documentation qualité.","context_cards":[{"title":"Discordance","content":"Les variants devant être rapportés diffèrent dans 6/48 cas. Un cas concerne une région d’épissage de MET potentiellement déterminante pour le traitement.","teaching_point":"Toute modification logicielle n’est pas purement technique."},{"title":"Versionnage","content":"Le projet de compte rendu n’indique aucune version du pipeline ; les anciens comptes rendus mentionnent seulement 'NGS Pipeline'.","teaching_point":"Sans versionnage, la traçabilité est perdue."},{"title":"Conflit d’équipe","content":"La bioinformatique dit : 'Le nouveau caller est meilleur.' La qualité demande : 'Où est la vérification ?' L’équipe clinique attend les comptes rendus.","teaching_point":"Meilleur ne signifie pas approuvé pour la routine."},{"title":"Risque","content":"Des modifications faussement positives comme faussement négatives sont possibles ; l’impact ne se limite pas à un seul cas.","teaching_point":"L’analyse d’impact doit être systématique."}],"pre_results":[{"title":"Série précédente","content":"Pipeline validé v3.4 avec performances documentées."},{"title":"Nouvelle série","content":"La v4.1 appelle des indels/variants d’épissage supplémentaires, dont un événement MET potentiellement rapportable."},{"title":"Documentation","content":"Aucune entrée de gestion des modifications, aucune approbation, aucune matrice de comparaison définie."}],"material_or_resource_constraints":["Pression clinique sur le TAT, mais impact potentiel sur la qualité du compte rendu.","Des jeux de données comparatifs et des séries antérieures sont disponibles.","Une réanalyse de cas antérieurs peut être nécessaire en cas d’impact systématique."],"reasoning_gate_upgrade":[{"id":"change_type","type":"single_choice","prompt":"Comment évaluer la modification du pipeline ?","options":[{"id":"qm_relevant","label":"modification de méthode/analyse pertinente pour la qualité nécessitant une gestion des modifications"},{"id":"cosmetic","label":"modification purement cosmétique"},{"id":"ignore","label":"sans importance si le logiciel est plus récent"},{"id":"clinical_only","label":"décision clinique uniquement"}],"correct":["qm_relevant"],"rationale":"Les versions du pipeline influencent les variants rapportés et doivent être maîtrisées."},{"id":"immediate","type":"single_choice","prompt":"Quelle est la bonne mesure immédiate ?","options":[{"id":"hold_impact","label":"Suspendre la libération des comptes rendus concernés et lancer une analyse d’impact"},{"id":"release_new","label":"libérer tous les nouveaux calls"},{"id":"rollback_silent","label":"effectuer un rollback silencieux sans documentation"},{"id":"delete_old","label":"supprimer les anciens résultats"}],"correct":["hold_impact"],"rationale":"Une libération sans évaluation de l’impact serait risquée."},{"id":"documentation","type":"multi_select","prompt":"Que faut-il documenter ?","options":[{"id":"version","label":"versions exactes du pipeline/caller/de la base de données"},{"id":"validation","label":"résultats de vérification/comparaison"},{"id":"approval","label":"approbation/gestion des modifications"},{"id":"none","label":"rien si le résultat paraît plausible"}],"correct":["version","validation","approval"],"rationale":"La traçabilité est une exigence fondamentale du post-analytique."},{"id":"affected_cases","type":"single_choice","prompt":"Comment gérer les cas potentiellement concernés ?","options":[{"id":"case_review","label":"identifier les cas concernés et les évaluer sur les plans médical et qualité"},{"id":"ignore_past","label":"ne jamais revoir les anciens cas"},{"id":"report_all","label":"rapporter tous les nouveaux variants sans vérification"},{"id":"annotation_only","label":"modifier uniquement l’annotation"}],"correct":["case_review"],"rationale":"L’analyse d’impact est spécifique au cas et au marqueur."}],"decision_task":"Décider comment gérer la modification non planifiée du pipeline, les calls discordants et la libération des comptes rendus.","expected_path":["Suspendre la libération des comptes rendus discordants ou déterminants pour la décision.","Compléter rétrospectivement la gestion des modifications : documenter la modification, sa raison, les versions et les responsables.","Réaliser la vérification à l’aide d’un ensemble défini de référence/anciens cas.","Évaluer les calls discordants sur les plans médical et technique et les confirmer par une méthode orthogonale si nécessaire.","Corriger les modèles de compte rendu pour inclure la version du pipeline/l’état de l’analyse.","Décider si des cas antérieurs doivent être réévalués."],"acceptable_alternatives":["Rollback temporaire vers le pipeline validé pour la libération en routine pendant la vérification de la v4.1.","Libération partielle des comptes rendus non concernés si la séparation est documentée de manière auditable."],"low_value_traps":[{"label":"Le nouveau pipeline est automatiquement meilleur","why_bad":"Pas de libération en routine sans vérification."},{"label":"Rollback silencieux","why_bad":"masque l’événement et détruit la piste d’audit."},{"label":"La bioinformatique décide seule","why_bad":"Les modifications cliniquement rapportables nécessitent une évaluation par la direction du laboratoire, la qualité et le corps médical."}],"twist":{"title":"Un ancien cas négatif serait aujourd’hui positif","content":"L’analyse d’impact montre que la v4.1 appelle de façon plausible une région d’épissage de MET dans un cas actuel, mais signale aussi deux anciens artéfacts de faible qualité comme variants. La modification améliore un domaine, mais crée de nouveaux besoins de revue.","why_critical":"Ce cas montre pourquoi la vérification n’est pas un frein à l’innovation, mais une mesure de protection des patients."},"result_packages":[{"id":"optimal_change_control","title":"Gestion des modifications + impact","result":"Les comptes rendus ont été suspendus, la v4.1 testée sur un ensemble d’anciens cas, le call MET confirmé par une méthode orthogonale, les filtres d’artéfacts ajustés et le versionnage documenté.","feedback":"Très bon équilibre entre innovation et management de la qualité."},{"id":"release_without_validation","title":"Nouveau pipeline libéré directement","result":"Des artéfacts discordants sont découverts ultérieurement et les comptes rendus doivent être corrigés.","feedback":"Erreur critique de post-analytique/qualité."},{"id":"rollback_no_doc","title":"Rollback silencieux","result":"La routine se poursuit, mais l’événement n’est pas traçable ; un écart d’audit est probable.","feedback":"Processus apparemment sauvé, mais auditabilité perdue."}],"followup_logic":[{"trigger":"absence de versionnage","action":"Pénalité de piste d’audit et plafond","consequence":"La Documentation et la Décision de processus sont affectées."},{"trigger":"Compte rendu libéré sans évaluation de l’impact","action":"critical_fail possible","consequence":"Plafond de score et avertissement dans le compte rendu."}],"debrief_points":["Les pipelines bioinformatiques font partie de la méthode.","La gestion des modifications ne protège pas du progrès, mais du progrès non maîtrisé.","Le versionnage doit être traçable dans le contexte du compte rendu/de l’archivage."],"instructor_notes":{"model_answer":"Hold/analyse d’impact, gestion des modifications, vérification, versionnage, évaluation médicale des cas discordants et, si nécessaire, rollback vers l’état validé jusqu’à l’approbation.","scoring_focus":["Décision de processus","Documentation","Sécurité des patients","CAPA/Audit"],"discussion_questions":["Quelle est la vérification minimale requise pour une mise à jour du pipeline ?","Quand faut-il réévaluer les anciens comptes rendus ?","Comment documenter les bases de données d’annotation ?"]},"report_additions":["Twist : meilleure sensibilité + nouvelle charge d’artéfacts","Erreur critique : libération sans vérification","Parcours de référence : Hold → Impact → Gestion des modifications → Vérification → Libération"]}}}};
const EXACT={"en":{"Pipeline-Version geändert, kein Change-Log → Bioinformatik-QM und Impact-Analyse":"Pipeline version changed, no change log → bioinformatics QC and impact analysis","Postanalytik / Bioinformatik / Change-Control":"Post-analytics / bioinformatics / change control","Complex":"Complex","Advanced":"Advanced","Core/MVP prüfen":"Review core/MVP","Variant Caller wurde von Version 3.4 auf 4.1 aktualisiert.":"The variant caller was updated from version 3.4 to 4.1.","Patientensicherheits- und Qualitätsrisiko des Ereignisses korrekt priorisieren":"Correctly prioritize the patient-safety and quality risk of the event","Pipeline-/Softwareänderungen über Change-Control, Revalidierung und Versionierung absichern":"Safeguard pipeline/software changes through change control, revalidation and versioning","Freigabe-, Sperr- oder Wiederholungsentscheidung auditfähig begründen":"Provide an audit-ready justification for release, hold or repeat decisions","Bioinformatik":"Bioinformatics","Pipeline":"Pipeline","Versionierung":"Versioning","Change-Control":"Change control","Audit":"Audit","NGS":"NGS","Pipeline ohne Change-Log":"Pipeline without a change log","Targeted DNA-NGS Pipeline":"Targeted DNA-NGS pipeline","Kein Change-Log, keine formale Freigabe, keine Verifizierungsnotiz.":"No change log, no formal approval, no verification record.","2 Wochen Routinebetrieb.":"2 weeks of routine operation.","Zwei Varianten werden in der neuen Version anders gefiltert/klassifiziert.":"Two variants are filtered/classified differently in the new version.","Nicht dokumentierte Pipelineänderung":"Undocumented pipeline change","Alte und neue Auswertung sind nicht mehr eindeutig vergleichbar.":"The old and new analyses are no longer directly comparable.","Falsch-negative oder falsch-positive Befundkonsequenzen, besonders bei therapieentscheidenden Varianten.":"False-negative or false-positive reporting consequences, especially for treatment-determining variants.","Rückverfolgbarkeit von Auswertungsschritten und Datenbank-/Pipelineversion fehlt.":"Traceability of analysis steps and database/pipeline versions is missing.","Weiterarbeiten mit neuer Software vs. Befunde pausieren und Impact klären.":"Continue with the new software vs. hold reports and clarify the impact.","Nichts tun, neue Pipeline ist vermutlich besser.":"Do nothing; the new pipeline is probably better.","Kritisch falsch: Softwareänderungen sind methodisch relevante Änderungen und müssen kontrolliert werden.":"Critically wrong: software changes are methodologically relevant changes and must be controlled.","Nur Bioinformatik informieren, Laborbefunde weiter freigeben.":"Inform bioinformatics only and continue releasing laboratory reports.","Unzureichend: Es geht um Befundvalidität, Freigabe und QM, nicht nur um Technik.":"Insufficient: this concerns report validity, release and quality management, not just technology.","Abweichung eröffnen, Freigabe risikobasiert pausieren, betroffene Fälle identifizieren, Impact-Analyse und ggf. Reanalyse festlegen.":"Open a deviation, pause release based on risk, identify affected cases, and define impact analysis and reanalysis if needed.","Optimal: Change-Control, Patientensicherheit und Audit-Trail werden gesichert.":"Optimal: change control, patient safety and the audit trail are secured.","Alle alten Befunde sofort pauschal zurückrufen.":"Immediately recall all previous reports across the board.","Zu pauschal: Reanalyse/Rückruf müssen durch Impact- und Risikoanalyse begründet werden.":"Too broad: reanalysis/recall must be justified by impact and risk analysis.","Alle Runs/Fälle im Zeitraum der neuen Pipelineversion identifizieren":"Identify all runs/cases processed during the period of the new pipeline version","Ohne Fallliste keine Impact-Analyse.":"No impact analysis is possible without a case list.","Prüfen, ob Calling/Filtering oder nur Annotation betroffen ist":"Check whether calling/filtering or only annotation is affected","Calling-/Filtering-Änderungen sind befundkritischer.":"Calling/filtering changes are more critical for reporting.","Bereits freigegebene therapieentscheidende Befunde priorisieren":"Prioritize already released reports that affect treatment decisions","Klinische Relevanz steuert Reanalysebedarf.":"Clinical relevance determines the need for reanalysis.","Negative Fälle nicht prüfen":"Do not review negative cases","Falsch: Gerade negative Befunde können betroffen sein.":"Wrong: negative reports in particular may be affected.","Referenz-/Verifizierungsdatensatz für Version 4.1 nachziehen":"Complete the reference/verification dataset for version 4.1","Neue Versionen müssen lokal kontrolliert werden.":"New versions must be evaluated locally.","Abweichung: nicht dokumentierte Pipelineänderung":"Deviation: undocumented pipeline change","Sofortmaßnahme: Freigaben risikobasiert pausieren/kontrollieren":"Immediate action: pause/control releases based on risk","Korrektur: Impact-Analyse und definierte Reanalyse":"Correction: impact analysis and defined reanalysis","Prävention: SOP für Pipeline-Change mit Pflichtfeldern":"Prevention: SOP for pipeline changes with mandatory fields","Wirksamkeitsprüfung: nächste Änderungen vollständig dokumentiert":"Effectiveness check: subsequent changes are fully documented","Alte/neue Pipelineversion und Zeitpunkt dokumentiert":"Old/new pipeline version and timing documented","Risikobewertung pro Befundklasse nachvollziehbar":"Risk assessment is traceable for each report class","Freigabe der neuen Pipelineversion dokumentiert":"Approval of the new pipeline version documented","Kommunikation/Schulung der betroffenen Personen dokumentiert":"Communication/training of affected personnel documented","Change nur intern mündlich besprechen, nicht dokumentieren":"Discuss the change only verbally in-house; do not document it","Optimale Lösung: Pipelineänderung als Abweichung behandeln, Impact-Analyse durchführen, betroffene Befunde risikobasiert reanalysieren und Change-Control für künftige Updates etablieren.":"Optimal solution: treat the pipeline change as a deviation, perform an impact analysis, reanalyse affected reports based on risk, and establish change control for future updates.","Pipeline-Version geändert, kein Change-Log: Bioinformatik-QM und Impact-Analyse":"Pipeline version changed, no change log: bioinformatics QC and impact analysis","LAB":"LAB","Advanced Integrated":"Advanced Integrated","Laborleitung / Bioinformatik-QM":"Laboratory management / bioinformatics QC","Pipeline-/Softwareänderungen als qualitätsrelevante Methodenänderung erkennen.":"Recognize pipeline/software changes as quality-relevant methodological changes.","Impact-Analyse, Versionierung und Revalidierung/Verifizierung ableiten.":"Derive the required impact analysis, versioning and revalidation/verification.","Befundfreigabe bei diskordanten Pipeline-Ergebnissen auditfähig steuern.":"Manage report release for discordant pipeline results in an audit-ready manner.","Ein Bioinformatik-Update wurde 'nur kurz' eingespielt, weil der neue Caller bessere Indel-Erkennung verspricht. Am nächsten Tag unterscheiden sich mehrere Variantenlisten von alten Ergebnissen. Ein Change-Log existiert nicht.":"A bioinformatics update was installed 'just quickly' because the new caller promises better indel detection. The next day, several variant lists differ from previous results. There is no change log.","Molekularpathologisches NGS-Panel, 48 Patientenfälle im aktuellen Batch. Variant Caller von 3.4 auf 4.1 aktualisiert. Referenzdatenbank und Annotation wurden ebenfalls minor aktualisiert. Die Änderung wurde nicht vorab in der QM-Dokumentation freigegeben.":"Molecular pathology NGS panel, 48 patient cases in the current batch. The variant caller was updated from 3.4 to 4.1. The reference database and annotation were also updated with minor revisions. The change was not approved in the quality documentation beforehand.","Diskordanz":"Discordance","Bei 6/48 Fällen unterscheiden sich reportable variants. Ein Fall betrifft eine potenziell therapieentscheidende MET-Splice-Region.":"Reportable variants differ in 6/48 cases. One case involves a potentially treatment-determining MET splice region.","Nicht jede Softwareänderung ist rein technisch.":"Not every software change is purely technical.","Im Berichtsentwurf ist keine Pipeline-Version angegeben; alte Reports enthalten nur 'NGS Pipeline'.":"The draft report does not specify a pipeline version; old reports contain only 'NGS Pipeline'.","Ohne Versionierung fehlt Rückverfolgbarkeit.":"Without versioning, traceability is lost.","Teamkonflikt":"Team conflict","Bioinformatik sagt: 'Der neue Caller ist besser.' QM fragt: 'Wo ist die Verifizierung?' Klinik wartet auf Befunde.":"Bioinformatics says: 'The new caller is better.' Quality management asks: 'Where is the verification?' The clinical team is waiting for reports.","Besser ist nicht gleich freigegeben.":"Better does not mean approved for release.","Risiko":"Risk","Sowohl falsch-positive als auch falsch-negative Änderungen sind möglich; Impact ist nicht auf einen Fall begrenzt.":"Both false-positive and false-negative changes are possible; the impact is not limited to a single case.","Impact-Analyse muss systematisch erfolgen.":"Impact analysis must be systematic.","Alter Lauf":"Previous run","Validierte Pipeline v3.4 mit dokumentierter Leistungsfähigkeit.":"Validated pipeline v3.4 with documented performance.","Neuer Lauf":"New run","v4.1 ruft zusätzliche Indels/Splice-Varianten, darunter ein potenziell reportables MET-Ereignis.":"v4.1 calls additional indels/splice variants, including a potentially reportable MET event.","Dokumentation":"Documentation","kein Change-Control-Eintrag, keine Freigabe, keine definierte Vergleichsmatrix.":"No change-control entry, no approval, no defined comparison matrix.","Klinischer TAT-Druck, aber potenzieller Einfluss auf Befundqualität.":"Clinical TAT pressure, but a potential impact on report quality.","Vergleichsdatensätze und Alt-Runs sind verfügbar.":"Comparison datasets and previous runs are available.","Re-Analyse früherer Fälle könnte nötig werden, wenn systematischer Einfluss besteht.":"Reanalysis of previous cases may be necessary if there is a systematic impact.","Wie ist die Pipelineänderung zu bewerten?":"How should the pipeline change be assessed?","qualitätsrelevante Methoden-/Auswertungsänderung mit Change-Control-Bedarf":"quality-relevant method/analysis change requiring change control","rein kosmetische Änderung":"purely cosmetic change","irrelevant, wenn Software neuer ist":"irrelevant if the software is newer","nur klinische Entscheidung":"clinical decision only","Pipelineversionen beeinflussen berichtete Varianten und benötigen Kontrolle.":"Pipeline versions affect reported variants and require control.","Was ist die richtige Sofortmaßnahme?":"What is the correct immediate action?","Freigabe betroffener Befunde pausieren und Impact-Analyse starten":"Pause release of affected reports and start an impact analysis","alle neuen Calls freigeben":"release all new calls","heimlich zurückrollen ohne Doku":"roll back silently without documentation","alte Ergebnisse löschen":"delete old results","Freigabe ohne Impact wäre riskant.":"Release without assessing the impact would be risky.","Was muss dokumentiert werden?":"What must be documented?","exakte Pipeline-/Caller-/DB-Versionen":"exact pipeline/caller/database versions","Verifizierungs-/Vergleichsergebnisse":"verification/comparison results","Freigabe/Change-Control":"approval/change control","nichts, wenn Ergebnis plausibel":"nothing if the result seems plausible","Rückverfolgbarkeit ist Kern der Postanalytik.":"Traceability is a core requirement of post-analytics.","Wie geht man mit potenziell betroffenen Fällen um?":"How should potentially affected cases be handled?","betroffene Fälle identifizieren und medizinisch/QM-seitig bewerten":"identify affected cases and assess them medically and from a quality perspective","alte Fälle nie prüfen":"never review old cases","alle neuen Varianten ohne Prüfung reporten":"report all new variants without review","nur Annotation ändern":"change annotation only","Impact-Analyse ist fall- und markerbezogen.":"Impact analysis is case- and marker-specific.","Entscheide, wie mit der ungeplanten Pipelineänderung, den diskordanten Calls und der Befundfreigabe umzugehen ist.":"Decide how to handle the unplanned pipeline change, discordant calls and report release.","Freigabe diskordanter/entscheidungsrelevanter Befunde pausieren.":"Pause release of discordant or decision-relevant reports.","Change-Control nachholen: Änderung, Grund, Versionen, Verantwortliche dokumentieren.":"Complete change control retrospectively: document the change, reason, versions and responsible persons.","Verifizierung mit definiertem Referenz-/Altfallset durchführen.":"Perform verification using a defined reference/previous-case set.","Diskordante Calls medizinisch-technisch bewerten und ggf. orthogonal bestätigen.":"Assess discordant calls medically and technically and confirm orthogonally if needed.","Berichtsvorlagen mit Pipeline-Version/Auswertungsstand korrigieren.":"Correct report templates to include the pipeline version/analysis status.","Entscheiden, ob frühere Fälle reevaluiert werden müssen.":"Decide whether previous cases need to be re-evaluated.","Temporärer Rollback auf validierte Pipeline für Routinefreigabe, während v4.1 verifiziert wird.":"Temporary rollback to the validated pipeline for routine release while v4.1 is being verified.","Teilfreigabe nicht betroffener Befunde, wenn Trennung auditfähig dokumentiert ist.":"Partial release of unaffected reports if the separation is documented in an audit-ready manner.","Neue Pipeline ist automatisch besser":"The new pipeline is automatically better","ohne Verifizierung keine Routinefreigabe.":"No routine release without verification.","Silent rollback":"Silent rollback","verschleiert das Ereignis und zerstört Audit-Trail.":"conceals the event and destroys the audit trail.","Nur Bioinformatik entscheidet":"Bioinformatics decides alone","klinisch-reportable Änderungen brauchen Laborleitung/QM/ärztliche Bewertung.":"Clinically reportable changes require assessment by laboratory management, quality management and medical staff.","Ein alter negativer Fall wäre heute positiv":"A previously negative case would be positive today","Die Impact-Analyse zeigt, dass v4.1 eine MET-Splice-Region in einem aktuellen Fall plausibel ruft, aber auch zwei alte low-quality Artefakte neu als Varianten markiert. Die Änderung verbessert einen Bereich, erzeugt aber neue Review-Bedürfnisse.":"The impact analysis shows that v4.1 plausibly calls a MET splice region in a current case, but also newly flags two old low-quality artefacts as variants. The change improves one area but creates new review requirements.","Der Fall zeigt, warum Verifizierung nicht Innovationsbremse, sondern Patientenschutz ist.":"The case shows why verification is not a brake on innovation but a patient-safety measure.","Change-Control + Impact":"Change control + impact","Befunde pausiert, v4.1 mit Altfallset geprüft, MET-Call orthogonal bestätigt, Artefaktfilter angepasst, Versionierung dokumentiert.":"Reports held, v4.1 tested with a previous-case set, the MET call confirmed orthogonally, artefact filters adjusted and versioning documented.","Sehr gute Balance aus Innovation und QM.":"Very good balance between innovation and quality management.","Neue Pipeline direkt freigegeben":"New pipeline released directly","Später werden diskordante Artefakte entdeckt, Reports müssen korrigiert werden.":"Discordant artefacts are discovered later and reports have to be corrected.","Kritischer Postanalytik-/QM-Fehler.":"Critical post-analytics/quality-management error.","Stiller Rollback":"Silent rollback","Routine läuft weiter, aber Ereignis ist nicht nachvollziehbar; Audit-Finding wahrscheinlich.":"Routine operation continues, but the event is not traceable; an audit finding is likely.","Prozess scheinbar gerettet, Auditfähigkeit verloren.":"Process apparently rescued, auditability lost.","keine Versionierung":"no versioning","Audit-Trail-Abzug und Cap":"Audit-trail deduction and cap","Documentation und Process Decision betroffen.":"Documentation and Process Decision are affected.","Befund freigegeben ohne Impact":"Report released without impact assessment","critical_fail möglich":"critical_fail possible","Score-Cap und Berichtswarnung.":"Score cap and report warning.","Bioinformatik-Pipelines sind Teil der Methode.":"Bioinformatics pipelines are part of the method.","Change-Control schützt nicht vor Fortschritt, sondern vor unkontrolliertem Fortschritt.":"Change control does not protect against progress; it protects against uncontrolled progress.","Versionierung muss im Befund-/Archivkontext rückverfolgbar sein.":"Versioning must be traceable in the report/archive context.","Hold/Impact-Analyse, Change-Control, Verifizierung, Versionierung, medizinische Bewertung diskordanter Fälle, ggf. Rollback auf validierten Stand bis Freigabe.":"Hold/impact analysis, change control, verification, versioning, medical assessment of discordant cases and, if needed, rollback to the validated state until approval.","Process Decision":"Process decision","Documentation":"Documentation","Patient Safety":"Patient safety","CAPA/Audit":"CAPA/Audit","Was ist minimale Verifizierung für Pipeline-Update?":"What is the minimum verification required for a pipeline update?","Wann müssen Altbefunde reevaluiert werden?":"When must previous reports be re-evaluated?","Wie dokumentiert man Annotation-Datenbanken?":"How should annotation databases be documented?","Twist: bessere Sensitivität + neue Artefaktlast":"Twist: better sensitivity + new artefact burden","Critical Error: Freigabe ohne Verifizierung":"Critical Error: release without verification","Musterpfad: Hold → Impact → Change-Control → Verifizierung → Freigabe":"Reference pathway: Hold → Impact → Change control → Verification → Release","System":"System","Ausgangslage":"Initial situation","Betroffene Zeit":"Affected period","Problem":"Problem","Auffälligkeit":"Finding","Audit-Risiko":"Audit risk","Konflikt":"Conflict","LAB; Länge=Complex; Schwierigkeit=Advanced; Status=curated-core":"LAB; length=complex; difficulty=advanced; status=curated-core"},"ro":{"Pipeline-Version geändert, kein Change-Log → Bioinformatik-QM und Impact-Analyse":"Versiunea pipeline-ului modificată, fără jurnal de schimbări → QM bioinformatic și analiză de impact","Postanalytik / Bioinformatik / Change-Control":"Postanalitică / bioinformatică / controlul modificărilor","Complex":"Complex","Advanced":"Avansat","Core/MVP prüfen":"Verificare core/MVP","Variant Caller wurde von Version 3.4 auf 4.1 aktualisiert.":"Apelatorul de variante a fost actualizat de la versiunea 3.4 la 4.1.","Patientensicherheits- und Qualitätsrisiko des Ereignisses korrekt priorisieren":"Prioritizați corect riscul pentru siguranța pacientului și calitate asociat evenimentului","Pipeline-/Softwareänderungen über Change-Control, Revalidierung und Versionierung absichern":"Asigurați modificările pipeline-ului/software-ului prin controlul modificărilor, revalidare și versionare","Freigabe-, Sperr- oder Wiederholungsentscheidung auditfähig begründen":"Justificați într-un mod auditabil decizia de eliberare, blocare sau repetare","Bioinformatik":"Bioinformatică","Pipeline":"Pipeline","Versionierung":"Versionare","Change-Control":"Controlul modificărilor","Audit":"Audit","NGS":"NGS","Pipeline ohne Change-Log":"Pipeline fără jurnal de schimbări","Targeted DNA-NGS Pipeline":"Pipeline NGS ADN țintit","Kein Change-Log, keine formale Freigabe, keine Verifizierungsnotiz.":"Fără jurnal de schimbări, fără aprobare formală, fără notă de verificare.","2 Wochen Routinebetrieb.":"2 săptămâni de funcționare de rutină.","Zwei Varianten werden in der neuen Version anders gefiltert/klassifiziert.":"Două variante sunt filtrate/clasificate diferit în noua versiune.","Nicht dokumentierte Pipelineänderung":"Modificare nedocumentată a pipeline-ului","Alte und neue Auswertung sind nicht mehr eindeutig vergleichbar.":"Analizele vechi și noi nu mai sunt comparabile în mod clar.","Falsch-negative oder falsch-positive Befundkonsequenzen, besonders bei therapieentscheidenden Varianten.":"Consecințe fals negative sau fals pozitive asupra raportării, în special pentru variante care influențează tratamentul.","Rückverfolgbarkeit von Auswertungsschritten und Datenbank-/Pipelineversion fehlt.":"Lipsește trasabilitatea etapelor de analiză și a versiunilor bazei de date/pipeline-ului.","Weiterarbeiten mit neuer Software vs. Befunde pausieren und Impact klären.":"Continuarea cu noul software vs. suspendarea rapoartelor și clarificarea impactului.","Nichts tun, neue Pipeline ist vermutlich besser.":"Nu faceți nimic; noul pipeline este probabil mai bun.","Kritisch falsch: Softwareänderungen sind methodisch relevante Änderungen und müssen kontrolliert werden.":"Critic greșit: modificările software sunt modificări metodologice relevante și trebuie controlate.","Nur Bioinformatik informieren, Laborbefunde weiter freigeben.":"Informați doar bioinformatica și continuați eliberarea rapoartelor de laborator.","Unzureichend: Es geht um Befundvalidität, Freigabe und QM, nicht nur um Technik.":"Insuficient: este vorba despre validitatea raportului, eliberare și managementul calității, nu doar despre tehnică.","Abweichung eröffnen, Freigabe risikobasiert pausieren, betroffene Fälle identifizieren, Impact-Analyse und ggf. Reanalyse festlegen.":"Deschideți o abatere, suspendați eliberarea pe baza riscului, identificați cazurile afectate și stabiliți analiza de impact și, dacă este necesar, reanaliza.","Optimal: Change-Control, Patientensicherheit und Audit-Trail werden gesichert.":"Optim: sunt asigurate controlul modificărilor, siguranța pacientului și pista de audit.","Alle alten Befunde sofort pauschal zurückrufen.":"Retrageți imediat, în mod generalizat, toate rapoartele anterioare.","Zu pauschal: Reanalyse/Rückruf müssen durch Impact- und Risikoanalyse begründet werden.":"Prea general: reanaliza/retragerea trebuie justificată prin analiza de impact și de risc.","Alle Runs/Fälle im Zeitraum der neuen Pipelineversion identifizieren":"Identificați toate rulările/cazurile din perioada noii versiuni a pipeline-ului","Ohne Fallliste keine Impact-Analyse.":"Fără o listă de cazuri nu este posibilă analiza de impact.","Prüfen, ob Calling/Filtering oder nur Annotation betroffen ist":"Verificați dacă sunt afectate calling-ul/filtering-ul sau doar adnotarea","Calling-/Filtering-Änderungen sind befundkritischer.":"Modificările de calling/filtering sunt mai critice pentru raportare.","Bereits freigegebene therapieentscheidende Befunde priorisieren":"Prioritizați rapoartele deja eliberate care influențează deciziile terapeutice","Klinische Relevanz steuert Reanalysebedarf.":"Relevanța clinică determină necesitatea reanalizei.","Negative Fälle nicht prüfen":"Nu revizuiți cazurile negative","Falsch: Gerade negative Befunde können betroffen sein.":"Greșit: tocmai rapoartele negative pot fi afectate.","Referenz-/Verifizierungsdatensatz für Version 4.1 nachziehen":"Completați setul de date de referință/verificare pentru versiunea 4.1","Neue Versionen müssen lokal kontrolliert werden.":"Versiunile noi trebuie evaluate local.","Abweichung: nicht dokumentierte Pipelineänderung":"Abatere: modificare nedocumentată a pipeline-ului","Sofortmaßnahme: Freigaben risikobasiert pausieren/kontrollieren":"Măsură imediată: suspendați/controlați eliberările pe baza riscului","Korrektur: Impact-Analyse und definierte Reanalyse":"Corecție: analiză de impact și reanaliză definită","Prävention: SOP für Pipeline-Change mit Pflichtfeldern":"Prevenție: SOP pentru modificări ale pipeline-ului cu câmpuri obligatorii","Wirksamkeitsprüfung: nächste Änderungen vollständig dokumentiert":"Verificarea eficacității: modificările următoare sunt documentate complet","Alte/neue Pipelineversion und Zeitpunkt dokumentiert":"Versiunea veche/nouă a pipeline-ului și momentul modificării sunt documentate","Risikobewertung pro Befundklasse nachvollziehbar":"Evaluarea riscului este trasabilă pentru fiecare clasă de raport","Freigabe der neuen Pipelineversion dokumentiert":"Aprobarea noii versiuni a pipeline-ului este documentată","Kommunikation/Schulung der betroffenen Personen dokumentiert":"Comunicarea/instruirea personalului afectat este documentată","Change nur intern mündlich besprechen, nicht dokumentieren":"Discutați schimbarea doar verbal, intern; nu o documentați","Optimale Lösung: Pipelineänderung als Abweichung behandeln, Impact-Analyse durchführen, betroffene Befunde risikobasiert reanalysieren und Change-Control für künftige Updates etablieren.":"Soluția optimă: tratați modificarea pipeline-ului ca pe o abatere, efectuați o analiză de impact, reanalizați pe baza riscului rapoartele afectate și instituiți controlul modificărilor pentru actualizările viitoare.","Pipeline-Version geändert, kein Change-Log: Bioinformatik-QM und Impact-Analyse":"Versiunea pipeline-ului modificată, fără jurnal de schimbări: QM bioinformatic și analiză de impact","LAB":"LAB","Advanced Integrated":"Avansat integrat","Laborleitung / Bioinformatik-QM":"Conducerea laboratorului / QM bioinformatic","Pipeline-/Softwareänderungen als qualitätsrelevante Methodenänderung erkennen.":"Recunoașteți modificările pipeline-ului/software-ului ca modificări metodologice relevante pentru calitate.","Impact-Analyse, Versionierung und Revalidierung/Verifizierung ableiten.":"Stabiliți analiza de impact, versionarea și revalidarea/verificarea necesare.","Befundfreigabe bei diskordanten Pipeline-Ergebnissen auditfähig steuern.":"Gestionați eliberarea rapoartelor în cazul rezultatelor discordante ale pipeline-ului într-un mod auditabil.","Ein Bioinformatik-Update wurde 'nur kurz' eingespielt, weil der neue Caller bessere Indel-Erkennung verspricht. Am nächsten Tag unterscheiden sich mehrere Variantenlisten von alten Ergebnissen. Ein Change-Log existiert nicht.":"O actualizare bioinformatică a fost instalată 'doar rapid', deoarece noul apelator promite o detecție mai bună a indelurilor. A doua zi, mai multe liste de variante diferă de rezultatele anterioare. Nu există jurnal de schimbări.","Molekularpathologisches NGS-Panel, 48 Patientenfälle im aktuellen Batch. Variant Caller von 3.4 auf 4.1 aktualisiert. Referenzdatenbank und Annotation wurden ebenfalls minor aktualisiert. Die Änderung wurde nicht vorab in der QM-Dokumentation freigegeben.":"Panel NGS de patologie moleculară, 48 de cazuri de pacienți în lotul curent. Apelatorul de variante a fost actualizat de la 3.4 la 4.1. Baza de date de referință și adnotarea au primit, de asemenea, actualizări minore. Modificarea nu a fost aprobată în prealabil în documentația de calitate.","Diskordanz":"Discordanță","Bei 6/48 Fällen unterscheiden sich reportable variants. Ein Fall betrifft eine potenziell therapieentscheidende MET-Splice-Region.":"Variantele raportabile diferă în 6/48 de cazuri. Un caz implică o regiune de splice MET cu potențial impact asupra tratamentului.","Nicht jede Softwareänderung ist rein technisch.":"Nu orice modificare software este pur tehnică.","Im Berichtsentwurf ist keine Pipeline-Version angegeben; alte Reports enthalten nur 'NGS Pipeline'.":"Proiectul de raport nu specifică versiunea pipeline-ului; rapoartele vechi conțin doar 'NGS Pipeline'.","Ohne Versionierung fehlt Rückverfolgbarkeit.":"Fără versionare, trasabilitatea lipsește.","Teamkonflikt":"Conflict în echipă","Bioinformatik sagt: 'Der neue Caller ist besser.' QM fragt: 'Wo ist die Verifizierung?' Klinik wartet auf Befunde.":"Bioinformatica spune: 'Noul apelator este mai bun.' QM întreabă: 'Unde este verificarea?' Echipa clinică așteaptă rapoartele.","Besser ist nicht gleich freigegeben.":"Mai bun nu înseamnă automat aprobat pentru utilizare.","Risiko":"Risc","Sowohl falsch-positive als auch falsch-negative Änderungen sind möglich; Impact ist nicht auf einen Fall begrenzt.":"Sunt posibile atât modificări fals pozitive, cât și fals negative; impactul nu este limitat la un singur caz.","Impact-Analyse muss systematisch erfolgen.":"Analiza de impact trebuie realizată sistematic.","Alter Lauf":"Rulare anterioară","Validierte Pipeline v3.4 mit dokumentierter Leistungsfähigkeit.":"Pipeline validat v3.4 cu performanță documentată.","Neuer Lauf":"Rulare nouă","v4.1 ruft zusätzliche Indels/Splice-Varianten, darunter ein potenziell reportables MET-Ereignis.":"v4.1 detectează indeluri/variante de splice suplimentare, inclusiv un eveniment MET potențial raportabil.","Dokumentation":"Documentație","kein Change-Control-Eintrag, keine Freigabe, keine definierte Vergleichsmatrix.":"Fără înregistrare de control al modificărilor, fără aprobare, fără matrice de comparație definită.","Klinischer TAT-Druck, aber potenzieller Einfluss auf Befundqualität.":"Presiune clinică privind TAT, dar cu posibil impact asupra calității raportului.","Vergleichsdatensätze und Alt-Runs sind verfügbar.":"Sunt disponibile seturi de date comparative și rulări anterioare.","Re-Analyse früherer Fälle könnte nötig werden, wenn systematischer Einfluss besteht.":"Reanaliza cazurilor anterioare poate fi necesară dacă există un impact sistematic.","Wie ist die Pipelineänderung zu bewerten?":"Cum trebuie evaluată modificarea pipeline-ului?","qualitätsrelevante Methoden-/Auswertungsänderung mit Change-Control-Bedarf":"modificare relevantă pentru calitate a metodei/analizei, care necesită controlul modificărilor","rein kosmetische Änderung":"modificare pur cosmetică","irrelevant, wenn Software neuer ist":"irelevant dacă software-ul este mai nou","nur klinische Entscheidung":"doar o decizie clinică","Pipelineversionen beeinflussen berichtete Varianten und benötigen Kontrolle.":"Versiunile pipeline-ului influențează variantele raportate și necesită control.","Was ist die richtige Sofortmaßnahme?":"Care este măsura imediată corectă?","Freigabe betroffener Befunde pausieren und Impact-Analyse starten":"Suspendați eliberarea rapoartelor afectate și începeți o analiză de impact","alle neuen Calls freigeben":"eliberați toate noile call-uri","heimlich zurückrollen ohne Doku":"reveniți în secret la versiunea anterioară fără documentare","alte Ergebnisse löschen":"ștergeți rezultatele vechi","Freigabe ohne Impact wäre riskant.":"Eliberarea fără evaluarea impactului ar fi riscantă.","Was muss dokumentiert werden?":"Ce trebuie documentat?","exakte Pipeline-/Caller-/DB-Versionen":"versiunile exacte ale pipeline-ului/caller-ului/bazei de date","Verifizierungs-/Vergleichsergebnisse":"rezultatele verificării/comparației","Freigabe/Change-Control":"aprobare/controlul modificărilor","nichts, wenn Ergebnis plausibel":"nimic dacă rezultatul pare plauzibil","Rückverfolgbarkeit ist Kern der Postanalytik.":"Trasabilitatea este o cerință esențială a postanaliticii.","Wie geht man mit potenziell betroffenen Fällen um?":"Cum trebuie gestionate cazurile potențial afectate?","betroffene Fälle identifizieren und medizinisch/QM-seitig bewerten":"identificați cazurile afectate și evaluați-le medical și din perspectiva calității","alte Fälle nie prüfen":"nu revizuiți niciodată cazurile vechi","alle neuen Varianten ohne Prüfung reporten":"raportați toate variantele noi fără verificare","nur Annotation ändern":"modificați doar adnotarea","Impact-Analyse ist fall- und markerbezogen.":"Analiza de impact este specifică fiecărui caz și marker.","Entscheide, wie mit der ungeplanten Pipelineänderung, den diskordanten Calls und der Befundfreigabe umzugehen ist.":"Decideți cum trebuie gestionate modificarea neplanificată a pipeline-ului, call-urile discordante și eliberarea rapoartelor.","Freigabe diskordanter/entscheidungsrelevanter Befunde pausieren.":"Suspendați eliberarea rapoartelor discordante sau relevante pentru decizie.","Change-Control nachholen: Änderung, Grund, Versionen, Verantwortliche dokumentieren.":"Completați retrospectiv controlul modificărilor: documentați schimbarea, motivul, versiunile și persoanele responsabile.","Verifizierung mit definiertem Referenz-/Altfallset durchführen.":"Efectuați verificarea folosind un set definit de referință/cazuri anterioare.","Diskordante Calls medizinisch-technisch bewerten und ggf. orthogonal bestätigen.":"Evaluați medical și tehnic call-urile discordante și confirmați-le ortogonal dacă este necesar.","Berichtsvorlagen mit Pipeline-Version/Auswertungsstand korrigieren.":"Corectați șabloanele de raport pentru a include versiunea pipeline-ului/stadiul analizei.","Entscheiden, ob frühere Fälle reevaluiert werden müssen.":"Decideți dacă trebuie reevaluate cazurile anterioare.","Temporärer Rollback auf validierte Pipeline für Routinefreigabe, während v4.1 verifiziert wird.":"Rollback temporar la pipeline-ul validat pentru eliberarea de rutină, în timp ce v4.1 este verificată.","Teilfreigabe nicht betroffener Befunde, wenn Trennung auditfähig dokumentiert ist.":"Eliberarea parțială a rapoartelor neafectate dacă separarea este documentată într-un mod auditabil.","Neue Pipeline ist automatisch besser":"Noul pipeline este automat mai bun","ohne Verifizierung keine Routinefreigabe.":"Fără eliberare de rutină fără verificare.","Silent rollback":"Rollback silențios","verschleiert das Ereignis und zerstört Audit-Trail.":"ascunde evenimentul și distruge pista de audit.","Nur Bioinformatik entscheidet":"Doar bioinformatica decide","klinisch-reportable Änderungen brauchen Laborleitung/QM/ärztliche Bewertung.":"Modificările raportabile clinic necesită evaluare din partea conducerii laboratorului, a QM și a personalului medical.","Ein alter negativer Fall wäre heute positiv":"Un caz anterior negativ ar fi astăzi pozitiv","Die Impact-Analyse zeigt, dass v4.1 eine MET-Splice-Region in einem aktuellen Fall plausibel ruft, aber auch zwei alte low-quality Artefakte neu als Varianten markiert. Die Änderung verbessert einen Bereich, erzeugt aber neue Review-Bedürfnisse.":"Analiza de impact arată că v4.1 identifică plauzibil o regiune de splice MET într-un caz curent, dar marchează și două artefacte vechi de calitate scăzută ca variante. Modificarea îmbunătățește un domeniu, dar creează noi necesități de revizuire.","Der Fall zeigt, warum Verifizierung nicht Innovationsbremse, sondern Patientenschutz ist.":"Cazul arată de ce verificarea nu frânează inovația, ci protejează pacientul.","Change-Control + Impact":"Controlul modificărilor + impact","Befunde pausiert, v4.1 mit Altfallset geprüft, MET-Call orthogonal bestätigt, Artefaktfilter angepasst, Versionierung dokumentiert.":"Rapoartele au fost suspendate, v4.1 a fost testată cu un set de cazuri anterioare, call-ul MET a fost confirmat ortogonal, filtrele de artefacte au fost ajustate și versionarea a fost documentată.","Sehr gute Balance aus Innovation und QM.":"Echilibru foarte bun între inovație și managementul calității.","Neue Pipeline direkt freigegeben":"Noul pipeline aprobat direct","Später werden diskordante Artefakte entdeckt, Reports müssen korrigiert werden.":"Ulterior sunt descoperite artefacte discordante, iar rapoartele trebuie corectate.","Kritischer Postanalytik-/QM-Fehler.":"Eroare critică de postanalitică/management al calității.","Stiller Rollback":"Rollback silențios","Routine läuft weiter, aber Ereignis ist nicht nachvollziehbar; Audit-Finding wahrscheinlich.":"Activitatea de rutină continuă, dar evenimentul nu este trasabil; este probabilă o constatare la audit.","Prozess scheinbar gerettet, Auditfähigkeit verloren.":"Procesul pare salvat, dar auditabilitatea este pierdută.","keine Versionierung":"fără versionare","Audit-Trail-Abzug und Cap":"Penalizare pentru pista de audit și plafon","Documentation und Process Decision betroffen.":"Sunt afectate Documentația și Decizia de proces.","Befund freigegeben ohne Impact":"Raport eliberat fără evaluarea impactului","critical_fail möglich":"critical_fail posibil","Score-Cap und Berichtswarnung.":"Plafon de scor și avertizare în raport.","Bioinformatik-Pipelines sind Teil der Methode.":"Pipeline-urile bioinformatice fac parte din metodă.","Change-Control schützt nicht vor Fortschritt, sondern vor unkontrolliertem Fortschritt.":"Controlul modificărilor nu protejează împotriva progresului, ci împotriva progresului necontrolat.","Versionierung muss im Befund-/Archivkontext rückverfolgbar sein.":"Versionarea trebuie să fie trasabilă în contextul raportului/arhivei.","Hold/Impact-Analyse, Change-Control, Verifizierung, Versionierung, medizinische Bewertung diskordanter Fälle, ggf. Rollback auf validierten Stand bis Freigabe.":"Hold/analiză de impact, controlul modificărilor, verificare, versionare, evaluarea medicală a cazurilor discordante și, dacă este necesar, rollback la starea validată până la aprobare.","Process Decision":"Decizie de proces","Documentation":"Documentație","Patient Safety":"Siguranța pacientului","CAPA/Audit":"CAPA/Audit","Was ist minimale Verifizierung für Pipeline-Update?":"Care este verificarea minimă necesară pentru o actualizare a pipeline-ului?","Wann müssen Altbefunde reevaluiert werden?":"Când trebuie reevaluate rapoartele anterioare?","Wie dokumentiert man Annotation-Datenbanken?":"Cum trebuie documentate bazele de date de adnotare?","Twist: bessere Sensitivität + neue Artefaktlast":"Twist: sensibilitate mai bună + o nouă povară de artefacte","Critical Error: Freigabe ohne Verifizierung":"Eroare critică: eliberare fără verificare","Musterpfad: Hold → Impact → Change-Control → Verifizierung → Freigabe":"Traseu de referință: Hold → Impact → Controlul modificărilor → Verificare → Eliberare","System":"Sistem","Ausgangslage":"Situație inițială","Betroffene Zeit":"Perioadă afectată","Problem":"Problemă","Auffälligkeit":"Constatare","Audit-Risiko":"Risc de audit","Konflikt":"Conflict","LAB; Länge=Complex; Schwierigkeit=Advanced; Status=curated-core":"LAB; lungime=complexă; dificultate=avansată; statut=curated-core"},"el":{"Pipeline-Version geändert, kein Change-Log → Bioinformatik-QM und Impact-Analyse":"Αλλαγή έκδοσης pipeline χωρίς αρχείο αλλαγών → ποιοτικός έλεγχος βιοπληροφορικής και ανάλυση επιπτώσεων","Postanalytik / Bioinformatik / Change-Control":"Μετα-αναλυτικό στάδιο / βιοπληροφορική / έλεγχος αλλαγών","Complex":"Σύνθετο","Advanced":"Προχωρημένο","Core/MVP prüfen":"Έλεγχος core/MVP","Variant Caller wurde von Version 3.4 auf 4.1 aktualisiert.":"Ο αλγόριθμος κλήσης παραλλαγών ενημερώθηκε από την έκδοση 3.4 στην 4.1.","Patientensicherheits- und Qualitätsrisiko des Ereignisses korrekt priorisieren":"Ιεραρχήστε σωστά τον κίνδυνο του συμβάντος για την ασφάλεια των ασθενών και την ποιότητα","Pipeline-/Softwareänderungen über Change-Control, Revalidierung und Versionierung absichern":"Διασφαλίστε τις αλλαγές pipeline/λογισμικού μέσω ελέγχου αλλαγών, επανεπικύρωσης και διαχείρισης εκδόσεων","Freigabe-, Sperr- oder Wiederholungsentscheidung auditfähig begründen":"Τεκμηριώστε με τρόπο κατάλληλο για έλεγχο την απόφαση αποδέσμευσης, αναστολής ή επανάληψης","Bioinformatik":"Βιοπληροφορική","Pipeline":"Pipeline","Versionierung":"Διαχείριση εκδόσεων","Change-Control":"Έλεγχος αλλαγών","Audit":"Έλεγχος","NGS":"NGS","Pipeline ohne Change-Log":"Pipeline χωρίς αρχείο αλλαγών","Targeted DNA-NGS Pipeline":"Στοχευμένο pipeline DNA-NGS","Kein Change-Log, keine formale Freigabe, keine Verifizierungsnotiz.":"Χωρίς αρχείο αλλαγών, χωρίς επίσημη έγκριση, χωρίς καταγραφή επαλήθευσης.","2 Wochen Routinebetrieb.":"2 εβδομάδες λειτουργίας ρουτίνας.","Zwei Varianten werden in der neuen Version anders gefiltert/klassifiziert.":"Δύο παραλλαγές φιλτράρονται/ταξινομούνται διαφορετικά στη νέα έκδοση.","Nicht dokumentierte Pipelineänderung":"Μη τεκμηριωμένη αλλαγή pipeline","Alte und neue Auswertung sind nicht mehr eindeutig vergleichbar.":"Η παλιά και η νέα ανάλυση δεν είναι πλέον σαφώς συγκρίσιμες.","Falsch-negative oder falsch-positive Befundkonsequenzen, besonders bei therapieentscheidenden Varianten.":"Ψευδώς αρνητικές ή ψευδώς θετικές συνέπειες στην αναφορά, ιδιαίτερα για παραλλαγές που καθορίζουν τη θεραπεία.","Rückverfolgbarkeit von Auswertungsschritten und Datenbank-/Pipelineversion fehlt.":"Απουσιάζει η ιχνηλασιμότητα των βημάτων ανάλυσης και των εκδόσεων βάσης δεδομένων/pipeline.","Weiterarbeiten mit neuer Software vs. Befunde pausieren und Impact klären.":"Συνέχιση με το νέο λογισμικό έναντι αναστολής των αναφορών και διερεύνησης των επιπτώσεων.","Nichts tun, neue Pipeline ist vermutlich besser.":"Καμία ενέργεια· το νέο pipeline είναι πιθανώς καλύτερο.","Kritisch falsch: Softwareänderungen sind methodisch relevante Änderungen und müssen kontrolliert werden.":"Κρίσιμο σφάλμα: οι αλλαγές λογισμικού είναι μεθοδολογικά σημαντικές αλλαγές και πρέπει να ελέγχονται.","Nur Bioinformatik informieren, Laborbefunde weiter freigeben.":"Ενημερώστε μόνο τη βιοπληροφορική και συνεχίστε την αποδέσμευση των εργαστηριακών αναφορών.","Unzureichend: Es geht um Befundvalidität, Freigabe und QM, nicht nur um Technik.":"Ανεπαρκές: αφορά την εγκυρότητα της αναφοράς, την αποδέσμευση και τη διαχείριση ποιότητας, όχι μόνο την τεχνική.","Abweichung eröffnen, Freigabe risikobasiert pausieren, betroffene Fälle identifizieren, Impact-Analyse und ggf. Reanalyse festlegen.":"Ανοίξτε απόκλιση, αναστείλετε την αποδέσμευση βάσει κινδύνου, εντοπίστε τα επηρεαζόμενα περιστατικά και καθορίστε ανάλυση επιπτώσεων και, εφόσον απαιτείται, επανάλυση.","Optimal: Change-Control, Patientensicherheit und Audit-Trail werden gesichert.":"Βέλτιστο: διασφαλίζονται ο έλεγχος αλλαγών, η ασφάλεια των ασθενών και το ίχνος ελέγχου.","Alle alten Befunde sofort pauschal zurückrufen.":"Ανακαλέστε άμεσα και συλλήβδην όλες τις παλαιότερες αναφορές.","Zu pauschal: Reanalyse/Rückruf müssen durch Impact- und Risikoanalyse begründet werden.":"Υπερβολικά γενικό: η επανάλυση/ανάκληση πρέπει να τεκμηριώνεται με ανάλυση επιπτώσεων και κινδύνου.","Alle Runs/Fälle im Zeitraum der neuen Pipelineversion identifizieren":"Εντοπίστε όλες τις σειρές/περιστατικά κατά την περίοδο χρήσης της νέας έκδοσης του pipeline","Ohne Fallliste keine Impact-Analyse.":"Χωρίς κατάλογο περιστατικών δεν είναι δυνατή η ανάλυση επιπτώσεων.","Prüfen, ob Calling/Filtering oder nur Annotation betroffen ist":"Ελέγξτε εάν επηρεάζονται το calling/filtering ή μόνο η επισημείωση","Calling-/Filtering-Änderungen sind befundkritischer.":"Οι αλλαγές στο calling/filtering είναι πιο κρίσιμες για την αναφορά.","Bereits freigegebene therapieentscheidende Befunde priorisieren":"Δώστε προτεραιότητα σε ήδη αποδεσμευμένες αναφορές που επηρεάζουν θεραπευτικές αποφάσεις","Klinische Relevanz steuert Reanalysebedarf.":"Η κλινική σημασία καθορίζει την ανάγκη επανάλυσης.","Negative Fälle nicht prüfen":"Μην ελέγξετε τα αρνητικά περιστατικά","Falsch: Gerade negative Befunde können betroffen sein.":"Λάθος: ιδιαίτερα οι αρνητικές αναφορές μπορεί να επηρεάζονται.","Referenz-/Verifizierungsdatensatz für Version 4.1 nachziehen":"Συμπληρώστε το σύνολο δεδομένων αναφοράς/επαλήθευσης για την έκδοση 4.1","Neue Versionen müssen lokal kontrolliert werden.":"Οι νέες εκδόσεις πρέπει να ελέγχονται τοπικά.","Abweichung: nicht dokumentierte Pipelineänderung":"Απόκλιση: μη τεκμηριωμένη αλλαγή pipeline","Sofortmaßnahme: Freigaben risikobasiert pausieren/kontrollieren":"Άμεσο μέτρο: αναστολή/έλεγχος αποδεσμεύσεων βάσει κινδύνου","Korrektur: Impact-Analyse und definierte Reanalyse":"Διόρθωση: ανάλυση επιπτώσεων και καθορισμένη επανάλυση","Prävention: SOP für Pipeline-Change mit Pflichtfeldern":"Πρόληψη: SOP για αλλαγές pipeline με υποχρεωτικά πεδία","Wirksamkeitsprüfung: nächste Änderungen vollständig dokumentiert":"Έλεγχος αποτελεσματικότητας: οι επόμενες αλλαγές τεκμηριώνονται πλήρως","Alte/neue Pipelineversion und Zeitpunkt dokumentiert":"Η παλιά/νέα έκδοση του pipeline και ο χρόνος αλλαγής έχουν τεκμηριωθεί","Risikobewertung pro Befundklasse nachvollziehbar":"Η αξιολόγηση κινδύνου είναι ιχνηλάσιμη για κάθε κατηγορία αναφοράς","Freigabe der neuen Pipelineversion dokumentiert":"Η έγκριση της νέας έκδοσης του pipeline έχει τεκμηριωθεί","Kommunikation/Schulung der betroffenen Personen dokumentiert":"Η επικοινωνία/εκπαίδευση του εμπλεκόμενου προσωπικού έχει τεκμηριωθεί","Change nur intern mündlich besprechen, nicht dokumentieren":"Συζητήστε την αλλαγή μόνο προφορικά εντός της ομάδας· μην την τεκμηριώσετε","Optimale Lösung: Pipelineänderung als Abweichung behandeln, Impact-Analyse durchführen, betroffene Befunde risikobasiert reanalysieren und Change-Control für künftige Updates etablieren.":"Βέλτιστη λύση: αντιμετωπίστε την αλλαγή pipeline ως απόκλιση, πραγματοποιήστε ανάλυση επιπτώσεων, επαναναλύστε βάσει κινδύνου τις επηρεαζόμενες αναφορές και καθιερώστε έλεγχο αλλαγών για μελλοντικές ενημερώσεις.","Pipeline-Version geändert, kein Change-Log: Bioinformatik-QM und Impact-Analyse":"Αλλαγή έκδοσης pipeline χωρίς αρχείο αλλαγών: ποιοτικός έλεγχος βιοπληροφορικής και ανάλυση επιπτώσεων","LAB":"LAB","Advanced Integrated":"Προχωρημένο ολοκληρωμένο","Laborleitung / Bioinformatik-QM":"Διοίκηση εργαστηρίου / ποιοτικός έλεγχος βιοπληροφορικής","Pipeline-/Softwareänderungen als qualitätsrelevante Methodenänderung erkennen.":"Αναγνωρίστε τις αλλαγές pipeline/λογισμικού ως μεθοδολογικές αλλαγές με σημασία για την ποιότητα.","Impact-Analyse, Versionierung und Revalidierung/Verifizierung ableiten.":"Προσδιορίστε την απαιτούμενη ανάλυση επιπτώσεων, διαχείριση εκδόσεων και επανεπικύρωση/επαλήθευση.","Befundfreigabe bei diskordanten Pipeline-Ergebnissen auditfähig steuern.":"Διαχειριστείτε την αποδέσμευση αναφορών σε ασύμφωνα αποτελέσματα pipeline με τρόπο κατάλληλο για έλεγχο.","Ein Bioinformatik-Update wurde 'nur kurz' eingespielt, weil der neue Caller bessere Indel-Erkennung verspricht. Am nächsten Tag unterscheiden sich mehrere Variantenlisten von alten Ergebnissen. Ein Change-Log existiert nicht.":"Μια ενημέρωση βιοπληροφορικής εγκαταστάθηκε 'στα γρήγορα', επειδή ο νέος caller υπόσχεται καλύτερη ανίχνευση indel. Την επόμενη ημέρα, αρκετές λίστες παραλλαγών διαφέρουν από τα παλαιότερα αποτελέσματα. Δεν υπάρχει αρχείο αλλαγών.","Molekularpathologisches NGS-Panel, 48 Patientenfälle im aktuellen Batch. Variant Caller von 3.4 auf 4.1 aktualisiert. Referenzdatenbank und Annotation wurden ebenfalls minor aktualisiert. Die Änderung wurde nicht vorab in der QM-Dokumentation freigegeben.":"Panel NGS μοριακής παθολογίας, 48 περιστατικά ασθενών στην τρέχουσα παρτίδα. Ο αλγόριθμος κλήσης παραλλαγών ενημερώθηκε από 3.4 σε 4.1. Η βάση δεδομένων αναφοράς και η επισημείωση ενημερώθηκαν επίσης σε μικρό βαθμό. Η αλλαγή δεν είχε εγκριθεί εκ των προτέρων στην τεκμηρίωση ποιότητας.","Diskordanz":"Ασυμφωνία","Bei 6/48 Fällen unterscheiden sich reportable variants. Ein Fall betrifft eine potenziell therapieentscheidende MET-Splice-Region.":"Οι παραλλαγές προς αναφορά διαφέρουν σε 6/48 περιστατικά. Ένα περιστατικό αφορά περιοχή splice του MET που ενδέχεται να καθορίζει τη θεραπεία.","Nicht jede Softwareänderung ist rein technisch.":"Δεν είναι κάθε αλλαγή λογισμικού καθαρά τεχνική.","Im Berichtsentwurf ist keine Pipeline-Version angegeben; alte Reports enthalten nur 'NGS Pipeline'.":"Στο προσχέδιο της αναφοράς δεν αναφέρεται έκδοση pipeline· οι παλιές αναφορές περιέχουν μόνο 'NGS Pipeline'.","Ohne Versionierung fehlt Rückverfolgbarkeit.":"Χωρίς διαχείριση εκδόσεων, χάνεται η ιχνηλασιμότητα.","Teamkonflikt":"Σύγκρουση στην ομάδα","Bioinformatik sagt: 'Der neue Caller ist besser.' QM fragt: 'Wo ist die Verifizierung?' Klinik wartet auf Befunde.":"Η βιοπληροφορική λέει: 'Ο νέος caller είναι καλύτερος.' Η διαχείριση ποιότητας ρωτά: 'Πού είναι η επαλήθευση;' Η κλινική ομάδα περιμένει τις αναφορές.","Besser ist nicht gleich freigegeben.":"Καλύτερο δεν σημαίνει αυτομάτως εγκεκριμένο για αποδέσμευση.","Risiko":"Κίνδυνος","Sowohl falsch-positive als auch falsch-negative Änderungen sind möglich; Impact ist nicht auf einen Fall begrenzt.":"Είναι δυνατές τόσο ψευδώς θετικές όσο και ψευδώς αρνητικές μεταβολές· οι επιπτώσεις δεν περιορίζονται σε ένα περιστατικό.","Impact-Analyse muss systematisch erfolgen.":"Η ανάλυση επιπτώσεων πρέπει να γίνεται συστηματικά.","Alter Lauf":"Παλαιότερη σειρά","Validierte Pipeline v3.4 mit dokumentierter Leistungsfähigkeit.":"Επικυρωμένο pipeline v3.4 με τεκμηριωμένη επίδοση.","Neuer Lauf":"Νέα σειρά","v4.1 ruft zusätzliche Indels/Splice-Varianten, darunter ein potenziell reportables MET-Ereignis.":"Η v4.1 καλεί επιπλέον indel/παραλλαγές splice, μεταξύ των οποίων ένα δυνητικά αναφέρσιμο συμβάν MET.","Dokumentation":"Τεκμηρίωση","kein Change-Control-Eintrag, keine Freigabe, keine definierte Vergleichsmatrix.":"Χωρίς καταχώριση ελέγχου αλλαγών, χωρίς έγκριση, χωρίς καθορισμένο πίνακα σύγκρισης.","Klinischer TAT-Druck, aber potenzieller Einfluss auf Befundqualität.":"Κλινική πίεση ως προς το TAT, αλλά με πιθανή επίπτωση στην ποιότητα της αναφοράς.","Vergleichsdatensätze und Alt-Runs sind verfügbar.":"Υπάρχουν διαθέσιμα σύνολα δεδομένων σύγκρισης και παλαιότερες σειρές.","Re-Analyse früherer Fälle könnte nötig werden, wenn systematischer Einfluss besteht.":"Μπορεί να απαιτηθεί επανάλυση παλαιότερων περιστατικών εάν υπάρχει συστηματική επίπτωση.","Wie ist die Pipelineänderung zu bewerten?":"Πώς πρέπει να αξιολογηθεί η αλλαγή του pipeline;","qualitätsrelevante Methoden-/Auswertungsänderung mit Change-Control-Bedarf":"αλλαγή μεθόδου/ανάλυσης με σημασία για την ποιότητα και ανάγκη ελέγχου αλλαγών","rein kosmetische Änderung":"αμιγώς αισθητική αλλαγή","irrelevant, wenn Software neuer ist":"άσχετο εφόσον το λογισμικό είναι νεότερο","nur klinische Entscheidung":"μόνο κλινική απόφαση","Pipelineversionen beeinflussen berichtete Varianten und benötigen Kontrolle.":"Οι εκδόσεις του pipeline επηρεάζουν τις παραλλαγές που αναφέρονται και απαιτούν έλεγχο.","Was ist die richtige Sofortmaßnahme?":"Ποιο είναι το σωστό άμεσο μέτρο;","Freigabe betroffener Befunde pausieren und Impact-Analyse starten":"Αναστείλετε την αποδέσμευση των επηρεαζόμενων αναφορών και ξεκινήστε ανάλυση επιπτώσεων","alle neuen Calls freigeben":"αποδεσμεύστε όλα τα νέα calls","heimlich zurückrollen ohne Doku":"σιωπηλή επαναφορά χωρίς τεκμηρίωση","alte Ergebnisse löschen":"διαγράψτε τα παλιά αποτελέσματα","Freigabe ohne Impact wäre riskant.":"Η αποδέσμευση χωρίς αξιολόγηση των επιπτώσεων θα ήταν επικίνδυνη.","Was muss dokumentiert werden?":"Τι πρέπει να τεκμηριωθεί;","exakte Pipeline-/Caller-/DB-Versionen":"ακριβείς εκδόσεις pipeline/caller/βάσης δεδομένων","Verifizierungs-/Vergleichsergebnisse":"αποτελέσματα επαλήθευσης/σύγκρισης","Freigabe/Change-Control":"έγκριση/έλεγχος αλλαγών","nichts, wenn Ergebnis plausibel":"τίποτα εάν το αποτέλεσμα φαίνεται εύλογο","Rückverfolgbarkeit ist Kern der Postanalytik.":"Η ιχνηλασιμότητα αποτελεί βασική απαίτηση του μετα-αναλυτικού σταδίου.","Wie geht man mit potenziell betroffenen Fällen um?":"Πώς πρέπει να αντιμετωπιστούν τα δυνητικά επηρεαζόμενα περιστατικά;","betroffene Fälle identifizieren und medizinisch/QM-seitig bewerten":"εντοπίστε τα επηρεαζόμενα περιστατικά και αξιολογήστε τα ιατρικά και από πλευράς ποιότητας","alte Fälle nie prüfen":"μην ελέγχετε ποτέ παλαιότερα περιστατικά","alle neuen Varianten ohne Prüfung reporten":"αναφέρετε όλες τις νέες παραλλαγές χωρίς έλεγχο","nur Annotation ändern":"αλλάξτε μόνο την επισημείωση","Impact-Analyse ist fall- und markerbezogen.":"Η ανάλυση επιπτώσεων είναι ειδική για το περιστατικό και τον δείκτη.","Entscheide, wie mit der ungeplanten Pipelineänderung, den diskordanten Calls und der Befundfreigabe umzugehen ist.":"Αποφασίστε πώς θα αντιμετωπιστούν η μη προγραμματισμένη αλλαγή του pipeline, τα ασύμφωνα calls και η αποδέσμευση των αναφορών.","Freigabe diskordanter/entscheidungsrelevanter Befunde pausieren.":"Αναστείλετε την αποδέσμευση ασύμφωνων ή κλινικά κρίσιμων αναφορών.","Change-Control nachholen: Änderung, Grund, Versionen, Verantwortliche dokumentieren.":"Ολοκληρώστε εκ των υστέρων τον έλεγχο αλλαγών: τεκμηριώστε την αλλαγή, την αιτία, τις εκδόσεις και τους υπευθύνους.","Verifizierung mit definiertem Referenz-/Altfallset durchführen.":"Πραγματοποιήστε επαλήθευση με καθορισμένο σύνολο αναφοράς/παλαιότερων περιστατικών.","Diskordante Calls medizinisch-technisch bewerten und ggf. orthogonal bestätigen.":"Αξιολογήστε τα ασύμφωνα calls ιατρικά και τεχνικά και επιβεβαιώστε τα ορθογωνικά εφόσον απαιτείται.","Berichtsvorlagen mit Pipeline-Version/Auswertungsstand korrigieren.":"Διορθώστε τα πρότυπα αναφοράς ώστε να περιλαμβάνουν την έκδοση του pipeline/κατάσταση ανάλυσης.","Entscheiden, ob frühere Fälle reevaluiert werden müssen.":"Αποφασίστε εάν πρέπει να επαναξιολογηθούν παλαιότερα περιστατικά.","Temporärer Rollback auf validierte Pipeline für Routinefreigabe, während v4.1 verifiziert wird.":"Προσωρινό rollback στο επικυρωμένο pipeline για αποδέσμευση ρουτίνας όσο επαληθεύεται η v4.1.","Teilfreigabe nicht betroffener Befunde, wenn Trennung auditfähig dokumentiert ist.":"Μερική αποδέσμευση μη επηρεαζόμενων αναφορών εφόσον ο διαχωρισμός τεκμηριώνεται με τρόπο κατάλληλο για έλεγχο.","Neue Pipeline ist automatisch besser":"Το νέο pipeline είναι αυτομάτως καλύτερο","ohne Verifizierung keine Routinefreigabe.":"Καμία αποδέσμευση ρουτίνας χωρίς επαλήθευση.","Silent rollback":"Σιωπηλό rollback","verschleiert das Ereignis und zerstört Audit-Trail.":"αποκρύπτει το συμβάν και καταστρέφει το ίχνος ελέγχου.","Nur Bioinformatik entscheidet":"Αποφασίζει μόνο η βιοπληροφορική","klinisch-reportable Änderungen brauchen Laborleitung/QM/ärztliche Bewertung.":"Οι κλινικά αναφέρσιμες αλλαγές απαιτούν αξιολόγηση από τη διοίκηση του εργαστηρίου, τη διαχείριση ποιότητας και ιατρικό προσωπικό.","Ein alter negativer Fall wäre heute positiv":"Ένα παλαιότερα αρνητικό περιστατικό θα ήταν σήμερα θετικό","Die Impact-Analyse zeigt, dass v4.1 eine MET-Splice-Region in einem aktuellen Fall plausibel ruft, aber auch zwei alte low-quality Artefakte neu als Varianten markiert. Die Änderung verbessert einen Bereich, erzeugt aber neue Review-Bedürfnisse.":"Η ανάλυση επιπτώσεων δείχνει ότι η v4.1 καλεί εύλογα μια περιοχή splice του MET σε τρέχον περιστατικό, αλλά επισημαίνει επίσης δύο παλαιά artefacts χαμηλής ποιότητας ως παραλλαγές. Η αλλαγή βελτιώνει έναν τομέα, αλλά δημιουργεί νέες ανάγκες ελέγχου.","Der Fall zeigt, warum Verifizierung nicht Innovationsbremse, sondern Patientenschutz ist.":"Το περιστατικό δείχνει γιατί η επαλήθευση δεν αποτελεί τροχοπέδη στην καινοτομία αλλά μέτρο προστασίας των ασθενών.","Change-Control + Impact":"Έλεγχος αλλαγών + επιπτώσεις","Befunde pausiert, v4.1 mit Altfallset geprüft, MET-Call orthogonal bestätigt, Artefaktfilter angepasst, Versionierung dokumentiert.":"Οι αναφορές τέθηκαν σε αναστολή, η v4.1 ελέγχθηκε με σύνολο παλαιότερων περιστατικών, το call του MET επιβεβαιώθηκε ορθογωνικά, τα φίλτρα artefacts προσαρμόστηκαν και η διαχείριση εκδόσεων τεκμηριώθηκε.","Sehr gute Balance aus Innovation und QM.":"Πολύ καλή ισορροπία μεταξύ καινοτομίας και διαχείρισης ποιότητας.","Neue Pipeline direkt freigegeben":"Άμεση έγκριση του νέου pipeline","Später werden diskordante Artefakte entdeckt, Reports müssen korrigiert werden.":"Αργότερα εντοπίζονται ασύμφωνα artefacts και οι αναφορές πρέπει να διορθωθούν.","Kritischer Postanalytik-/QM-Fehler.":"Κρίσιμο σφάλμα μετα-αναλυτικού σταδίου/διαχείρισης ποιότητας.","Stiller Rollback":"Σιωπηλό rollback","Routine läuft weiter, aber Ereignis ist nicht nachvollziehbar; Audit-Finding wahrscheinlich.":"Η λειτουργία ρουτίνας συνεχίζεται, αλλά το συμβάν δεν είναι ιχνηλάσιμο· είναι πιθανό εύρημα ελέγχου.","Prozess scheinbar gerettet, Auditfähigkeit verloren.":"Η διαδικασία φαίνεται να διασώθηκε, αλλά χάθηκε η δυνατότητα ελέγχου.","keine Versionierung":"χωρίς διαχείριση εκδόσεων","Audit-Trail-Abzug und Cap":"Αφαίρεση για το ίχνος ελέγχου και ανώτατο όριο","Documentation und Process Decision betroffen.":"Επηρεάζονται η Τεκμηρίωση και η Απόφαση διαδικασίας.","Befund freigegeben ohne Impact":"Αναφορά αποδεσμεύτηκε χωρίς αξιολόγηση επιπτώσεων","critical_fail möglich":"δυνατό critical_fail","Score-Cap und Berichtswarnung.":"Ανώτατο όριο βαθμολογίας και προειδοποίηση στην αναφορά.","Bioinformatik-Pipelines sind Teil der Methode.":"Τα pipeline βιοπληροφορικής αποτελούν μέρος της μεθόδου.","Change-Control schützt nicht vor Fortschritt, sondern vor unkontrolliertem Fortschritt.":"Ο έλεγχος αλλαγών δεν προστατεύει από την πρόοδο, αλλά από την ανεξέλεγκτη πρόοδο.","Versionierung muss im Befund-/Archivkontext rückverfolgbar sein.":"Η διαχείριση εκδόσεων πρέπει να είναι ιχνηλάσιμη στο πλαίσιο αναφοράς/αρχειοθέτησης.","Hold/Impact-Analyse, Change-Control, Verifizierung, Versionierung, medizinische Bewertung diskordanter Fälle, ggf. Rollback auf validierten Stand bis Freigabe.":"Hold/ανάλυση επιπτώσεων, έλεγχος αλλαγών, επαλήθευση, διαχείριση εκδόσεων, ιατρική αξιολόγηση ασύμφωνων περιστατικών και, εφόσον απαιτείται, rollback στην επικυρωμένη κατάσταση έως την έγκριση.","Process Decision":"Απόφαση διαδικασίας","Documentation":"Τεκμηρίωση","Patient Safety":"Ασφάλεια ασθενών","CAPA/Audit":"CAPA/Έλεγχος","Was ist minimale Verifizierung für Pipeline-Update?":"Ποια είναι η ελάχιστη επαλήθευση που απαιτείται για ενημέρωση pipeline;","Wann müssen Altbefunde reevaluiert werden?":"Πότε πρέπει να επαναξιολογούνται παλαιότερες αναφορές;","Wie dokumentiert man Annotation-Datenbanken?":"Πώς πρέπει να τεκμηριώνονται οι βάσεις δεδομένων επισημείωσης;","Twist: bessere Sensitivität + neue Artefaktlast":"Ανατροπή: καλύτερη ευαισθησία + νέο φορτίο artefacts","Critical Error: Freigabe ohne Verifizierung":"Κρίσιμο σφάλμα: αποδέσμευση χωρίς επαλήθευση","Musterpfad: Hold → Impact → Change-Control → Verifizierung → Freigabe":"Πρότυπη διαδρομή: Hold → Επιπτώσεις → Έλεγχος αλλαγών → Επαλήθευση → Αποδέσμευση","System":"Σύστημα","Ausgangslage":"Αρχική κατάσταση","Betroffene Zeit":"Επηρεαζόμενη περίοδος","Problem":"Πρόβλημα","Auffälligkeit":"Εύρημα","Audit-Risiko":"Κίνδυνος ελέγχου","Konflikt":"Σύγκρουση","LAB; Länge=Complex; Schwierigkeit=Advanced; Status=curated-core":"LAB· διάρκεια=σύνθετη· δυσκολία=προχωρημένη· κατάσταση=curated-core"},"es":{"Pipeline-Version geändert, kein Change-Log → Bioinformatik-QM und Impact-Analyse":"Versión del pipeline modificada, sin registro de cambios → calidad bioinformática y análisis de impacto","Postanalytik / Bioinformatik / Change-Control":"Postanalítica / bioinformática / control de cambios","Complex":"Complejo","Advanced":"Avanzado","Core/MVP prüfen":"Revisar core/MVP","Variant Caller wurde von Version 3.4 auf 4.1 aktualisiert.":"El caller de variantes se actualizó de la versión 3.4 a la 4.1.","Patientensicherheits- und Qualitätsrisiko des Ereignisses korrekt priorisieren":"Priorizar correctamente el riesgo del evento para la seguridad del paciente y la calidad","Pipeline-/Softwareänderungen über Change-Control, Revalidierung und Versionierung absichern":"Asegurar los cambios del pipeline/software mediante control de cambios, revalidación y versionado","Freigabe-, Sperr- oder Wiederholungsentscheidung auditfähig begründen":"Justificar de forma auditable la decisión de liberar, bloquear o repetir","Bioinformatik":"Bioinformática","Pipeline":"Pipeline","Versionierung":"Versionado","Change-Control":"Control de cambios","Audit":"Auditoría","NGS":"NGS","Pipeline ohne Change-Log":"Pipeline sin registro de cambios","Targeted DNA-NGS Pipeline":"Pipeline de NGS de ADN dirigido","Kein Change-Log, keine formale Freigabe, keine Verifizierungsnotiz.":"Sin registro de cambios, sin aprobación formal y sin nota de verificación.","2 Wochen Routinebetrieb.":"2 semanas de funcionamiento rutinario.","Zwei Varianten werden in der neuen Version anders gefiltert/klassifiziert.":"Dos variantes se filtran/clasifican de forma diferente en la nueva versión.","Nicht dokumentierte Pipelineänderung":"Cambio de pipeline no documentado","Alte und neue Auswertung sind nicht mehr eindeutig vergleichbar.":"Los análisis antiguo y nuevo ya no son claramente comparables.","Falsch-negative oder falsch-positive Befundkonsequenzen, besonders bei therapieentscheidenden Varianten.":"Consecuencias falsamente negativas o positivas en el informe, especialmente en variantes que determinan el tratamiento.","Rückverfolgbarkeit von Auswertungsschritten und Datenbank-/Pipelineversion fehlt.":"Falta la trazabilidad de los pasos de análisis y de las versiones de la base de datos/pipeline.","Weiterarbeiten mit neuer Software vs. Befunde pausieren und Impact klären.":"Seguir trabajando con el nuevo software frente a pausar los informes y aclarar el impacto.","Nichts tun, neue Pipeline ist vermutlich besser.":"No hacer nada; probablemente el nuevo pipeline sea mejor.","Kritisch falsch: Softwareänderungen sind methodisch relevante Änderungen und müssen kontrolliert werden.":"Críticamente incorrecto: los cambios de software son cambios metodológicos relevantes y deben controlarse.","Nur Bioinformatik informieren, Laborbefunde weiter freigeben.":"Informar solo a bioinformática y seguir liberando los informes de laboratorio.","Unzureichend: Es geht um Befundvalidität, Freigabe und QM, nicht nur um Technik.":"Insuficiente: se trata de la validez del informe, la liberación y la gestión de calidad, no solo de la técnica.","Abweichung eröffnen, Freigabe risikobasiert pausieren, betroffene Fälle identifizieren, Impact-Analyse und ggf. Reanalyse festlegen.":"Abrir una desviación, pausar la liberación en función del riesgo, identificar los casos afectados y definir el análisis de impacto y, si procede, el reanálisis.","Optimal: Change-Control, Patientensicherheit und Audit-Trail werden gesichert.":"Óptimo: se aseguran el control de cambios, la seguridad del paciente y la pista de auditoría.","Alle alten Befunde sofort pauschal zurückrufen.":"Retirar de inmediato y de forma general todos los informes anteriores.","Zu pauschal: Reanalyse/Rückruf müssen durch Impact- und Risikoanalyse begründet werden.":"Demasiado general: el reanálisis/la retirada deben justificarse mediante un análisis de impacto y riesgo.","Alle Runs/Fälle im Zeitraum der neuen Pipelineversion identifizieren":"Identificar todas las corridas/casos del periodo de la nueva versión del pipeline","Ohne Fallliste keine Impact-Analyse.":"Sin una lista de casos no es posible realizar un análisis de impacto.","Prüfen, ob Calling/Filtering oder nur Annotation betroffen ist":"Comprobar si se ven afectados el calling/filtering o solo la anotación","Calling-/Filtering-Änderungen sind befundkritischer.":"Los cambios de calling/filtering son más críticos para el informe.","Bereits freigegebene therapieentscheidende Befunde priorisieren":"Priorizar los informes ya liberados que condicionan decisiones terapéuticas","Klinische Relevanz steuert Reanalysebedarf.":"La relevancia clínica determina la necesidad de reanálisis.","Negative Fälle nicht prüfen":"No revisar los casos negativos","Falsch: Gerade negative Befunde können betroffen sein.":"Incorrecto: precisamente los informes negativos pueden estar afectados.","Referenz-/Verifizierungsdatensatz für Version 4.1 nachziehen":"Completar el conjunto de datos de referencia/verificación para la versión 4.1","Neue Versionen müssen lokal kontrolliert werden.":"Las nuevas versiones deben evaluarse localmente.","Abweichung: nicht dokumentierte Pipelineänderung":"Desviación: cambio de pipeline no documentado","Sofortmaßnahme: Freigaben risikobasiert pausieren/kontrollieren":"Medida inmediata: pausar/controlar las liberaciones según el riesgo","Korrektur: Impact-Analyse und definierte Reanalyse":"Corrección: análisis de impacto y reanálisis definido","Prävention: SOP für Pipeline-Change mit Pflichtfeldern":"Prevención: SOP para cambios del pipeline con campos obligatorios","Wirksamkeitsprüfung: nächste Änderungen vollständig dokumentiert":"Comprobación de eficacia: los cambios posteriores quedan completamente documentados","Alte/neue Pipelineversion und Zeitpunkt dokumentiert":"Versión antigua/nueva del pipeline y momento del cambio documentados","Risikobewertung pro Befundklasse nachvollziehbar":"La evaluación de riesgo es trazable para cada clase de informe","Freigabe der neuen Pipelineversion dokumentiert":"Aprobación de la nueva versión del pipeline documentada","Kommunikation/Schulung der betroffenen Personen dokumentiert":"Comunicación/formación del personal afectado documentada","Change nur intern mündlich besprechen, nicht dokumentieren":"Comentar el cambio solo verbalmente de forma interna; no documentarlo","Optimale Lösung: Pipelineänderung als Abweichung behandeln, Impact-Analyse durchführen, betroffene Befunde risikobasiert reanalysieren und Change-Control für künftige Updates etablieren.":"Solución óptima: tratar el cambio del pipeline como una desviación, realizar un análisis de impacto, reanalizar según el riesgo los informes afectados y establecer control de cambios para futuras actualizaciones.","Pipeline-Version geändert, kein Change-Log: Bioinformatik-QM und Impact-Analyse":"Versión del pipeline modificada, sin registro de cambios: calidad bioinformática y análisis de impacto","LAB":"LAB","Advanced Integrated":"Avanzado integrado","Laborleitung / Bioinformatik-QM":"Dirección del laboratorio / calidad bioinformática","Pipeline-/Softwareänderungen als qualitätsrelevante Methodenänderung erkennen.":"Reconocer los cambios del pipeline/software como cambios metodológicos relevantes para la calidad.","Impact-Analyse, Versionierung und Revalidierung/Verifizierung ableiten.":"Derivar el análisis de impacto, el versionado y la revalidación/verificación necesarios.","Befundfreigabe bei diskordanten Pipeline-Ergebnissen auditfähig steuern.":"Gestionar de forma auditable la liberación de informes ante resultados discordantes del pipeline.","Ein Bioinformatik-Update wurde 'nur kurz' eingespielt, weil der neue Caller bessere Indel-Erkennung verspricht. Am nächsten Tag unterscheiden sich mehrere Variantenlisten von alten Ergebnissen. Ein Change-Log existiert nicht.":"Se instaló 'rápidamente' una actualización bioinformática porque el nuevo caller promete una mejor detección de indels. Al día siguiente, varias listas de variantes difieren de los resultados anteriores. No existe registro de cambios.","Molekularpathologisches NGS-Panel, 48 Patientenfälle im aktuellen Batch. Variant Caller von 3.4 auf 4.1 aktualisiert. Referenzdatenbank und Annotation wurden ebenfalls minor aktualisiert. Die Änderung wurde nicht vorab in der QM-Dokumentation freigegeben.":"Panel NGS de patología molecular, 48 casos de pacientes en el lote actual. El caller de variantes se actualizó de 3.4 a 4.1. La base de datos de referencia y la anotación también recibieron actualizaciones menores. El cambio no había sido aprobado previamente en la documentación de calidad.","Diskordanz":"Discordancia","Bei 6/48 Fällen unterscheiden sich reportable variants. Ein Fall betrifft eine potenziell therapieentscheidende MET-Splice-Region.":"Las variantes informables difieren en 6/48 casos. Un caso afecta a una región de splice de MET potencialmente determinante para el tratamiento.","Nicht jede Softwareänderung ist rein technisch.":"No todos los cambios de software son puramente técnicos.","Im Berichtsentwurf ist keine Pipeline-Version angegeben; alte Reports enthalten nur 'NGS Pipeline'.":"El borrador del informe no indica la versión del pipeline; los informes antiguos solo contienen 'NGS Pipeline'.","Ohne Versionierung fehlt Rückverfolgbarkeit.":"Sin versionado se pierde la trazabilidad.","Teamkonflikt":"Conflicto de equipo","Bioinformatik sagt: 'Der neue Caller ist besser.' QM fragt: 'Wo ist die Verifizierung?' Klinik wartet auf Befunde.":"Bioinformática dice: 'El nuevo caller es mejor.' Calidad pregunta: '¿Dónde está la verificación?' El equipo clínico espera los informes.","Besser ist nicht gleich freigegeben.":"Mejor no significa aprobado para su liberación.","Risiko":"Riesgo","Sowohl falsch-positive als auch falsch-negative Änderungen sind möglich; Impact ist nicht auf einen Fall begrenzt.":"Son posibles cambios tanto falsamente positivos como falsamente negativos; el impacto no se limita a un solo caso.","Impact-Analyse muss systematisch erfolgen.":"El análisis de impacto debe realizarse de forma sistemática.","Alter Lauf":"Corrida anterior","Validierte Pipeline v3.4 mit dokumentierter Leistungsfähigkeit.":"Pipeline validado v3.4 con rendimiento documentado.","Neuer Lauf":"Nueva corrida","v4.1 ruft zusätzliche Indels/Splice-Varianten, darunter ein potenziell reportables MET-Ereignis.":"v4.1 detecta indels/variantes de splice adicionales, incluido un evento MET potencialmente informable.","Dokumentation":"Documentación","kein Change-Control-Eintrag, keine Freigabe, keine definierte Vergleichsmatrix.":"Sin registro de control de cambios, sin aprobación y sin matriz de comparación definida.","Klinischer TAT-Druck, aber potenzieller Einfluss auf Befundqualität.":"Presión clínica por el TAT, pero con posible impacto en la calidad del informe.","Vergleichsdatensätze und Alt-Runs sind verfügbar.":"Hay disponibles conjuntos de datos comparativos y corridas anteriores.","Re-Analyse früherer Fälle könnte nötig werden, wenn systematischer Einfluss besteht.":"Puede ser necesario reanalizar casos anteriores si existe un impacto sistemático.","Wie ist die Pipelineänderung zu bewerten?":"¿Cómo debe evaluarse el cambio del pipeline?","qualitätsrelevante Methoden-/Auswertungsänderung mit Change-Control-Bedarf":"cambio de método/análisis relevante para la calidad que requiere control de cambios","rein kosmetische Änderung":"cambio puramente cosmético","irrelevant, wenn Software neuer ist":"irrelevante si el software es más nuevo","nur klinische Entscheidung":"solo una decisión clínica","Pipelineversionen beeinflussen berichtete Varianten und benötigen Kontrolle.":"Las versiones del pipeline afectan a las variantes informadas y requieren control.","Was ist die richtige Sofortmaßnahme?":"¿Cuál es la medida inmediata correcta?","Freigabe betroffener Befunde pausieren und Impact-Analyse starten":"Pausar la liberación de los informes afectados e iniciar un análisis de impacto","alle neuen Calls freigeben":"liberar todos los nuevos calls","heimlich zurückrollen ohne Doku":"hacer un rollback silencioso sin documentación","alte Ergebnisse löschen":"eliminar los resultados antiguos","Freigabe ohne Impact wäre riskant.":"Liberar sin evaluar el impacto sería arriesgado.","Was muss dokumentiert werden?":"¿Qué debe documentarse?","exakte Pipeline-/Caller-/DB-Versionen":"versiones exactas del pipeline/caller/base de datos","Verifizierungs-/Vergleichsergebnisse":"resultados de verificación/comparación","Freigabe/Change-Control":"aprobación/control de cambios","nichts, wenn Ergebnis plausibel":"nada si el resultado parece plausible","Rückverfolgbarkeit ist Kern der Postanalytik.":"La trazabilidad es un requisito esencial de la postanalítica.","Wie geht man mit potenziell betroffenen Fällen um?":"¿Cómo deben gestionarse los casos potencialmente afectados?","betroffene Fälle identifizieren und medizinisch/QM-seitig bewerten":"identificar los casos afectados y evaluarlos médica y cualitativamente","alte Fälle nie prüfen":"no revisar nunca los casos antiguos","alle neuen Varianten ohne Prüfung reporten":"informar todas las variantes nuevas sin revisión","nur Annotation ändern":"cambiar solo la anotación","Impact-Analyse ist fall- und markerbezogen.":"El análisis de impacto es específico del caso y del marcador.","Entscheide, wie mit der ungeplanten Pipelineänderung, den diskordanten Calls und der Befundfreigabe umzugehen ist.":"Decidir cómo gestionar el cambio no planificado del pipeline, los calls discordantes y la liberación de informes.","Freigabe diskordanter/entscheidungsrelevanter Befunde pausieren.":"Pausar la liberación de informes discordantes o relevantes para la decisión.","Change-Control nachholen: Änderung, Grund, Versionen, Verantwortliche dokumentieren.":"Completar retrospectivamente el control de cambios: documentar el cambio, el motivo, las versiones y los responsables.","Verifizierung mit definiertem Referenz-/Altfallset durchführen.":"Realizar la verificación con un conjunto definido de referencia/casos anteriores.","Diskordante Calls medizinisch-technisch bewerten und ggf. orthogonal bestätigen.":"Evaluar médica y técnicamente los calls discordantes y confirmarlos de forma ortogonal si es necesario.","Berichtsvorlagen mit Pipeline-Version/Auswertungsstand korrigieren.":"Corregir las plantillas de informe para incluir la versión del pipeline/el estado del análisis.","Entscheiden, ob frühere Fälle reevaluiert werden müssen.":"Decidir si es necesario reevaluar casos anteriores.","Temporärer Rollback auf validierte Pipeline für Routinefreigabe, während v4.1 verifiziert wird.":"Rollback temporal al pipeline validado para la liberación rutinaria mientras se verifica v4.1.","Teilfreigabe nicht betroffener Befunde, wenn Trennung auditfähig dokumentiert ist.":"Liberación parcial de los informes no afectados si la separación está documentada de forma auditable.","Neue Pipeline ist automatisch besser":"El nuevo pipeline es automáticamente mejor","ohne Verifizierung keine Routinefreigabe.":"No hay liberación rutinaria sin verificación.","Silent rollback":"Rollback silencioso","verschleiert das Ereignis und zerstört Audit-Trail.":"oculta el evento y destruye la pista de auditoría.","Nur Bioinformatik entscheidet":"Solo bioinformática decide","klinisch-reportable Änderungen brauchen Laborleitung/QM/ärztliche Bewertung.":"Los cambios clínicamente informables requieren evaluación por la dirección del laboratorio, calidad y personal médico.","Ein alter negativer Fall wäre heute positiv":"Un caso antiguo negativo sería hoy positivo","Die Impact-Analyse zeigt, dass v4.1 eine MET-Splice-Region in einem aktuellen Fall plausibel ruft, aber auch zwei alte low-quality Artefakte neu als Varianten markiert. Die Änderung verbessert einen Bereich, erzeugt aber neue Review-Bedürfnisse.":"El análisis de impacto muestra que v4.1 detecta de forma plausible una región de splice de MET en un caso actual, pero también marca dos artefactos antiguos de baja calidad como variantes. El cambio mejora un área, pero genera nuevas necesidades de revisión.","Der Fall zeigt, warum Verifizierung nicht Innovationsbremse, sondern Patientenschutz ist.":"El caso muestra por qué la verificación no frena la innovación, sino que protege al paciente.","Change-Control + Impact":"Control de cambios + impacto","Befunde pausiert, v4.1 mit Altfallset geprüft, MET-Call orthogonal bestätigt, Artefaktfilter angepasst, Versionierung dokumentiert.":"Se pausaron los informes, se evaluó v4.1 con un conjunto de casos anteriores, se confirmó ortogonalmente el call de MET, se ajustaron los filtros de artefactos y se documentó el versionado.","Sehr gute Balance aus Innovation und QM.":"Muy buen equilibrio entre innovación y gestión de calidad.","Neue Pipeline direkt freigegeben":"Nuevo pipeline liberado directamente","Später werden diskordante Artefakte entdeckt, Reports müssen korrigiert werden.":"Más tarde se descubren artefactos discordantes y es necesario corregir los informes.","Kritischer Postanalytik-/QM-Fehler.":"Error crítico de postanalítica/gestión de calidad.","Stiller Rollback":"Rollback silencioso","Routine läuft weiter, aber Ereignis ist nicht nachvollziehbar; Audit-Finding wahrscheinlich.":"La rutina continúa, pero el evento no es trazable; es probable un hallazgo de auditoría.","Prozess scheinbar gerettet, Auditfähigkeit verloren.":"Proceso aparentemente salvado, pero se pierde la auditabilidad.","keine Versionierung":"sin versionado","Audit-Trail-Abzug und Cap":"Penalización por pista de auditoría y tope","Documentation und Process Decision betroffen.":"Se ven afectadas la Documentación y la Decisión de proceso.","Befund freigegeben ohne Impact":"Informe liberado sin evaluación de impacto","critical_fail möglich":"critical_fail posible","Score-Cap und Berichtswarnung.":"Tope de puntuación y advertencia en el informe.","Bioinformatik-Pipelines sind Teil der Methode.":"Los pipelines bioinformáticos forman parte del método.","Change-Control schützt nicht vor Fortschritt, sondern vor unkontrolliertem Fortschritt.":"El control de cambios no protege frente al progreso, sino frente al progreso no controlado.","Versionierung muss im Befund-/Archivkontext rückverfolgbar sein.":"El versionado debe ser trazable en el contexto del informe/archivo.","Hold/Impact-Analyse, Change-Control, Verifizierung, Versionierung, medizinische Bewertung diskordanter Fälle, ggf. Rollback auf validierten Stand bis Freigabe.":"Hold/análisis de impacto, control de cambios, verificación, versionado, evaluación médica de los casos discordantes y, si es necesario, rollback al estado validado hasta la aprobación.","Process Decision":"Decisión de proceso","Documentation":"Documentación","Patient Safety":"Seguridad del paciente","CAPA/Audit":"CAPA/Auditoría","Was ist minimale Verifizierung für Pipeline-Update?":"¿Cuál es la verificación mínima necesaria para una actualización del pipeline?","Wann müssen Altbefunde reevaluiert werden?":"¿Cuándo deben reevaluarse los informes anteriores?","Wie dokumentiert man Annotation-Datenbanken?":"¿Cómo deben documentarse las bases de datos de anotación?","Twist: bessere Sensitivität + neue Artefaktlast":"Giro: mejor sensibilidad + nueva carga de artefactos","Critical Error: Freigabe ohne Verifizierung":"Error crítico: liberación sin verificación","Musterpfad: Hold → Impact → Change-Control → Verifizierung → Freigabe":"Ruta de referencia: Hold → Impacto → Control de cambios → Verificación → Liberación","System":"Sistema","Ausgangslage":"Situación inicial","Betroffene Zeit":"Periodo afectado","Problem":"Problema","Auffälligkeit":"Hallazgo","Audit-Risiko":"Riesgo de auditoría","Konflikt":"Conflicto","LAB; Länge=Complex; Schwierigkeit=Advanced; Status=curated-core":"LAB; longitud=compleja; dificultad=avanzada; estado=curated-core"},"fr":{"Pipeline-Version geändert, kein Change-Log → Bioinformatik-QM und Impact-Analyse":"Version du pipeline modifiée, sans journal des modifications → qualité bioinformatique et analyse d’impact","Postanalytik / Bioinformatik / Change-Control":"Post-analytique / bioinformatique / gestion des modifications","Complex":"Complexe","Advanced":"Avancé","Core/MVP prüfen":"Vérifier core/MVP","Variant Caller wurde von Version 3.4 auf 4.1 aktualisiert.":"Le logiciel d’appel de variants a été mis à jour de la version 3.4 à la 4.1.","Patientensicherheits- und Qualitätsrisiko des Ereignisses korrekt priorisieren":"Hiérarchiser correctement le risque de l’événement pour la sécurité des patients et la qualité","Pipeline-/Softwareänderungen über Change-Control, Revalidierung und Versionierung absichern":"Sécuriser les modifications du pipeline/logiciel par la gestion des modifications, la revalidation et le versionnage","Freigabe-, Sperr- oder Wiederholungsentscheidung auditfähig begründen":"Justifier de manière auditable la décision de libérer, bloquer ou répéter","Bioinformatik":"Bioinformatique","Pipeline":"Pipeline","Versionierung":"Versionnage","Change-Control":"Gestion des modifications","Audit":"Audit","NGS":"NGS","Pipeline ohne Change-Log":"Pipeline sans journal des modifications","Targeted DNA-NGS Pipeline":"Pipeline de NGS ADN ciblé","Kein Change-Log, keine formale Freigabe, keine Verifizierungsnotiz.":"Aucun journal des modifications, aucune approbation formelle, aucune note de vérification.","2 Wochen Routinebetrieb.":"2 semaines d’utilisation en routine.","Zwei Varianten werden in der neuen Version anders gefiltert/klassifiziert.":"Deux variants sont filtrés/classés différemment dans la nouvelle version.","Nicht dokumentierte Pipelineänderung":"Modification non documentée du pipeline","Alte und neue Auswertung sind nicht mehr eindeutig vergleichbar.":"Les analyses ancienne et nouvelle ne sont plus clairement comparables.","Falsch-negative oder falsch-positive Befundkonsequenzen, besonders bei therapieentscheidenden Varianten.":"Conséquences faussement négatives ou positives sur le compte rendu, en particulier pour les variants déterminant le traitement.","Rückverfolgbarkeit von Auswertungsschritten und Datenbank-/Pipelineversion fehlt.":"La traçabilité des étapes d’analyse et des versions de la base de données/du pipeline fait défaut.","Weiterarbeiten mit neuer Software vs. Befunde pausieren und Impact klären.":"Continuer avec le nouveau logiciel ou suspendre les comptes rendus et clarifier l’impact.","Nichts tun, neue Pipeline ist vermutlich besser.":"Ne rien faire ; le nouveau pipeline est probablement meilleur.","Kritisch falsch: Softwareänderungen sind methodisch relevante Änderungen und müssen kontrolliert werden.":"Erreur critique : les modifications logicielles sont des changements méthodologiquement pertinents et doivent être maîtrisées.","Nur Bioinformatik informieren, Laborbefunde weiter freigeben.":"Informer uniquement la bioinformatique et continuer à libérer les comptes rendus de laboratoire.","Unzureichend: Es geht um Befundvalidität, Freigabe und QM, nicht nur um Technik.":"Insuffisant : il s’agit de la validité du compte rendu, de sa libération et de la qualité, pas seulement de la technique.","Abweichung eröffnen, Freigabe risikobasiert pausieren, betroffene Fälle identifizieren, Impact-Analyse und ggf. Reanalyse festlegen.":"Ouvrir une déviation, suspendre la libération selon le risque, identifier les cas concernés et définir l’analyse d’impact ainsi qu’une éventuelle réanalyse.","Optimal: Change-Control, Patientensicherheit und Audit-Trail werden gesichert.":"Optimal : la gestion des modifications, la sécurité des patients et la piste d’audit sont garanties.","Alle alten Befunde sofort pauschal zurückrufen.":"Rappeler immédiatement et systématiquement tous les anciens comptes rendus.","Zu pauschal: Reanalyse/Rückruf müssen durch Impact- und Risikoanalyse begründet werden.":"Trop général : la réanalyse/le rappel doivent être justifiés par une analyse d’impact et de risque.","Alle Runs/Fälle im Zeitraum der neuen Pipelineversion identifizieren":"Identifier toutes les séries/tous les cas de la période d’utilisation de la nouvelle version du pipeline","Ohne Fallliste keine Impact-Analyse.":"Aucune analyse d’impact n’est possible sans liste des cas.","Prüfen, ob Calling/Filtering oder nur Annotation betroffen ist":"Vérifier si le calling/le filtrage ou seulement l’annotation sont concernés","Calling-/Filtering-Änderungen sind befundkritischer.":"Les modifications du calling/filtrage sont plus critiques pour le compte rendu.","Bereits freigegebene therapieentscheidende Befunde priorisieren":"Prioriser les comptes rendus déjà libérés influençant une décision thérapeutique","Klinische Relevanz steuert Reanalysebedarf.":"La pertinence clinique détermine la nécessité d’une réanalyse.","Negative Fälle nicht prüfen":"Ne pas revoir les cas négatifs","Falsch: Gerade negative Befunde können betroffen sein.":"Faux : les comptes rendus négatifs peuvent justement être concernés.","Referenz-/Verifizierungsdatensatz für Version 4.1 nachziehen":"Compléter le jeu de données de référence/vérification pour la version 4.1","Neue Versionen müssen lokal kontrolliert werden.":"Les nouvelles versions doivent être contrôlées localement.","Abweichung: nicht dokumentierte Pipelineänderung":"Déviation : modification non documentée du pipeline","Sofortmaßnahme: Freigaben risikobasiert pausieren/kontrollieren":"Mesure immédiate : suspendre/contrôler les libérations en fonction du risque","Korrektur: Impact-Analyse und definierte Reanalyse":"Correction : analyse d’impact et réanalyse définie","Prävention: SOP für Pipeline-Change mit Pflichtfeldern":"Prévention : SOP pour les modifications du pipeline avec champs obligatoires","Wirksamkeitsprüfung: nächste Änderungen vollständig dokumentiert":"Vérification d’efficacité : les modifications suivantes sont intégralement documentées","Alte/neue Pipelineversion und Zeitpunkt dokumentiert":"Ancienne/nouvelle version du pipeline et date du changement documentées","Risikobewertung pro Befundklasse nachvollziehbar":"L’évaluation du risque est traçable pour chaque catégorie de compte rendu","Freigabe der neuen Pipelineversion dokumentiert":"Approbation de la nouvelle version du pipeline documentée","Kommunikation/Schulung der betroffenen Personen dokumentiert":"Communication/formation des personnes concernées documentée","Change nur intern mündlich besprechen, nicht dokumentieren":"Discuter du changement uniquement oralement en interne ; ne pas le documenter","Optimale Lösung: Pipelineänderung als Abweichung behandeln, Impact-Analyse durchführen, betroffene Befunde risikobasiert reanalysieren und Change-Control für künftige Updates etablieren.":"Solution optimale : traiter la modification du pipeline comme une déviation, réaliser une analyse d’impact, réanalyser les comptes rendus concernés selon le risque et instaurer une gestion des modifications pour les futures mises à jour.","Pipeline-Version geändert, kein Change-Log: Bioinformatik-QM und Impact-Analyse":"Version du pipeline modifiée, sans journal des modifications : qualité bioinformatique et analyse d’impact","LAB":"LAB","Advanced Integrated":"Avancé intégré","Laborleitung / Bioinformatik-QM":"Direction du laboratoire / qualité bioinformatique","Pipeline-/Softwareänderungen als qualitätsrelevante Methodenänderung erkennen.":"Reconnaître les modifications du pipeline/logiciel comme des changements méthodologiques pertinents pour la qualité.","Impact-Analyse, Versionierung und Revalidierung/Verifizierung ableiten.":"Déduire l’analyse d’impact, le versionnage et la revalidation/vérification nécessaires.","Befundfreigabe bei diskordanten Pipeline-Ergebnissen auditfähig steuern.":"Gérer de manière auditable la libération des comptes rendus en cas de résultats discordants du pipeline.","Ein Bioinformatik-Update wurde 'nur kurz' eingespielt, weil der neue Caller bessere Indel-Erkennung verspricht. Am nächsten Tag unterscheiden sich mehrere Variantenlisten von alten Ergebnissen. Ein Change-Log existiert nicht.":"Une mise à jour bioinformatique a été installée 'juste rapidement', car le nouveau caller promet une meilleure détection des indels. Le lendemain, plusieurs listes de variants diffèrent des résultats antérieurs. Il n’existe aucun journal des modifications.","Molekularpathologisches NGS-Panel, 48 Patientenfälle im aktuellen Batch. Variant Caller von 3.4 auf 4.1 aktualisiert. Referenzdatenbank und Annotation wurden ebenfalls minor aktualisiert. Die Änderung wurde nicht vorab in der QM-Dokumentation freigegeben.":"Panel NGS de pathologie moléculaire, 48 cas patients dans le lot actuel. Le logiciel d’appel de variants est passé de la version 3.4 à 4.1. La base de données de référence et l’annotation ont également fait l’objet de mises à jour mineures. La modification n’avait pas été approuvée au préalable dans la documentation qualité.","Diskordanz":"Discordance","Bei 6/48 Fällen unterscheiden sich reportable variants. Ein Fall betrifft eine potenziell therapieentscheidende MET-Splice-Region.":"Les variants devant être rapportés diffèrent dans 6/48 cas. Un cas concerne une région d’épissage de MET potentiellement déterminante pour le traitement.","Nicht jede Softwareänderung ist rein technisch.":"Toute modification logicielle n’est pas purement technique.","Im Berichtsentwurf ist keine Pipeline-Version angegeben; alte Reports enthalten nur 'NGS Pipeline'.":"Le projet de compte rendu n’indique aucune version du pipeline ; les anciens comptes rendus mentionnent seulement 'NGS Pipeline'.","Ohne Versionierung fehlt Rückverfolgbarkeit.":"Sans versionnage, la traçabilité est perdue.","Teamkonflikt":"Conflit d’équipe","Bioinformatik sagt: 'Der neue Caller ist besser.' QM fragt: 'Wo ist die Verifizierung?' Klinik wartet auf Befunde.":"La bioinformatique dit : 'Le nouveau caller est meilleur.' La qualité demande : 'Où est la vérification ?' L’équipe clinique attend les comptes rendus.","Besser ist nicht gleich freigegeben.":"Meilleur ne signifie pas approuvé pour la routine.","Risiko":"Risque","Sowohl falsch-positive als auch falsch-negative Änderungen sind möglich; Impact ist nicht auf einen Fall begrenzt.":"Des modifications faussement positives comme faussement négatives sont possibles ; l’impact ne se limite pas à un seul cas.","Impact-Analyse muss systematisch erfolgen.":"L’analyse d’impact doit être systématique.","Alter Lauf":"Série précédente","Validierte Pipeline v3.4 mit dokumentierter Leistungsfähigkeit.":"Pipeline validé v3.4 avec performances documentées.","Neuer Lauf":"Nouvelle série","v4.1 ruft zusätzliche Indels/Splice-Varianten, darunter ein potenziell reportables MET-Ereignis.":"La v4.1 appelle des indels/variants d’épissage supplémentaires, dont un événement MET potentiellement rapportable.","Dokumentation":"Documentation","kein Change-Control-Eintrag, keine Freigabe, keine definierte Vergleichsmatrix.":"Aucune entrée de gestion des modifications, aucune approbation, aucune matrice de comparaison définie.","Klinischer TAT-Druck, aber potenzieller Einfluss auf Befundqualität.":"Pression clinique sur le TAT, mais impact potentiel sur la qualité du compte rendu.","Vergleichsdatensätze und Alt-Runs sind verfügbar.":"Des jeux de données comparatifs et des séries antérieures sont disponibles.","Re-Analyse früherer Fälle könnte nötig werden, wenn systematischer Einfluss besteht.":"Une réanalyse de cas antérieurs peut être nécessaire en cas d’impact systématique.","Wie ist die Pipelineänderung zu bewerten?":"Comment évaluer la modification du pipeline ?","qualitätsrelevante Methoden-/Auswertungsänderung mit Change-Control-Bedarf":"modification de méthode/analyse pertinente pour la qualité nécessitant une gestion des modifications","rein kosmetische Änderung":"modification purement cosmétique","irrelevant, wenn Software neuer ist":"sans importance si le logiciel est plus récent","nur klinische Entscheidung":"décision clinique uniquement","Pipelineversionen beeinflussen berichtete Varianten und benötigen Kontrolle.":"Les versions du pipeline influencent les variants rapportés et doivent être maîtrisées.","Was ist die richtige Sofortmaßnahme?":"Quelle est la bonne mesure immédiate ?","Freigabe betroffener Befunde pausieren und Impact-Analyse starten":"Suspendre la libération des comptes rendus concernés et lancer une analyse d’impact","alle neuen Calls freigeben":"libérer tous les nouveaux calls","heimlich zurückrollen ohne Doku":"effectuer un rollback silencieux sans documentation","alte Ergebnisse löschen":"supprimer les anciens résultats","Freigabe ohne Impact wäre riskant.":"Une libération sans évaluation de l’impact serait risquée.","Was muss dokumentiert werden?":"Que faut-il documenter ?","exakte Pipeline-/Caller-/DB-Versionen":"versions exactes du pipeline/caller/de la base de données","Verifizierungs-/Vergleichsergebnisse":"résultats de vérification/comparaison","Freigabe/Change-Control":"approbation/gestion des modifications","nichts, wenn Ergebnis plausibel":"rien si le résultat paraît plausible","Rückverfolgbarkeit ist Kern der Postanalytik.":"La traçabilité est une exigence fondamentale du post-analytique.","Wie geht man mit potenziell betroffenen Fällen um?":"Comment gérer les cas potentiellement concernés ?","betroffene Fälle identifizieren und medizinisch/QM-seitig bewerten":"identifier les cas concernés et les évaluer sur les plans médical et qualité","alte Fälle nie prüfen":"ne jamais revoir les anciens cas","alle neuen Varianten ohne Prüfung reporten":"rapporter tous les nouveaux variants sans vérification","nur Annotation ändern":"modifier uniquement l’annotation","Impact-Analyse ist fall- und markerbezogen.":"L’analyse d’impact est spécifique au cas et au marqueur.","Entscheide, wie mit der ungeplanten Pipelineänderung, den diskordanten Calls und der Befundfreigabe umzugehen ist.":"Décider comment gérer la modification non planifiée du pipeline, les calls discordants et la libération des comptes rendus.","Freigabe diskordanter/entscheidungsrelevanter Befunde pausieren.":"Suspendre la libération des comptes rendus discordants ou déterminants pour la décision.","Change-Control nachholen: Änderung, Grund, Versionen, Verantwortliche dokumentieren.":"Compléter rétrospectivement la gestion des modifications : documenter la modification, sa raison, les versions et les responsables.","Verifizierung mit definiertem Referenz-/Altfallset durchführen.":"Réaliser la vérification à l’aide d’un ensemble défini de référence/anciens cas.","Diskordante Calls medizinisch-technisch bewerten und ggf. orthogonal bestätigen.":"Évaluer les calls discordants sur les plans médical et technique et les confirmer par une méthode orthogonale si nécessaire.","Berichtsvorlagen mit Pipeline-Version/Auswertungsstand korrigieren.":"Corriger les modèles de compte rendu pour inclure la version du pipeline/l’état de l’analyse.","Entscheiden, ob frühere Fälle reevaluiert werden müssen.":"Décider si des cas antérieurs doivent être réévalués.","Temporärer Rollback auf validierte Pipeline für Routinefreigabe, während v4.1 verifiziert wird.":"Rollback temporaire vers le pipeline validé pour la libération en routine pendant la vérification de la v4.1.","Teilfreigabe nicht betroffener Befunde, wenn Trennung auditfähig dokumentiert ist.":"Libération partielle des comptes rendus non concernés si la séparation est documentée de manière auditable.","Neue Pipeline ist automatisch besser":"Le nouveau pipeline est automatiquement meilleur","ohne Verifizierung keine Routinefreigabe.":"Pas de libération en routine sans vérification.","Silent rollback":"Rollback silencieux","verschleiert das Ereignis und zerstört Audit-Trail.":"masque l’événement et détruit la piste d’audit.","Nur Bioinformatik entscheidet":"La bioinformatique décide seule","klinisch-reportable Änderungen brauchen Laborleitung/QM/ärztliche Bewertung.":"Les modifications cliniquement rapportables nécessitent une évaluation par la direction du laboratoire, la qualité et le corps médical.","Ein alter negativer Fall wäre heute positiv":"Un ancien cas négatif serait aujourd’hui positif","Die Impact-Analyse zeigt, dass v4.1 eine MET-Splice-Region in einem aktuellen Fall plausibel ruft, aber auch zwei alte low-quality Artefakte neu als Varianten markiert. Die Änderung verbessert einen Bereich, erzeugt aber neue Review-Bedürfnisse.":"L’analyse d’impact montre que la v4.1 appelle de façon plausible une région d’épissage de MET dans un cas actuel, mais signale aussi deux anciens artéfacts de faible qualité comme variants. La modification améliore un domaine, mais crée de nouveaux besoins de revue.","Der Fall zeigt, warum Verifizierung nicht Innovationsbremse, sondern Patientenschutz ist.":"Ce cas montre pourquoi la vérification n’est pas un frein à l’innovation, mais une mesure de protection des patients.","Change-Control + Impact":"Gestion des modifications + impact","Befunde pausiert, v4.1 mit Altfallset geprüft, MET-Call orthogonal bestätigt, Artefaktfilter angepasst, Versionierung dokumentiert.":"Les comptes rendus ont été suspendus, la v4.1 testée sur un ensemble d’anciens cas, le call MET confirmé par une méthode orthogonale, les filtres d’artéfacts ajustés et le versionnage documenté.","Sehr gute Balance aus Innovation und QM.":"Très bon équilibre entre innovation et management de la qualité.","Neue Pipeline direkt freigegeben":"Nouveau pipeline libéré directement","Später werden diskordante Artefakte entdeckt, Reports müssen korrigiert werden.":"Des artéfacts discordants sont découverts ultérieurement et les comptes rendus doivent être corrigés.","Kritischer Postanalytik-/QM-Fehler.":"Erreur critique de post-analytique/qualité.","Stiller Rollback":"Rollback silencieux","Routine läuft weiter, aber Ereignis ist nicht nachvollziehbar; Audit-Finding wahrscheinlich.":"La routine se poursuit, mais l’événement n’est pas traçable ; un écart d’audit est probable.","Prozess scheinbar gerettet, Auditfähigkeit verloren.":"Processus apparemment sauvé, mais auditabilité perdue.","keine Versionierung":"absence de versionnage","Audit-Trail-Abzug und Cap":"Pénalité de piste d’audit et plafond","Documentation und Process Decision betroffen.":"La Documentation et la Décision de processus sont affectées.","Befund freigegeben ohne Impact":"Compte rendu libéré sans évaluation de l’impact","critical_fail möglich":"critical_fail possible","Score-Cap und Berichtswarnung.":"Plafond de score et avertissement dans le compte rendu.","Bioinformatik-Pipelines sind Teil der Methode.":"Les pipelines bioinformatiques font partie de la méthode.","Change-Control schützt nicht vor Fortschritt, sondern vor unkontrolliertem Fortschritt.":"La gestion des modifications ne protège pas du progrès, mais du progrès non maîtrisé.","Versionierung muss im Befund-/Archivkontext rückverfolgbar sein.":"Le versionnage doit être traçable dans le contexte du compte rendu/de l’archivage.","Hold/Impact-Analyse, Change-Control, Verifizierung, Versionierung, medizinische Bewertung diskordanter Fälle, ggf. Rollback auf validierten Stand bis Freigabe.":"Hold/analyse d’impact, gestion des modifications, vérification, versionnage, évaluation médicale des cas discordants et, si nécessaire, rollback vers l’état validé jusqu’à l’approbation.","Process Decision":"Décision de processus","Documentation":"Documentation","Patient Safety":"Sécurité des patients","CAPA/Audit":"CAPA/Audit","Was ist minimale Verifizierung für Pipeline-Update?":"Quelle est la vérification minimale requise pour une mise à jour du pipeline ?","Wann müssen Altbefunde reevaluiert werden?":"Quand faut-il réévaluer les anciens comptes rendus ?","Wie dokumentiert man Annotation-Datenbanken?":"Comment documenter les bases de données d’annotation ?","Twist: bessere Sensitivität + neue Artefaktlast":"Twist : meilleure sensibilité + nouvelle charge d’artéfacts","Critical Error: Freigabe ohne Verifizierung":"Erreur critique : libération sans vérification","Musterpfad: Hold → Impact → Change-Control → Verifizierung → Freigabe":"Parcours de référence : Hold → Impact → Gestion des modifications → Vérification → Libération","System":"Système","Ausgangslage":"Situation initiale","Betroffene Zeit":"Période concernée","Problem":"Problème","Auffälligkeit":"Anomalie","Audit-Risiko":"Risque d’audit","Konflikt":"Conflit","LAB; Länge=Complex; Schwierigkeit=Advanced; Status=curated-core":"LAB ; longueur=complexe ; difficulté=avancée ; statut=curated-core"}};
const LANGS=['de','en','ro','el','es','fr'];
